size_t input_values_count = 0;

// Define a function to validate the input and store it in the array
void processInput(const int value) {
    struct InputData data = {value, (value >= 0)}; // Validate the input
    if (!data.valid) {
        return; // Ignore invalid inputs
    }

    // Add the valid input to the array
    size_t i = input_values_count++;
    if (i == SIZE_MAX || !input_values) {
        size_t new_size = input_values_count * 2;
        struct InputData* new_values = realloc(input_values, new_size);
        if (!new_values) {
            perror("realloc"); // Handle error
            return;
        }
        input_values = new_values;
    }
    input_values[i].value = data.value;
}

// Define a function to determine and print the largest integer seen so far
void getLargestInput() {
    size_t max_index = 0;
    for (size_t i = 1; i < input_values_count; i++) {
        if (input_values[i].value > input_values[max_index].value) {
            max_index = i;
        }
    }
    printf("Largest integer seen so far: %d\n", input_values[max_index].value);
}

