    memset(&serv_addr, 0, sizeof(serv_addr)); // Zero-initialize the structure
    serv_addr.sin_family = AF_INET; // IPv4 address family
    inet_pton(AF_INET, "127.0.0.1", &serv_addr.sin_addr); // Server address
    serv_addr.sin_port = htons(8080); // Server port number

    // Create a socket and bind it to the specified address and port
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
