    sa.sa_handler = &signalHandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        exit(1);
    }

    // Start the data processing loop
    while (true) {
        char buffer[512]; // Buffer to hold the incoming data
        size_t len = recvfrom(SOCKET_FD, buffer, sizeof(buffer), 0, NULL, NULL);
        if (len < 0) {
