        if (sigprocmask(SIG_BLOCK, NULL, &sa.sa_mask) < 0 || sigpending(&sa.sa_mask) < 0) {
            perror("sigprocmask");
            continue;
        }
        if (sigismember(&sa.sa_mask, SIGINT) || sigismember(&sa.sa_mask, SIGTERM)) {
            break; // Catch the signal and break out of the loop
        }
    }

    // Flush the data to the remote monitoring service every second
    while (true) {
        flushData();
        sleep(1);
    }

    return 0;
}
