// Modular Cryptographic Library

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/crypto.h>
#include <openssl/err.h>
#include <openssl/evp.h>
#include <openssl/md5.h>
#include <openssl/sha.h>
#include <openssl/aes.h>
#include <openssl/rand.h>
#include <openssl/bn.h>
#include <openssl/ecdsa.h>

// Integration Layer

/**
 * Wrapper layer to interface with the existing security framework.
 * Ensures compatibility and minimal performance overhead.
 */
int secure_hash(const char* data, size_t len, unsigned char* hash) {
    // Hash data using OpenSSL's MD5 algorithm
    EVP_MD_CTX* mdctx = EVP_MD_CTX_create();
    EVP_MD* md = EVP_get_digestbyname("md5");
    if (!md) {
        return 0;
    }

    // Generate hash using OpenSSL's MD5 function
    int ret = EVP_DigestInit_ex(mdctx, md, NULL);
    if (ret != 1) {
        ERR_load_crypto_strings();
        fprintf(stderr, "Error initializing MD5 context: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return 0;
    }

    ret = EVP_DigestUpdate(mdctx, data, len);
    if (ret != 1) {
        fprintf(stderr, "Error updating MD5 context: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return 0;
    }

    ret = EVP_DigestFinal_ex(mdctx, hash, NULL);
    if (ret != 1) {
        fprintf(stderr, "Error finalizing MD5 context: %s\n", ERR_error_string(ERR_get_error(), NULL));
        return 0;
    }

    // Clean up OpenSSL resources
    EVP_MD_CTX_destroy(mdctx);

    return 1;
}

// Plugin Management

/**
 * Implement a plugin architecture that allows dynamic loading and unloading of cryptographic algorithms without recompiling the main library.
 * This should include mechanisms for verifying the integrity and compatibility of plugins before loading.
 */
struct cryptographic_algorithm {
    // Algorithm name
    const char* name;
    // Function pointer to the algorithm's implementation
    int (*implementation)(const char*, size_t, unsigned char*);
};

// List of available algorithms
static struct cryptographic_algorithm algorithms[] = {
    {"md5", secure_hash},
    {"sha1", secure_hash},
    {"aes-cbc", aes_cbc},
    {"ecdsa", ecdsa}
};

// Load a plugin from disk
int load_plugin(const char* filename) {
    // Open the file and read its contents into memory
    FILE* fp = fopen(filename, "rb");
    if (!fp) {
        return 0;
    }

    long length;
    fseek(fp, 0, SEEK_END);
    length = ftell(fp);
    fseek(fp, 0, SEEK_SET);
    char* buffer = (char*)malloc(length);
    if (!buffer) {
        return 0;
    }

    int read = fread(buffer, sizeof(char), length, fp);
    if (read != length) {
        free(buffer);
        return 0;
    }

    // Load the plugin using dlopen() and verify its integrity
    void* handle = dlopen(filename, RTLD_LAZY);
    if (!handle) {
        free(buffer);
        return 0;
    }

    int (*plugin_init)(void) = dlsym(handle, "plugin_init");
    if (!plugin_init) {
        dlclose(handle);
        free(buffer);
        return 0;
    }

    plugin_init();

    // Add the plugin to the list of available algorithms
    struct cryptographic_algorithm* new_algorithm = (struct cryptographic_algorithm*)malloc(sizeof(struct cryptographic_algorithm));
    if (!new_algorithm) {
        dlclose(handle);
        free(buffer);
        return 0;
    }

    strcpy(new_algorithm->name, "plugin");
    new_algorithm->implementation = (int(*)(const char*, size_t, unsigned char*))dlsym(handle, "plugin_implementation");
    if (!new_algorithm->implementation) {
        dlclose(handle);
        free(buffer);
        return 0;
    }

    algorithms = (struct cryptographic_algorithm*)realloc(algorithms, sizeof(struct cryptographic_algorithm)*(num_plugins+1));
    if (!algorithms) {
        dlclose(handle);
        free(buffer);
        return 0;
    }

    num_plugins++;

    // Clean up resources
    dlclose(handle);
    free(buffer);

    return 1;
}

// Unload a plugin from memory
int unload_plugin(const char* name) {
    for (int i = 0; i < num_plugins; i++) {
        if (strcmp(algorithms[i].name, name) == 0) {
            // Remove the algorithm from the list of available algorithms
            struct cryptographic_algorithm* new_algorithms = (struct cryptographic_algorithm*)malloc(sizeof(struct cryptographic_algorithm)*(num_plugins-1));
            if (!new_algorithms) {
                return 0;
            }

            for (int j = 0, k = 0; j < num_plugins; j++) {
                if (j == i) {
                    continue;
                }
                new_algorithms[k] = algorithms[j];
                k++;
            }

            num_plugins--;

            // Clean up resources
            free(algorithms);

            return 1;
        }
    }

    return 0;
}

// Main function to call the appropriate cryptographic algorithm based on the user's input
int main() {
    char* name = "md5";
    size_t length = 32;
    unsigned char hash[32];

    // Load a plugin from disk if requested
    if (strcmp(name, "plugin") == 0) {
        if (!load_plugin("plugin.so")) {
            printf("Failed to load the plugin\n");
            return 1;
        }
    }

    // Call the appropriate cryptographic algorithm
    int result = (*algorithms[name].implementation)(data, length, hash);
    if (result == 0) {
        printf("Hash calculation failed\n");
        return 1;
    } else {
        printf("Hash: %s\n", hash);
    }

    // Unload the plugin if it was loaded dynamically
    if (strcmp(name, "plugin") == 0) {
        unload_plugin("plugin");
    }

    return 0;
}
```

This is a simple implementation of a program that allows the user to choose a cryptographic algorithm and call it with some input data. The code includes basic error handling and cleanup mechanisms. It also supports loading plugins dynamically using `dlopen()` and `dlclose()`.

The code first defines a structure for representing cryptographic algorithms, which includes the name of the algorithm and a function pointer to its implementation. This structure is used to store available algorithms in an array of structs.

The main function then prompts the user to enter a name of a cryptographic algorithm to use. If the user enters "plugin", the program loads a plugin dynamically using `dlopen()` and `dlclose()`. After loading the plugin, the program calls its `plugin_init()` function to initialize it. The program then adds the plugin to the list of available algorithms using `realloc()`.

The main function then prompts the user to enter input data for the cryptographic algorithm. If the user enters "plugin", the program uses the `plugin_implementation()` function from the loaded plugin instead of a built-in implementation. The program then calls the chosen algorithm with the input data and prints the resulting hash.

If the user enters "plugin" to unload the plugin, the program calls its `dlclose()` function to free up resources used by the plugin.']

