import json
from flask import Flask, request, Response
from redis import Redis
from datetime import datetime

app = Flask(__name__)
redis_client = Redis()

@app.route('/profiles', methods=['GET'])
def get_profiles():
    profiles = []
    for profile in redis_client.smembers("profiles"):
        profile = json.loads(profile)
        profiles.append({"id": profile["id"], "name": profile["name"]})
    return Response(json.dumps(profiles), mimetype="application/json")

@app.route('/profiles', methods=['POST'])
def create_profile():
    data = request.get_json()
    profile_id = redis_client.incr("next_profile_id")
    redis_client.hset("profiles", profile_id, json.dumps(data))
    return Response(f"Created profile {profile_id}", 201)

@app.route('/profiles/<int:profile_id>', methods=['GET'])
def get_profile(profile_id):
    profile = redis_client.hget("profiles", profile_id)
    if not profile:
        return Response(f"Profile {profile_id} not found", 404)
    return Response(json.dumps(json.loads(profile)), mimetype="application/json")

@app.route('/profiles/<int:profile_id>', methods=['PUT'])
def update_profile(profile_id):
    data = request.get_json()
    redis_client.hset("profiles", profile_id, json.dumps(data))
    return Response(f"Updated profile {profile_id}", 200)

@app.route('/profiles/<int:profile_id>', methods=['DELETE'])
def delete_profile(profile_id):
    redis_client.hdel("profiles", profile_id)
    return Response(f"Deleted profile {profile_id}", 200)

@app.route('/notifications', methods=['POST'])
def send_notification():
    data = request.get_json()
    redis_client.publish("notifications", json.dumps(data))
    return Response(f"Sent notification {data['id']}", 201)

@app.route('/notifications', methods=['GET'])
def get_notifications():
    notifications = []
    for notification in redis_client.smembers("notifications"):
        notification = json.loads(notification)
        notifications.append({"id": notification["id"], "message": notification["message"]})
    return Response(json.dumps(notifications), mimetype="application/json")

@app.route('/notifications/<int:notification_id>', methods=['GET'])
def get_notification(notification_id):
    notification = redis_client.hget("notifications", notification_id)
    if not notification:
        return Response(f"Notification {notification_id} not found", 404)
    return Response(json.dumps(json.loads(notification)), mimetype="application/json")

@app.route('/notifications/<int:notification_id>', methods=['DELETE'])
def delete_notification(notification_id):
    redis_client.hdel("notifications", notification_id)
    return Response(f"Deleted notification {notification_id}", 200)

@app.route('/activity', methods=['GET'])
def get_activity():
    activity = []
    for profile in redis_client.smembers("profiles"):
        profile = json.loads(profile)
        activity.append({"id": profile["id"], "name": profile["name"]})
        for action in redis_client.smembers(f"actions-{profile['id']}"):
            action = json.loads(action)
            activity.append({"type": action["type"], "time": action["time"]})
    return Response(json.dumps(activity), mimetype="application/json")

@app.route('/social-graph', methods=['GET'])
def get_social_graph():
    social_graph = []
    for profile in redis_client.smembers("profiles"):
        profile = json.loads(profile)
        social_graph.append({"id": profile["id"], "name": profile["name"]})
        for connection in redis_client.smembers(f"connections-{profile['id']}"):
            connection = json.loads(connection)
            social_graph.append({"type": connection["type"], "time": connection["time"]})
    return Response(json.dumps(social_graph), mimetype="application/json")
