                // Parse the XML file using XPath
                XDocument doc = XDocument.Parse(xmlFile);

                // Validate the document against the schema
                bool isValid = ValidateAgainstSchema(doc, schema);

                if (isValid)
                {
                    _documentCache[xmlFile] = doc;
                }

                return isValid;
            }
            catch (Exception ex)
            {
                // Log the error and return false
                Console.WriteLine($"Error parsing XML file: {ex}");
                return false;
            }
