// Octree Data Structure
struct OctreeNode {
    int leaf; // Whether this node is a leaf or not
    int size; // Size of the feature represented by this node
    int x, y, z; // Coordinates of this node in 3D space
    OctreeNode* children[8]; // Array of child nodes
};

// Octree Class
class Octree {
private:
    OctreeNode* root; // Root node of the octree
    int leafSize; // Size of a leaf node
    int numLeaves; // Number of leaves in the octree
    int featureSize; // Size of the features represented by the octree
    double xMin, yMin, zMin; // Minimum coordinates of the octree
    double xMax, yMax, zMax; // Maximum coordinates of the octree

public:
    Octree(int leafSize, int featureSize, double xMin, double yMin, double zMin, double xMax, double yMax, double zMax);
    ~Octree();

    void insert(int x, int y, int z, int size); // Insert a new entity into the octree
    void retrieve(int x, int y, int z, int size); // Retrieve entities within a certain distance from a point
};

// Constructor
Octree::Octree(int leafSize, int featureSize, double xMin, double yMin, double zMin, double xMax, double yMax, double zMax) {
    this->leafSize = leafSize;
    this->featureSize = featureSize;
    this->xMin = xMin;
    this->yMin = yMin;
    this->zMin = zMin;
    this->xMax = xMax;
    this->yMax = yMax;
    this->zMax = zMax;

    // Initialize root node and child nodes
    root = new OctreeNode();
    root->leaf = true;
    root->size = featureSize;
    root->x = (xMin + xMax) / 2;
    root->y = (yMin + yMax) / 2;
    root->z = (zMin + zMax) / 2;
    for (int i = 0; i < 8; i++) {
        OctreeNode* child = new OctreeNode();
        child->leaf = false;
        child->x = root->x;
        child->y = root->y;
        child->z = root->z;
        root->children[i] = child;
    }
}

// Destructor
Octree::~Octree() {
    // Free memory allocated for the octree nodes
    delete root;
}

// Insert a new entity into the octree
void Octree::insert(int x, int y, int z, int size) {
    // Check if the point is within the bounds of the octree
    if (x < xMin || x >= xMax || y < yMin || y >= yMax || z < zMin || z >= zMax) {
        return;
    }

    // Find the appropriate child node for the entity
    OctreeNode* current = root;
    while (!current->leaf) {
        int index = (x - current->x) / featureSize + 4 * ((y - current->y) / featureSize + 2 * ((z - current->z) / featureSize));
        if (index < 0 || index >= 8) {
            return; // Entity is outside the bounds of this node, so do not insert it here
        }
        current = current->children[index];
    }

    // Insert the entity into the leaf node
    current->leaf = false;
    int numEntities = 0;
    while (numEntities < current->size && !current->leaf) {
        numEntities += 8;
        OctreeNode* newChild = new OctreeNode();
        newChild->leaf = true;
        newChild->x = x;
        newChild->y = y;
        newChild->z = z;
        current->children[numEntities] = newChild;
    }
}

// Retrieve entities within a certain distance from a point
void Octree::retrieve(int x, int y, int z, int size) {
    // Check if the point is within the bounds of the octree
    if (x < xMin || x >= xMax || y < yMin || y >= yMax || z < zMin || z >= zMax) {
        return;
    }

    // Find the appropriate child node for the entity
    OctreeNode* current = root;
    while (!current->leaf) {
        int index = (x - current->x) / featureSize + 4 * ((y - current->y) / featureSize + 2 * ((z - current->z) / featureSize));
        if (index < 0 || index >= 8) {
            return; // Entity is outside the bounds of this node, so do not retrieve it here
        }
        current = current->children[index];
    }

    // Retrieve entities from the leaf node and its children
    std::vector<int> retrievedEntities;
    retrieveEntities(current, x, y, z, size, retrievedEntities);
}

// Recursive function to retrieve entities from a node and its children
void retrieveEntities(OctreeNode* current, int x, int y, int z, int size, std::vector<int>& retrievedEntities) {
    // If the current node is a leaf, check if it intersects with the query sphere
    if (current->leaf) {
        double distance = sqrt((x - current->x) * (x - current->x) + (y - current->y) * (y - current->y) + (z - current->z) * (z - current->z));
        if (distance <= size) {
            retrievedEntities.push_back(current->x);
            retrievedEntities.push_back(current->y);
            retrievedEntities.push_back(current->z);
        }
    } else {
        // If the current node is not a leaf, check if it intersects with the query sphere and recurse on its children
        double distance = sqrt((x - current->x) * (x - current->x) + (y - current->y) * (y - current->y) + (z - current->z) * (z - current->z));
        if (distance <= size) {
            for (int i = 0; i < 8; i++) {
                retrieveEntities(current->children[i], x, y, z, size, retrievedEntities);
            }
        }
    }
}']

