import pandas as pd

# Define the API endpoints for fetching metadata
CLOUD_SERVICE_ENDPOINTS = {
    "Amazon Web Services": "https://api.aws.amazon.com/some-endpoint",
    "Microsoft Azure": "https://api.azure.microsoft.com/some-other-endpoint",
    "Google Cloud Platform": "https://cloud.google.com/some-third-endpoint"
}

# Define the filter categories for cloud services
FILTER_CATEGORIES = {
    "Compute": ["Amazon Web Services", "Microsoft Azure"],
    "Storage": ["Google Cloud Platform"],
    "Security and Identity": ["Amazon Web Services"]
}

class TextProcessor:
    def __init__(self, text: str):
        self.text = text

    def process_text(self) -> List[Dict]:
        """Tokenize the input text into individual words, filter out stopwords, and return a list of unique words with their counts."""
        # Tokenize the input text into individual words
        tokens = self.text.split()

        # Filter out stopwords and punctuation
        filtered_tokens = [token for token in tokens if not token.isalpha() or not token.isnumeric() or len(token) > 2]

        # Count the frequency of each word
        word_counts = {word: filtered_tokens.count(word) for word in set(filtered_tokens)}

        return word_counts

class CloudServiceAnalyzer:
    def __init__(self, text: str):
        self.text = text

    def analyze_cloud_services(self) -> List[Dict]:
        """Analyze the input text for mentions of cloud computing services and return a list of unique cloud service names with their frequencies."""
        # Tokenize the input text into individual words
        tokens = self.text.split()

        # Filter out stopwords and punctuation
        filtered_tokens = [token for token in tokens if not token.isalpha() or not token.isnumeric() or len(token) > 2]

        # Initialize an empty list to store the unique cloud service names with their frequencies
        cloud_service_names = []

        # Iterate over each word and check if it is a cloud service name
        for word in filtered_tokens:
            if word.lower() in CLOUD_SERVICE_ENDPOINTS:
                # Add the cloud service name to the list with its frequency
                cloud_service_names.append({"name": word, "frequency": filtered_tokens.count(word)})

        return cloud_service_names

class MetadataFetcher:
    def __init__(self, cloud_services: List[Dict]):
        self.cloud_services = cloud_services

    def fetch_metadata(self) -> Dict:
        """Fetch metadata for each cloud service and return a dictionary of metadata with the cloud service names as keys."""
        # Initialize an empty dictionary to store the metadata
        metadata = {}

        # Iterate over each cloud service name and fetch its metadata
        for cloud_service in self.cloud_services:
            # Fetch the metadata for the current cloud service using the API endpoint
            response = requests.get(CLOUD_SERVICE_ENDPOINTS[cloud_service["name"]])

            # Check if the request was successful and extract the metadata from the response
            if response.ok:
                metadata[cloud_service["name"]] = json.loads(response.text)

        return metadata

class FilteredCloudServiceAnalyzer:
    def __init__(self, cloud_services: List[Dict], filter_categories: Dict):
        self.cloud_services = cloud_services
        self.filter_categories = filter_categories

    def analyze_filtered_cloud_services(self) -> List[Dict]:
        """Analyze the input text for mentions of cloud computing services and return a list of unique cloud service names with their frequencies, filtered by the specified categories."""
        # Filter the cloud service names based on the specified filter categories
        filtered_cloud_service_names = [cloud_service["name"] for cloud_service in self.cloud_services if cloud_service["name"] in FILTER_CATEGORIES[self.filter_categories]]

        # Initialize an empty list to store the unique cloud service names with their frequencies
        filtered_cloud_service_names_and_frequencies = []

        # Iterate over each filtered cloud service name and count its frequency in the input text
        for cloud_service_name in filtered_cloud_service_names:
            # Count the frequency of the current cloud service name in the input text
            frequency = self.text.count(cloud_service_name)

            # Add the current cloud service name and its frequency to the list
            filtered_cloud_service_names_and_frequencies.append({"name": cloud_service_name, "frequency": frequency})

        return filtered_cloud_service_names_and_frequencies

class TextAnalyzer:
    def __init__(self, text: str):
        self.text = text

    def analyze_text(self) -> Dict:
        """Analyze the input text for mentions of cloud computing services and return a structured report that includes a list of all unique technical terms, their frequency, and contextual usage."""
        # Tokenize the input text into individual words
        tokens = self.text.split()

        # Filter out stopwords and punctuation
        filtered_tokens = [token for token in tokens if not token.isalpha() or not token.isnumeric() or len(token) > 2]

        # Initialize an empty dictionary to store the unique technical terms with their frequencies
        technical_terms = {}

        # Iterate over each word and count its frequency
        for word in filtered_tokens:
            # Add the current word to the list of unique technical terms if it is not already present
            if word not in technical_terms:
                technical_terms[word] = 0

            # Increment the frequency of the current word
            technical_terms[word] += 1

        # Initialize an empty list to store the unique cloud service names with their frequencies
        cloud_service_names_and_frequencies = []

        # Analyze the input text for mentions of cloud computing services and add them to the list
        cloud_services = CloudServiceAnalyzer(self.text).analyze_cloud_services()
        for cloud_service in cloud_services:
            cloud_service_names_and_frequencies.append({"name": cloud_service["name"], "frequency": cloud_service["frequency"]})

        # Initialize an empty dictionary to store the metadata for each cloud service
        metadata = {}

        # Fetch the metadata for each cloud service and add it to the dictionary
        fetched_metadata = MetadataFetcher(cloud_services).fetch_metadata()
        for cloud_service in self.cloud_services:
            metadata[cloud_service["name"]] = fetched_metadata[cloud_service["name"]]

        # Initialize an empty list to store the filtered cloud service names with their frequencies
        filtered_cloud_service_names_and_frequencies = []

        # Analyze the input text for mentions of cloud computing services and add them to the list, filtered by the specified categories
        filtered_cloud_services = FilteredCloudServiceAnalyzer(cloud_services, self.filter_categories).analyze_filtered_cloud_services()
        for cloud_service in filtered_cloud_services:
            filtered_cloud_service_names_and_frequencies.append({"name": cloud_service["name"], "frequency": cloud_service["frequency"]})

        # Initialize an empty dictionary to store the structured report
        structured_report = {
            "text": self.text,
            "technical_terms": technical_terms,
            "cloud_service_names_and_frequencies": cloud_service_names_and_frequencies,
            "metadata": metadata,
            "filtered_cloud_service_names_and_frequencies": filtered_cloud_service_names_and_frequencies
        }

        return structured_report
```

