async function loadResourceBundle() {
  const headers = new Headers();
  headers.append('Accept', 'application/json');

  const requestOptions = {
    method: 'GET',
    headers: headers,
    timeout: 10000, // 10 seconds
    retry: true,
    retryAttempts: 3,
  };

  try {
    const response = await fetch('https://example.com/resource_bundle', requestOptions);
    if (!response.ok) {
      throw new Error(`Failed to load resource bundle. Status code: ${response.status}`);
    }

    const json = await response.json();
    return json.length;
  } catch (error) {
    console.error(error);
    return null;
  }
}
