use std::net::{TcpStream, ToSocketAddrs};
use std::io;
use std::sync::Arc;
use std::thread;
use std::time::Duration;
use reqwest::blocking::Client as HttpClient;
use log::info;

struct AsyncHttpClient {
    client: HttpClient,
    urls: Vec<String>,
}

impl AsyncHttpClient {
    pub fn new(urls: &[&str]) -> Self {
        let mut url_vec = Vec::new();
        for url in urls {
            url_vec.push(url.to_string());
        }
        AsyncHttpClient {
            client: HttpClient::builder().build(),
            urls: url_vec,
        }
    }

    pub fn fetch(&self, url: &str) -> Result<String, reqwest::Error> {
        let url = format!("{}", url);
        self.client
            .get(url.as_str())
            .send()?
            .text()
            .map_err(|e| e.into())
    }
}

fn main() -> Result<(), io::Error> {
    let mut client = AsyncHttpClient::new(&["https://example.com", "https://example2.com"]);
    let url = "https://example3.com";
    let resp = client.fetch(url)?;
    info!("Response: {}", resp);
    Ok(())
}
```
