C Code:
```c
#include <stdlib.h>
#include <stdio.h>
#include <semaphore.h>

// Function to create a semaphore for a given clinic ID
int createSemaphore(int clinic_id) {
    // Create the semaphore with an initial value of 1
    sem_t *sem = sem_open("/sem", O_CREAT, 0644, 1);
    if (sem == SEM_FAILED) {
        perror("Error creating semaphore");
        return -1;
    }

    // Set the clinic ID as the name of the semaphore
    char *name = malloc(sizeof(clinic_id));
    sprintf(name, "%d", clinic_id);
    sem_unlink(name);
    sem_close(sem);
    free(name);

    return 0;
}

// Function to delete a semaphore for a given clinic ID
int deleteSemaphore(int clinic_id) {
    // Open the semaphore with the same name as the clinic ID
    sem_t *sem = sem_open("/sem", O_RDWR);
    if (sem == SEM_FAILED) {
        perror("Error opening semaphore");
        return -1;
    }

    // Remove the clinic ID from the semaphore's name
    char *name = malloc(sizeof(clinic_id));
    sprintf(name, "%d", clinic_id);
    sem_unlink(name);
    sem_close(sem);
    free(name);

    return 0;
}

// Function to acquire a semaphore for a given clinic ID
int acquireSemaphore(int clinic_id) {
    // Open the semaphore with the same name as the clinic ID
    sem_t *sem = sem_open("/sem", O_RDWR);
    if (sem == SEM_FAILED) {
        perror("Error opening semaphore");
        return -1;
    }

    // Acquire a lock on the semaphore
    int ret = sem_wait(sem);
    if (ret < 0) {
        perror("Error acquiring semaphore");
        return -1;
    }

    return 0;
}

// Function to release a semaphore for a given clinic ID
int releaseSemaphore(int clinic_id) {
    // Open the semaphore with the same name as the clinic ID
    sem_t *sem = sem_open("/sem", O_RDWR);
    if (sem == SEM_FAILED) {
        perror("Error opening semaphore");
        return -1;
    }

    // Release the lock on the semaphore
    int ret = sem_post(sem);
    if (ret < 0) {
        perror("Error releasing semaphore");
        return -1;
    }

    return 0;
}
