package main;

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"log"
	"net/http"
)

const certificateAuthorityAPI = "https://certificate-authority.com/api/v1"
const certificateLifetime = 60 * 60 * 24 // 24 hours in seconds
const cacheDirectory = "/var/run/certificate-service/cache/"

// PrivateKey represents the private key used for OAuth authentication
type PrivateKey struct {
	Value string `json:"value"`
}

// Certificate represents the certificate issued by the certificate authority
type Certificate struct {
	Value string `json:"value"`
	Expiry int64  `json:"expiry"`
}

// CombinedPEM represents a combined PEM file containing both the private key and certificate
type CombinedPEM struct {
	PrivateKey PrivateKey
	Certificate Certificate
}

func main() {
	http.HandleFunc("/generate-combined-pem", generateCombinedPEM)
	log.Fatal(http.ListenAndServe(":8080", nil))
}

// generateCombinedPEM is an HTTP handler function that generates a combined PEM file containing both the private key and certificate for OAuth authentication
func generateCombinedPEM(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "text/plain")

	// Parse the request body as JSON
	var reqBody map[string]interface{}
	err := json.NewDecoder(r.Body).Decode(&reqBody)
	if err != nil {
		http.Error(w, fmt.Sprintf("failed to parse request body: %v", err), http.StatusBadRequest)
		return
	}

	// Fetch the private key and certificate from the certificate authority API
	privateKey := &PrivateKey{}
	certificate := &Certificate{}
	err = fetchCredentials(reqBody["username"].(string), reqBody["password"].(string), privateKey, certificate)
	if err != nil {
		http.Error(w, fmt.Sprintf("failed to fetch credentials: %v", err), http.StatusInternalServerError)
		return
	}

	// Generate the combined PEM file
	combinedPEM := &CombinedPEM{
		PrivateKey: *privateKey,
		Certificate: *certificate,
	}
	pemFile, err := generatePEM(combinedPEM)
	if err != nil {
		http.Error(w, fmt.Sprintf("failed to generate PEM file: %v", err), http.StatusInternalServerError)
		return
	}

	// Write the combined PEM file to the response body
	_, err = w.Write(pemFile)
	if err != nil {
		http.Error(w, fmt.Sprintf("failed to write response body: %v", err), http.StatusInternalServerError)
	}
}

// fetchCredentials is a function that fetches the private key and certificate from the certificate authority API
func fetchCredentials(username string, password string, privateKey *PrivateKey, certificate *Certificate) error {
	// Fetch the private key from the certificate authority API
	req, err := http.NewRequest("GET", fmt.Sprintf("%s/private-key/%s", certificateAuthorityAPI, username), nil)
	if err != nil {
		return fmt.Errorf("failed to create request: %v", err)
	}
	req.SetBasicAuth(username, password)
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return fmt.Errorf("failed to fetch private key: %v", err)
	}
	defer resp.Body.Close()

	// Parse the response body as JSON
	var respBody map[string]interface{}
	err = json.NewDecoder(resp.Body).Decode(&respBody)
	if err != nil {
		return fmt.Errorf("failed to parse response body: %v", err)
	}

	// Validate the private key
	privateKeyValue, ok := respBody["private_key"].(string)
	if !ok || len(privateKeyValue) == 0 {
		return fmt.Errorf("invalid private key")
	}

	// Set the private key in the response
	privateKey.Value = privateKeyValue

	// Fetch the certificate from the certificate authority API
	req, err = http.NewRequest("GET", fmt.Sprintf("%s/certificate/%s", certificateAuthorityAPI, username), nil)
	if err != nil {
		return fmt.Errorf("failed to create request: %v", err)
	}
	resp, err = http.DefaultClient.Do(req)
	if err != nil {
		return fmt.Errorf("failed to fetch certificate: %v", err)
	}
	defer resp.Body.Close()

	// Parse the response body as JSON
	var respBody map[string]interface{}
	err = json.NewDecoder(resp.Body).Decode(&respBody)
	if err != nil {
		return fmt.Errorf("failed to parse response body: %v", err)
	}

	// Validate the certificate
	certificateValue, ok := respBody["certificate"].(string)
	if !ok || len(certificateValue) == 0 {
		return fmt.Errorf("invalid certificate")
	}

	// Set the certificate in the response
	certificate.Value = certificateValue

	// Calculate the expiry of the certificate
	expiry := time.Now().Add(time.Duration(certificateLifetime) * time.Second).Unix()
	certificate.Expiry = expiry

	return nil
}

// generatePEM is a function that generates a combined PEM file containing both the private key and certificate
func generatePEM(combinedPEM *CombinedPEM) ([]byte, error) {
	// Generate the private key PEM
	privateKeyPem := []byte{}
	if len(combinedPEM.PrivateKey.Value) > 0 {
		privateKeyPem = append(privateKeyPem, fmt.Sprintf("-----BEGIN PRIVATE KEY-----\n%s\n-----END PRIVATE KEY-----\n", combinedPEM.PrivateKey.Value)...)
	}

	// Generate the certificate PEM
	certificatePem := []byte{}
	if len(combinedPEM.Certificate.Value) > 0 {
		certificatePem = append(certificatePem, fmt.Sprintf("-----BEGIN CERTIFICATE-----\n%s\n-----END CERTIFICATE-----\n", combinedPEM.Certificate.Value)...)
	}

	// Generate the combined PEM file
	pem := []byte{}
	pem = append(pem, privateKeyPem...)
	pem = append(pem, certificatePem...)

	return pem, nil
}']

