                'https://external-auth.example/api/update_password',
                ['json' => [
                    'email' => $request->input('email'),
                    'newPassword' => $request->input('password')
                ]]
            );

            if ($response->getStatusCode() !== 200) {
                throw new \Exception("Error updating password: {$response->getBody()}");
