    state_list* head = create_state_list(states, num_states, fsa, 0);
    assert(head != NULL);
    assert(head->state == 0);
    assert(head->next != NULL);
    free(head);
    free(fsa);
}

void test_update_state_list() {
    // Test with a null pointer for the head node
    update_state_list(NULL, -1);

    // Test with an invalid input for the new state
    int* states = malloc(sizeof(int));
    assert(create_state_list(states, 0, NULL, -1) == NULL);

    // Test with a valid input and ensure that the head node is properly updated
    fsa* fsa = malloc(sizeof(fsa));
    state_list* head = create_state_list(states, 0, fsa, -1);
    update_state_list(head, 1);
    assert(head->state == 1);
    free(head);
    free(fsa);
}

void test_delete_state_list() {
    // Test with a null pointer for the head node
    delete_state_list(NULL);

    // Test with a valid input and ensure that all nodes are properly freed
    int* states = malloc(sizeof(int));
    assert(create_state_list(states, 0, NULL, -1) == NULL);

    fsa* fsa = malloc(sizeof(fsa));
    state_list* head = create_state_list(states, 0, fsa, -1);
    delete_state_list(head);
    assert(head == NULL);
    free(fsa);
}

void test_get_state_from_list() {
    // Test with a null pointer for the head node
    int index = get_state_from_list(NULL, 0);
    assert(index == -1);

    // Test with an invalid input for the index
    int* states = malloc(sizeof(int));
    assert(create_state_list(states, 0, NULL, -1) == NULL);

    fsa* fsa = malloc(sizeof(fsa));
    state_list* head = create_state_list(states, 0, fsa, -1);
    index = get_state_from_list(head, -1);
    assert(index == -1);

    // Test with a valid input and ensure that the correct state is returned
    for (int i = 0; i < 5; i++) {
        states[i] = i;
    }
    head = create_state_list(states, 5, fsa, 0);
    index = get_state_from_list(head, 2);
    assert(index == 2);
    free(head);
    free(fsa);
}
