    private static final int THREAD_COUNT = 8;
    private static final long TIMEOUT = 3000L; // milliseconds
    private static final Predicate<FinancialTransaction> FILTER = transaction -> {
        Instant now = Instant.now();
        return (transaction.getAge() < 180) && (transaction.getFrequency() > 3) && (transaction.getWeightedSum() >= 50);
    };

    private ConcurrentLinkedQueue<FinancialTransaction> transactions = new ConcurrentLinkedQueue<>();
    private ThreadPoolExecutor executor = Executors.newFixedThreadPool(THREAD_COUNT);

    public FinancialTransactionService() {
        // initialize the service with a rolling window of 10 minutes (600 seconds)
        for (int i = 0; i < 10; i++) {
            transactions.add(new FinancialTransaction());
        }
    }

    public void processTransaction(FinancialTransaction transaction) throws InterruptedException {
        if (!FILTER.test(transaction)) {
            // reject transaction based on filtering criteria
            return;
        }

        executor.execute(() -> {
            try {
                // process the transaction in a separate thread
                processTransactionInternal(transaction);
            } catch (Exception e) {
                System.out.println("Error processing transaction: " + e.getMessage());
            }
        });
    }

    private void processTransactionInternal(FinancialTransaction transaction) {
        // update the rolling window of transactions for frequency check
        transactions.add(transaction);
        if (transactions.size() > 10) {
            transactions.remove();
        }

        // apply weighted sum threshold
        int totalWeight = transactions.stream().mapToInt(FinancialTransaction::getWeight).sum();
        if (totalWeight < 50) {
            // reject transaction based on weighted sum threshold
            return;
        }

        // process the transaction
        System.out.println("Processing transaction: " + transaction);
    }
}

