        private static readonly Dictionary<Type, List<Func<float>>> ProbabilityDistributions = new Dictionary<Type, List<Func<float>>>()
        {
            [typeof(int)] = new List<Func<float>>() { () => 0.5f },
            [typeof(float)] = new List<Func<float>>() { () => 0.5f },
            [typeof(Vector2)] = new List<Func<float>>() { () => 1.0f, () => 0.5f },
