            [typeof(float)] = new List<WeightedRandomSelection>() { new WeightedRandomSelection("Option 1", 0.5f), new WeightedRandomSelection("Option 2", 0.5f) },
            [typeof(Vector2)] = new List<WeightedRandomSelection>() { new WeightedRandomSelection("Option 1", 0.5f, Vector2.zero), new WeightedRandomSelection("Option 2", 0.5f, Vector2.one) },
            [typeof(Quaternion)] = new List<WeightedRandomSelection>() { new WeightedRandomSelection("Option 1", 0.5f, Quaternion.identity), new WeightedRandomSelection("Option 2", 0.5f, Quaternion.Euler(90, 0, 0)) },
            [typeof(Matrix4x4)] = new List<WeightedRandomSelection>() { new WeightedRandomSelection("Option 1", 0.5f, Matrix4x4.identity), new WeightedRandomSelection("Option 2", 0.5f, Matrix4x4.CreateRotationZ(90)) }
        };

        // Define a list of supported external data sources for bound parameters and probability distributions
        private static readonly List<ExternalDataSource> SupportedDataSources = new List<ExternalDataSource>()
        {
            new DatabaseDataSource(),
            new FileDataSource()
        };

        // Define a list of logging levels for debugging and monitoring purposes
        private static readonly List<LoggingLevel> LoggingLevels = new List<LoggingLevel>()
        {
            LoggingLevel.Debug,
            LoggingLevel.Info,
            LoggingLevel.Warn,
            LoggingLevel.Error
        };

        // Define a function for generating random values within specified ranges, both inclusively and exclusively
        public static object GetRandomValue(Type type)
        {
            // Validate the input type
            if (!SupportedTypes.Contains(type))
                throw new ArgumentException("Invalid type", nameof(type));

            // Retrieve the bound parameters for the specified type
            var boundParameters = BoundParameters[type];

            // Generate a random value within the specified range
            var randomValue = Random.Range(boundParameters[0], boundParameters[1]);

            // If the type has conditional probability distributions, apply them
            if (ProbabilityDistributions.ContainsKey(type))
            {
                var probabilityDistribution = ProbabilityDistributions[type];
                randomValue = probabilityDistribution.Aggregate((accumulator, next) => accumulator + next());
            }

            // If the type has weighted random selections, apply them
            if (WeightedSelections.ContainsKey(type))
            {
                var weightedSelection = WeightedSelections[type];
                randomValue = weightedSelection.Random();
            }

            return randomValue;
        }

