using namespace std;

// Struct to represent a resource bundle
struct ResourceBundle {
  string name;
  vector<string> files;
  map<string, string> metadata;
};

// Function to load the resource bundle from disk asynchronously
void loadResourceBundle(const string& filepath, function<void(const ResourceBundle&)> callback) {
  // Create a new thread to handle the resource bundle loading
  thread t([filepath, callback]() {
    // Open the file and read its contents
    ifstream in_file(filepath);
    string contents((istreambuf_iterator<char>(in_file)), istreambuf_iterator<char>());

    // Parse the contents of the file to extract the metadata and resource files
    map<string, string> metadata;
    vector<string> resources;
    size_t pos = 0;
    while (pos < contents.size()) {
      // Extract the next key-value pair from the metadata
      size_t end = contents.find("\n", pos);
      string key = contents.substr(pos, end - pos);
      pos = end + 1;

      // If the key is not empty, it must be a valid metadata entry
      if (!key.empty()) {
        // Extract the value of the key and add it to the metadata map
        size_t val_start = contents.find(" ", pos);
        string val = contents.substr(val_start + 1, end - val_start - 2);
        metadata[key] = val;
      } else {
        // If the key is empty, it must be a resource file path
        resources.push_back(contents.substr(pos, end - pos));
      }

      pos = end + 1;
    }

    // Create a new resource bundle struct and populate its fields
    ResourceBundle bundle;
    bundle.name = metadata["name"];
    bundle.metadata = metadata;
    for (const string& file : resources) {
      bundle.files.push_back(file);
    }

    // Notify the main thread that the resource bundle has been loaded
    callback(bundle);
  });
  t.detach();
}

