// Function to load and process resource bundles concurrently
void loadAndProcessResourceBundles(const vector<string>& filepaths, function<void(const string&)> callback) {
  // Create a new thread pool to handle the loading and processing of resource bundles
  thread_pool tp;

  // Loop through each filepath and schedule its corresponding task in the thread pool
  for (const string& filepath : filepaths) {
    tp.schedule([filepath, callback]() {
      loadResourceBundle(filepath, [callback](const ResourceBundle& bundle) {
        processResourceBundle(bundle, callback);
      });
    });
  }

  // Wait for all tasks to complete before exiting the function
