    if (!is_valid) {
        log_message(log_file, LOG_ERROR, "Failed to parse metadata from resource file");
        return PARSE_ERROR;
    }

    // Load the rest of the file
    while ((read_len = getline(&line, &line_len, fp)) != -1) {
        // Parse each line and add it to the bundle
        is_valid = parse_item(line, &bundle);
        if (!is_valid) {
            log_message(log_file, LOG_ERROR, "Failed to parse item from resource file");
            return PARSE_ERROR;
        }
    }

    // Close the file and free memory
    fclose(fp);
    free(line);

    // Validate the bundle with the external API service
    is_valid = validate_bundle(&bundle, settings);
    if (!is_valid) {
        log_message(log_file, LOG_ERROR, "Failed to validate resource bundle with external API service");
        return API_ERROR;
    }

    // Return the number of valid items in the bundle
    num_items = get_num_items(&bundle);
    free_bundle(&bundle);
    return num_items;
}

// Function to parse metadata from a resource file line
int parse_metadata(char *line, resource_bundle *bundle) {
    // Initialize variables
    int is_valid = 1;
    char *key = NULL;
    char *value = NULL;
    size_t pos = 0;

    // Skip leading whitespace and check for a key-value delimiter
    while (isspace(line[pos]) || line[pos] == '=') {
        pos++;
    }

    // Extract the key and value from the line
    key = strsep(&line, "=");
    value = strsep(&line, "\n");

    // Check that both key and value are non-empty
    if (key == NULL || value == NULL) {
        return 0;
    }

    // Parse the key and value based on the format
    if (!strcmp(bundle->format, "json")) {
        is_valid = parse_json_metadata(key, value, bundle);
    } else if (!strcmp(bundle->format, "csv")) {
        is_valid = parse_csv_metadata(key, value, bundle);
    }

    // Return the parsing result
    return is_valid;
}

// Function to parse metadata from a JSON resource file line
int parse_json_metadata(char *key, char *value, resource_bundle *bundle) {
    // Initialize variables
    int is_valid = 1;
    json_object *obj = NULL;
    json_object *tmp = NULL;

    // Create a new JSON object from the line
    obj = json_tokener_parse(value);
    if (obj == NULL) {
        return 0;
    }

    // Check that the key is present in the object
    tmp = json_object_object_get(obj, key);
    if (tmp == NULL) {
        return 0;
    }

    // Parse the value based on the type of the key
    if (!strcmp(key, "version")) {
        bundle->data = strdup(json_object_get_string(tmp));
    } else if (!strcmp(key, "num_items")) {
        bundle->num_items = json_object_get_int64(tmp);
    }

    // Return the parsing result
    return is_valid;
}

// Function to parse metadata from a CSV resource file line
int parse_csv_metadata(char *key, char *value, resource_bundle *bundle) {
    // Initialize variables
    int is_valid = 1;
    char **fields = NULL;
    size_t num_fields = 0;

    // Split the line into fields based on the delimiter
    fields = csv_strsplit(value, ',', &num_fields);
    if (fields == NULL) {
        return 0;
    }

    // Check that the key is present in the first field
    if (!strcmp(key, "version")) {
        bundle->data = strdup(fields[1]);
    } else if (!strcmp(key, "num_items")) {
        bundle->num_items = atoi(fields[2]);
    }

    // Free memory and return the parsing result
    free(fields);
    return is_valid;
}

// Function to parse an item from a resource file line
int parse_item(char *line, resource_bundle *bundle) {
    // Initialize variables
    int is_valid = 1;
    char **fields = NULL;
    size_t num_fields = 0;

    // Split the line into fields based on the delimiter
    fields = csv_strsplit(line, ',', &num_fields);
    if (fields == NULL) {
        return 0;
    }

    // Check that the number of fields is correct
    if (num_fields != bundle->num_fields) {
        return 0;
    }

    // Parse each field based on the type
    for (size_t i = 0; i < num_fields; i++) {
        char *field = fields[i];
        if (!strcmp(bundle->format, "json")) {
            is_valid = parse_json_item(field, bundle);
        } else if (!strcmp(bundle->format, "csv")) {
            is_valid = parse_csv_item(field, bundle);
        }
    }

    // Free memory and return the parsing result
    free(fields);
    return is_valid;
}

// Function to parse an item from a JSON resource file line
int parse_json_item(char *field, resource_bundle *bundle) {
    // Initialize variables
    int is_valid = 1;
    json_object *obj = NULL;
    json_object *tmp = NULL;

    // Create a new JSON object from the field
    obj = json_tokener_parse(field);
    if (obj == NULL) {
        return 0;
    }

    // Check that all required fields are present in the object
    for (size_t i = 0; i < bundle->num_required_fields; i++) {
        tmp = json_object_object_get(obj, bundle->required_fields[i]);
        if (tmp == NULL) {
            return 0;
        }
    }

    // Parse the fields based on their types
    for (size_t i = 0; i < bundle->num_fields; i++) {
        tmp = json_object_object_get(obj, bundle->fields[i]);
        if (tmp == NULL) {
            return 0;
        }
        switch (bundle->types[i]) {
            case TYPE_INT:
                bundle->data[i] = atoi(json_object_get_string(tmp));
                break;
            case TYPE_FLOAT:
                bundle->data[i] = strtof(json_object_get_string(tmp), NULL);
                break;
            case TYPE_STRING:
                bundle->data[i] = strdup(json_object_get_string(tmp));
                break;
        }
    }

    // Return the parsing result
    return is_valid;
}

// Function to parse an item from a CSV resource file line
int parse_csv_item(char *field, resource_bundle *bundle) {
    // Initialize variables
    int is_valid = 1;
    char **fields = NULL;
    size_t num_fields = 0;

    // Split the field into sub-fields based on the delimiter
    fields = csv_strsplit(field, ',', &num_fields);
    if (fields == NULL) {
        return 0;
    }

    // Check that the number of sub-fields is correct
    if (num_fields != bundle->num_required_fields) {
        return 0;
    }

    // Parse each sub-field based on its type
    for (size_t i = 0; i < num_fields; i++) {
        char *sub_field = fields[i];
        switch (bundle->types[i]) {
            case TYPE_INT:
                bundle->data[i] = atoi(sub_field);
                break;
            case TYPE_FLOAT:
                bundle->data[i] = strtof(sub_field, NULL);
                break;
            case TYPE_STRING:
                bundle->data[i] = strdup(sub_field);
                break;
        }
    }

    // Free memory and return the parsing result
    free(fields);
    return is_valid;
}

// Function to validate a resource bundle
int validate_resource_bundle(resource_bundle *rb) {
    // Check that all required fields are present in the data
    for (size_t i = 0; i < rb->num_required_fields; i++) {
        if (!strcmp(rb->data[i], "")) {
            return 0;
        }
    }

    // Check that all fields are of the correct type
    for (size_t i = 0; i < rb->num_fields; i++) {
        if (!strcmp(rb->types[i], "int")) {
            int x = atoi(rb->data[i]);
            if (x == 0) {
                return 0;
            }
        } else if (!strcmp(rb->types[i], "float")) {
            float x = strtof(rb->data[i], NULL);
            if (x == 0.0) {
                return 0;
            }
        } else if (!strcmp(rb->types[i], "string")) {
            char *s = rb->data[i];
            if (*s == '\0') {
                return 0;
            }
        }
    }

    // If all checks pass, return 1
    return 1;
}

// Function to parse a resource bundle from a file
int parse_resource_bundle(char *filename, resource_bundle **rb) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("Error opening file");
        return 1;
    }

    // Read the first line of the file to determine the format
    char *line = malloc(sizeof(char) * MAX_LINE_LENGTH);
    fgets(line, MAX_LINE_LENGTH, file);

    if (strcmp(line, "JSON") == 0) {
        // Create a new JSON resource bundle
        json_resource_bundle *json_rb = malloc(sizeof(json_resource_bundle));
        json_rb->data = NULL;

        // Read the rest of the file line by line and add each line to the data array
        while (fgets(line, MAX_LINE_LENGTH, file)) {
            int len = strlen(line);
            if (len > 0 && line[len - 1] == '\n') {
                line[len - 1] = '\0';
            }
            json_rb->data = realloc(json_rb->data, sizeof(char *) * (json_rb->num_lines + 1));
            json_rb->data[json_rb->num_lines] = strdup(line);
            json_rb->num_lines++;
        }

        // Validate the JSON resource bundle and create a generic resource bundle if it is valid
        if (validate_resource_bundle(json_rb)) {
            *rb = malloc(sizeof(resource_bundle));
            (*rb)->data = json_rb->data;
            (*rb)->num_fields = json_rb->num_lines;
            return 0;
        } else {
            fprintf(stderr, "Invalid JSON resource bundle\n");
            free(json_rb);
            return 1;
        }
    } else if (strcmp(line, "CSV") == 0) {
        // Create a new CSV resource bundle
        csv_resource_bundle *csv_rb = malloc(sizeof(csv_resource_bundle));
        csv_rb->data = NULL;

        // Read the rest of the file line by line and add each line to the data array
        while (fgets(line, MAX_LINE_LENGTH, file)) {
            int len = strlen(line);
            if (len > 0 && line[len - 1] == '\n') {
                line[len - 1] = '\0';
            }
            csv_rb->data = realloc(csv_rb->data, sizeof(char *) * (csv_rb->num_lines + 1));
            csv_rb->data[csv_rb->num_lines] = strdup(line);
            csv_rb->num_lines++;
        }

        // Validate the CSV resource bundle and create a generic resource bundle if it is valid
        if (validate_resource_bundle(csv_rb)) {
            *rb = malloc(sizeof(resource_bundle));
            (*rb)->data = csv_rb->data;
            (*rb)->num_fields = csv_rb->num_lines;
            return 0;
        } else {
            fprintf(stderr, "Invalid CSV resource bundle\n");
            free(csv_rb);
            return 1;
        }
    } else {
        fprintf(stderr, "Unknown file format\n");
        return 1;
    }
}
```

