// Function to request OAuth2 token from auth service
int request_oauth2_token(oauth2_token_t* token) {
    // Set up HTTP/2 connection
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("Socket creation failed");
        return -1;
    }

    struct sockaddr_in serv_addr;
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(80);

    if (inet_pton(AF_INET, token->endpoint, &serv_addr.sin_addr) <= 0) {
        perror("Invalid address");
        return -1;
    }

    // Connect to auth service
    if (connect(sock, (struct sockaddr*)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("Connection failed");
        return -1;
    }

    // Send OAuth2 token request
    char* request = "GET /oauth/token HTTP/1.1\r\nHost: localhost:8080\r\nContent-Type: application/x-www-form-urlencoded\r\n\r\n";
    if (send(sock, request, strlen(request), 0) < 0) {
        perror("Send failed");
        return -1;
    }

    // Receive OAuth2 token response
    char buffer[4096];
    int bytes_received = recv(sock, buffer, sizeof(buffer), 0);
    if (bytes_received < 0) {
        perror("Recv failed");
        return -1;
    }
    buffer[bytes_received] = '\0';

    // Parse OAuth2 token response
    char* token_start = strstr(buffer, "\"accessToken\": \"");
    if (!token_start) {
        printf("Failed to obtain access token\n");
        return -1;
    }
    token_start += 16; // length of "\"accessToken\": \""
    char* token_end = strstr(token_start, "\"}");
    if (!token_end) {
        printf("Failed to obtain access token\n");
        return -1;
    }
    *token_end = '\0';
    token->token = malloc(strlen(token_start) + 1);
    strcpy(token->token, token_start);

    // Close HTTP/2 connection
    close(sock);

    return 0;
}

// Function to validate OAuth2 access token
int validate_oauth2_token(oauth2_token_t* token) {
    // Set up HTTP/2 connection
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("Socket creation failed");
        return -1;
    }

    struct sockaddr_in serv_addr;
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(80);

    if (inet_pton(AF_INET, token->endpoint, &serv_addr.sin_addr) <= 0) {
        perror("Invalid address");
        return -1;
    }

    // Connect to auth service
    if (connect(sock, (struct sockaddr*)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("Connection failed");
        return -1;
    }

    // Send OAuth2 token validation request
    char* request = "GET /oauth/token/validate HTTP/1.1\r\nHost: localhost:8080\r\nContent-Type: application/json\r\nAuthorization: Bearer ";
    strcat(request, token->token);
    strcat(request, "\r\n\r\n");
    if (send(sock, request, strlen(request), 0) < 0) {
        perror("Send failed");
        return -1;
    }

    // Receive OAuth2 token validation response
    char buffer[4096];
    int bytes_received = recv(sock, buffer, sizeof(buffer), 0);
    if (bytes_received < 0) {
        perror("Recv failed");
        return -1;
    }
    buffer[bytes_received] = '\0';

    // Parse OAuth2 token validation response
    char* valid_start = strstr(buffer, "\"valid\": true");
    if (!valid_start) {
        printf("Access token is not valid\n");
        return -1;
    }

    // Close HTTP/2 connection
    close(sock);

    return 0;
}

int main() {
    oauth2_token_t* token = malloc(sizeof(oauth2_token_t));
    token->endpoint = "http://localhost:8080";
    if (validate_oauth2_token(token) != 0) {
        printf("Failed to validate access token\n");
        return -1;
    }

    free(token);
    return 0;
}']

