    public byte[] Decrypt(string name, byte[] data)
    {
        if (name == null || data == null)
            throw new ArgumentNullException("Invalid arguments");

        var algorithm = _encryptionAlgorithms[name];
        var key = _encryptionKeys[name];

        return algorithm.Decrypt(data, key);
