using Newtonsoft.Json;
using Microsoft.Extensions.Logging;

namespace DecryptionAndDeserializationModule
{
    public class DecryptionAndDeserializationService
    {
        private readonly ILogger<DecryptionAndDeserializationService> _logger;
        private readonly IDatabaseConnection _databaseConnection;
        private readonly Dictionary<string, SymmetricAlgorithm> _encryptionKeys;
        private readonly Dictionary<string, byte[]> _initializationVectors;

        public DecryptionAndDeserializationService(ILogger<DecryptionAndDeserializationService> logger, IDatabaseConnection databaseConnection)
        {
            _logger = logger;
            _databaseConnection = databaseConnection;
            _encryptionKeys = new Dictionary<string, SymmetricAlgorithm>();
            _initializationVectors = new Dictionary<string, byte[]>();
        }

        public async Task<T> DecryptAndDeserializeAsync<T>(Stream encryptedDataStream) where T : class
        {
            try
            {
                string encryptionKeyName = await GetEncryptionKeyNameAsync();
                string initializationVector = await GetInitializationVectorAsync(encryptionKeyName);
                SymmetricAlgorithm encryptionKey = GetEncryptionKey(encryptionKeyName);

                using (AesCryptoServiceProvider aes = new AesCryptoServiceProvider())
                {
                    aes.KeySize = 256;
                    aes.BlockSize = 128;
                    aes.Mode = CipherMode.CBC;
                    aes.Padding = PaddingMode.PKCS7;
                    aes.IV = Encoding.UTF8.GetBytes(initializationVector);
                    aes.Key = encryptionKey.Key;

                    using (MemoryStream memoryStream = new MemoryStream())
                    {
                        using (CryptoStream cryptoStream = new CryptoStream(memoryStream, aes.CreateDecryptor(), CryptoStreamMode.Write))
                        {
                            await encryptedDataStream.CopyToAsync(cryptoStream);
                        }

                        memoryStream.Position = 0;
                        return JsonConvert.DeserializeObject<T>(Encoding.UTF8.GetString(memoryStream.ToArray()));
                    }
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to decrypt and deserialize data.");
                throw;
            }
        }

        private async Task<string> GetEncryptionKeyNameAsync()
        {
            string encryptionKeyName = await _databaseConnection.GetStringValueAsync("SELECT TOP 1 EncryptionKeyName FROM EncryptionKeys WHERE IsActive = 1");
            return encryptionKeyName;
        }

        private async Task<string> GetInitializationVectorAsync(string encryptionKeyName)
        {
            byte[] initializationVectorBytes = await _databaseConnection.GetByteArrayValueAsync($"SELECT InitializationVector FROM EncryptionKeys WHERE EncryptionKeyName = '{encryptionKeyName}'");
            return Encoding.UTF8.GetString(initializationVectorBytes);
        }

        private SymmetricAlgorithm GetEncryptionKey(string encryptionKeyName)
        {
            if (_encryptionKeys.ContainsKey(encryptionKeyName))
            {
                return _encryptionKeys[encryptionKeyName];
            }

            SymmetricAlgorithm encryptionKey = new AesCryptoServiceProvider();
            byte[] keyBytes = Encoding.UTF8.GetBytes(encryptionKeyName);
            encryptionKey.GenerateKey();
            encryptionKey.GenerateIV();

            _initializationVectors[encryptionKeyName] = encryptionKey.IV;
            _encryptionKeys[encryptionKeyName] = encryptionKey;

            return encryptionKey;
        }
    }
}
