  const filesize = upload.file.size;
  if (!acceptedFileTypes.includes(path.extname(filename).toLowerCase())) {
    throw new Error(`Invalid file type: ${filename}`);
  }
  if (filesize > maxFileSize) {
    throw new Error(`Maximum file size exceeded: ${filename} (${filesize} bytes)`);
  }

  // Perform server-side validation and security checks
