    await upload.file.mv(path.join(__dirname, 'uploads', filename));
    console.log(`Uploaded ${filename} successfully`);
  } catch (err) {
    throw new Error(`Failed to upload ${filename}: ${err}`);
  }
};

// Set up file upload handler
app.post('/upload', async (req, res) => {
  const filename = req.file.originalname;
  const filesize = req.file.size;
  if (!acceptedFileTypes.includes(path.extname(filename).toLowerCase())) {
    return res.status(400).send(`Invalid file type: ${filename}`);
  }
  if (filesize > maxFileSize) {
    return res.status(413).send(`Maximum file size exceeded: ${filename} (${filesize} bytes)`);
  }

  // Add the upload to the queue and process it if the queue is not full
  const newUpload = { filename, filesize };
  if (concurrentUploads < 5) {
    await processUpload(newUpload);
    return res.status(201).send(`Uploaded ${filename} successfully`);
  } else {
    pendingUploads++;
    uploadQueue.push(newUpload);
    console.log(`Pending upload: ${JSON.stringify(upload)}`);
    return res.status(202).send(`Queued for upload: ${filename}`);
  }
});

// Set up file upload monitoring and status endpoint
app.get('/upload-status', (req, res) => {
  const status = {
    pendingUploads,
    concurrentUploads,
    queueLength: uploadQueue.length,
  };
  return res.json(status);
});

// Start the server and listen for incoming requests
app.listen(port, () => {
  console.log(`File Upload Server listening on port ${port}`);
});
```
