#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <limits.h>
#include <pthread.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <fcntl.h>

#define MAX_LINE_LEN 1024
#define MAX_CHUNK_SIZE (1 << 16)
#define MAX_LOG_LENGTH 512
#define MAX_RETRIES 3

typedef enum {
    MODE_CHECKSUM,
    MODE_REPLACE,
    MODE_HELP
} mode_t;

struct file_descriptor {
    int fd;
    off_t offset;
};

struct chunk {
    char* data;
    size_t len;
};

static void usage(const char* argv0) {
    printf("Usage: %s [-c] [-r] input output [chunk_size]\n", argv0);
    printf("\n");
    printf("Options:\n");
    printf("  -c, --checksum        Generate checksum for file\n");
    printf("  -r, --replace         Replace all occurrences of ERROR with WARNING in each line\n");
    printf("  -h, --help            Display help and exit\n");
}

static int parse_args(int argc, char** argv) {
    mode_t mode = MODE_HELP;
    struct file_descriptor* input = NULL;
    struct file_descriptor* output = NULL;
    size_t chunk_size = MAX_CHUNK_SIZE;

    int c;
    opterr = 0;
    while ((c = getopt(argc, argv, "c:r:h")) != -1) {
        switch (c) {
            case 'c':
                mode = MODE_CHECKSUM;
                break;
            case 'r':
                mode = MODE_REPLACE;
                break;
            case 'h':
                mode = MODE_HELP;
                break;
        }
    }

    if (optind < argc) {
        input = open_file(argv[optind]);
        optind++;
    } else {
        usage(argv[0]);
        exit(EXIT_FAILURE);
    }

    if (optind < argc) {
        output = open_file(argv[optind]);
        optind++;
    } else {
        usage(argv[0]);
        exit(EXIT_FAILURE);
    }

    if (optind < argc) {
        chunk_size = strtoull(argv[optind], NULL, 10);
        optind++;
    }

    return mode;
}

static struct file_descriptor* open_file(const char* path) {
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    struct file_descriptor* fdptr = malloc(sizeof(struct file_descriptor));
    fdptr->fd = fd;
    fdptr->offset = 0;

    return fdptr;
}

static void close_file(struct file_descriptor* fdptr) {
    if (close(fdptr->fd) < 0) {
        perror("close");
        exit(EXIT_FAILURE);
    }

    free(fdptr);
}

static void process_chunk(struct chunk* chunk, struct file_descriptor* input, struct file_descriptor* output) {
    char* data = mmap(NULL, chunk->len, PROT_READ, MAP_PRIVATE, input->fd, 0);
    if (data == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < chunk->len; i++) {
        char c = data[i];
        if (c == 'E' && data[i + 1] == 'R' && data[i + 2] == 'R' && data[i + 3] == 'O' && data[i + 4] == 'R') {
            memcpy(data + i, "WARNING", sizeof("WARNING"));
        }
    }

    if (write(output->fd, chunk->data, chunk->len) < 0) {
        perror("write");
        exit(EXIT_FAILURE);
    }

    munmap(data, chunk->len);
}

static void generate_checksum(struct file_descriptor* input, struct file_descriptor* output) {
    uint32_t checksum = 0;

    while (1) {
        struct chunk* chunk = read_chunk(input, MAX_CHUNK_SIZE);
        if (!chunk) {
            break;
        }

        process_chunk(chunk, input, output);

        free(chunk->data);
        free(chunk);
    }
}

static struct chunk* read_chunk(struct file_descriptor* fdptr, size_t size) {
    char* data = mmap(NULL, size, PROT_READ, MAP_PRIVATE, fdptr->fd, 0);
    if (data == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    off_t offset = lseek(fdptr->fd, fdptr->offset, SEEK_SET);
    if (offset < 0) {
        perror("lseek");
        exit(EXIT_FAILURE);
    }

    struct chunk* chunk = malloc(sizeof(struct chunk));
    chunk->data = data;
    chunk->len = size;

    fdptr->offset += size;

    return chunk;
}

static void main(int argc, char** argv) {
    mode_t mode = parse_args(argc, argv);
    struct file_descriptor* input = NULL;
    struct file_descriptor* output = NULL;
    size_t chunk_size = MAX_CHUNK_SIZE;

    if (mode == MODE_HELP) {
        usage(argv[0]);
        exit(EXIT_SUCCESS);
    }

    input = open_file(argv[optind - 1]);
    output = open_file(argv[optind + 2]);

    if (mode == MODE_CHECKSUM) {
        generate_checksum(input, output);
    } else {
        process_chunk(read_chunk(input, chunk_size), input, output);
    }

    close_file(input);
    close_file(output);
}']

