// System Integration and Dependency Management
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dlfcn.h>

#define MAX_DEPENDENCIES 10

typedef struct {
    char* name;
    void* handle;
} Dependency;

static Dependency dependencies[MAX_DEPENDENCIES];
static int num_dependencies = 0;

void initializeDependencies() {
    // Load the existing security framework
    void* handle = dlopen("security-framework", RTLD_LAZY);
    if (!handle) {
        printf("Error loading security framework: %s\n", dlerror());
        exit(1);
    }

    // Load third-party cryptographic libraries
    for (int i = 0; i < MAX_DEPENDENCIES; i++) {
        Dependency dependency = dependencies[i];
        if (dependency.name == NULL) break;

        handle = dlopen(dependency.name, RTLD_LAZY);
        if (!handle) {
            printf("Error loading dependency %s: %s\n", dependency.name, dlerror());
            exit(1);
        }
    }
}

void* loadDependency(char* name) {
    // Check if the dependency is already loaded
    for (int i = 0; i < num_dependencies; i++) {
        Dependency dependency = dependencies[i];
        if (strcmp(dependency.name, name) == 0) return dependency.handle;
    }

    // Load the dependency
    void* handle = dlopen(name, RTLD_LAZY);
    if (!handle) {
        printf("Error loading dependency %s: %s\n", name, dlerror());
        exit(1);
    }

    // Add the dependency to the list of loaded dependencies
    Dependency new_dependency = {name, handle};
    if (num_dependencies < MAX_DEPENDENCIES) {
        dependencies[num_dependencies++] = new_dependency;
    } else {
        printf("Maximum number of dependencies reached\n");
        exit(1);
    }

    return handle;
}

void unloadDependency(char* name) {
    // Find the dependency in the list of loaded dependencies
    for (int i = 0; i < num_dependencies; i++) {
        Dependency dependency = dependencies[i];
        if (strcmp(dependency.name, name) == 0) {
            dlclose(dependency.handle);
            memmove(&dependencies[i], &dependencies[i+1], sizeof(Dependency) * (num_dependencies - i - 1));
            num_dependencies--;
            return;
        }
    }
}
