// RandomEngine.h
#pragma once

namespace RandomEngine {

class MersenneTwister {
public:
    explicit MersenneTwister(uint64_t seed = 0);
    ~MersenneTwister();

    // Thread-local storage
    static thread_local std::unique_ptr<MersenneTwister> instance;

    // Random number generation
    uint32_t generateUInt32();
    double generateDouble();

    // Concurrent access handling
    void setThread(uint64_t threadID);
    static void handleConcurrency();

private:
    uint64_t seed;
    std::uniform_int_distribution<uint32_t> dist;
    std::mt19937 mt;
};

} // namespace RandomEngine

// MersenneTwister.cpp
#include "MersenneTwister.h"
#include <cstdlib>
#include <ctime>
#include <thread>

namespace RandomEngine {

MersenneTwister::MersenneTwister(uint64_t seed) : seed(seed), mt(seed) {}

MersenneTwister::~MersenneTwister() = default;

void MersenneTwister::setThread(uint64_t threadID) {
    instance = std::make_unique<MersenneTwister>(threadID);
}

void MersenneTwister::handleConcurrency() {
    if (instance == nullptr) {
        // Create new instance of the RNG class
        uint64_t threadID = std::hash<std::thread::id>{}(std::this_thread::get_id());
        instance = std::make_unique<MersenneTwister>(threadID);
    }
}

uint32_t MersenneTwister::generateUInt32() {
    handleConcurrency();
    return instance->mt();
}

double MersenneTwister::generateDouble() {
    handleConcurrency();
    return instance->dist(instance->mt);
}

} // namespace RandomEngine

// Main.cpp
#include <iostream>
#include "MersenneTwister.h"

int main() {
    uint64_t seed = 123;
    RandomEngine::MersenneTwister rng(seed);

    for (int i = 0; i < 10; ++i) {
        std::cout << rng.generateUInt32() << ' ';
    }
    std::cout << '\n';

    for (int i = 0; i < 5; ++i) {
        std::cout << rng.generateDouble() << ' ';
    }
    std::cout << '\n';

    return 0;
}']

