typedef struct Configuration {
    int sizeLimit;
    char delimiterType;
    bool nullStringHandlingEnabled;
    bool emptyStringHandlingEnabled;
    bool loggingEnabled;
} Configuration;

char* appendDelimiter(const char* inputString, size_t sizeLimit, Configuration config) {
    // Validate configuration settings
    if (sizeLimit < 0 || config.delimiterType != '*' && config.delimiterType != '/') {
        return NULL;
    }

    // Handle null strings according to the Configuration settings
    if (!inputString || inputString[0] == '\0') {
        if (config.nullStringHandlingEnabled) {
            inputString = "";
        } else {
            return NULL;
        }
    }

    // Get length of `inputString` and calculate new string size
    size_t inputLength = strlen(inputString);
    size_t newSize = inputLength + 1; // Plus one for null terminator
    if (config.delimiterType == '*') {
        newSize += 2; // Add two characters for the delimiter
    }

    // Ensure size limit is not exceeded
    if (newSize > sizeLimit) {
        return NULL;
    }

    // Allocate memory for the new string
    char* newString = malloc(newSize);
    if (!newString) {
        return NULL;
    }

    // Append delimiter to `inputString` and copy to `newString`
    strcpy(newString, inputString);
    if (config.delimiterType == '*') {
        newString[inputLength] = '/';
        newString[inputLength + 1] = '\0';
    } else {
        newString[inputLength] = config.delimiterType;
        newString[inputLength + 1] = '\0';
    }

    // Log length of `inputString` and whether a delimiter was added
    if (config.loggingEnabled) {
        printf("Input string length: %zu\n", inputLength);
        if (config.delimiterType == '*') {
            printf("Delimiter added: Yes\n");
        } else {
            printf("Delimiter added: No\n");
        }
    }

    return newString;
}
