Here is an example of a lexer and parser written in Rust that can convert a provided grammar string into LLVM IR:
```rust
use std::io::{self, Read};
use llvm_ir::*;

struct Lexer<'a> {
    input: &'a str,
    pos: usize,
}

impl<'a> Lexer<'a> {
    fn new(input: &'a str) -> Self {
        Self { input, pos: 0 }
    }

    fn next(&mut self) -> Option<Token> {
        if self.pos >= self.input.len() {
            return None;
        }

        let c = self.input[self.pos];
        self.pos += 1;

        match c {
            '(' | ')' | '+' | '-' => Some(Token::Op(c)),
            '0'..='9' => Some(Token::Num(c.to_digit(10).unwrap())),
            _ => None,
        }
    }
}

struct Parser {
    lexer: Lexer,
}

impl Parser {
    fn new(lexer: Lexer) -> Self {
        Self { lexer }
    }

    fn parse(&mut self) -> Result<Expr, String> {
        let mut tokens = vec![];

        loop {
            match self.lexer.next() {
                Some(Token::Op(op)) => tokens.push(op),
                Some(Token::Num(num)) => tokens.push(num as f64),
                None => break,
                _ => return Err("Invalid token".to_string()),
            }
        }

        if tokens.len() == 0 {
            return Err("No tokens found".to_string());
        }

        let mut expr = Expr::new(tokens[0]);

        for i in 1..tokens.len() {
            expr = match tokens[i] {
                Token::Op('+') => expr + tokens[i - 1],
                Token::Op('-') => expr - tokens[i - 1],
                _ => return Err("Invalid operator".to_string()),
            };
        }

        Ok(expr)
    }
}
```
This code uses the `std::io` module to read input from a string and the `llvm_ir` crate to generate LLVM IR. The `Lexer` struct is used to tokenize the input string, while the `Parser` struct is used to parse the tokens into an expression tree.

To use this code, you can create a new instance of the `Lexer` struct and pass it a string representing the grammar to be converted. Then, you can call the `parse()` method on the `Parser` struct to generate the LLVM IR. For example:
```rust
let lexer = Lexer::new("(+ 1 2)");
let parser = Parser::new(lexer);
let expr = parser.parse().unwrap();
println!("{}", expr); // Output: "(+ (int 1) (int 2))"
```
This code will tokenize the input string and parse it into an expression tree, which can then be converted into LLVM IR using the `llvm_ir` crate.']

