// MemoryManager.h
#include <map>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <atomic>
#include <chrono>
#include <iostream>

class Record {
public:
    long offset;
    int key;
    float value;
};

class MemoryManager {
private:
    std::map<int, std::vector<Record>> records;
    std::mutex mtx;
    std::condition_variable cv;
    std::atomic<bool> running;

public:
    explicit MemoryManager(const int numThreads);
    ~MemoryManager();

    void run();

    bool addRecord(const Record& record, const float deadline);
    bool updateRecord(const Record& record, const float deadline);
    bool removeRecord(const int key, const float deadline);

private:
    void threadLoop(const int tid);
    bool allocateMemory(const long offset, const float deadline);
    bool freeMemory(const long offset, const float deadline);
};
```

```
// MemoryManager.cpp
#include "MemoryManager.h"
#include <cassert>
#include <chrono>
#include <thread>

MemoryManager::MemoryManager(const int numThreads) : running(true), cv(running) {
    // Initialize the memory map and thread pool
    records = std::map<int, std::vector<Record>>();
    for (int i = 0; i < numThreads; i++) {
        threads.emplace_back([this]() { this->threadLoop(i); });
    }
}

MemoryManager::~MemoryManager() {
    // Stop the thread pool and wait for all threads to finish
    running = false;
    cv.notify_all();
    for (auto& t : threads) {
        if (t.joinable()) {
            t.join();
        }
    }
}

void MemoryManager::run() {
    // Start the thread pool and wait for all threads to finish
    for (auto& t : threads) {
        t.detach();
    }
    cv.wait(true);
}

bool MemoryManager::addRecord(const Record& record, const float deadline) {
    // Acquire the mutex and check if there is enough memory available
    std::lock_guard<std::mutex> lock(mtx);
    if (!allocateMemory(record.offset, deadline)) {
        return false;
    }

    // Update the record in the map
    records[record.key].emplace_back(record);

    // Release the mutex and return success
    return true;
}

bool MemoryManager::updateRecord(const Record& record, const float deadline) {
    // Acquire the mutex and check if there is enough memory available
    std::lock_guard<std::mutex> lock(mtx);
    if (!allocateMemory(record.offset, deadline)) {
        return false;
    }

    // Update the record in the map
    records[record.key].back() = record;

    // Release the mutex and return success
    return true;
}

bool MemoryManager::removeRecord(const int key, const float deadline) {
    // Acquire the mutex and check if there is enough memory available
    std::lock_guard<std::mutex> lock(mtx);
    if (!freeMemory(records[key].back().offset, deadline)) {
        return false;
    }

    // Remove the record from the map
    records.erase(key);

    // Release the mutex and return success
    return true;
}

void MemoryManager::threadLoop(const int tid) {
    while (running) {
        // Wait for a condition variable notification
        cv.wait(tid);

        // Check if there are any records to process
        if (!records.empty()) {
            // Process the records and release the mutex
            processRecords();
        }
    }
}

bool MemoryManager::allocateMemory(const long offset, const float deadline) {
    // Check if there is enough memory available
    if (records.size() >= MAX_RECORDS || offset >= MAX_MEMORY) {
        return false;
    }

    // Allocate the memory and add it to the map
    records[offset].emplace_back(Record{offset, 0, 0});

    // Return success
    return true;
}

bool MemoryManager::freeMemory(const long offset, const float deadline) {
    // Check if there is enough memory available
    if (records.size() <= MIN_RECORDS || offset < MIN_MEMORY) {
        return false;
    }

    // Free the memory and remove it from the map
    records.erase(offset);

    // Return success
    return true;
}
```
Note that this is just a basic implementation of a memory manager, and there are many ways to optimize and improve its performance depending on the specific requirements of your application. Additionally, this implementation assumes that you have already defined the `Record` structure and the `MAX_RECORDS`, `MIN_RECORDS`, and `MAX_MEMORY` constants.']

