    if (str == nullptr || sizeLimit < 0 || !isProduction || bookReferenceService.countBookReferences(str) > sizeLimit) {
        logService.logError("Invalid input");
        return nullptr;
    }

    // Initialize variables
    const int kMaxTimestampLength = 256;
    char* timestamp = (char*)malloc(kMaxTimestampLength);
