            bookReferenceCounts[string(current)]++;
            totalBookReferences++;
            current += strlen(current);
        } else {
            current++;
        }
    }
    regfree(&regex);

    // Get current timestamp
    time_t currentTimestamp = 0;
    if (isProduction) {
        currentTimestamp = timestampService.getCurrentTimestamp();
    } else {
        currentTimestamp = time(NULL);
    }

    // Generate output string
    char* output = (char*)malloc(strlen(str) + kMaxTimestampLength + 1);
    sprintf(output, "%s: %d", str, totalBookReferences);

    // Add timestamp to output if production environment
    if (isProduction) {
        char* timestampString = ctime(&currentTimestamp);
        output[strlen(output)] = ' ';
