# LogManager.py
import logging
import json

class LogManager:
    def __init__(self, log_path='/var/log/myapp', log_level='info'):
        self.log_path = log_path
        self.log_level = log_level

    def create_log(self, message, level):
        # Create a new log file if it doesn't exist
        if not os.path.exists(self.log_path):
            with open(self.log_path, 'w') as f:
                f.write('{}')

        # Append the message to the log file
        with open(self.log_path, 'a+') as f:
            logs = json.load(f)
            logs.append({'message': message, 'level': level})
            f.seek(0)
            json.dump(logs, f)

    def retain_log(self, message_id, level):
        # Retain the log by moving it to a different location
        with open(self.log_path, 'r+') as f:
            logs = json.load(f)
            for log in logs:
                if log['message_id'] == message_id and log['level'] == level:
                    os.rename(self.log_path, self.log_path + '.retained')
                    return True
        return False

    def delete_log(self, message_id):
        # Delete the log by removing it from the log file
        with open(self.log_path, 'r+') as f:
            logs = json.load(f)
            for log in logs:
                if log['message_id'] == message_id:
                    logs.remove(log)
                    break
            else:
                return False
            with open(self.log_path, 'w') as f:
                json.dump(logs, f)
        return True

    def filter_logs(self, log_levels):
        # Filter the logs by level and retain them in a separate file
        retained_logs = []
        with open(self.log_path, 'r+') as f:
            logs = json.load(f)
            for log in logs:
                if log['level'] in log_levels:
                    os.rename(self.log_path, self.log_path + '.retained')
                    retained_logs.append(log)
        with open(self.log_path, 'w') as f:
            json.dump(retained_logs, f)
