            queue.offer(line);
        }
        executor.execute(() -> {
            try {
                while (!queue.isEmpty()) {
                    String line = queue.poll();
                    for (LogProcessor processor : processors) {
                        processor.processLine(line);
                    }
                }
            } catch (InterruptedException e) {
                logger.log(Level.SEVERE, "Error processing log lines", e);
            }
        });
