// Define constants for filename components
#define MAX_FILENAME_LENGTH 256
#define TIMESTAMP_FORMAT "%Y-%m-%d %H:%M:%S"
#define VERSION_IDENTIFIER "v1"

// Struct to represent a generated filename
typedef struct {
    char *filename;
} GeneratedFilename;

// Function to generate a unique filename based on the input parameters
GeneratedFilename *generateFileName(char *baseName, char *extension) {
    // Initialize variables for timestamp and hash
    time_t rawtime;
    struct tm *timeinfo;
    unsigned char shaHash[SHA256_DIGEST_LENGTH];

    // Get current timestamp
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Create SHA-256 hash of the base name and timestamp
    SHA256(baseName, strlen(baseName), shaHash);

    // Allocate memory for the generated filename
    GeneratedFilename *filename = malloc(sizeof(GeneratedFilename));

    // Initialize the filename with the base name, timestamp, and version identifier
    filename->filename = malloc(MAX_FILENAME_LENGTH + 1);
    sprintf(filename->filename, "%s-%s-%s%s", baseName, asctime(timeinfo), VERSION_IDENTIFIER, extension);

    return filename;
}

// Function to free memory used by a generated filename
void freeFileName(GeneratedFilename *filename) {
    free(filename->filename);
    free(filename);
}
