struct crc_list {
    NFAPI_CRC_INDICATION_PDU_T* pdu;
    struct crc_list* next;
};

typedef struct {
    struct crc_list* head;
    struct crc_list* tail;
    size_t count;
    size_t max_count;
    semaphore_t lock;
} crc_list_t;

struct thread_args {
    crc_list_t* list;
    database_handle_t dbh;
};

static void *crc_list_thread(void *arg) {
    struct thread_args *args = (struct thread_args *) arg;
    while (1) {
        semaphore_wait(&args->lock);
        if (!args->list->head) {
            continue;
        }
        NFAPI_CRC_INDICATION_PDU_T* pdu = args->list->head->pdu;
        database_write(args->dbh, pdu->data, pdu->length);
        struct crc_list* temp = args->list->head;
        args->list->head = args->list->head->next;
        free(temp);
    }
}

int crc_indication_pdu_store(NFAPI_CRC_INDICATION_PDU_T* pdu, database_handle_t dbh) {
    crc_list_t* list = (crc_list_t*) malloc(sizeof(crc_list_t));
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    list->max_count = 10000;
    semaphore_init(&list->lock, 0);
    struct thread_args *args = (struct thread_args *) malloc(sizeof(struct thread_args));
    args->list = list;
    args->dbh = dbh;
    pthread_create(&crc_list_thread, NULL, crc_list_thread, args);
    if (!list->head) {
        list->head = (struct crc_list*) malloc(sizeof(struct crc_list));
        list->tail = list->head;
        list->count++;
        memcpy(list->head->pdu, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    } else {
        struct crc_list* new_node = (struct crc_list*) malloc(sizeof(struct crc_list));
        list->tail->next = new_node;
        list->tail = new_node;
        list->count++;
        memcpy(new_node->pdu, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    semaphore_post(&list->lock);
}
