  transition->from = from;
  transition->to = to;
  transition->type = -1;
  transition->data = NULL;
}

// Add a state transition to the state management library
int add_transition(StateLibrary *library, int type, State *from, State *to) {
  // Check if the transition already exists in the library
  for (int i = 0; i < library->num_transitions; ++i) {
    if (library->transitions[i]->type == type && library->transitions[i]->from == from && library->transitions[i]->to == to) {
      return -1; // Transition already exists
    }
  }

  // Allocate memory for the new transition
  StateTransition *transition = malloc(sizeof(StateTransition));
  if (!transition) {
    return -2; // Memory allocation error
  }

  // Set the properties of the new transition
  init_transition(transition, from, to);
  transition->type = type;
  transition->data = NULL;

  // Add the transition to the library
  library->transitions = realloc(library->transitions, (library->num_transitions + 1) * sizeof(StateTransition));
  if (!library->transitions) {
    free(transition);
    return -2; // Memory allocation error
  }
  library->transitions[library->num_transitions] = transition;
  ++library->num_transitions;

  return 0; // Success
}

// Remove a state transition from the state management library
int remove_transition(StateLibrary *library, int type, State *from, State *to) {
  // Find the index of the transition to be removed
  int i = 0;
  while (i < library->num_transitions && (library->transitions[i]->type != type || library->transitions[i]->from != from || library->transitions[i]->to != to)) {
    ++i;
  }
  if (i == library->num_transitions) {
    return -1; // Transition not found
  }

  // Remove the transition from the library
  StateTransition *transition = library->transitions[i];
  for (int j = i; j < library->num_transitions - 1; ++j) {
    library->transitions[j] = library->transitions[j + 1];
  }
  --library->num_transitions;

  // Free the memory of the removed transition
  free(transition);

  return 0; // Success
}

// Initialize a state machine
void init_state_machine(StateMachine *machine) {
  machine->current = NULL;
  machine->pending = false;
  machine->transitions = malloc(sizeof(StateTransition));
  if (!machine->transitions) {
    return; // Memory allocation error
  }
  machine->num_transitions = 0;
}

// Add a state transition to the state machine
void add_transition(StateMachine *machine, State *from, State *to) {
  int type = -1;
  if (from == NULL && to != NULL) {
    // Transition from the initial state
    type = 0;
  } else if (from != NULL && to == NULL) {
    // Transition to a final state
    type = 1;
  } else if (from != NULL && to != NULL) {
    // Normal transition
    type = 2;
  } else {
    return; // Invalid transition
  }
  add_transition(machine->transitions, type, from, to);
}

// Remove a state transition from the state machine
void remove_transition(StateMachine *machine, State *from, State *to) {
  int type = -1;
  if (from == NULL && to != NULL) {
    // Transition from the initial state
    type = 0;
  } else if (from != NULL && to == NULL) {
    // Transition to a final state
    type = 1;
  } else if (from != NULL && to != NULL) {
    // Normal transition
    type = 2;
  } else {
    return; // Invalid transition
  }
  remove_transition(machine->transitions, type, from, to);
}

// Execute a state machine
void execute_state_machine(StateMachine *machine) {
  while (true) {
    // Check for pending transitions
    if (machine->pending) {
      break;
    }

    // Check for incoming transitions
    if (machine->current == NULL && machine->num_transitions > 0) {
      machine->current = machine->transitions[0]->from;
      machine->pending = true;
      break;
    }
  }
}

// Handle a state transition
void handle_transition(StateMachine *machine, int type, State *from, State *to) {
  // Check for invalid transitions
  if (type == -1 || from == NULL && to != NULL || from != NULL && to == NULL) {
    return; // Invalid transition
  }

  // Add the transition to the state machine
  add_transition(machine, type, from, to);
}

// Handle a state transition
void remove_transition(StateMachine *machine, int type, State *from, State *to) {
  // Check for invalid transitions
  if (type == -1 || from == NULL && to != NULL || from != NULL && to == NULL) {
    return; // Invalid transition
  }

  // Remove the transition from the state machine
  remove_transition(machine, type, from, to);
}']

