using System;
using System.Threading;
using System.Threading.Tasks;
using System.Net;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text;
using Microsoft.AspNetCore.Mvc;
using Newtonsoft.Json;
using MySql.Data.MySqlClient;
using Google.Protobuf;

namespace CryptoStorageService
{
    public class EncryptionManager
    {
        private readonly IConfiguration _configuration;
        private readonly IDictionary<string, AesCipher> _ciphers = new Dictionary<string, AesCipher>();
        private readonly string[] _keySources = new string[0];
        private readonly string[] _allowedAlgorithms = new string[0];

        public EncryptionManager(IConfiguration configuration)
        {
            _configuration = configuration;
            Init();
        }

        public async Task<byte[]> EncryptAsync(string keyId, byte[] data, CancellationToken cancellationToken = default)
        {
            if (!_ciphers.TryGetValue(keyId, out var cipher))
            {
                throw new Exception($"Invalid key ID: {keyId}");
            }

            return await cipher.EncryptAsync(data, cancellationToken);
        }

        public async Task<byte[]> DecryptAsync(string keyId, byte[] data, CancellationToken cancellationToken = default)
        {
            if (!_ciphers.TryGetValue(keyId, out var cipher))
            {
                throw new Exception($"Invalid key ID: {keyId}");
            }

            return await cipher.DecryptAsync(data, cancellationToken);
        }

        private void Init()
        {
            foreach (var keySource in _keySources)
            {
                var aesCipher = new AesCipher(_configuration[keySource]);
                _ciphers.Add(aesCipher.KeyId, aesCipher);
            }
        }
    }

    public class CryptoStorageService : IHttpTrigger
    {
        private readonly EncryptionManager _encryptionManager;
        private readonly MySqlConnection _dbConnection;

        public CryptoStorageService(EncryptionManager encryptionManager, MySqlConnection dbConnection)
        {
            _encryptionManager = encryptionManager;
            _dbConnection = dbConnection;
        }

        [FunctionName("CryptoStorageService")]
        public async Task<IActionResult> Run(
            [HttpTrigger(AuthorizationLevel.Anonymous, "post", Route = null)] HttpRequest req)
        {
            var requestBody = await new StreamReader(req.Body).ReadToEndAsync();
            var jsonData = JsonConvert.DeserializeObject<JsonData>(requestBody);

            if (!_allowedAlgorithms.Contains(jsonData.Algorithm))
            {
                return new BadRequestResult();
            }

            byte[] encryptedData;
            try
            {
                var keyId = jsonData.KeyId ?? "default";
                encryptedData = await _encryptionManager.EncryptAsync(keyId, Encoding.UTF8.GetBytes(jsonData.Data));
            }
            catch (Exception ex)
            {
                return new BadRequestResult();
            }

            var sqlInsertQuery = $"INSERT INTO CryptoStorage (data) VALUES ({encryptedData})";

            try
            {
                await _dbConnection.OpenAsync();
                using (var command = _dbConnection.CreateCommand())
                {
                    command.CommandText = sqlInsertQuery;
                    await command.ExecuteNonQueryAsync();
                }
            }
            catch (Exception ex)
            {
                return new BadRequestResult();
            }
            finally
            {
                _dbConnection.Close();
            }

            var jsonResponse = new JsonResponse()
            {
                Status = "OK",
                Data = encryptedData
            };

            return new OkObjectResult(jsonResponse);
        }
    }
}
