package com.example.restapi;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

@Component
public class UserSubscriptionService {

    @Autowired
    private InMemoryCache cache;

    @Autowired
    private RelationalDatabase database;

    @Autowired
    private ExternalAnalyticsPlatform analyticsPlatform;

    public void addUserSubscription(String userId, String subscriptionType) {
        // Validate input parameters
        if (userId == null || subscriptionType == null) {
            throw new IllegalArgumentException("Invalid input parameters");
        }

        // Check if the user already has a subscription of this type
        if (hasUserSubscription(userId, subscriptionType)) {
            return;
        }

        // Create a new subscription object and save it to the database
        Subscription subscription = new Subscription();
        subscription.setUserId(userId);
        subscription.setSubscriptionType(subscriptionType);
        database.save(subscription);

        // Update the cache with the new subscription
        cache.put(userId, subscription);
    }

    public void updateUserSubscription(String userId, String subscriptionType) {
        // Validate input parameters
        if (userId == null || subscriptionType == null) {
            throw new IllegalArgumentException("Invalid input parameters");
        }

        // Check if the user has a subscription of this type
        Subscription subscription = getUserSubscription(userId, subscriptionType);
        if (subscription == null) {
            return;
        }

        // Update the subscription in the database
        subscription.setSubscriptionType(subscriptionType);
        database.update(subscription);

        // Update the cache with the updated subscription
        cache.put(userId, subscription);
    }

    public void deleteUserSubscription(String userId, String subscriptionType) {
        // Validate input parameters
        if (userId == null || subscriptionType == null) {
            throw new IllegalArgumentException("Invalid input parameters");
        }

        // Check if the user has a subscription of this type
        Subscription subscription = getUserSubscription(userId, subscriptionType);
        if (subscription == null) {
            return;
        }

        // Delete the subscription from the database
        database.delete(subscription);

        // Update the cache with the deleted subscription
        cache.remove(userId);
    }

    public boolean hasUserSubscription(String userId, String subscriptionType) {
        // Validate input parameters
        if (userId == null || subscriptionType == null) {
            throw new IllegalArgumentException("Invalid input parameters");
        }

        // Check if the user has a subscription of this type in the cache
        Subscription subscription = cache.get(userId);
        if (subscription != null && subscription.getSubscriptionType().equals(subscriptionType)) {
            return true;
        }

        // Check if the user has a subscription of this type in the database
        subscription = database.findByUserIdAndSubscriptionType(userId, subscriptionType);
        if (subscription != null) {
            cache.put(userId, subscription);
            return true;
        }

        return false;
    }

    public Subscription getUserSubscription(String userId, String subscriptionType) {
        // Validate input parameters
        if (userId == null || subscriptionType == null) {
            throw new IllegalArgumentException("Invalid input parameters");
        }

        // Check if the user has a subscription of this type in the cache
        Subscription subscription = cache.get(userId);
        if (subscription != null && subscription.getSubscriptionType().equals(subscriptionType)) {
            return subscription;
        }

        // Check if the user has a subscription of this type in the database
        subscription = database.findByUserIdAndSubscriptionType(userId, subscriptionType);
        if (subscription != null) {
            cache.put(userId, subscription);
            return subscription;
        }

        return null;
    }
}
