// Forward declarations
class IExternalConfigService;
class IDataProcessor;
class IStorageManager;
class IAlerter;
class IMonitoringClient;

// Define the function signature
void ProcessAndStoreSensorData(const std::vector<SensorReading>& dataStream, const IExternalConfigService& configService, const IDataProcessor& dataProcessor, const IStorageManager& storageManager, const IAlerter& alertService, const IMonitoringClient& monitoringClient) {
    // Load configuration parameters from the config service
    auto config = configService.GetConfig();

    // Set up a pool of worker threads to process the data stream
    std::vector<std::thread> workers;
    for (int i = 0; i < config->numWorkers; ++i) {
        workers.emplace_back([&dataStream]() {
            while (!dataStream.empty()) {
                // Process the next data point in the stream
                auto reading = dataStream.front();
                dataProcessor.Process(reading);

                // Store the processed data in the storage manager
                storageManager.StoreData(reading);

                // Check for anomalies and send alerts if necessary
                bool isAnomaly = alertService.CheckForAnomalies(reading);
                if (isAnomaly) {
                    alertService.SendAlert(reading);
                }

                // Remove the processed data point from the stream
                dataStream.pop_front();
            }
        });
    }

    // Wait for all worker threads to finish processing the data stream
    for (auto& worker : workers) {
        worker.join();
    }
}

// Define the SensorReading struct
struct SensorReading {
    double timestamp;
    std::string sensorId;
    double value;
};
```
