import os
from typing import List, Dict, Set
from collections import defaultdict

class CloudServiceAnalyzer:
    def __init__(self, api_url: str, api_key: str):
        self.api_url = api_url
        self.api_key = api_key
        self.cache = {}

    def fetch_metadata(self, uuids: List[str]) -> Dict[str, dict]:
        metadata = defaultdict(dict)
        for uuid in uuids:
            try:
                response = requests.get(f"{self.api_url}/vms/{uuid}", headers={"Authorization": f"Bearer {self.api_key}"})
                if response.status_code == 200:
                    metadata[uuid] = response.json()
            except requests.RequestException as e:
                print(f"Error fetching metadata for VM with UUID {uuid}: {e}")
        return metadata

    def analyze_documents(self, documents: List[str]) -> Dict[str, dict]:
        unique_terms = set()
        contextual_usage = defaultdict(list)
        filtered_documents = []
        for document in documents:
            vm_uuids = self.extract_vm_uuids(document)
            if not vm_uuids:
                continue
            metadata = self.fetch_metadata(vm_uuids)
            for uuid, vm_data in metadata.items():
                unique_terms.add(vm_data["name"])
                contextual_usage[vm_data["category"]].append(vm_data["name"])
            filtered_documents.append({"uuid": vm_uuids[0], "text": document})
        return {
            "unique_terms": unique_terms,
            "contextual_usage": contextual_usage,
            "filtered_documents": filtered_documents
        }

    def extract_vm_uuids(self, text: str) -> List[str]:
        return [uuid for uuid in re.findall(r"(?i)(\b[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\b)", text)]

    def filter_documents(self, documents: List[str], filters: Dict[str, Set]) -> List[str]:
        filtered_documents = []
        for document in documents:
            vm_uuids = self.extract_vm_uuids(document)
            if not vm_uuids:
                continue
            metadata = self.fetch_metadata(vm_uuids)
            category_filter = filters["category"]
            for uuid, vm_data in metadata.items():
                if category_filter and vm_data["category"] not in category_filter:
                    continue
                filtered_documents.append({"uuid": uuid, "text": document})
        return filtered_documents

    def generate_report(self, documents: List[str], filters: Dict[str, Set]) -> str:
        analysis = self.analyze_documents(documents)
        unique_terms = ", ".join(analysis["unique_terms"])
        contextual_usage = "\n".join([f"{k}: {', '.join(v)}" for k, v in analysis["contextual_usage"].items()])
        filtered_documents = self.filter_documents(documents, filters)
        report = f"""Unique Terms: {unique_terms}

Contextual Usage:
{contextual_usage}

Filtered Documents:
{filtered_documents}"""
        return report
