// Define a struct to represent an OAuth2 access token response
struct AccessToken {
    std::string access_token;
    int expires_in;
    std::string token_type;
    std::string refresh_token;
};

// Define a function to parse an OAuth2 access token response from a JSON string
AccessToken parseAccessToken(const std::string& json) {
    // Use the nlohmann::json library to parse the JSON string
    nlohmann::json j = nlohmann::json::parse(json);

    // Check for required fields in the response
    if (!j.contains("access_token") || !j.contains("expires_in") || !j.contains("token_type")) {
        throw std::runtime_error("Required fields missing from access token response");
    }

    // Validate the values of the required fields
    if (j["token_type"] != "Bearer") {
        throw std::runtime_error("Invalid token type in access token response");
    }

    int expires_in = j["expires_in"].get<int>();
    if (expires_in <= 0) {
        throw std::runtime_error("Expires in value must be a positive integer");
    }

    // Return the parsed access token response
    return AccessToken{
        .access_token = j["access_token"].get<std::string>(),
        .expires_in = expires_in,
        .token_type = "Bearer",
        .refresh_token = j.contains("refresh_token") ? j["refresh_token"].get<std::string>() : ""
    };
}

// Define a function to verify the validity of an access token using an external time service API
bool isValidAccessToken(const AccessToken& token) {
    // Use the curl library to make a GET request to the external time service API
    std::string url = "https://api.example.com/time";
    std::string response;
    CURL* curl = curl_easy_init();
    if (curl) {
        CURLcode res = curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        if (res != CURLE_OK) {
            throw std::runtime_error("Failed to set URL for external time service API");
        }

        // Set the access token as a header in the request
        struct curl_slist* headers = NULL;
        headers = curl_slist_append(headers, "Authorization: Bearer " + token.access_token);
        res = curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        if (res != CURLE_OK) {
            throw std::runtime_error("Failed to set access token header for external time service API");
        }

        // Perform the request and get the response
        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            throw std::runtime_error("Failed to perform GET request to external time service API");
        }

        // Get the response body as a string
        char* buffer;
        res = curl_easy_getinfo(curl, CURLINFO_RESPONSE_STRING, &buffer);
        if (res != CURLE_OK) {
            throw std::runtime_error("Failed to get response body from external time service API");
        }

        // Parse the response as JSON and check for a successful response
        nlohmann::json j = nlohmann::json::parse(buffer);
        if (!j.contains("valid")) {
            throw std::runtime_error("Invalid response from external time service API");
        }

        // Return the validity of the access token
        return j["valid"].get<bool>();
    } else {
        throw std::runtime_error("Failed to initialize curl for external time service API");
    }
}

// Define a function to handle transient errors when verifying the validity of an access token using an external time service API
void retryVerifyAccessToken(const AccessToken& token, int attempt) {
    // Use an exponential backoff strategy to avoid overloading the external service
    int delay = (1 << (attempt - 1)) * 100; // milliseconds
    std::this_thread::sleep_for(std::chrono::milliseconds(delay));

    // Verify the access token again, incrementing the attempt count if necessary
    try {
        isValidAccessToken(token);
    } catch (const std::runtime_error& e) {
        if (attempt < 5) {
            retryVerifyAccessToken(token, attempt + 1);
        } else {
            throw;
        }
    }
}

// Define a function to handle malformed JSON in the access token response gracefully
std::string formatErrorMessage(const std::string& error) {
    return "Malformed JSON in access token response: " + error;
}

// Define a class to represent the OAuth2 access token cache, with thread safety and efficient memory usage
class AccessTokenCache {
public:
    // Add an access token to the cache
    void addAccessToken(const AccessToken& token) {
        std::lock_guard<std::mutex> lock(m);
        tokens.push_back(token);
    }

    // Get the most recently added access token from the cache, if it is still valid
    const AccessToken* getValidAccessToken() {
        std::lock_guard<std::mutex> lock(m);
        for (auto it = tokens.rbegin(); it != tokens.rend(); ++it) {
            if (isValidAccessToken(*it)) {
                return &*it;
            }
        }
        return nullptr;
    }
private:
    std::mutex m; // mutex to ensure thread safety when accessing the cache
    std::vector<AccessToken> tokens; // vector to store the access tokens in the cache
};

// Define a function to handle OAuth2 access token responses from an external service, with retry mechanisms and error handling
void handleExternalServiceResponse(const std::string& json) {
    try {
        // Parse the JSON string into an access token response
        AccessToken token = parseAccessToken(json);

        // Verify the validity of the access token using an external time service API
        if (isValidAccessToken(token)) {
            // Add the access token to the cache, if it is still valid
            std::lock_guard<std::mutex> lock(m);
            tokens.addAccessToken(token);
        } else {
            // Log an error message if the access token is not valid
            std::cout << "Invalid access token received from external service" << std::endl;
        }
    } catch (const std::runtime_error& e) {
        // Handle malformed JSON in the response gracefully
        std::cout << formatErrorMessage(e.what()) << std::endl;
    }
}

// Main function to handle OAuth2 access token responses from an external service, with thread safety and efficient memory usage
int main() {
    // Create a cache for the access tokens
    AccessTokenCache tokens;

    // Handle OAuth2 access token responses from an external service, with retry mechanisms and error handling
    while (true) {
        std::string json = receiveOAuth2AccessTokenResponse();
        handleExternalServiceResponse(json);
    }
    return 0;
}
