use std::fs;
use std::path::Path;
use std::io::Error;
use llvm_ir::IRBuilder;
use parser::Parser;
use lexer::Lexer;

fn parse_file(path: &str) -> Result<(), Error> {
    let file = fs::File::open(Path::new(path))?;
    let mut lexer = Lexer::new(file);
    let mut parser = Parser::new(&mut lexer);
    let mut builder = IRBuilder::new();

    while let Some(token) = parser.next_token() {
        match token {
            TokenType::Int => {
                let value = parser.parse_int();
                builder.build_add(value, 0);
            }
            TokenType::Float => {
                let value = parser.parse_float();
                builder.build_fadd(value, 0.0);
            }
            TokenType::Ident => {
                let ident = parser.parse_ident();
                match ident.as_str() {
                    "add" => {
                        let value1 = parser.parse_int();
                        let value2 = parser.parse_int();
                        builder.build_add(value1, value2);
                    }
                    "sub" => {
                        let value1 = parser.parse_int();
                        let value2 = parser.parse_int();
                        builder.build_sub(value1, value2);
                    }
                    "mul" => {
                        let value1 = parser.parse_int();
                        let value2 = parser.parse_int();
                        builder.build_mul(value1, value2);
                    }
                    "div" => {
                        let value1 = parser.parse_int();
                        let value2 = parser.parse_int();
                        builder.build_div(value1, value2);
                    }
                    _ => panic!("invalid ident"),
                }
            }
            _ => panic!("unexpected token"),
        }
    }

    Ok(())
}
