char* secureAppendDelimiter(const char* inputString, size_t sizeLimit, Configuration config) {
    // Handle null or empty strings according to the configuration settings
    if (inputString == NULL || strlen(inputString) == 0) {
        if (config.allowEmptyStrings) {
            return "";
        } else {
            return NULL;
        }
    }

    // Determine delimiter type and length based on configuration
    char delimiter = config.delimiterType;
    size_t delimiterLen = strlen(delimiter);

    // Calculate new string length and allocate memory for it
    size_t newStringLen = strlen(inputString) + delimiterLen;
    if (newStringLen > sizeLimit) {
        return NULL;
    }
    char* newString = malloc(sizeof(char) * (newStringLen + 1));
    if (newString == NULL) {
        return NULL;
    }

    // Append delimiter to input string and copy it to the new string
    strcpy(newString, inputString);
    strcat(newString, delimiter);

    // Log length of input string and whether a delimiter was added
    if (config.loggingEnabled) {
        printf("Input string length: %zu\n", strlen(inputString));
        printf("Delimiter added: %s\n", newString + strlen(inputString));
