// Define configuration struct with size limit and delimiter options
typedef struct Configuration {
    int size_limit;
    char* delimiters;
} Configuration;

// Define function prototypes
void appendDelimiter(char* input, char delimiter, Configuration config);
unsigned char* calculateMD5(const char* input, size_t length);

// Implement function to append a specified delimiter to an input string
void appendDelimiter(char* input, char delimiter, Configuration config) {
    // Check for null strings and invalid configurations
    if (input == NULL || delimiter == '\0' || config.size_limit < 0) {
        printf("Error: Invalid arguments\n");
        return;
    }

    // Check if resulting string exceeds size limit
    int new_length = strlen(input) + 1 + config.delimiters[0];
    if (new_length > config.size_limit) {
        printf("Error: Size limit exceeded\n");
        return;
    }

    // Append delimiter to input string and check for buffer overflow
    char* new_input = realloc(input, new_length);
    if (new_input == NULL) {
        printf("Error: Reallocation failed\n");
        free(input);
        return;
    }
    input = new_input;
    input[strlen(input)] = delimiter;
    input[strlen(input) + 1] = '\0';
}

// Implement function to calculate MD5 hash of a given string
unsigned char* calculateMD5(const char* input, size_t length) {
    // Use standard cryptographic library for MD5 hashing
    unsigned char* hash = (unsigned char*) malloc(16);
    if (hash == NULL) {
        printf("Error: Memory allocation failed\n");
        return NULL;
    }
    MD5_CTX ctx;
    MD5Init(&ctx);
    MD5Update(&ctx, input, length);
    MD5Final(hash, &ctx);

    // Check for errors during hashing and free memory if necessary
    if (MD5IsError()) {
        printf("Error: Hashing failed\n");
        free(hash);
        return NULL;
    }
    return hash;
}
