        // retrieve all data from the source and copy it to the destination
        string data = retrieveData(source);
        processData(data, destination, ranges);
    } else {
        // retrieve specified byte ranges from the source and copy them to the destination
        vector<future<string>> futures; // list of futures for concurrent requests
        for (const auto& range : ranges) {
            int start = range.first;
            int end = range.second;
            string url = config.apiEndpoint + "?" + source + "&start=" + to_string(start) + "&end=" + to_string(end);
            futures.push_back(async(launch::async, retrieveData, url));
        }
        for (const auto& future : futures) {
            string data = future.get();
            processData(data, destination, ranges);
        }
    }
    return 0;
}
```
