            snprintf(timestamp_string, MIN_TIMESTAMP_LENGTH, "%lu", (unsigned long)timestamp);
            break;
        case TIMESTAMP_FORMAT_ISO_8601:
            timestamp_string = malloc(MAX_TIMESTAMP_LENGTH);
            struct tm* tm_info = localtime(&timestamp);
            strftime(timestamp_string, MAX_TIMESTAMP_LENGTH, "%Y-%m-%dT%H:%M:%SZ", tm_info);
            break;
    }

