    if (fp == NULL) {
        perror("fopen");
        return NULL;
    }

    // Create a hash context using the desired algorithm
    EVP_MD_CTX* ctx = EVP_MD_CTX_create();
    const EVP_MD* digest = EVP_get_digestbyname(HASH_ALGORITHM_SHA256);
    if (!EVP_DigestInit_ex(ctx, digest, NULL)) {
        perror("EVP_DigestInit_ex");
        return NULL;
    }

    // Read the file in chunks and update the hash context
    size_t buffer_size = 4096;
    unsigned char* buffer = malloc(buffer_size);
    while (1) {
        size_t bytes_read = fread(buffer, sizeof(unsigned char), buffer_size, fp);
        if (bytes_read == 0) {
            break;
        }

        if (!EVP_DigestUpdate(ctx, buffer, bytes_read)) {
            perror("EVP_DigestUpdate");
            return NULL;
        }
    }

    // Close the file and free the resources
    fclose(fp);
    free(buffer);

    // Get the final hash value from the context
    unsigned char* hash = malloc(MAX_HASH_LENGTH);
    EVP_DigestFinal_ex(ctx, hash, NULL);
    EVP_MD_CTX_destroy(ctx);

    return hash;
}
