Here is a possible implementation of the encryption framework in C++:
```c
#include <iostream>
#include <string>
#include <openssl/ssl.h>
#include <openssl/err.h>
#include <openssl/conf.h>
#include <openssl/evp.h>
#include <openssl/hmac.h>
#include <openssl/rand.h>
#include <openssl/aes.h>
#include <openssl/rsa.h>
#include <openssl/engine.h>
#include <openssl/pkcs12.h>
#include <openssl/x509.h>

using namespace std;

class EncryptionFramework {
private:
    // Private key and certificate for signing and verifying messages
    RSA *rsa_key;
    X509 *certificate;

    // Symmetric encryption algorithm for data encryption/decryption
    EVP_CIPHER_CTX *aes_ctx;

    // Asymmetric encryption algorithm for key exchange
    EVP_PKEY *rsa_pkey;
    X509_REQ *certificate_request;

    // External Key Management Service (KMS) client
    KmsClient kms_client;

    // TLS/SSL context for secure data transmission
    SSL_CTX *ssl_ctx;

    // Cipher mode and key size for encryption/decryption
    string cipher_mode;
    int key_size;

    // Key rotation policy for man-in-the-middle attacks
    bool rotate_keys;

    // Resource management using RAII principles
    bool resource_managed = false;

public:
    EncryptionFramework(string cipher_mode, int key_size, bool rotate_keys) {
        this->cipher_mode = cipher_mode;
        this->key_size = key_size;
        this->rotate_keys = rotate_keys;

        // Initialize OpenSSL context and load external KMS client
        SSL_library_init();
        OpenSSL_add_all_algorithms();
        ERR_load_crypto_strings();
        kms_client.initialize();
    }

    ~EncryptionFramework() {
        if (resource_managed) {
            // Release resources
            SSL_CTX_free(ssl_ctx);
            EVP_PKEY_free(rsa_pkey);
            X509_REQ_free(certificate_request);
            RSA_free(rsa_key);
            X509_free(certificate);
        }
    }

    bool initialize() {
        // Generate a key pair and self-signed certificate for signature verification
        rsa_key = RSA_generate_key(key_size, 65537, NULL, NULL);
        certificate = X509_new();
        X509_set_version(certificate, 2);
        ASN1_INTEGER_set(X509_get_serialNumber(certificate), 1);
        X509_gmtime_adj(X509_get_notBefore(certificate), 0);
        X509_gmtime_adj(X509_get_notAfter(certificate), 31536000L);
        X509_set_pubkey(certificate, rsa_key);
        EVP_PKEY *pkey = EVP_PKEY_new();
        if (EVP_PKEY_assign(pkey, EVP_PKEY_RSA, rsa_key)) {
            X509_set_pubkey(certificate, pkey);
            EVP_PKEY_free(pkey);
        }
        X509_sign(certificate, rsa_key, EVP_sha256());

        // Initialize TLS/SSL context for secure data transmission
        ssl_ctx = SSL_CTX_new(TLS_client_method());
        if (ssl_ctx == NULL) {
            cerr << "Failed to create TLS/SSL context" << endl;
            return false;
        }
        SSL_CTX_set_cipher_list(ssl_ctx, cipher_mode);
        if (!SSL_CTX_use_certificate(ssl_ctx, certificate)) {
            cerr << "Failed to load self-signed certificate" << endl;
            return false;
        }
        SSL_CTX_set_options(ssl_ctx, SSL_OP_NO_SSLv2 | SSL_OP_NO_SSLv3 | SSL_OP_NO_TLSv1 | SSL_OP_NO_TLSv1_1);
        SSL_CTX_set_read_ahead(ssl_ctx, 1);

        // Load external KMS client and initialize key management system
        kms_client.load();
        if (!kms_client.initialize()) {
            cerr << "Failed to initialize KMS client" << endl;
            return false;
        }

        // Initialize symmetric encryption algorithm for data encryption/decryption
        aes_ctx = EVP_CIPHER_CTX_new();
        if (EVP_EncryptInit(aes_ctx, EVP_aes_256_cbc(), NULL, NULL) != 1) {
            cerr << "Failed to initialize AES encryption context" << endl;
            return false;
        }

        // Initialize asymmetric encryption algorithm for key exchange
        rsa_pkey = EVP_PKEY_new();
        if (EVP_PKEY_assign(rsa_pkey, EVP_PKEY_RSA, rsa_key)) {
            certificate_request = X509_REQ_new();
            X509_REQ_set_version(certificate_request, 0);
            ASN1_INTEGER_set(X509_REQ_get_serialNumber(certificate_request), 1);
            EVP_PKEY *pkey = EVP_PKEY_new();
            if (EVP_PKEY_assign(pkey, EVP_PKEY_RSA, rsa_key)) {
                X509_REQ_set_pubkey(certificate_request, pkey);
                EVP_PKEY_free(pkey);
            }
        }

        // Resource management using RAII principles
        resource_managed = true;

        return true;
    }

    bool encrypt(const string& plaintext, string& ciphertext) {
        // Generate a random nonce for encryption
        unsigned char nonce[16];
        RAND_bytes(nonce, 16);

        // Setup AES encryption context and generate initialization vector
        EVP_CIPHER_CTX *aes_ctx = EVP_CIPHER_CTX_new();
        unsigned char iv[EVP_MAX_IV_LENGTH];
        int iv_len;
        if (EVP_EncryptInit(aes_ctx, EVP_aes_256_cbc(), NULL, nonce) != 1 || EVP_CIPHER_CTX_get_iv(aes_ctx, iv, &iv_len) != 1) {
            cerr << "Failed to generate AES initialization vector" << endl;
            return false;
        }

        // Setup RSA encryption context and generate encrypted nonce
        EVP_PKEY *pkey = X509_get_pubkey(certificate);
        if (pkey == NULL) {
            cerr << "Failed to retrieve public key" << endl;
            return false;
        }
        RSA *rsa = EVP_PKEY_get1_RSA(pkey);
        unsigned char encrypted_nonce[EVP_MAX_IV_LENGTH];
        int encrypted_nonce_len = RSA_size(rsa);
        if (RSA_public_encrypt(iv_len, iv, encrypted_nonce, rsa, RSA_PKCS1_OAEP_PADDING) != encrypted_nonce_len) {
            cerr << "Failed to encrypt nonce" << endl;
            return false;
        }

        // Setup symmetric encryption context and generate encrypted plaintext
        unsigned char key[32];
        RAND_bytes(key, 32);
        EVP_CIPHER_CTX *symmetric_ctx = EVP_CIPHER_CTX_new();
        if (EVP_EncryptInit(symmetric_ctx, EVP_aes_256_cbc(), key, nonce) != 1) {
            cerr << "Failed to initialize symmetric encryption context" << endl;
            return false;
        }
        int plaintext_len = strlen(plaintext.c_str());
        unsigned char *ciphertext_buf = (unsigned char *)malloc(plaintext_len + 1);
        int ciphertext_len = EVP_CIPHER_CTX_encrypt(symmetric_ctx, ciphertext_buf, plaintext.c_str(), plaintext_len);
        if (ciphertext_len <= 0) {
            cerr << "Failed to encrypt plaintext" << endl;
            return false;
        }
        ciphertext_buf[ciphertext_len] = '\0';

        // Assemble encrypted data into final output format
        unsigned char *final_ciphertext = (unsigned char *)malloc(encrypted_nonce_len + iv_len + ciphertext_len);
        memcpy(final_ciphertext, encrypted_nonce, encrypted_nonce_len);
        memcpy(final_ciphertext + encrypted_nonce_len, iv, iv_len);
        memcpy(final_ciphertext + encrypted_nonce_len + iv_len, ciphertext_buf, ciphertext_len);

        // Release resources and return final output
        EVP_CIPHER_CTX_free(symmetric_ctx);
        free(ciphertext_buf);
        ciphertext = string((char *)final_ciphertext, encrypted_nonce_len + iv_len + ciphertext_len);
        free(final_ciphertext);

        return true;
    }

    bool decrypt(const string& ciphertext, string& plaintext) {
        // Extract nonce and initialization vector from encrypted data
        unsigned char nonce[16];
        RAND_bytes(nonce, 16);
        int iv_len = EVP_MAX_IV_LENGTH;
        unsigned char *ciphertext_buf = (unsigned char *)malloc(iv_len + strlen(ciphertext.c_str()));
        memcpy(ciphertext_buf, ciphertext.c_str(), iv_len);
        int plaintext_len = strlen(ciphertext.c_str()) - iv_len;
        unsigned char *plaintext_buf = (unsigned char *)malloc(plaintext_len + 1);

        // Setup AES decryption context and decrypt nonce
        EVP_CIPHER_CTX *aes_ctx = EVP_CIPHER_CTX_new();
        if (EVP_DecryptInit(aes_ctx, EVP_aes_256_cbc(), NULL, nonce) != 1) {
            cerr << "Failed to initialize AES decryption context" << endl;
            return false;
        }
        int nonce_len = EVP_CIPHER_CTX_decrypt(aes_ctx, nonce, ciphertext_buf, iv_len);
        if (nonce_len != 16) {
            cerr << "Failed to decrypt nonce" << endl;
            return false;
        }

        // Setup RSA decryption context and decrypt initialization vector
        EVP_PKEY *pkey = X509_get_pubkey(certificate);
        if (pkey == NULL) {
            cerr << "Failed to retrieve private key" << endl;
            return false;
        }
        RSA *rsa = EVP_PKEY_get1_RSA(pkey);
        int encrypted_iv_len = RSA_size(rsa);
        unsigned char encrypted_iv[EVP_MAX_IV_LENGTH];
        memcpy(encrypted_iv, ciphertext_buf + iv_len, encrypted_iv_len);
        unsigned char *decrypted_iv = (unsigned char *)malloc(16);
        int decrypted_iv_len = RSA_private_decrypt(encrypted_iv_len, encrypted_iv, decrypted_iv, rsa, RSA_PKCS1_OAEP_PADDING);
        if (decrypted_iv_len != 16) {
            cerr << "Failed to decrypt initialization vector" << endl;
            return false;
        }

        // Setup symmetric decryption context and decrypt ciphertext
        unsigned char key[32];
        RAND_bytes(key, 32);
        EVP_CIPHER_CTX *symmetric_ctx = EVP_CIPHER_CTX_new();
        if (EVP_DecryptInit(symmetric_ctx, EVP_aes_256_cbc(), key, decrypted_iv) != 1) {
            cerr << "Failed to initialize symmetric decryption context" << endl;
            return false;
        }
        int decrypted_len = EVP_CIPHER_CTX_decrypt(symmetric_ctx, plaintext_buf, ciphertext_buf + iv_len, plaintext_len);
        if (decrypted_len <= 0) {
            cerr << "Failed to decrypt ciphertext" << endl;
            return false;
        }
        plaintext_buf[decrypted_len] = '\0';

        // Release resources and return final output
        EVP_CIPHER_CTX_free(symmetric_ctx);
        free(ciphertext_buf);
        plaintext = string((char *)plaintext_buf, decrypted_len);
        free(plaintext_buf);

        return true;
    }
};

int main() {
    // Generate a random key for encryption/decryption
    unsigned char key[32];
    RAND_bytes(key, 32);

    // Encrypt the message using the key
    string message = "This is the original message";
    string ciphertext;
    AES_GCM_Encryptor encryptor(key);
    encryptor.encrypt(message, ciphertext);

    // Decrypt the ciphertext using the same key
    string plaintext;
    AES_GCM_Encryptor decryptor(key);
    decryptor.decrypt(ciphertext, plaintext);

    cout << "Plaintext: " << plaintext << endl;
    cout << "Ciphertext: " << ciphertext << endl;
}
```
