        if (get_use_asymmetric_encryption()) {
            use_asymmetric_encryption(plaintext, ciphertext);
        } else if (get_use_symmetric_encryption()) {
            use_symmetric_encryption(plaintext, ciphertext);
        }
    }

    string decrypt(string ciphertext) {
