            return use_asymmetric_decryption(ciphertext);
        } else if (get_use_symmetric_encryption()) {
            return use_symmetric_decryption(ciphertext);
        }
    }

private:
    void use_asymmetric_encryption(string plaintext, string& ciphertext) {
        // Generate a new key pair if needed
        if (public_key_.Get() == NULL || private_key_.Get() == NULL) {
            generate_new_keys();
        }

        // Encrypt the plaintext using RSA encryption
        CryptoPP::RSAES<CryptoPP::SHA1>::Encryption encryptor(public_key_);
        CryptoPP::StringSource(plaintext, true, new CryptoPP::PK_EncryptorFilter(encryptor, new CryptoPP::StringSink(ciphertext)));
    }

    void use_asymmetric_decryption(string ciphertext) {
        // Decrypt the ciphertext using RSA decryption
        CryptoPP::RSAES<CryptoPP::SHA1>::Decryption decryptor(private_key_);
        CryptoPP::StringSource(ciphertext, true, new CryptoPP::PK_DecryptorFilter(decryptor, new CryptoPP::StringSink(plaintext)));
    }

    void use_symmetric_encryption(string plaintext, string& ciphertext) {
        // Generate a new key if needed
        if (aes_encryption_.GetKey() == NULL) {
            generate_new_key();
        }

        // Encrypt the plaintext using AES encryption
        CryptoPP::StringSource(plaintext, true, new CryptoPP::StreamTransformationFilter(aes_encryption_, new CryptoPP::StringSink(ciphertext)));
    }

    string use_symmetric_decryption(string ciphertext) {
        // Decrypt the ciphertext using AES decryption
        CryptoPP::StringSource(ciphertext, true, new CryptoPP::StreamTransformationFilter(aes_decryption_, new CryptoPP::StringSink(plaintext)));
    }

    void generate_new_keys() {
        // Generate a new key pair using RSA encryption
        public_key_.GenerateKey(CryptoPP::RSA::DEFAULT_KEYSIZE);
        private_key_.GenerateKey(public_key_, CryptoPP::RSA::DEFAULT_KEYSIZE);
    }

    void generate_new_key() {
        // Generate a new key using AES encryption
        aes_encryption_.SetKeyWithIV(CryptoPP::AES::GenerateKey(CryptoPP::AES::MAX_KEYLENGTH, CryptoPP::AutoSeededRandomPool()), CryptoPP::AES::BLOCKSIZE);
    }
};
