Here is a sample code block that demonstrates a modular, scalable, and maintainable Python library for managing large-scale, distributed file storage and retrieval systems:
```python
import hashlib
import json
from collections import defaultdict
from datetime import datetime
from pathlib import Path
from typing import Dict, List, Optional

import requests


class FileManager:
    def __init__(self, base_url: str) -> None:
        self.base_url = base_url

    def upload(self, file_path: str, metadata: Optional[Dict] = None) -> Dict:
        """Upload a file to the file storage system."""
        # Compute checksum of file content
        with open(file_path, "rb") as f:
            checksum = hashlib.md5(f.read()).hexdigest()

        # Generate metadata if not provided
        if metadata is None:
            metadata = {
                "filename": Path(file_path).name,
                "created_at": datetime.now().isoformat(),
                "checksum": checksum,
            }

        # Upload file to storage service
        response = requests.post(self.base_url + "/upload", json=metadata)

        if response.status_code == 201:
            return metadata
        else:
            raise RuntimeError(f"Failed to upload file: {response.text}")

    def download(self, file_id: str) -> Dict:
        """Download a file from the file storage system."""
        response = requests.get(self.base_url + f"/download/{file_id}")

        if response.status_code == 200:
            return json.loads(response.text)
        else:
            raise RuntimeError(f"Failed to download file: {response.text}")

    def get_metadata(self, file_id: str) -> Dict:
        """Get metadata for a file in the file storage system."""
        response = requests.get(self.base_url + f"/metadata/{file_id}")

        if response.status_code == 200:
            return json.loads(response.text)
        else:
            raise RuntimeError(f"Failed to get metadata for file {file_id}: {response.text}")

    def list_files(self, page: int = 1, limit: int = 20) -> List[Dict]:
        """List files in the file storage system."""
        response = requests.get(self.base_url + f"/list?page={page}&limit={limit}")

        if response.status_code == 200:
            return json.loads(response.text)["files"]
        else:
            raise RuntimeError(f"Failed to list files: {response.text}")

    def delete_file(self, file_id: str) -> None:
        """Delete a file from the file storage system."""
        response = requests.delete(self.base_url + f"/delete/{file_id}")

        if response.status_code == 204:
            return None
        else:
            raise RuntimeError(f"Failed to delete file {file_id}: {response.text}")


class FileCache:
    def __init__(self) -> None:
        self.cache = defaultdict(list)

    def add(self, key: str, value: Dict) -> None:
        """Add a file to the cache."""
        self.cache[key].append(value)

    def get(self, key: str) -> Optional[Dict]:
        """Get a file from the cache."""
        if not self.cache[key]:
            return None
        else:
            return self.cache[key][-1]

    def update(self, key: str, value: Dict) -> None:
        """Update a file in the cache."""
        self.cache[key].append(value)

    def delete(self, key: str) -> bool:
        """Delete a file from the cache."""
        if not self.cache[key]:
            return False
        else:
            del self.cache[key]
            return True
```
