import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.Lock;
import java.util.zip.DeflaterOutputStream;
import com.google.protobuf.ProtocolMessageEnum;

public class RealTimeDataProcessor {
    private static final int DEFAULT_CACHE_SIZE = 10000;
    private static final int MAX_MESSAGE_SIZE = 4 * 1024; // 4KB
    private static final long MAX_AGE_SECS = 60; // 1 minute
    private static final boolean ENABLE_COMPRESSION = true;
    private static final int COMPRESSION_LEVEL = DeflaterOutputStream.DEFAULT_COMPRESSION;
    private static final String CACHE_NAME = "realTimeDataCache";
    private static final String METRICS_NAME = "RealTimeDataProcessorMetrics";
    private static final String LOCK_NAME = "realTimeDataLock";

    private ConcurrentHashMap<String, Object> cache;
    private Lock lock;
    private ProtocolMessageEnum dataFormat;
    private int messageSizeLimit;
    private long ageLimitSecs;
    private boolean enableCompression;
    private int compressionLevel;
    private Metrics metrics;

    public RealTimeDataProcessor(ProtocolMessageEnum dataFormat, int messageSizeLimit, long ageLimitSecs, boolean enableCompression, int compressionLevel) {
        this.cache = new ConcurrentHashMap<>(DEFAULT_CACHE_SIZE);
        this.lock = new ReentrantLock();
        this.dataFormat = dataFormat;
        this.messageSizeLimit = messageSizeLimit;
        this.ageLimitSecs = ageLimitSecs;
        this.enableCompression = enableCompression;
        this.compressionLevel = compressionLevel;
        this.metrics = new Metrics();
    }

    public void process(String data) {
        try {
            lock.lock();
            if (cache.size() >= messageSizeLimit || cache.isEmpty()) {
                cache.clear();
            }
            cache.put(data, data);
            metrics.incrementCounter("messagesReceived", 1);
            metrics.incrementCounter("messageBytesReceived", data.length());
        } finally {
            lock.unlock();
        }
    }

    public void process(String data, int messageSize) {
        try {
            lock.lock();
            if (cache.size() >= messageSizeLimit || cache.isEmpty()) {
                cache.clear();
            }
            cache.put(data, data);
            metrics.incrementCounter("messagesReceived", 1);
            metrics.incrementCounter("messageBytesReceived", messageSize);
        } finally {
            lock.unlock();
        }
    }

    public void process(String data, long ageSecs) {
        try {
            lock.lock();
            if (cache.size() >= messageSizeLimit || cache.isEmpty()) {
                cache.clear();
            }
            cache.put(data, data);
            metrics.incrementCounter("messagesReceived", 1);
            metrics.incrementCounter("messageBytesReceived", data.length());
            if (ageSecs > ageLimitSecs) {
                cache.remove(data);
            }
        } finally {
            lock.unlock();
        }
    }

    public String getMessage() {
        try {
            lock.lock();
            if (!cache.isEmpty()) {
                String data = cache.get(0);
                metrics.incrementCounter("messagesServed", 1);
                return data;
            }
        } finally {
            lock.unlock();
        }
    }

    public void clearCache() {
        try {
            lock.lock();
            cache.clear();
        } finally {
            lock.unlock();
        }
    }

    private static class Metrics {
        private final Counter messagesReceived;
        private final Counter messageBytesReceived;
        private final Counter messagesServed;

        public Metrics() {
            this.messagesReceived = new Counter("messagesReceived", "Number of messages received");
            this.messageBytesReceived = new Counter("messageBytesReceived", "Total number of bytes received in messages");
            this.messagesServed = new Counter("messagesServed", "Number of messages served to clients");
        }

        public void incrementCounter(String name, long value) {
            if (name.equals("messagesReceived")) {
                messagesReceived.increment(value);
            } else if (name.equals("messageBytesReceived")) {
                messageBytesReceived.increment(value);
            } else if (name.equals("messagesServed")) {
                messagesServed.increment(value);
            }
        }
    }
}
```
