using namespace std;

// Define a struct to represent a drone in the system
struct Drone {
    int id;
    string name;
    vector<string> endpoints;
};

// Define a struct to represent a message in the system
struct Message {
    int sender_id;
    int recipient_id;
    string payload;
};

// Define a struct to represent a queue of messages in the system
struct MessageQueue {
    vector<Message> messages;
    mutex mtx;
    condition_variable cv;
};

// Define a function to send a message from one drone to another
void send_message(Drone& sender, Drone& recipient, string payload) {
    // Acquire the lock on the message queue for the sending drone
    unique_lock<mutex> lk(sender.mtx);

    // Create a new message and add it to the queue
    Message msg;
    msg.sender_id = sender.id;
    msg.recipient_id = recipient.id;
    msg.payload = payload;
    sender.messages.push_back(msg);

    // Notify all threads waiting on the condition variable that a new message has been added
    sender.cv.notify_all();
}

// Define a function to receive a message from one drone
void receive_message(Drone& recipient, MessageQueue& queue) {
    unique_lock<mutex> lk(recipient.mtx);

    // Wait until a new message is available in the queue
    while (queue.messages.empty()) {
        recipient.cv.wait(lk);
    }

    // Remove the first message from the queue and return it to the caller
    Message msg = queue.messages.front();
    queue.messages.pop_front();
    return msg;
}

// Define a function to handle incoming messages
void handle_message(Drone& drone, MessageQueue& queue) {
    // Acquire the lock on the message queue for the drone
    unique_lock<mutex> lk(drone.mtx);

    // Loop until the queue is empty
    while (!queue.messages.empty()) {
        // Remove the first message from the queue and process it
        Message msg = queue.messages.front();
        queue.messages.pop_front();
        process_message(drone, msg);
    }
}

// Define a function to process an incoming message
void process_message(Drone& drone, Message msg) {
    // Implement the specific logic for handling the received message here
}

// Define a function to handle outgoing messages
void handle_outgoing_messages(Drone& drone, vector<Message>& outgoing_messages) {
    // Acquire the lock on the message queue for the drone
    unique_lock<mutex> lk(drone.mtx);

    // Loop until all outgoing messages have been processed
    while (!outgoing_messages.empty()) {
        // Remove the first message from the vector and send it to the corresponding endpoint
        Message msg = outgoing_messages.front();
        drone.endpoints[msg.endpoint].send(msg.payload);
        outgoing_messages.pop_front();
    }
}

// Define a function to handle incoming messages from all drones
void handle_incoming_messages(vector<Drone>& drones, MessageQueue& queue) {
    // Acquire the lock on the message queue for each drone
    unique_lock<mutex> lk(drones[0].mtx);

    // Loop until all incoming messages have been handled
    while (!queue.messages.empty()) {
        // Remove the first message from the queue and handle it
        Message msg = queue.messages.front();
        queue.messages.pop_front();
        handle_message(drones[msg.sender_id], msg);
    }
}

// Define a function to handle outgoing messages from all drones
void handle_outgoing_messages(vector<Drone>& drones, vector<Message>& outgoing_messages) {
    // Acquire the lock on the message queue for each drone
    unique_lock<mutex> lk(drones[0].mtx);

    // Loop until all outgoing messages have been processed
    while (!outgoing_messages.empty()) {
        // Remove the first message from the vector and send it to the corresponding endpoint
        Message msg = outgoing_messages.front();
        drones[msg.sender_id].endpoints[msg.endpoint].send(msg.payload);
        outgoing_messages.pop_front();
    }
}

// Define a function to handle incoming and outgoing messages for all drones
void handle_all_messages(vector<Drone>& drones) {
    // Create a vector of message queues for each drone
    vector<MessageQueue> queue;
    queue.resize(drones.size());

    // Create a vector of outgoing messages for each drone
    vector<vector<Message>> outgoing_messages;
    outgoing_messages.resize(drones.size());

    // Acquire the lock on all message queues and outgoing message vectors
    unique_lock<mutex> lk(drones[0].mtx);

    // Loop until all incoming and outgoing messages have been handled
    while (!queue.empty() || !outgoing_messages.empty()) {
        // Handle incoming messages from each drone
        for (int i = 0; i < drones.size(); ++i) {
            handle_incoming_messages(drones[i], queue[i]);
        }

        // Handle outgoing messages from each drone
        for (int i = 0; i < drones.size(); ++i) {
            handle_outgoing_messages(drones[i], outgoing_messages[i]);
        }
    }
}

// Define a function to send messages between two drones
void send_message(Drone& from, Drone& to, string payload) {
    // Acquire the lock on both message queues for the drones
    unique_lock<mutex> lk1(from.mtx);
    unique_lock<mutex> lk2(to.mtx);

    // Add a new message to the from drone's outgoing messages vector
    Message msg;
    msg.sender_id = from.id;
    msg.recipient_id = to.id;
    msg.endpoint = 0;
    msg.payload = payload;
    from.outgoing_messages.push_back(msg);

    // Notify all threads waiting on the condition variable that a new message has been added
    from.cv.notify_all();
}
