// Helper function for applying changes to a document
function applyChangesToDocument(changes, currentDoc) {
  // Parse the JSON representation of the document
  const doc = JSON.parse(currentDoc);

  // Apply the changes to the document
  changes.forEach((change) => {
    switch (change.type) {
      case 'insert':
        doc.content[change.position].push(change.value);
        break;
      case 'delete':
        doc.content[change.position].splice(change.from, change.to - change.from);
        break;
      case 'update':
        doc.content[change.position][change.from] = change.value;
        break;
    }
  });

  // Return the updated document
  return doc;
}

