```c
#include <stdlib.h>
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>

// Structure for the list of NFAPI_CRC_INDICATION_PDUs
typedef struct nfapi_crc_indication_list {
  uint32_t size;
  uint32_t capacity;
  NFAPI_CRC_INDICATION_PDU_T *elements;
} nfapi_crc_indication_list_t;

// Function for creating a new list of NFAPI_CRC_INDICATION_PDUs
nfapi_crc_indication_list_t *nfapi_crc_indication_list_create() {
  nfapi_crc_indication_list_t *list = malloc(sizeof(nfapi_crc_indication_list_t));
  if (list == NULL) {
    return NULL;
  }
  list->size = 0;
  list->capacity = 0;
  list->elements = NULL;
  return list;
}

// Function for destroying a list of NFAPI_CRC_INDICATION_PDUs
void nfapi_crc_indication_list_destroy(nfapi_crc_indication_list_t *list) {
  free(list->elements);
  free(list);
}

// Function for adding a new NFAPI_CRC_INDICATION_PDU to the list
int nfapi_crc_indication_list_add(nfapi_crc_indication_list_t *list, NFAPI_CRC_INDICATION_PDU_T *element) {
  if (list->capacity == 0) {
    // If the list is empty, allocate space for the first element
    list->elements = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list->elements == NULL) {
      return -1;
    }
    list->capacity = 1;
  } else if (list->size == list->capacity) {
    // If the list is full, double the capacity and allocate space for new elements
    NFAPI_CRC_INDICATION_PDU_T *new_elements = realloc(list->elements, 2 * list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_elements == NULL) {
      return -1;
    }
    list->elements = new_elements;
    list->capacity *= 2;
  }
  // Copy the new element into the next available slot in the list
  memcpy(&list->elements[list->size], element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
  list->size++;
  return 0;
}

// Function for retrieving a NFAPI_CRC_INDICATION_PDU from the list by index
NFAPI_CRC_INDICATION_PDU_T *nfapi_crc_indication_list_get(nfapi_crc_indication_list_t *list, uint32_t index) {
  if (index >= list->size) {
    return NULL;
  }
  return &list->elements[index];
}

// Function for iterating over the NFAPI_CRC_INDICATION_PDUs in the list
void nfapi_crc_indication_list_foreach(nfapi_crc_indication_list_t *list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
  for (uint32_t i = 0; i < list->size; i++) {
    callback(&list->elements[i]);
  }
}

// Function for retrieving the size of the list
uint32_t nfapi_crc_indication_list_size(nfapi_crc_indication_list_t *list) {
  return list->size;
}
