// Function to parse TIFF image file and extract metadata
void parse_tiff(const char *filename, struct image_metadata *metadata) {
    // Open TIFF image file
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Error opening TIFF image file!\n");
        return;
    }

    // Read TIFF header and check for validity
    char tiff_header[4];
    fread(tiff_header, 1, 4, file);
    if (strncmp(tiff_header, "MM\x00\x2a", 4) != 0 && strncmp(tiff_header, "\x2a\x00M", 4) != 0) {
        printf("Error: TIFF image file is not valid!\n");
        fclose(file);
        return;
    }

    // Read image width and height from TIFF header
    int image_width, image_height;
    fread(&image_width, sizeof(int), 1, file);
    fread(&image_height, sizeof(int), 1, file);
    if (image_width <= 0 || image_height <= 0) {
        printf("Error: Invalid TIFF image dimensions!\n");
        fclose(file);
        return;
    }

    // Read bits per sample from TIFF header
    int bits_per_sample;
    fread(&bits_per_sample, sizeof(int), 1, file);
    if (bits_per_sample < MIN_BITS_PER_SAMPLE || bits_per_sample > MAX_BITS_PER_SAMPLE) {
        printf("Error: Invalid number of bits per sample!\n");
        fclose(file);
        return;
    }

    // Read sample per pixel from TIFF header
    int sample_per_pixel;
    fread(&sample_per_pixel, sizeof(int), 1, file);
    if (sample_per_pixel <= 0) {
        printf("Error: Invalid number of samples per pixel!\n");
        fclose(file);
        return;
    }

    // Read compression type from TIFF header
    char compression_type[16];
    fread(compression_type, 1, 16, file);
    if (strncmp(compression_type, "none", 4) != 0 && strncmp(compression_type, "ccittfax3", 8) != 0 && strncmp(compression_type, "jpeg", 4) != 0 && strncmp(compression_type, "lzw", 3) != 0 && strncmp(compression_type, "old-jpeg", 7) != 0 && strncmp(compression_type, "deflate", 7) != 0 && strncmp(compression_type, "packbits", 8) != 0 && strncmp(compression_type, "thunderscan", 10) != 0 && strncmp(compression_type, "neutron", 6) != 0) {
        printf("Error: Unsupported compression type!\n");
        fclose(file);
        return;
    }

    // Read color profile from TIFF header
    char color_profile[32];
    fread(color_profile, 1, 32, file);
    if (strncmp(color_profile, "sRGB IEC61966-2.1", 14) != 0 && strncmp(color_profile, "Adobe RGB", 8) != 0 && strncmp(color_profile, "Apple RGB", 8) != 0 && strncmp(color_profile, "Wide Gamut RGB", 12) != 0) {
        printf("Error: Unsupported color profile!\n");
        fclose(file);
        return;
    }

    // Read extra samples from TIFF header
    int extra_samples;
    fread(&extra_samples, sizeof(int), 1, file);
    if (extra_samples < MIN_EXTRA_SAMPLES || extra_samples > MAX_EXTRA_SAMPLES) {
        printf("Error: Invalid number of extra samples!\n");
        fclose(file);
        return;
    }

    // Read information about each extra sample
    struct extra_sample_info *extra_sample_list = (struct extra_sample_info *) malloc(sizeof(struct extra_sample_info) * extra_samples);
    for (int i = 0; i < extra_samples; i++) {
        int type, name[16], value;
        fread(&type, sizeof(int), 1, file);
        fread(name, 1, 16, file);
        fread(&value, sizeof(float), 1, file);
        extra_sample_list[i].type = type;
        strncpy(extra_sample_list[i].name, name, 16);
        extra_sample_list[i].value = value;
    }

    // Close TIFF image file
    fclose(file);

    // Update metadata structure with extracted information
    metadata->bits_per_sample = bits_per_sample;
    metadata->sample_per_pixel = sample_per_pixel;
    strncpy(metadata->compression_type, compression_type, 16);
    strncpy(metadata->color_profile, color_profile, 32);
    metadata->extra_samples = extra_samples;
    memcpy(metadata->extra_sample_list, extra_sample_list, sizeof(struct extra_sample_info) * extra_samples);

    // Free memory allocated for extra sample list
    free(extra_sample_list);
}

void extractMetadataFromJPEG(const char *filepath, struct metadata *metadata) {
    // Open JPEG file
    FILE *file = fopen(filepath, "rb");

    // Check if file opened successfully
    if (file == NULL) {
        printf("Error: Unable to open JPEG file!\n");
        return;
    }

    // Read JPEG file signature
    char sig[4];
    fread(sig, 1, 4, file);

