    if (strncmp(sig, "\xFF\xD8\xFF", 3) != 0) {
        printf("Error: Invalid JPEG file signature!\n");
        fclose(file);
        return;
    }

    // Read JPEG file header
    char header[12];
    fread(header, 1, 12, file);

    // Extract metadata from JPEG file header
    metadata->bits_per_sample = header[9] & 0x7F;
    metadata->sample_per_pixel = (header[11] >> 4) + 1;
    strncpy(metadata->compression_type, "JPEG", 4);
    strncpy(metadata->color_profile, "sRGB IEC61966-2.1", 15);

    // Close JPEG file
    fclose(file);
}

void extractMetadataFromPNG(const char *filepath, struct metadata *metadata) {
    // Open PNG file
