    int height = (header[0x16] << 24) + (header[0x17] << 16) + (header[0x18] << 8) + header[0x19];

    metadata->bits_per_sample = 8;
    metadata->sample_per_pixel = 3;
    strncpy(metadata->compression_type, "deflate", 7);
    strncpy(metadata->color_profile, "sRGB IEC61966-2.1", 15);

    // Close PNG file
    fclose(file);
}

