// NetMonLib.h
#pragma once

#include <vector>
#include <map>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <chrono>
#include <future>
#include <functional>

class NetMonLib {
 public:
  // Constructor and Destructor
  NetMonLib();
  ~NetMonLib();

  // Initialize the library with a list of network segments
  void init(const std::vector<std::string>& networkSegments);

  // Run a diagnostic command on all connected networks
  void runDiagnosticCommand(const std::string& command,
                            const std::function<void(const std::string&)>& callback = nullptr);

 private:
  // Struct to store information about each network segment
  struct NetworkSegment {
    std::string name;
    std::string address;
    bool isConnected;
    int connectionStatus;
  };

  // Map of network segments and their status
  std::map<std::string, NetworkSegment> networkSegments_;

  // Mutex for protecting concurrent access to the network segment map
  std::mutex mutex_;

  // Condition variable for notifying when new data is available
  std::condition_variable cv_;

  // Thread pool for executing diagnostic commands
  std::vector<std::thread> threadPool_;

  // Number of threads in the thread pool
  int numThreads_;

  // Run a diagnostic command on a single network segment
  void runDiagnosticCommand(const NetworkSegment& segment, const std::string& command);

  // Handle the results of a diagnostic command execution
  void handleResults(const NetworkSegment& segment, const std::string& results);
};

// NetMonLib.cpp
#include "NetMonLib.h"

#include <iostream>
#include <sstream>
#include <iomanip>

void NetMonLib::init(const std::vector<std::string>& networkSegments) {
  for (auto& segment : networkSegments) {
    NetworkSegment newSegment;
    newSegment.name = segment;
    newSegment.address = segment;
    newSegment.isConnected = false;
    newSegment.connectionStatus = -1;
    networkSegments_.insert(std::make_pair(segment, newSegment));
