import java.util.concurrent.Executors;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import org.apache.kafka.clients.consumer.KafkaConsumer;
import org.apache.kafka.common.serialization.StringDeserializer;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.google.gson.Gson;
import org.slf4j.LoggerFactory;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.context.annotation.Bean;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.*;
import io.confluent.common.utils.RateLimitInterceptor;
import io.confluent.kafka.serializers.KafkaJsonDeserializer;
import io.confluent.kafka.streams.serdes.avro.specific.SpecificAvroSerializer;
import org.apache.kafka.streams.KeyValue;
import org.apache.kafka.streams.StreamsConfig;
import org.apache.kafka.streams.kstream.KStream;
import org.apache.kafka.streams.kstream.Materialized;
import org.apache.kafka.streams.kstream.Produced;
import org.apache.kafka.streams.kstream.Serialized;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.ApplicationContext;
import org.springframework.web.client.RestTemplate;
import java.util.Map;

@SpringBootApplication
public class SensorDataAggregator {

    private static final Logger LOGGER = LoggerFactory.getLogger(SensorDataAggregator.class);

    @Autowired
    private ApplicationContext applicationContext;

    @Bean
    public RestTemplate restTemplate() {
        return new RestTemplate();
    }

    @Bean
    public KafkaConsumer<String, JsonNode> kafkaConsumer(String bootstrapServers) {
        Map<String, Object> configProps = new HashMap<>();
        configProps.put(StreamsConfig.BOOTSTRAP_SERVERS_CONFIG, bootstrapServers);
        configProps.put(StreamsConfig.DEFAULT_KEY_SERDE_CLASS_CONFIG, StringDeserializer.class);
        configProps.put(StreamsConfig.DEFAULT_VALUE_SERDE_CLASS_CONFIG, KafkaJsonDeserializer.class);
        return new KafkaConsumer<>(configProps);
    }

    @Bean
    public ExecutorService executorService() {
        return Executors.newFixedThreadPool(10);
    }

    @Bean
    public Gson gson() {
        return new Gson();
    }

    @Bean
    public ObjectMapper objectMapper() {
        return new ObjectMapper();
    }

    @Bean
    public RateLimitInterceptor rateLimitInterceptor(String rateLimitingConfig) {
        return new RateLimitInterceptor(rateLimitingConfig);
    }

    @PostMapping("/sensor-data")
    @RateLimit
    public ResponseEntity<String> aggregateSensorData(@RequestBody JsonNode sensorData) throws IOException {
        LOGGER.info("Received request to aggregate sensor data");

        // Parse the JSON message and extract the sensor ID and reading values
        String sensorId = sensorData.get("sensor_id").asText();
        double reading1 = sensorData.get("reading1").asDouble();
        double reading2 = sensorData.get("reading2").asDouble();

        // Create a new Kafka producer to send the aggregated data to the output topic
        KafkaProducer<String, JsonNode> producer = applicationContext.getBean(KafkaProducer.class);

        // Aggregate the readings and convert them to JSON format
        Map<String, Object> aggregatedReadings = new HashMap<>();
        aggregatedReadings.put("sensor_id", sensorId);
        aggregatedReadings.put("reading1", reading1 + reading2);

        JsonNode aggregatedData = objectMapper().writeValueAsString(aggregatedReadings);

        // Send the aggregated data to the output topic
        producer.send(new ProducerRecord<>(OUTPUT_TOPIC, sensorId, aggregatedData));

        return new ResponseEntity<>("Aggregation successful", HttpStatus.OK);
    }

    @Bean
    public KStream<String, JsonNode> inputStream(KafkaConsumer<String, JsonNode> kafkaConsumer) {
        // Consume messages from the input topic and convert them to JSON format
        return kafkaConsumer.toStream()
                .map((k, v) -> new KeyValue<>(v.get("sensor_id").asText(), v));
    }

    @Bean
    public KStream<String, JsonNode> outputStream(KafkaProducer<String, JsonNode> kafkaProducer) {
        // Send the aggregated data to the output topic
        return inputStream.map((k, v) -> new KeyValue<>(v.get("sensor_id").asText(), v));
    }
}
```
