import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class UserProfileService {
    private final ConcurrentHashMap<String, UserProfile> profiles = new ConcurrentHashMap<>();
    private final ExecutorService executor = Executors.newFixedThreadPool(5);
    private final ExternalUserDataAPI api;

    public UserProfileService(ExternalUserDataAPI api) {
        this.api = api;
    }

    public void addSite(String siteName, String directoryPath) throws Exception {
        if (!directoryPath.endsWith("\\") && !directoryPath.endsWith("/")) {
            directoryPath += "\\";
        }
        if (new File(directoryPath + "web.config").exists()) {
            UserProfile profile = new UserProfile(siteName, directoryPath);
            profiles.put(profile.getId(), profile);
            executor.submit(() -> api.updateUserData(profile));
        } else {
            throw new IllegalArgumentException("Invalid site: no web.config file found");
        }
    }

    public UserProfile getUserProfile(String userId) {
        return profiles.get(userId);
    }

    public void updateUserData() throws Exception {
        executor.submit(() -> api.updateUserData(profiles));
    }

    private static class ExternalUserDataAPI {
        public void updateUserData(ConcurrentHashMap<String, UserProfile> profiles) throws Exception {
            // API call to retrieve user data
        }
    }

    private static class UserProfile {
        private final String id;
        private final String directoryPath;

        public UserProfile(String id, String directoryPath) {
            this.id = id;
            this.directoryPath = directoryPath;
        }

        public String getId() {
            return id;
        }

        public String getDirectoryPath() {
            return directoryPath;
        }
    }
}
