// Define a registry for storing factory functions for creating JSON object parsers
class JsonObjectFactory {
public:
    // Register a new factory function for creating JSON object parsers
    void registerFactoryFunction(const std::string& id, std::function<std::shared_ptr<JsonParser>(const std::string&)> factory) {
        factories[id] = factory;
    }

