// Define structs for configuration options and file metadata
struct ConfigOptions {
    root_dir: String, // default: "/opt/config"
    force_recreate: bool,
    compression_format: String, // default: "gzip"
    cache_expiration_time: u64, // default: 300 (5 minutes)
}

struct FileMetadata {
    path: PathBuf,
    size: u64,
    hash: String,
    timestamp: u64,
}

// Implement the configuration directory management module
mod config_dir_manager {
    // Private fields and methods
    const ROOT_DIR: &str = "/opt/config";
    let cache: HashMap<PathBuf, FileMetadata> = HashMap::new();
    let mut compression_format: String = "gzip".to_string();
    let mut cache_expiration_time: u64 = 300;

    // Public methods
    fn init(&self, config_options: ConfigOptions) {
        self.root_dir = config_options.root_dir;
        self.force_recreate = config_options.force_recreate;
        self.compression_format = config_options.compression_format;
        self.cache_expiration_time = config_options.cache_expiration_time;
    }

    fn create_config_directory(&self) {
        // Create the configuration directory if it does not exist
        let mut path = PathBuf::from(ROOT_DIR);
        if !path.exists() {
            fs::create_dir(path.as_path()).unwrap();
        }
    }

    fn get_config_file(&self, file_name: &str) -> Result<FileMetadata, String> {
        // Return the metadata for the specified configuration file
        let mut path = PathBuf::from(ROOT_DIR);
        path.push(file_name);
        if !path.exists() {
            return Err("File does not exist".to_string());
        }

        // Read and hash the file
        let mut hasher = Hasher::new();
        hasher.update(&read_file(path).unwrap().as_slice()).unwrap();
        let hash = hasher.finalize().unwrap();

        // Return the metadata for the configuration file
        Ok(FileMetadata {
            path: path,
            size: get_file_size(path),
            hash: hash,
            timestamp: get_file_timestamp(path)
        })
    }

    fn set_config_file(&self, file_name: &str, content: String) -> Result<(), String> {
        // Write the specified configuration file with the provided content
        let mut path = PathBuf::from(ROOT_DIR);
        path.push(file_name);
        if !path.exists() {
            return Err("File does not exist".to_string());
        }

        // Write the file and update the cache
        write_file(path, content).unwrap();
        self.cache.insert(path, FileMetadata {
            path: path,
            size: get_file_size(path),
            hash: compute_hash(&content),
            timestamp: get_file_timestamp(path)
        });

        Ok(())
    }

    fn delete_config_file(&self, file_name: &str) -> Result<(), String> {
        // Delete the specified configuration file
        let mut path = PathBuf::from(ROOT_DIR);
        path.push(file_name);
        if !path.exists() {
            return Err("File does not exist".to_string());
        }

        // Delete the file and remove it from the cache
        fs::remove_file(path).unwrap();
        self.cache.remove(path);

        Ok(())
    }

    fn list_config_files(&self) -> Result<Vec<FileMetadata>, String> {
        // Return a list of metadata for all configuration files in the directory
        let mut path = PathBuf::from(ROOT_DIR);
        if !path.exists() {
            return Err("Directory does not exist".to_string());
        }

        // List all files and filter out directories
        let mut files: Vec<FileMetadata> = Vec::new();
        for entry in read_dir(path).unwrap().into_iter() {
            let entry_path = entry.path();
            if !entry_path.is_file() {
                continue;
            }

            // Read and hash the file
            let mut hasher = Hasher::new();
            hasher.update(&read_file(entry_path).unwrap().as_slice()).unwrap();
            let hash = hasher.finalize().unwrap();

            // Add the metadata for the configuration file to the list
            files.push(FileMetadata {
                path: entry_path,
                size: get_file_size(entry_path),
                hash: hash,
                timestamp: get_file_timestamp(entry_path)
            });
        }

        Ok(files)
    }
}
```
