    if (mysql_real_connect(&mysql, db_host, db_user, db_pass, db_name, db_port, NULL, 0) == NULL) {
        fprintf(stderr, "Error connecting to the database\n");
        exit(1);
    }
}

// Initialize the socket listening and processing threads
void init_sockets(void) {
    int i;
    for (i = 0; i < num_sockets; i++) {
        client_fd[i] = -1; // Set to invalid file descriptor initially
        pthread_create(&client_threads[i], NULL, &process_log, &client_addr[i]);
    }
}

// Process log messages from each socket
void *process_log(void *args) {
    struct sockaddr_in *client_addr = args;
    char log_buffer[buffer_size]; // Buffer for log message
    int num_bytes = 0; // Number of bytes read from the client
    json_t *json_data = NULL; // JSON data object for filtering
    pthread_mutex_lock(&lock);
    while (num_bytes > 0) {
        memset(log_buffer, 0, buffer_size);
        num_bytes = recvfrom(client_fd[i], log_buffer, buffer_size, 0, client_addr, &sin_len);
        if (num_bytes > 0) {
            // Process the log message
            process_log(log_buffer, num_bytes);
            // Increment the number of logs received
            num_logs++;
        } else {
            // Disconnect from the client
            close(client_fd[i]);
            client_fd[i] = -1;
        }
    }
    pthread_mutex_unlock(&lock);
}

// Process a single log message
void process_log(char *log_buffer, int num_bytes) {
    char log_message[num_bytes]; // Log message
    json_t *json_data = NULL; // JSON data object for filtering
    memcpy(log_message, log_buffer, num_bytes);
    // Parse the log message as JSON
    json_data = json_loads(log_message, 0, &error);
    if (json_data == NULL) {
        fprintf(stderr, "Error parsing JSON data: %s\n", error.text);
    } else {
        // Filter the log message based on HTTP method, response code, and client IP address
        json_t *http_method = json_object_get(json_data, "http-method");
        json_t *response_code = json_object_get(json_data, "response-code");
        json_t *client_ip = json_object_get(json_data, "client-ip");
        if (http_method == NULL || response_code == NULL || client_ip == NULL) {
            fprintf(stderr, "Error getting JSON data: %s\n", error.text);
        } else {
            // Insert the log message into the database
            insert_log(json_data);
        }
    }
}

// Insert a log message into the database
void insert_log(json_t *json_data) {
    char *query = "INSERT INTO logs (log) VALUES (?)";
    mysql_real_escape_string(&mysql, query, json_dumps(json_data), strlen(json_dumps(json_data)));
    if (mysql_query(&mysql, query) != 0) {
        fprintf(stderr, "Error inserting log into database\n");
    }
}

// Main function for the logging analytics platform
int main(void) {
    int i; // Loop counter
    pthread_t client_threads[num_sockets]; // Threads for each socket
    struct sockaddr_in server_addr; // Server address
    memset(&server_addr, 0, sizeof(struct sockaddr_in));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = htonl(INADDR_ANY);
    server_addr.sin_port = htons(PORT);
    if (bind(sock, (struct sockaddr *)&server_addr, sizeof(struct sockaddr)) < 0) {
        fprintf(stderr, "Error binding to socket\n");
        exit(1);
    }
    // Listen for incoming connections
    if (listen(sock, BACKLOG) < 0) {
        fprintf(stderr, "Error listening on socket\n");
        exit(1);
    }
    init_sockets(); // Initialize the socket threads
    while (1) {
        memset(&server_addr, 0, sizeof(struct sockaddr));
        if ((client_fd = accept(sock, (struct sockaddr *)&client_addr, &sin_len)) < 0) {
            fprintf(stderr, "Error accepting client connection\n");
            continue;
        }
        // Create a new thread to process the client request
        pthread_create(&client_threads[i], NULL, &process_log, &client_addr[i]);
    }
    return 0;
}
