                retryInterval = stoi(args[++i]);
            } else if (args[i] == "-a" && i + 1 < args.size()) {
                tracingAndMonitoringType = getTracingAndMonitoringType(args[++i]);
            } else if (args[i] == "-s" && i + 1 < args.size()) {
                monitoringEndpoints = vector<string>(args[++i].begin(), args[++i].end());
            } else if (args[i] == "-f" && i + 1 < args.size()) {
                inputFilePath = args[++i];
            } else if (args[i] == "-d" && i + 1 < args.size()) {
                outputFilePath = args[++i];
            }
        }
    }

    // Function to get the throttling mechanism type
    ThrottlingMechanism getThrottlingMechanism(const string& type) {
        if (type == "dynamic") {
            return ThrottlingMechanism::DYNAMIC;
        } else if (type == "static") {
            return ThrottlingMechanism::STATIC;
        } else {
            throw runtime_error("Invalid throttling mechanism type");
        }
    }

    // Function to get the role-based access control policy
