        if (policy == "whitelist") {
            return Policy::WHITELIST;
        } else if (policy == "blacklist") {
            return Policy::BLACKLIST;
        } else if (policy == "ratelimit") {
            return Policy::RATE_LIMIT;
        } else {
            throw runtime_error("Invalid role-based access control policy");
        }
    }

    // Function to get the distributed tracing and monitoring type
    TracingAndMonitoringType getTracingAndMonitoringType(const string& type) {
        if (type == "distributed") {
            return TracingAndMonitoringType::DISTRIBUTED_TRACING;
        } else if (type == "monitoring") {
            return TracingAndMonitoringType::MONITORING;
        } else {
            throw runtime_error("Invalid distributed tracing and monitoring type");
        }
    }

