        if not self.security_manager_service.authenticate_user("admin", "password"):
            return False
        else:
            return self.load_balancer_service.add_node(node)

    def remove_node(self, node):
        if not self.security_manager_service.authenticate_user("admin", "password"):
            return False
        else:
            return self.load_balancer_service.remove_node(node)

    def get_node(self):
        if not self.security_manager_service.authenticate_user("admin", "password"):
            return None
        else:
            return self.load_balancer_service.get_node()

