    def __init__(self, limit=10):
        self.limit = limit
        self.current_count = 0

    def increment_counter(self):
        self.current_count += 1
        if self.current_count > self.limit:
            return False
        else:
            return True

class SecurityManagerAPI:
    def __init__(self):
