namespace DynamicNotificationSystem
{
    public class NotificationManager
    {
        private readonly Dictionary<string, NotificationTemplate> _templates = new();
        private readonly Dictionary<string, UserProfile> _profiles = new();
        private readonly Dictionary<string, NotificationConnection> _connections = new();
        private readonly ILogger _logger;

        public NotificationManager(ILogger logger)
        {
            _logger = logger;
        }

        public async Task SendNotificationAsync(string userId, string templateId, object data)
        {
            if (!_templates.TryGetValue(templateId, out var template))
            {
                throw new ArgumentException($"Invalid notification template ID: {templateId}");
            }

            if (!_profiles.TryGetValue(userId, out var profile))
            {
                throw new ArgumentException($"Invalid user ID: {userId}");
            }

            foreach (var connection in _connections)
            {
                var notification = template.GetNotification(profile, data);
                await connection.SendAsync(notification).ConfigureAwait(false);
            }
        }

        public async Task RegisterTemplateAsync(string templateId, NotificationTemplate template)
        {
            _templates[templateId] = template;
        }

        public async Task RegisterUserProfileAsync(string userId, UserProfile profile)
        {
            _profiles[userId] = profile;
        }

        public async Task RegisterConnectionAsync(string connectionId, NotificationConnection connection)
        {
            _connections[connectionId] = connection;
        }
    }
}
```
