// Global variables
const std::string STRATEGY_ENDPOINT = "https://api.example.com/strategies";
const std::string CHARACTER_ENDPOINT = "https://api.example.com/characters";
const int API_TIMEOUT = 5000; // in milliseconds
const int COOLDOWN_PERIOD = 1000; // in milliseconds
const int CONCURRENT_EXECUTIONS = 8; // number of concurrent executions allowed
