// Exception class for API errors
class APIError : public std::runtime_error {
public:
    explicit APIError(const std::string& what) : runtime_error(what) {}
};

// Function to fetch strategy data from the REST API
std::vector<nlohmann::json> fetchStrategies() {
    CURL* curl;
    CURLcode res;
    std::string url = STRATEGY_ENDPOINT;
    std::vector<nlohmann::json> strategies;

    // Set up cURL handle and URL
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        curl_easy_setopt(curl, CURLOPT_TIMEOUT_MS, API_TIMEOUT);

        // Perform the request and handle errors
        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            throw APIError("API error: " + std::string(curl_easy_strerror(res)));
        }

        // Parse JSON response into vector of strategies
        nlohmann::json jsonResponse = nlohmann::json::parse(curl_easy_getinfo(curl, CURLINFO_RESPONSE_BODY));
        if (!jsonResponse.is_array()) {
            throw std::runtime_error("Invalid JSON response from API");
        }
        strategies = jsonResponse;
    }

    // Clean up cURL handle
    curl_easy_cleanup(curl);

    return strategies;
}

// Function to execute a strategy for a character
void executeStrategy(int characterId, int strategyId) {
    CURL* curl;
    CURLcode res;
    std::string url = CHARACTER_ENDPOINT + "/" + std::to_string(characterId);
    nlohmann::json jsonData;

    // Set up cURL handle and URL
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        curl_easy_setopt(curl, CURLOPT_TIMEOUT_MS, API_TIMEOUT);

        // Prepare JSON data for strategy execution request
        jsonData["characterId"] = characterId;
        jsonData["strategyId"] = strategyId;

        // Perform the request and handle errors
        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            throw APIError("API error: " + std::string(curl_easy_strerror(res)));
        }
    }

    // Clean up cURL handle
    curl_easy_cleanup(curl);
}

// Function to manage strategy execution and cooldowns for multiple characters concurrently
void executeOptimizedStrategy(std::vector<int> characterIds) {
    // Lock cooldown mutex to ensure thread safety during cooldown management
    std::lock_guard<std::mutex> lock(cooldownMutex);

    // Fetch strategies from API and handle errors
    try {
        std::vector<nlohmann::json> strategies = fetchStrategies();
        if (strategies.empty()) {
            throw std::runtime_error("No strategies found");
        }
    } catch (const std::exception& e) {
        std::cerr << "Error fetching strategies: " << e.what() << std::endl;
        return;
    }

    // Execute strategies concurrently for each character, enforcing cooldowns and handling delays
    std::vector<std::future<void>> futures;
    for (int characterId : characterIds) {
        try {
            int strategyId = getOptimalStrategy(characterId);
            if (!strategyId) {
                // No suitable strategies found, try again later
                continue;
            }

            // Check cooldown period and schedule execution if necessary
            std::chrono::system_clock::time_point currentTime = std::chrono::system_clock::now();
            auto it = cooldownTimes.find(characterId);
            if (it != cooldownTimes.end() && it->second > currentTime) {
                // Cooldown period not yet elapsed, schedule execution later
                futures.push_back(std::async(executeStrategy, characterId, strategyId));
            } else {
                // No cooldown or cooldown elapsed, execute strategy immediately
                executeStrategy(characterId, strategyId);
            }
        } catch (const std::exception& e) {
            std::cerr << "Error executing strategy: " << e.what() << std::endl;
        }
    }

    // Wait for all concurrent executions to complete
    if (!futures.empty()) {
        try {
            for (auto& future : futures) {
                future.wait();
            }
        } catch (const std::exception& e) {
            std::cerr << "Error waiting for concurrent executions: " << e.what() << std::endl;
        }
    }
}

// Function to simulate realistic strategy preparation times with intentional delays
void delayStrategyPreparation(int characterId, int strategyId) {
    // Add intentional delay for simulation purpose
    std::this_thread::sleep_for(std::chrono::seconds(5));
}

// Function to get optimal strategy for a character based on cooldown and effectiveness metrics
int getOptimalStrategy(int characterId) {
    // Simulate realistic strategy preparation time with intentional delay
    delayStrategyPreparation(characterId, 0);

    // Fetch strategies from API and handle errors
    try {
        std::vector<nlohmann::json> strategies = fetchStrategies();
        if (strategies.empty()) {
            throw std::runtime_error("No strategies found");
        }
    } catch (const std::exception& e) {
        std::cerr << "Error fetching strategies: " << e.what() << std::endl;
        return 0;
    }

    // Evaluate each strategy and select optimal one based on cooldown and effectiveness metrics
    int optimalStrategyId = 0;
    for (auto& strategy : strategies) {
        // Check cooldown period and schedule execution if necessary
        std::chrono::system_clock::time_point currentTime = std::chrono::system_clock::now();
        auto it = cooldownTimes.find(characterId);
        if (it != cooldownTimes.end() && it->second > currentTime) {
            // Cooldown period not yet elapsed, skip strategy for now
            continue;
        }

        // Evaluate strategy effectiveness based on metrics
        int effectivenessMetric = evaluateStrategyEffectiveness(characterId, strategy);
        if (effectivenessMetric > 0) {
            optimalStrategyId = strategy["id"];
        }
    }

    return optimalStrategyId;
}

// Function to evaluate strategy effectiveness based on metrics
int evaluateStrategyEffectiveness(int characterId, nlohmann::json strategy) {
    // Simulate realistic strategy preparation time with intentional delay
    delayStrategyPreparation(characterId, strategy["id"]);

    // Fetch data from API and handle errors
    try {
        std::vector<nlohmann::json> characterData = fetchCharacterData();
        if (characterData.empty()) {
            throw std::runtime_error("No character data found");
        }
    } catch (const std::exception& e) {
        std::cerr << "Error fetching character data: " << e.what() << std::endl;
        return 0;
    }

    // Evaluate strategy effectiveness based on metrics
    int effectivenessMetric = 0;
    for (auto& dataPoint : characterData) {
        if (dataPoint["characterId"] == characterId) {
            // Check if strategy was previously executed and if so, evaluate effectiveness based on previous results
            if (dataPoint["strategyId"] == strategy["id"]) {
                int previousEffectivenessMetric = dataPoint["effectivenessMetric"];
                if (previousEffectivenessMetric > 0) {
                    effectivenessMetric += previousEffectivenessMetric;
                } else {
                    // Previous execution failed, skip strategy for now
                    continue;
                }
            }
        }
    }

    return effectivenessMetric;
}

