### Solution 3 - Using C++ asynchronous programming with futures (std::async and std::future)

The third solution uses the C++ `std::async` function to create a future object for each character and then waits for their completion using the `std::future::get()` method. The `std::async` function returns an object of type `std::future`, which allows us to schedule an asynchronous computation, capture variables by value or reference, and return a result when the computation completes.

```cpp
#include <iostream>
#include <future>
#include <vector>

// Function to fetch character data from API
std::vector<nlohmann::json> fetchCharacterData() {
    // Fetch character data from API and handle errors
    try {
        // Fetch character data from API
        std::vector<nlohmann::json> characterData = apiClient.get("/characters");
        if (characterData.empty()) {
            throw std::runtime_error("No character data found");
        }
        return characterData;
    } catch (const std::exception& e) {
        // Handle API errors and log messages
        handleApiErrorsAndLogMessages(e.what());
    }
}

// Function to execute strategy for a single character
std::future<void> executeStrategyForCharacter(int characterId) {
    try {
        // Fetch strategy data from API
        nlohmann::json strategyData = apiClient.get("/strategies/" + std::to_string(characterId));
        if (strategyData.empty()) {
            throw std::runtime_error("No strategy data found");
        }
        // Execute strategy for character asynchronously using std::async and return a future object
        return std::async(std::launch::async, [&apiClient, characterId, strategyData]() {
            apiClient.post("/characters/" + std::to_string(characterId) + "/executeStrategy", strategyData);
        });
    } catch (const std::exception& e) {
        // Handle API errors and log messages
        handleApiErrorsAndLogMessages(e.what());
    }
}

// Function to manage cooldowns for multiple characters
void executeOptimizedStrategy(std::vector<int> characterIds) {
    try {
        // Create a future object for each character and wait for their completion using std::future::get()
        std::vector<std::future<void>> futures;
        for (auto characterId : characterIds) {
            futures.emplace_back(executeStrategyForCharacter(characterId));
        }
        // Wait for all futures to complete using std::future::get()
        for (auto& future : futures) {
            future.get();
        }
    } catch (const std::exception& e) {
        // Handle API errors and log messages
        handleApiErrorsAndLogMessages(e.what());
    }
}

int main() {
    // Initialize API client and set up logging for errors and messages
    initApiClient();
    initLogger();

    // Fetch character data from API and handle errors
    std::vector<nlohmann::json> characterData = fetchCharacterData();
    if (characterData.empty()) {
        return 0;
    }

    // Execute optimized strategy for multiple characters using C++ asynchronous programming with futures (std::async and std::future)
    executeOptimizedStrategy({1, 2, 3});
