// Define the function to load the state from a file
int load_state(const char* path, struct MoSTState** state) {
    // Open the file and read it into memory
    FILE* fp = fopen(path, "r");
    if (fp == NULL) {
        printf("Error: failed to open file %s\n", path);
        return -1;
    }
    fseek(fp, 0, SEEK_END);
    long len = ftell(fp);
    rewind(fp);
    char* buffer = malloc(len + 1);
    if (buffer == NULL) {
        printf("Error: failed to allocate memory for file %s\n", path);
        return -1;
    }
    fread(buffer, len, 1, fp);
    fclose(fp);
    buffer[len] = '\0';

    // Parse the JSON data and store it in the state object
    json_error_t error;
    json_t* root = json_loads(buffer, 0, &error);
    if (root == NULL) {
        printf("Error: failed to parse JSON data from %s\n", path);
        return -1;
    }
    struct MoSTState* state_ptr = malloc(sizeof(struct MoSTState));
    state_ptr->json = buffer;
    state_ptr->json_len = len;
    json_decref(root);

    // Open the CSV file and store it in the state object
    state_ptr->csv_fd = open(path, O_RDONLY);
    if (state_ptr->csv_fd == -1) {
        printf("Error: failed to open CSV file %s\n", path);
        return -1;
    }

    // Return the state object
    *state = state_ptr;
    return 0;
}

// Define the function to validate the state
int validate_state(struct MoSTState* state) {
    // Check if the JSON data is valid
    json_error_t error;
    json_t* root = json_loads(state->json, 0, &error);
    if (root == NULL) {
        printf("Error: failed to parse JSON data from state\n");
        return -1;
    }
    json_decref(root);

    // Check if the CSV file is valid
    struct stat sb;
    if (fstat(state->csv_fd, &sb) == -1) {
        printf("Error: failed to open CSV file %s\n", state->csv_fd);
        return -1;
    }

    // Return success if both the JSON and CSV data are valid
    return 0;
}

// Define the function to update the state
int update_state(struct MoSTState* state, const char* path) {
    // Load the new state from the file
    struct MoSTState* new_state = NULL;
    int ret = load_state(path, &new_state);
    if (ret != 0) {
        printf("Error: failed to load new state\n");
        return -1;
    }

    // Validate the new state
    ret = validate_state(new_state);
    if (ret != 0) {
        printf("Error: failed to validate new state\n");
        free(new_state);
        return -1;
    }

    // Update the JSON data in the state object
    char* json = realloc(state->json, new_state->json_len + 1);
    if (json == NULL) {
        printf("Error: failed to allocate memory for new JSON data\n");
        free(new_state);
        return -1;
    }
    memcpy(json, new_state->json, new_state->json_len + 1);
    state->json = json;
    state->json_len = new_state->json_len;

    // Update the CSV file in the state object
    int csv_fd = open(path, O_RDONLY);
    if (csv_fd == -1) {
        printf("Error: failed to open CSV file %s\n", path);
        free(new_state);
        return -1;
    }
    state->csv_fd = csv_fd;

    // Free the memory for the new state object
    free(new_state);

    // Return success
    return 0;
}

