#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <errno.h>

#define PORT 8080
#define BUFFER_SIZE 1024
#define MAX_CONNECTIONS 5

// Structure to store information about each connection
typedef struct {
    int socket; // Socket file descriptor
    char* data; // Buffer to store incoming data
} connection_t;

// Function to handle connections
void* handleConnection(void* args) {
    connection_t* conn = (connection_t*)args;
    ssize_t bytesReceived;
    size_t totalBytesReceived = 0;
    char buffer[BUFFER_SIZE];

    // Receive data until the client closes the socket
    while ((bytesReceived = recv(conn->socket, buffer, BUFFER_SIZE, 0)) > 0) {
        totalBytesReceived += bytesReceived;
        printf("Received %zu bytes from client\n", totalBytesReceived);
    }

    // Check if an error occurred during receiving
    if (bytesReceived < 0) {
        perror("recv");
    } else {
        printf("Client closed the socket\n");
    }

    close(conn->socket);
    free(conn->data);
    free(conn);
    return NULL;
}

int main() {
    int serverSocket, clientSocket;
    socklen_t clientLen = sizeof(clientSocket);
    struct sockaddr_in serverAddr, clientAddr;
    connection_t* conn;

    // Create a socket for the server
    if ((serverSocket = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket");
        exit(1);
    }

    // Set up the address structure
    memset(&serverAddr, 0, sizeof(serverAddr));
    serverAddr.sin_family = AF_INET;
    serverAddr.sin_addr.s_addr = INADDR_ANY;
    serverAddr.sin_port = htons(PORT);

    // Bind the socket to our address and port
    if (bind(serverSocket, (struct sockaddr*)&serverAddr, sizeof(serverAddr)) < 0) {
        perror("bind");
        exit(1);
    }

    // Listen for incoming connections
    if (listen(serverSocket, MAX_CONNECTIONS) < 0) {
        perror("listen");
        exit(1);
    }

    while (1) {
        clientLen = sizeof(clientAddr);

        // Accept an incoming connection
        if ((clientSocket = accept(serverSocket, (struct sockaddr*)&clientAddr, &clientLen)) < 0) {
            perror("accept");
            continue;
        }

        printf("New client connected from %s:%d\n", inet_ntoa(clientAddr.sin_addr), ntohs(clientAddr.sin_port));

        // Create a new connection structure and save the socket file descriptor and buffer
        conn = (connection_t*)malloc(sizeof(connection_t));
        conn->socket = clientSocket;
        conn->data = (char*)malloc(BUFFER_SIZE);

        // Spawn a thread to handle this connection
        pthread_t tid;
        if (pthread_create(&tid, NULL, handleConnection, conn) < 0) {
            perror("pthread_create");
            exit(1);
        }
    }
}']

