    int latency;
    bool active;
};

// Define a map to store all the network connection status indicators
using NetworkStatusMap = std::map<std::string, NetworkStatus>;

// Define a function to add a new network connection status indicator
void addNetworkStatus(const std::string& ipAddress, uint16_t port) {
    // Check if the IP address and port combination already exists in the map
    if (networkStatusMap.find(ipAddress + ":" + port) != networkStatusMap.end()) {
        return;
    }

    // Add a new entry to the map with the specified IP address and port
    NetworkStatus status = {ipAddress, port, 0, false};
    networkStatusMap[ipAddress + ":" + port] = status;
}

// Define a function to update an existing network connection status indicator
void updateNetworkStatus(const std::string& ipAddress, uint16_t port) {
    // Check if the IP address and port combination exists in the map
    if (networkStatusMap.find(ipAddress + ":" + port) == networkStatusMap.end()) {
        return;
    }

    // Update the latency value for the specified IP address and port
    NetworkStatus& status = networkStatusMap[ipAddress + ":" + port];
    ++status.latency;
}

// Define a function to remove an existing network connection status indicator
void removeNetworkStatus(const std::string& ipAddress, uint16_t port) {
    // Check if the IP address and port combination exists in the map
    if (networkStatusMap.find(ipAddress + ":" + port) == networkStatusMap.end()) {
        return;
    }

    // Remove the entry from the map for the specified IP address and port
    networkStatusMap.erase(ipAddress + ":" + port);
}

// Define a function to serialize the connection status database into a binary file
void saveNetworkStatusDatabase(const std::string& filename) {
    // Create a binary output stream to write to the file
    boost::serialization::binary_oarchive oa(filename, boost::serialization::binary_file_format::binary);

    // Serialize the entire map of network status indicators into the archive
    for (const auto& [ipAddress, port] : networkStatusMap) {
        const NetworkStatus& status = networkStatusMap[ipAddress + ":" + port];
        oa & BOOST_SERIALIZATION_NVP(status);
    }
}

// Define a function to deserialize the connection status database from a binary file
void loadNetworkStatusDatabase(const std::string& filename) {
    // Create a binary input stream to read from the file
    boost::serialization::binary_iarchive ia(filename, boost::serialization::binary_file_format::binary);

    // Deserialize the entire map of network status indicators from the archive
    for (const auto& [ipAddress, port] : networkStatusMap) {
        NetworkStatus& status = networkStatusMap[ipAddress + ":" + port];
        ia & BOOST_SERIALIZATION_NVP(status);
    }
}
