// Struct representing a thread-safe resource pool manager for filename generation
struct ResourcePoolManager {
    // Pool of available resources
    std::vector<FileNameInfo*> pool_;
    // Mutex to protect the pool from concurrent access
    std::mutex mutex_;

    // Allocate a new resource in the pool
    FileNameInfo* allocate() {
        std::lock_guard<std::mutex> lock(mutex_);
        if (pool_.size() == 0) {
            return nullptr;
        } else {
            auto resource = pool_.back();
            pool_.pop_back();
            return resource;
        }
    }

    // Release a resource back to the pool
    void release(FileNameInfo* info) {
        std::lock_guard<std::mutex> lock(mutex_);
        pool_.push_back(info);
    }
};

// Struct representing a filename generation configuration
struct Configuration {
    // Timestamp format (e.g., %Y%m%d-%H%M%S)
    std::string timestampFormat_;
