fn parse_log(log: &str) -> Result<HashMap<String, Value>, ParseError> {
    let mut parsed = HashMap::new();

    // Parse the log using the appropriate format based on the source
    match log.parse() {
        Ok(json) => {
            parsed.insert("log".to_string(), json);
        }
        Err(_) => {
            return Err(ParseError::new("Failed to parse log"));
        }
    };

    // Apply customizable filters based on request methods, response codes, client IP addresses, and user roles
    parsed.retain(|k, v| matches!(v, Value::Number(_) => k == "request_method" || k == "response_code" || k == "client_ip_address" || k == "user_role"));

    // Handle daylight saving time changes and account for heterogeneous log formats
    parsed.insert("time".to_string(), format!("{}", parsed["time"].timestamp().unwrap()));

    Ok(parsed)
}

fn create_parser(format: &str, source: &str) -> Result<HashMap<String, Value>, ParseError> {
    match format.parse() {
        Ok(json) => {
            let mut parsed = HashMap::new();
            parsed.insert("log".to_string(), json);
            parsed.retain(|k, v| matches!(v, Value::Number(_) => k == "request_method" || k == "response_code" || k == "client_ip_address" || k == "user_role"));
            parsed.insert("time".to_string(), format!("{}", parsed["time"].timestamp().unwrap()));
            Ok(parsed)
        }
        Err(_) => {
            return Err(ParseError::new("Failed to parse log"));
