#include <openssl/modes.h>
#include <openssl/ossl_typ.h>
#include <openssl/err.h>
#include "encryption.h"

/* Function to encrypt data using AES */
int aes_encrypt(unsigned char *plaintext, unsigned char *key, unsigned char *iv, int plaintext_len, int key_len, int iv_len) {
	// Initialize variables
	EVP_CIPHER_CTX *ctx;
	size_t len;
	int ret = 0;

	// Create and initialize the context for AES encryption
	if (!(ctx = EVP_CIPHER_CTX_new())) {
		ERR_load_crypto_strings();
		printf("[!] EVP_CIPHER_CTX_new failed.\n");
	}

	// Set the encryption algorithm and mode
	if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv)) {
		printf("[!] EVP_EncryptInit_ex failed.\n");
	}

	// Provide the plaintext to be encrypted
	if (!EVP_EncryptUpdate(ctx, plaintext, &len, plaintext, plaintext_len)) {
		ERR_load_crypto_strings();
		printf("[!] EVP_EncryptUpdate failed.\n");
	}

	// Finalize the encryption operation
	if (!EVP_EncryptFinal_ex(ctx, plaintext + len, &len)) {
		ERR_load_crypto_strings();
		printf("[!] EVP_EncryptFinal_ex failed.\n");
	}

	// Free the context
	EVP_CIPHER_CTX_free(ctx);

	return ret;
}

/* Function to decrypt data using AES */
int aes_decrypt(unsigned char *ciphertext, unsigned char *key, unsigned char *iv, int ciphertext_len, int key_len, int iv_len) {
	// Initialize variables
	EVP_CIPHER_CTX *ctx;
	size_t len;
	int ret = 0;

	// Create and initialize the context for AES decryption
	if (!(ctx = EVP_CIPHER_CTX_new())) {
		ERR_load_crypto_strings();
		printf("[!] EVP_CIPHER_CTX_new failed.\n");
	}

	// Set the decryption algorithm and mode
	if (!EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv)) {
		printf("[!] EVP_DecryptInit_ex failed.\n");
	}

	// Provide the ciphertext to be decrypted
	if (!EVP_DecryptUpdate(ctx, ciphertext, &len, ciphertext, ciphertext_len)) {
		ERR_load_crypto_strings();
		printf("[!] EVP_DecryptUpdate failed.\n");
	}

	// Finalize the decryption operation
	if (!EVP_DecryptFinal_ex(ctx, ciphertext + len, &len)) {
		ERR_load_crypto_strings();
		printf("[!] EVP_DecryptFinal_ex failed.\n");
	}

	// Free the context
	EVP_CIPHER_CTX_free(ctx);

	return ret;
}

/* Function to encrypt data using ChaCha20 */
int chacha20_encrypt(unsigned char *plaintext, unsigned char *key, unsigned char *nonce, int plaintext_len, int key_len, int nonce_len) {
	// Initialize variables
	chacha20_ctx ctx;
	size_t len;
	int ret = 0;

	// Create and initialize the context for ChaCha20 encryption
	if (!chacha20_init(&ctx, key, nonce, key_len, nonce_len)) {
		printf("[!] chacha20_init failed.\n");
	}

	// Provide the plaintext to be encrypted
	if (!chacha20_encrypt(&ctx, plaintext, plaintext, plaintext_len)) {
		printf("[!] chacha20_encrypt failed.\n");
	}

	return ret;
}

/* Function to decrypt data using ChaCha20 */
int chacha20_decrypt(unsigned char *ciphertext, unsigned char *key, unsigned char *nonce, int ciphertext_len, int key_len, int nonce_len) {
	// Initialize variables
	chacha20_ctx ctx;
	size_t len;
	int ret = 0;

	// Create and initialize the context for ChaCha20 decryption
	if (!chacha20_init(&ctx, key, nonce, key_len, nonce_len)) {
		printf("[!] chacha20_init failed.\n");
	}

	// Provide the ciphertext to be decrypted
	if (!chacha20_decrypt(&ctx, ciphertext, ciphertext, ciphertext_len)) {
		printf("[!] chacha20_decrypt failed.\n");
	}

	return ret;
}

/* Function to encrypt data using ChaCha20-Poly1305 */
int chacha20poly1305_encrypt(unsigned char *plaintext, unsigned char *key, unsigned char *nonce, int plaintext_len, int key_len, int nonce_len) {
	// Initialize variables
	chacha20poly1305_ctx ctx;
	size_t len;
	int ret = 0;

	// Create and initialize the context for ChaCha20-Poly1305 encryption
	if (!chacha20poly1305_init(&ctx, key, nonce, key_len, nonce_len)) {
		printf("[!] chacha20poly1305_init failed.\n");
	}

	// Provide the plaintext to be encrypted
