	}

	return ret;
}

/* Function to sign data using Ed25519 */
int ed25519_sign(unsigned char *message, unsigned char *private_key, int message_len, unsigned char *signature, int signature_len) {
	// Initialize variables
	ed25519_ctx ctx;
	size_t len;
	int ret = 0;

