		printf("[!] ed25519_sign failed.\n");
	}

	return ret;
}

/* Function to verify the signature using Ed25519 */
int ed25519_verify(unsigned char *message, unsigned char *public_key, int message_len, unsigned char *signature, int signature_len) {
	// Initialize variables
