public class DynamicLogger {
    private static final Map<String, String> LOG_LEVELS = new HashMap<>();
    private static final List<LogDestination> LOG_DESTINATIONS = new ArrayList<>();

    // Initialize log levels and destinations on startup
    static {
        LOG_LEVELS.put("DEBUG", "0");
        LOG_LEVELS.put("INFO", "1");
        LOG_LEVELS.put("WARNING", "2");
        LOG_LEVELS.put("ERROR", "3");
        LOG_DESTINATIONS.add(new ConsoleLogDestination());
    }

    private static void initialize() {
        // Initialize monitoring and tracing tools here
    }

    public static void log(String message, String level) {
        if (LOG_LEVELS.containsKey(level)) {
            int logLevel = Integer.parseInt(LOG_LEVELS.get(level));
            for (LogDestination destination : LOG_DESTINATIONS) {
                destination.log(message, logLevel);
            }
        } else {
            System.out.println("Invalid log level: " + level);
        }
    }

    public static void addLogDestination(LogDestination destination) {
        LOG_DESTINATIONS.add(destination);
    }

    public static void removeLogDestination(LogDestination destination) {
        LOG_DESTINATIONS.remove(destination);
    }

    // ConsoleLogDestination implementation
    private static class ConsoleLogDestination implements LogDestination {
        @Override
        public void log(String message, int level) {
            System.out.println("[" + LOG_LEVELS.get(level) + "] " + message);
        }
    }

    // FileLogDestination implementation
    private static class FileLogDestination implements LogDestination {
        private final String filename;

        public FileLogDestination(String filename) {
            this.filename = filename;
        }

        @Override
        public void log(String message, int level) {
            try (FileWriter writer = new FileWriter(filename)) {
                writer.write("[" + LOG_LEVELS.get(level) + "] " + message + "\n");
            } catch (IOException e) {
                System.out.println("Error writing to file: " + filename);
            }
        }
    }

