['```csharp
using System;
using System.Collections.Generic;
using System.Data;
using System.Threading;
using System.Threading.Tasks;

namespace ModularCApp
{
    public class SemaphoreManager
    {
        private readonly Dictionary<string, SemaphoreSlim> _semaphores = new Dictionary<string, SemaphoreSlim>();

        public void Initialize(int initialValue = 1)
        {
            foreach (var semaphore in _semaphores.Values)
            {
                semaphore.Release();
            }
        }

        public void Acquire(string semaphoreName, int count = 1)
        {
            if (!_semaphores.TryGetValue(semaphoreName, out var semaphore))
            {
                semaphore = new SemaphoreSlim(initialValue);
                _semaphores[semaphoreName] = semaphore;
            }

            while (count > 0)
            {
                if (!semaphore.Wait(1000))
                {
                    throw new TimeoutException($"Failed to acquire semaphore '{semaphoreName}' within the timeout period");
                }

                count--;
            }
        }

        public void Release(string semaphoreName, int count = 1)
        {
            if (!_semaphores.TryGetValue(semaphoreName, out var semaphore))
            {
                throw new InvalidOperationException($"Semaphore '{semaphoreName}' does not exist");
            }

            while (count > 0)
            {
                semaphore.Release();
                count--;
            }
        }
    }

    public class ConnectionPool<T> where T : IDisposable
    {
        private readonly List<T> _connections = new List<T>();
        private readonly object _lock = new object();

        public int Size => _connections.Count;

        public async Task<T> AcquireAsync(Func<Task<T>> factory)
        {
            T connection = null;

            lock (_lock)
            {
                if (_connections.Count > 0)
                {
                    connection = _connections[0];
                    _connections.RemoveAt(0);
                }
            }

            if (connection == null)
            {
                connection = await factory();
            }

            return connection;
        }

        public void Release(T connection)
        {
            lock (_lock)
            {
                _connections.Add(connection);
            }
        }
    }

    public class SqlExecutor
    {
        private readonly ConnectionPool<SqlConnection> _connectionPool;
        private readonly SemaphoreManager _semaphoreManager;

        public SqlExecutor(int connectionCount, int semaphoreInitialValue = 1)
        {
            _connectionPool = new ConnectionPool<SqlConnection>(connectionCount);
            _semaphoreManager = new SemaphoreManager();
            _semaphoreManager.Initialize(semaphoreInitialValue);
        }

        public async Task<IDataReader> ExecuteReaderAsync(string connectionString, string commandText)
        {
            var semaphoreName = $"{connectionString}#{commandText}";
            _semaphoreManager.Acquire(semaphoreName);

            using (var connection = await _connectionPool.AcquireAsync(() => CreateConnectionAsync(connectionString)))
            {
                try
                {
                    var command = new SqlCommand(commandText, connection);
                    return await command.ExecuteReaderAsync();
                }
                catch (Exception ex) when (!ex.IsFatal())
                {
                    _semaphoreManager.Release(semaphoreName);
                    throw;
                }
            }
        }

        private async Task<SqlConnection> CreateConnectionAsync(string connectionString)
        {
            var connection = new SqlConnection(connectionString);
            await connection.OpenAsync();
            return connection;
        }
    }

    public class RetryPolicy
    {
        private readonly int _maxRetries;
        private readonly TimeSpan _backoffPeriod;
        private int _currentRetryCount = 0;
        private DateTime _lastFailureTime;

        public RetryPolicy(int maxRetries, TimeSpan backoffPeriod)
        {
            _maxRetries = maxRetries;
            _backoffPeriod = backoffPeriod;
        }

        public async Task<T> ExecuteAsync<T>(Func<Task<T>> action)
        {
            while (true)
            {
                try
                {
                    return await action();
                }
                catch (Exception ex) when (!ex.IsFatal())
                {
                    if (_currentRetryCount >= _maxRetries || DateTime.Now - _lastFailureTime > _backoffPeriod)
                    {
                        throw;
                    }

                    _currentRetryCount++;
                    _lastFailureTime = DateTime.Now;
                    await Task.Delay(_backoffPeriod);
                }
            }
        }
    }

    public class LoggingService
    {
        private readonly ILogger _logger;

        public LoggingService(ILogger logger)
        {
            _logger = logger;
        }

        public void Critical(Exception ex, string message = null) => _logger.LogError(ex, message);
        public void Error(string message) => _logger.LogError(message);
        public void Warning(string message) => _logger.LogWarning(message);
        public void Information(string message) => _logger.LogInformation(message);
    }
}
```
