// Define the cache for storing resource bundles
static struct ResourceBundle* cache = NULL;

// Define the function to initialize the cache
void initCache() {
  // Allocate memory for the cache
  cache = malloc(sizeof(struct ResourceBundle*) * MAX_CONCURRENT_REQUESTS);
  if (cache == NULL) {
    printf("Failed to allocate memory for the cache\n");
    exit(1);
  }
  memset(cache, 0, sizeof(struct ResourceBundle*) * MAX_CONCURRENT_REQUESTS);
}

// Define the function to destroy the cache
void destroyCache() {
  // Free the memory for the cache
  if (cache != NULL) {
    free(cache);
    cache = NULL;
  }
}

// Define the function to clear the cache
void clearCache() {
  // Clear the cache entries
  memset(cache, 0, sizeof(struct ResourceBundle*) * MAX_CONCURRENT_REQUESTS);
}

// Define the function to add a resource bundle to the cache
int addToCache(const char* id, const char* type, const char* format, const char* data) {
