    printf("The cache is full\n");
    return -1;
  }

  // Find an empty slot in the cache
  int index = 0;
  while (index < MAX_CONCURRENT_REQUESTS && cache[index].id != NULL) {
    index++;
  }

  // Add the resource bundle to the cache
  if (index < MAX_CONCURRENT_REQUESTS) {
    cache[index].id = strdup(id);
    cache[index].type = strdup(type);
    cache[index].format = strdup(format);
    cache[index].data = strdup(data);
  } else {
    printf("Failed to add the resource bundle to the cache\n");
    return -1;
  }

  // Return the index of the added resource bundle in the cache
  return index;
}

// Define the function to remove a resource bundle from the cache
