  // Find the resource bundle in the cache
  int index = findInCache(id);
  if (index < 0) {
    printf("Failed to find the resource bundle in the cache\n");
    return -1;
  }

  // Remove the resource bundle from the cache
  if (index < MAX_CONCURRENT_REQUESTS) {
    free(cache[index].id);
    free(cache[index].type);
    free(cache[index].format);
    free(cache[index].data);
    cache[index].id = NULL;
    cache[index].type = NULL;
    cache[index].format = NULL;
    cache[index].data = NULL;
  } else {
    printf("Failed to remove the resource bundle from the cache\n");
    return -1;
  }

  // Return the index of the removed resource bundle in the cache
  return index;
}

// Define the function to find a resource bundle in the cache
int findInCache(const char* id) {
