    return index;
  } else {
    printf("Failed to find the resource bundle in the cache\n");
    return -1;
  }
}

// Define the function to retrieve a resource bundle from the cache
struct ResourceBundle* getFromCache(const char* id) {
  // Find the resource bundle in the cache
  int index = findInCache(id);
  if (index < 0) {
    printf("Failed to find the resource bundle in the cache\n");
    return NULL;
  }

  // Return the retrieved resource bundle from the cache
  struct ResourceBundle* bundle = malloc(sizeof(struct ResourceBundle));
  if (bundle == NULL) {
    printf("Failed to allocate memory for the retrieved resource bundle\n");
    exit(1);
  }
  memcpy(bundle, &cache[index], sizeof(struct ResourceBundle));
