// Define the function to retrieve a list of resource bundles from the cache
struct ResourceBundle* getListFromCache() {
  // Allocate memory for the retrieved list of resource bundles
  struct ResourceBundle* list = malloc(sizeof(struct ResourceBundle) * numEntriesInCache());
  if (list == NULL) {
    printf("Failed to allocate memory for the retrieved list of resource bundles\n");
    exit(1);
  }

  // Retrieve the list of resource bundles from the cache
  int index = 0;
  while (index < MAX_CONCURRENT_REQUESTS && cache[index].id != NULL) {
    memcpy(&list[index], &cache[index], sizeof(struct ResourceBundle));
    index++;
  }

  // Return the retrieved list of resource bundles from the cache
  return list;
}

// Define the function to check if a resource bundle exists in the cache
int isInCache(const char* id) {
  // Check if the cache is empty
  if (cache == NULL || numEntriesInCache() <= 0) {
    printf("The cache is empty\n");
    return -1;
  }

  // Find the resource bundle in the cache
  int index = findInCache(id);

  // Return the result of checking if a resource bundle exists in the cache
  if (index < MAX_CONCURRENT_REQUESTS) {
    return 1;
  } else {
    return 0;
  }
}

// Define the function to retrieve the number of entries in the cache
int numEntriesInCache() {
  // Check if the cache is empty
  if (cache == NULL) {
    printf("The cache is empty\n");
    return -1;
  }

  // Return the number of entries in the cache
  int count = 0;
  while (count < MAX_CONCURRENT_REQUESTS && cache[count].id != NULL) {
    count++;
  }
  return count;
}

// Define the function to retrieve the total size of the cache
int totalSizeInCache() {
  // Check if the cache is empty
  if (cache == NULL || numEntriesInCache() <= 0) {
    printf("The cache is empty\n");
    return -1;
  }

  // Retrieve the total size of the cache
  int total_size = 0;
  while (total_size < MAX_CONCURRENT_REQUESTS && cache[total_size].id != NULL) {
    total_size++;
  }
  return total_size;
}

// Define the function to clear the cache
void clearCache() {
  // Check if the cache is empty
  if (cache == NULL || numEntriesInCache() <= 0) {
    printf("The cache is empty\n");
    return;
  }

  // Clear the cache
  int index = 0;
  while (index < MAX_CONCURRENT_REQUESTS && cache[index].id != NULL) {
    free(cache[index].id);
    cache[index].id = NULL;
    index++;
  }
}

// Define the function to add a resource bundle to the cache
void addToCache(struct ResourceBundle* bundle) {
  // Check if the cache is full
  if (totalSizeInCache() == MAX_CONCURRENT_REQUESTS) {
    printf("The cache is full\n");
    return;
  }

  // Add the resource bundle to the cache
  int index = totalSizeInCache();
  cache[index].id = malloc(strlen(bundle->id) + 1);
  strcpy(cache[index].id, bundle->id);
  cache[index].type = bundle->type;
  cache[index].uri = bundle->uri;
}

// Define the function to retrieve a resource bundle from the cache based on its ID
struct ResourceBundle* getResourceBundleFromCache(const char* id) {
  // Check if the cache is empty
  if (cache == NULL || numEntriesInCache() <= 0) {
    printf("The cache is empty\n");
    return NULL;
  }

  // Retrieve the resource bundle from the cache based on its ID
  int index = findInCache(id);
  if (index < MAX_CONCURRENT_REQUESTS) {
    struct ResourceBundle* bundle = malloc(sizeof(struct ResourceBundle));
    if (bundle == NULL) {
      printf("Failed to allocate memory for the retrieved resource bundle\n");
      exit(1);
    }
    memcpy(bundle, &cache[index], sizeof(struct ResourceBundle));
    return bundle;
  } else {
    return NULL;
  }
}
