class ConnectionStatus {
public:
    ConnectionStatus() : active_(true) {}

    bool isActive() const { return active_; }

    void setInactive() { active_ = false; }

private:
    bool active_;
};

class ConnectionManager {
public:
    static std::unique_ptr<ConnectionManager> instance() {
        static std::unique_ptr<ConnectionManager> sInstance(new ConnectionManager());
        return sInstance;
    }

    void addConnection(const std::string& ipAddress, uint16_t port) {
        std::lock_guard<std::mutex> lock(mutex_);
        connections_.emplace(ipAddress + ":" + std::to_string(port), ConnectionStatus());
    }

    void removeConnection(const std::string& ipAddress, uint16_t port) {
        std::lock_guard<std::mutex> lock(mutex_);
        connections_.erase(ipAddress + ":" + std::to_string(port));
    }

    void setConnectionStatus(const std::string& ipAddress, uint16_t port, bool active) {
        std::lock_guard<std::mutex> lock(mutex_);
        connections_[ipAddress + ":" + std::to_string(port)]->setInactive();
    }

    void updateConnectionStatus(const std::string& ipAddress, uint16_t port) {
        std::lock_guard<std::mutex> lock(mutex_);
        connections_[ipAddress + ":" + std::to_string(port)]->setActive();
    }

    bool isConnectionActive(const std::string& ipAddress, uint16_t port) const {
        std::lock_guard<std::mutex> lock(mutex_);
        return connections_.find(ipAddress + ":" + std::to_string(port))->isActive();
    }

private:
    ConnectionManager() {}
    std::unordered_map<std::string, ConnectionStatus*> connections_;
    std::mutex mutex_;
};
```
