using System;
using System.Security.Cryptography;
using System.Threading.Tasks;

namespace MessageProcessingService
{
    public class MessageProcessor
    {
        private readonly Aes _aes;
        private readonly TripleDES _tripleDes;

        public MessageProcessor()
        {
            // Initialize the encryption algorithms
            _aes = new AesCryptoServiceProvider();
            _tripleDes = new TripleDESCryptoServiceProvider();
        }

        public async Task<string> ProcessMessage(string message, string key, string iv)
        {
            // Validate input parameters
            if (string.IsNullOrEmpty(message))
                throw new ArgumentException("Message is required", nameof(message));
            if (string.IsNullOrEmpty(key))
                throw new ArgumentException("Key is required", nameof(key));
            if (string.IsNullOrEmpty(iv))
                throw new ArgumentException("IV is required", nameof(iv));

            // Determine the encryption algorithm to use based on the key length
            int keyLength = _aes.LegalKeySizes[0].MaxSize;
            bool useAes = (key.Length == keyLength);

            // Initialize the encryption algorithm and decrypt the message
            SymmetricAlgorithm symmetricAlgorithm = useAes ? _aes : _tripleDes;
            symmetricAlgorithm.Key = Convert.FromBase64String(key);
            symmetricAlgorithm.IV = Convert.FromBase64String(iv);
            string decryptedMessage = symmetricAlgorithm.Decrypt(message);

            // Return the decrypted message as a JSON response
            return $"{{ \"decrypted_message\": \"{decryptedMessage}\" }}";
        }
    }
}
```

