```rust
use std::collections::HashMap;
use std::sync::Mutex;

struct ProjectDirectory {
    name: String,
    metadata: HashMap<String, String>,
}

struct ProjectDirectories {
    directories: HashMap<String, ProjectDirectory>,
    cache: Mutex<HashMap<String, ProjectDirectory>>,
}

impl ProjectDirectories {
    fn new() -> Self {
        ProjectDirectories {
            directories: HashMap::new(),
            cache: Mutex::new(HashMap::new()),
        }
    }

    fn create_project_directory(&self, name: &str) -> Result<(), String> {
        let mut directories = self.directories.lock().unwrap();
        if directories.contains_key(name) {
            return Err("Project directory already exists".to_string());
        }

        directories.insert(name.into(), ProjectDirectory::new(name));
        Ok(())
    }

    fn list_project_directories(&self) -> Vec<String> {
        let mut directories = self.directories.lock().unwrap();
        let mut directory_names: Vec<String> = directories.keys().map(|k| k.clone()).collect();
        directory_names.sort();
        directory_names
    }

    fn delete_project_directory(&self, name: &str) -> Result<(), String> {
        let mut directories = self.directories.lock().unwrap();
        if !directories.contains_key(name) {
            return Err("Project directory does not exist".to_string());
        }

        directories.remove(name);
        Ok(())
    }

    fn activate_project_directory(&self, name: &str) -> Result<(), String> {
        let mut directories = self.directories.lock().unwrap();
        if !directories.contains_key(name) {
            return Err("Project directory does not exist".to_string());
        }

        let directory = directories.get_mut(name).unwrap();
        directory.metadata["active"] = "true";
        Ok(())
    }

    fn deactivate_project_directory(&self, name: &str) -> Result<(), String> {
        let mut directories = self.directories.lock().unwrap();
        if !directories.contains_key(name) {
            return Err("Project directory does not exist".to_string());
        }

        let directory = directories.get_mut(name).unwrap();
        directory.metadata["active"] = "false";
        Ok(())
    }
}
```
