    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct nfapi_crc_indication_node* next;
} nfapi_crc_indication_node_t;

// Define the linked list head pointer for holding all NFAPI_CRC_INDICATION_PDU_T structures
static nfapi_crc_indication_node_t* head = NULL;

// Define the function for adding a new node to the linked list
void add_node(NFAPI_CRC_INDICATION_PDU_T pdu) {
    // Create a new node and initialize it with the given NFAPI_CRC_INDICATION_PDU_T structure
    nfapi_crc_indication_node_t* new_node = malloc(sizeof(nfapi_crc_indication_node_t));
    new_node->pdu = pdu;

    // Lock the mutex to prevent concurrent access to the linked list
    pthread_mutex_lock(&mutex);

    // Check if the linked list is empty
    if (head == NULL) {
        head = new_node;
    } else {
        nfapi_crc_indication_node_t* current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

// Define the function for removing a node from the linked list
