// SecureMessageHandler.cs
using System;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

namespace SecureMessageHandler
{
    public class SecureMessageHandler
    {
        private readonly TripleDESCryptoServiceProvider _csp = new TripleDESCryptoServiceProvider();
        private readonly byte[] _ivBytes = new byte[8];
        private readonly byte[] _keyBytes = new byte[24];

        public SecureMessageHandler(byte[] key, byte[] iv)
        {
            if (key == null || key.Length != 24)
                throw new ArgumentException("Key length must be 24 bytes.", nameof(key));
            if (iv == null || iv.Length != 8)
                throw new ArgumentException("IV length must be 8 bytes.", nameof(iv));

            _keyBytes = key;
            _ivBytes = iv;
        }

        public async Task<string> EncryptMessageAsync(string message)
        {
            if (string.IsNullOrEmpty(message))
                throw new ArgumentException("Message cannot be empty.", nameof(message));

            byte[] plainTextBytes = Encoding.UTF8.GetBytes(message);
            byte[] cipherTextBytes = await EncryptAsync(plainTextBytes, _keyBytes, _ivBytes).ConfigureAwait(false);

            return Convert.ToBase64String(cipherTextBytes);
        }

        public async Task<string> DecryptMessageAsync(string message)
        {
            if (string.IsNullOrEmpty(message))
                throw new ArgumentException("Message cannot be empty.", nameof(message));

            byte[] cipherTextBytes = Convert.FromBase64String(message);
            byte[] plainTextBytes = await DecryptAsync(cipherTextBytes, _keyBytes, _ivBytes).ConfigureAwait(false);

            return Encoding.UTF8.GetString(plainTextBytes);
        }

        private async Task<byte[]> EncryptAsync(byte[] plainTextBytes, byte[] keyBytes, byte[] ivBytes)
        {
            using (var encryptor = _csp.CreateEncryptor(keyBytes, ivBytes))
            {
                return await Task.Run(() =>
                {
                    var memoryStream = new MemoryStream();
                    var cryptoStream = new CryptoStream(memoryStream, encryptor, CryptoStreamMode.Write);

                    cryptoStream.Write(plainTextBytes, 0, plainTextBytes.Length);
                    cryptoStream.FlushFinalBlock();

                    return memoryStream.ToArray();
                });
            }
        }

        private async Task<byte[]> DecryptAsync(byte[] cipherTextBytes, byte[] keyBytes, byte[] ivBytes)
        {
            using (var decryptor = _csp.CreateDecryptor(keyBytes, ivBytes))
            {
                return await Task.Run(() =>
                {
                    var memoryStream = new MemoryStream(cipherTextBytes);
                    var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Read);

                    byte[] plainTextBytes = new byte[cipherTextBytes.Length];
                    int readByteCount = cryptoStream.Read(plainTextBytes, 0, plainTextBytes.Length);

                    return plainTextBytes;
                });
            }
        }
    }
}

// TripleDESCryptoServiceProvider.cs
using System.Security.Cryptography;

namespace SecureMessageHandler
{
    public class TripleDESCryptoServiceProvider : SymmetricAlgorithm
    {
        private readonly DesEncryptor _encryptor;
        private readonly DesDecryptor _decryptor;

        public TripleDESCryptoServiceProvider()
        {
            _encryptor = new DesEncryptor();
            _decryptor = new DesDecryptor();
        }

        public override ICryptoTransform CreateDecryptor(byte[] rgbKey, byte[] rgbIV)
        {
            return _decryptor.CreateDecryptor(rgbKey, rgbIV);
        }

        public override ICryptoTransform CreateEncryptor(byte[] rgbKey, byte[] rgbIV)
        {
            return _encryptor.CreateEncryptor(rgbKey, rgbIV);
        }
    }
}

