```csharp
using System;
using System.IO;
using System.Net;
using System.Security.Authentication;
using System.Text;
using System.Threading.Tasks;
using TripleDES = System.Security.Cryptography.TripleDESCryptoServiceProvider;

namespace Base64EncryptedTripleDESEncryptionDecryptionService
{
    public class EncryptionService
    {
        private static readonly HttpClient Client = new HttpClient();
        private static readonly Random Rnd = new Random();

        public async Task<string> DecryptAsync(string encryptedMessage)
        {
            // Decode the Base64-encoded message.
            byte[] messageBytes = Convert.FromBase64String(encryptedMessage);

            // Generate a secure random key and initialization vector (IV).
            byte[] key = new byte[128];
            Rnd.NextBytes(key);

            byte[] iv = new byte[16];
            Rnd.NextBytes(iv);

            // Use the Triple DES algorithm to decrypt the message.
            using (TripleDES des = new TripleDESCryptoServiceProvider())
            {
                des.Key = key;
                des.IV = iv;

                return Encoding.UTF8.GetString(des.CreateDecryptor().TransformFinalBlock(messageBytes, 0, messageBytes.Length));
            }
        }
    }
}
```
