    private const string EncryptionAlgorithm = "TripleDES";
    private const int KeySize = 192;
    private const int BlockSize = 64;
    private const int InitializationVectorSize = 8;

    private readonly Dictionary<string, DialogFieldRefreshStatus> _refreshStatus = new Dictionary<string, DialogFieldRefreshStatus>();

    public DynamicDialogUpdater(string key, string iv)
    {
        _key = Encoding.UTF8.GetBytes(key);
        _iv = Encoding.UTF8.GetBytes(iv);
    }

    public Dictionary<string, DialogFieldRefreshStatus> RefreshFields(string encryptedMessage, int resourceId)
    {
        var decryptedMessage = Decrypt(encryptedMessage);
        var jsonPayload = JObject.Parse(decryptedMessage);
        var fieldsToRefresh = new List<DialogField>();

        foreach (var field in jsonPayload["fields"])
        {
            var fieldName = field["name"].ToString();
            var fieldUrl = field["url"].ToString();

            if (!_refreshStatus.ContainsKey(fieldName))
            {
                _refreshStatus[fieldName] = new DialogFieldRefreshStatus();
            }

            var refreshStatus = _refreshStatus[fieldName];

            try
            {
                RefreshDialogField(resourceId, fieldUrl);
                refreshStatus.IsSuccessful = true;
            }
            catch (Exception ex)
            {
                refreshStatus.ErrorMessage = ex.Message;
                refreshStatus.IsSuccessful = false;
            }
        }

        return _refreshStatus;
    }

    private string Decrypt(string encryptedMessage)
    {
        var encryptedBytes = Convert.FromBase64String(encryptedMessage);
        using (var tripleDes = new TripleDESCryptoServiceProvider())
        {
            tripleDes.KeySize = KeySize;
            tripleDes.BlockSize = BlockSize;
            tripleDes.IV = Encoding.UTF8.GetBytes(_iv);
            var decryptedBytes = tripleDes.CreateDecryptor().TransformFinalBlock(encryptedBytes, 0, encryptedBytes.Length);
            return Encoding.UTF8.GetString(decryptedBytes);
        }
    }

    private void RefreshDialogField(int resourceId, string fieldUrl)
    {
        var request = new HttpRequestMessage(HttpMethod.Put, fieldUrl);
        request.Headers.Add("Content-Type", "application/json");
        request.Headers.Add("Authorization", $"Bearer {resourceId}");
        using (var client = new HttpClient())
        {
            var response = client.SendAsync(request).Result;
            if (!response.IsSuccessStatusCode)
            {
                throw new Exception($"Failed to refresh dialog field: {response.ReasonPhrase}");
            }
        }
    }
}

public class DialogFieldRefreshStatus
{
    public bool IsSuccessful { get; set; }
    public string ErrorMessage { get; set; }
}
