['// SecureMessageHandler.cs
using System;
using System.Security.Cryptography;
using System.Text;

namespace SecureMessageHandler
{
    public class MessageHandler
    {
        // Encryption and Decryption Methods

        public static string EncryptMessage(string message, string key)
        {
            if (key == null || key.Length != 24)
                throw new ArgumentException("Invalid Key Length", "key");

            var des = TripleDES.Create();
            des.Key = Encoding.ASCII.GetBytes(key);
            des.IV = Encoding.ASCII.GetBytes(key).Substring(0, 8);

            return Convert.ToBase64String(des.CreateEncryptor().TransformFinalBlock(Encoding.UTF8.GetBytes(message), 0, message.Length));
        }

        public static string DecryptMessage(string cipherText, string key)
        {
            if (key == null || key.Length != 24)
                throw new ArgumentException("Invalid Key Length", "key");

            var des = TripleDES.Create();
            des.Key = Encoding.ASCII.GetBytes(key);
            des.IV = Encoding.ASCII.GetBytes(key).Substring(0, 8);

            return Encoding.UTF8.GetString(des.CreateDecryptor().TransformFinalBlock(Convert.FromBase64String(cipherText), 0, Convert.FromBase64String(cipherText).Length));
        }

        // Encryption with Key Pair Method

        public static string EncryptWithKeyPair(string message, string publicKey, string privateKey)
        {
            if (publicKey == null || privateKey == null)
                throw new ArgumentException("Invalid Key Length", "key");

            var rsa = RSA.Create();
            rsa.ImportParameters(new RSAParameters() { Exponent = Encoding.ASCII.GetBytes(publicKey), Modulus = Encoding.ASCII.GetBytes(privateKey) });

            return Convert.ToBase64String(rsa.Encrypt(Encoding.UTF8.GetBytes(message), RSAEncryptionPadding.OaepSHA512));
        }
    }
}

