int main(int argc, char** argv) {
    int fd[MAX_STREAMS]; // file descriptors for each stream
    int nStreams = 0; // number of streams being processed
    int* maxCount = malloc(sizeof(int)); // maximum count of a value
    *maxCount = 0; // initialize to zero

    while (nStreams < MAX_STREAMS && argc - 1 > nStreams) {
        fd[nStreams] = open(argv[nStreams + 1], O_RDONLY);
        if (fd[nStreams] < 0) {
            perror("open error");
            exit(EXIT_FAILURE);
        }
        nStreams++;
    }

    while (nStreams > 0 && *maxCount == 0) {
        fd_set readFds; // set of file descriptors to monitor for readiness
        FD_ZERO(&readFds);
        for (int i = 0; i < nStreams; i++) {
            FD_SET(fd[i], &readFds);
        }
        struct timeval timeout = {.tv_sec = 1, .tv_usec = 0}; // 1 second timeout
        int retval = select(nStreams + 1, &readFds, NULL, NULL, &timeout);
        if (retval < 0) {
            perror("select error");
            exit(EXIT_FAILURE);
        } else if (retval == 0) {
            // timeout reached, check for errors and continue
            for (int i = 0; i < nStreams; i++) {
                int fdError = errno;
                if (fdError != EAGAIN && fdError != EWOULDBLOCK) {
                    perror("error on file descriptor");
                    exit(EXIT_FAILURE);
                }
            }
        } else {
            // data available, process it
            for (int i = 0; i < nStreams; i++) {
                if (FD_ISSET(fd[i], &readFds)) {
                    int x = readInteger(fd[i]);
                    processInteger(x);
                    updateMaxCount();
                }
            }
        }
    }

    // print the largest integer along with its count
    printLargestInteger();

    exit(EXIT_SUCCESS);
}
