struct Delimiter {
    std::string value;
    size_t size;
};

class StringProcessor {
public:
    StringProcessor(const std::vector<Delimiter>& delimiters) : delimiters_(delimiters) {}

    std::string appendDelimiter(const std::string& input, const Delimiter& delimiter) {
        if (input.empty()) return "";
        if (delimiter.value.empty()) return input;

        // Check for null or empty strings
        if (!input || !delimiter.value) return "";

        // Check for valid size limits
        if (delimiter.size < 0) return "";

        std::stringstream output;

        // Iterate through the input string and add delimiters as needed
        for (const char& c : input) {
            if (c == delimiter.value[0]) {
                output << delimiter.value;
            } else {
                output << c;
            }
        }

        return output.str();
    }

private:
    std::vector<Delimiter> delimiters_;
};

// Example usage:
int main() {
    // Define delimiters
    const std::vector<Delimiter> delimiters = {
        {" ", 1},
        {"-", 2}
    };

    // Create a StringProcessor object with the defined delimiters
    StringProcessor processor(delimiters);

    // Test the appendDelimiter function
    std::string input = "Hello World!";
    std::string output = processor.appendDelimiter(input, Delimiter("-", 2));
    std::cout << output << std::endl; // Output: "Hello-World!"

    return 0;
}
