#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <sys/wait.h>

#define MAX_CONCURRENT_TESTS 20
#define STATEFUL_MOCKING_FRAMEWORK "stateful-mocking-framework"

typedef struct {
    char *label;
    void (*f)();
} test_t;

void run_test(test_t *test);
void handle_error(char *message);
void print_usage();

int main(int argc, char **argv) {
    if (argc < 2) {
        print_usage();
        return -1;
    }

    test_t *tests = NULL;
    int num_tests = 0;
    for (int i = 1; i < argc; i++) {
        char *label = argv[i];
        void (*f)() = dlsym(RTLD_DEFAULT, label);
        if (f == NULL) {
            handle_error("Failed to find test implementation");
        }
        tests = realloc(tests, sizeof(test_t) * (num_tests + 1));
        tests[num_tests].label = label;
        tests[num_tests].f = f;
        num_tests++;
    }

    for (int i = 0; i < num_tests; i++) {
        run_test(&tests[i]);
    }

    return 0;
}

void run_test(test_t *test) {
    pid_t pid = fork();
    if (pid == 0) {
        // Child process
        char *argv[] = {"stateful-mocking-framework", test->label, NULL};
        execvp("stateful-mocking-framework", argv);
        handle_error("Failed to run stateful mocking framework");
    } else if (pid > 0) {
        // Parent process
        int status;
        wait(&status);
        if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
            printf("Test %s failed\n", test->label);
        } else {
            printf("Test %s passed\n", test->label);
        }
    }
}

void handle_error(char *message) {
    fprintf(stderr, "%s: %s\n", message, strerror(errno));
    exit(-1);
}

void print_usage() {
    printf("Usage: ./test-orchestrator <test label 1> [<test label 2> ...]\n");
    printf("       Test labels must be in the form of '<name>(<argument 1>, <argument 2>)'\n");
}
