        try {
            statement = dbConnection.prepareStatement("SELECT * FROM ran_cu_signaling_events WHERE nas_id=?");
            statement.setString(1, nasId);
            resultSet = statement.executeQuery();
            List<String> rans = new ArrayList<>();
            while (resultSet.next()) {
                rans.add(resultSet.getString("ran"));
            }
            return rans;
        } catch (SQLException e) {
            System.out.println("Error querying database: " + e.getMessage());
            return null;
        } finally {
            if (statement != null) {
                try {
                    statement.close();
                } catch (SQLException e) {}
            }
            if (resultSet != null) {
                try {
                    resultSet.close();
                } catch (SQLException e) {}
            }
        }
    }

    private static void processNASMessage(String nasId, String type, String timestamp, String data, String ran, Connection dbConnection) {
        // Update the database with the validated NAS message
        PreparedStatement statement = null;
        try {
            statement = dbConnection.prepareStatement("INSERT INTO nas_messages (nas_id, type, timestamp, data, ran) VALUES (?, ?, ?, ?, ?)");
            statement.setString(1, nasId);
            statement.setString(2, type);
            statement.setString(3, timestamp);
            statement.setString(4, data);
            statement.setString(5, ran);
            statement.executeUpdate();
        } catch (SQLException e) {
            System.out.println("Error updating database: " + e.getMessage());
        } finally {
            if (statement != null) {
                try {
                    statement.close();
                } catch (SQLException e) {}
            }
        }
    }
}
