// Forward declaration of the Octree class
class Octree;

// Factory pattern to register and instantiate octree subclasses
class OctreeFactory {
public:
    // Register a new octree subclass with the factory
    static void registerOctree(const std::string& name, const std::function<std::shared_ptr<Octree>(int)>& createFunction);

    // Instantiate an octree subclass with the specified name and parameters
    static std::shared_ptr<Octree> createOctree(const std::string& name, int featureSize, int numLeafNodes, int dataCapacity);
};

// Base class for all octree subclasses
class Octree {
public:
    // Constructor and destructor
    Octree(int featureSize, int numLeafNodes, int dataCapacity) : featureSize_(featureSize), numLeafNodes_(numLeafNodes), dataCapacity_(dataCapacity) {}
    virtual ~Octree() = default;

    // Insert a new data point into the octree
    virtual void insert(const std::vector<float>& point, const std::shared_ptr<void>& data) = 0;

    // Delete a data point from the octree
    virtual bool delete(const std::vector<float>& point) = 0;

    // Query for nearest neighbors to a given point
    virtual void queryNearestNeighbors(const std::vector<float>& point, int k, std::vector<std::shared_ptr<void>>& results) = 0;
};

// Octree manager class that manages the creation and deletion of octrees
class OctreeManager {
public:
    // Constructor and destructor
    OctreeManager() : currentCapacity_(0), maxCapacity_(1 << 24) {}
    virtual ~OctreeManager() = default;

    // Initialize a new octree with the specified parameters
    void init(int featureSize, int numLeafNodes, int dataCapacity);

    // Insert a new data point into the appropriate octree
    void insert(const std::vector<float>& point, const std::shared_ptr<void>& data);

    // Delete a data point from the appropriate octree
    bool delete(const std::vector<float>& point);

    // Query for nearest neighbors to a given point
    void queryNearestNeighbors(const std::vector<float>& point, int k, std::vector<std::shared_ptr<void>>& results);

private:
    // Map of octree subclasses registered with the factory
    static std::unordered_map<std::string, std::function<std::shared_ptr<Octree>(int)>> octreeMap_;

    // Current capacity of the octree manager
    size_t currentCapacity_;

    // Maximum capacity of the octree manager
    size_t maxCapacity_;

    // Mutex to protect concurrent access to the octree manager
    std::mutex mutex_;
};

// Register a new octree subclass with the factory
void OctreeFactory::registerOctree(const std::string& name, const std::function<std::shared_ptr<Octree>(int)>& createFunction) {
    octreeMap_.emplace(name, createFunction);
}

// Instantiate an octree subclass with the specified name and parameters
std::shared_ptr<Octree> OctreeFactory::createOctree(const std::string& name, int featureSize, int numLeafNodes, int dataCapacity) {
    if (octreeMap_.find(name) != octreeMap_.end()) {
        return octreeMap_.at(name)(featureSize, numLeafNodes, dataCapacity);
    } else {
        throw std::invalid_argument("Invalid octree type: " + name);
    }
}

// Initialize a new octree with the specified parameters
void OctreeManager::init(int featureSize, int numLeafNodes, int dataCapacity) {
    // Update the current capacity of the octree manager
    currentCapacity_ += dataCapacity;

    if (currentCapacity_ > maxCapacity_) {
        throw std::invalid_argument("Octree manager has exceeded its maximum capacity");
    }

    // Create a new octree instance with the specified parameters
    auto octree = OctreeFactory::createOctree("Default", featureSize, numLeafNodes, dataCapacity);

    // Add the new octree to the octree manager
    octrees_.emplace_back(octree);
}

// Insert a new data point into the appropriate octree
void OctreeManager::insert(const std::vector<float>& point, const std::shared_ptr<void>& data) {
    // Acquire the mutex to protect concurrent access to the octree manager
    std::lock_guard<std::mutex> lock(mutex_);

    // Find the appropriate octree for the given point
    auto octree = findOctree(point);

    // Insert the data point into the octree
    octree->insert(point, data);
}

// Delete a data point from the appropriate octree
bool OctreeManager::delete(const std::vector<float>& point) {
    // Acquire the mutex to protect concurrent access to the octree manager
    std::lock_guard<std::mutex> lock(mutex_);

    // Find the appropriate octree for the given point
    auto octree = findOctree(point);

    // Delete the data point from the octree
    return octree->delete(point);
}

// Query for nearest neighbors to a given point
void OctreeManager::queryNearestNeighbors(const std::vector<float>& point, int k, std::vector<std::shared_ptr<void>>& results) {
    // Acquire the mutex to protect concurrent access to the octree manager
    std::lock_guard<std::mutex> lock(mutex_);

    // Find the appropriate octree for the given point
    auto octree = findOctree(point);

    // Query for nearest neighbors in the octree
    octree->queryNearestNeighbors(point, k, results);
}

// Find the appropriate octree for a given point
Octree* OctreeManager::findOctree(const std::vector<float>& point) {
    // Check if any of the existing octrees contain the given point
    for (auto& octree : octrees_) {
        if (octree->contains(point)) {
            return &octree;
        }
    }

    // If no existing octree contains the point, create a new one
    auto octree = OctreeFactory::createOctree("Default", point.size(), 0, 0);
    octrees_.emplace_back(octree);

    return &octree;
}
