        public async Task<UserAccount> CreateUserAsync(string username, string password)
        {
            // Validate input parameters
            if (string.IsNullOrEmpty(username)) throw new ArgumentException("Username is required", nameof(username));
            if (string.IsNullOrEmpty(password)) throw new ArgumentException("Password is required", nameof(password));

            // Create user account in external authentication service
            var authResponse = await _externalAuthService.CreateUserAsync(username, password);

            // If creation failed, return null and log error
