            // If creation failed, roll back and log error
            if (!dbResponse.IsSuccess)
            {
                try
                {
                    await RollbackTransactionAsync(authResponse.UserId);
                }
                catch (Exception ex)
                {
                    Logger.Error($"Failed to roll back transaction for user {username} with reason: {ex.Message}");
                }

                throw new Exception("Failed to create user account in local database");
            }

