class GeospatialTransformationManager {
public:
    void transformGeospatialData(const std::string& input_file, const std::string& output_dir) {
        std::cout << "Transforming geospatial data..." << std::endl;

        // retrieve configuration parameters from config service
        auto params = ConfigService::getInstance().getParams();
        size_t max_filename_length = params["max_filename_length"];
        std::string default_timestamp_format = params["default_timestamp_format"];

        // open input file and check if it exists
        std::ifstream input(input_file);
        if (!input.good()) {
            throw std::runtime_error("Input file does not exist");
        }

        // generate unique filename for output file
        auto timestamp = std::chrono::high_resolution_clock::now().time_since_epoch().count();
        auto hash = GeospatialTransformer::generateHash(input);
        auto version_id = GeospatialTransformer::getVersionId();
        std::string output_filename = "output_" + std::to_string(timestamp) + "_" + hash + "_v" + version_id;

        // check if output filename is too long and truncate if necessary
        if (output_filename.length() > max_filename_length) {
            output_filename = output_filename.substr(0, max_filename_length);
        }

        // open output file and write transformed data to it
        std::ofstream output(output_dir + "/" + output_filename);
        GeospatialTransformer::transformGeospatialData(input, output);
    }

private:
    static std::atomic<int> version_id_;
};

std::atomic<int> GeospatialTransformationManager::version_id_{0};
