import logging
from datetime import datetime
from enum import Enum

class LogLevel(Enum):
    CRITICAL = 50
    ERROR = 40
    WARNING = 30
    INFO = 20
    DEBUG = 10

class LogTag:
    def __init__(self, name, description):
        self.name = name
        self.description = description

class LogRetentionPolicy:
    def __init__(self, name, max_age=None, max_size=None):
        self.name = name
        self.max_age = max_age
        self.max_size = max_size

class LogFormatter:
    def __init__(self, format_string, datefmt=None):
        self.format_string = format_string
        self.datefmt = datefmt

class LogHandler:
    def __init__(self, log_level, log_tag, log_retention_policy):
        self.log_level = log_level
        self.log_tag = log_tag
        self.log_retention_policy = log_retention_policy

class LogAggregator:
    def __init__(self, log_handlers, aggragation_strategy):
        self.log_handlers = log_handlers
        self.aggragation_strategy = aggragation_strategy

class LoggingFramework:
    def __init__(self, log_aggregator, enable_centralized_logging=False):
        self.log_aggregator = log_aggregator
        self.enable_centralized_logging = enable_centralized_logging

    def add_log_handler(self, log_handler):
        self.log_aggregator.add_log_handler(log_handler)

    def remove_log_handler(self, log_handler):
        self.log_aggregator.remove_log_handler(log_handler)

    def get_all_log_handlers(self):
        return self.log_aggregator.get_all_log_handlers()
