from typing import List, Dict, Optional

class LogMessage(object):
    def __init__(self, message: str, level: int, category: str) -> None:
        self.message = message
        self.level = level
        self.category = category

class LogSink(object):
    def __init__(self, name: str) -> None:
        self.name = name

class LogProcessor(object):
    def __init__(self, sink: List[LogSink]) -> None:
        self.sinks = sink
        self.queue = concurrent.futures.Queue()
        self.workers = []
        self.running = True

    def start(self) -> None:
        for worker in self.workers:
            worker.start()

    def stop(self) -> None:
        self.running = False
        self.queue.put(None)
        for worker in self.workers:
            worker.join()

    def add_sink(self, sink: LogSink) -> None:
        self.sinks.append(sink)

    def process_message(self, message: LogMessage) -> None:
        if not self.running:
            return
        for sink in self.sinks:
            self.queue.put((sink, message))

class LogWorker(object):
    def __init__(self, queue: concurrent.futures.Queue, process_message) -> None:
        self.queue = queue
        self.process_message = process_message

    def run(self) -> None:
        while True:
            sink, message = self.queue.get()
            if not self.running:
                break
            try:
                self.process_message(sink, message)
            except Exception as e:
                print("Error processing message", e)
            finally:
                self.queue.task_done()

class LogPipeline(object):
    def __init__(self, sink: List[LogSink]) -> None:
        self.sinks = sink
        self.workers = []

    def start(self) -> None:
        for worker in self.workers:
            worker.start()

