        }

    private:
        const std::string& sourceName;
        int ingestionSpeedLimit;
    };

    class Aggregator {
    public:
        Aggregator() : sources(), aggregateData(), mutex(), cv() {}

        void run() {
            while (true) {
                // Wait for data to become available
                std::unique_lock<std::mutex> lock(mutex);
                cv.wait(lock, [&] { return !sources.empty(); });

                // Aggregate data from all sources
                for (auto source : sources) {
                    aggregateData[source].push_back(data[source]);
                }

                // Send aggregated data to output stream
                // Update source status
            }
        }

        void addSource(const std::string& sourceName) {
            sources.insert(sourceName);
        }

        void removeSource(const std::string& sourceName) {
            sources.erase(sourceName);
        }

    private:
        std::set<std::string> sources;
        std::map<std::string, std::vector<Data>> aggregateData;
        std::mutex mutex;
        std::condition_variable cv;
    };

    std::map<std::string, bool> dataSources;
    std::vector<DataIngester*> ingesters;
    std::vector<std::thread> threads;
    Aggregator aggregator;
    int ingestionSpeedLimit;
    const std::string& outputStream;
    const std::string& errorStream;
};
