                var plainText = await Task.Run(() => {
                    using (var rsa = new RSACryptoServiceProvider())
                    {
                        return aes.Decrypt(rsa.Decrypt(cipherText, false));
                    }
                });

                // Return the decrypted text
                return Encoding.UTF8.GetString(plainText);
            }
        }

        private async Task<byte[]> GetEncryptionKeyAsync(string encryptionKeyId)
        {
            // Check if the encryption key is in the cache, if not fetch it from the cloud service
            if (!_encryptionCache.ContainsKey(encryptionKeyId))
            {
                _encryptionCache[encryptionKeyId] = await FetchEncryptionKeyAsync(encryptionKeyId);
            }

            // Return the encryption key from the cache
            return _encryptionCache[encryptionKeyId].Item1;
