            if (!_decryptionCache.ContainsKey(decryptionKeyId))
            {
                _decryptionCache[decryptionKeyId] = await FetchDecryptionKeyAsync(decryptionKeyId);
            }

            // Return the decryption key from the cache
            return _decryptionCache[decryptionKeyId].Item1;
