        {
            // Get the encryption key and IV from the cloud service based on the ID
            var encryptionKey = await CloudService.GetEncryptionKeyAsync(encryptionKeyId);
            var iv = GetInitializationVector();

            // Create a new instance of AES-256 with the encryption key and IV
            using (var aes = new AesManaged())
            {
                aes.KeySize = 256;
                aes.BlockSize = 128;
                aes.IV = iv;
                aes.Key = encryptionKey;

                // Return the encryption key and IV as a tuple
                return Tuple.Create(aes.Key, aes.IV);
            }
        }

        private async Task<Tuple<Aes, Rsa>> FetchDecryptionKeyAsync(string decryptionKeyId)
        {
            // Get the decryption key and IV from the cloud service based on the ID
            var decryptionKey = await CloudService.GetDecryptionKeyAsync(decryptionKeyId);
            var iv = GetInitializationVector();

            // Create a new instance of AES-256 with the decryption key and IV
            using (var aes = new AesManaged())
            {
                aes.KeySize = 256;
                aes.BlockSize = 128;
                aes.IV = iv;
                aes.Key = decryptionKey;

                // Return the decryption key and IV as a tuple
                return Tuple.Create(aes.Key, aes.IV);
            }
        }

        private void Dispose()
        {
            foreach (var cacheEntry in _encryptionCache)
            {
                cacheEntry.Value.Item1?.Dispose();
                cacheEntry.Value.Item2?.Dispose();
            }
        }
    }
}
