}

// Define the function to pause operations until resources become available
void pause_operations() {
    // Lock the mutex for thread safety
    pthread_mutex_lock(&crc_lock);

    // Pause operations until resources become available
    while (cpu_usage > MAX_CPU_USAGE || memory_usage > MAX_MEMORY_USAGE) {
        usleep(100000);
