using namespace std;

const int MAX_THREADS = 8; // Maximum number of threads to use for concurrent requests
const int MAX_QUEUE_SIZE = 1000; // Maximum size of the request queue
const int MIN_REQUEST_DELAY = 50; // Minimum delay between requests (in milliseconds)

// A structure to represent a single web API endpoint and its associated data
struct WebAPIEndpoint {
    string url; // URL of the API endpoint
    string token; // Authentication token for the API endpoint
    int quota; // Quota for the API endpoint (maximum number of requests per minute)
};

// A structure to represent a single request and its associated data
struct Request {
    WebAPIEndpoint endpoint; // The web API endpoint associated with the request
    string jsonData; // The JSON data associated with the request
};

// A queue to hold pending requests
queue<Request> requestQueue;

// A mutex to protect the request queue
mutex queueMutex;

// A condition variable to signal when new requests are available in the queue
condition_variable queueCondVar;

// A vector of futures for running threads
vector<future<void>> threadFutures;

// A mutex to protect the vector of futures
mutex futureMutex;

// A condition variable to signal when a thread is finished running
condition_variable futureCondVar;

// A variable to track the number of requests made
atomic<int> numRequests = 0;

// A variable to track the number of successful responses
atomic<int> numSuccessfulResponses = 0;

// A variable to track the number of failed responses
atomic<int> numFailedResponses = 0;

// A variable to track the total time taken for processing requests (in milliseconds)
atomic<long long> totalProcessingTime = 0;

// A function to fetch and process data from a single web API endpoint
void fetchAndProcessData(WebAPIEndpoint endpoint) {
    // Initialize variables for tracking request duration and response status
    auto startTime = chrono::steady_clock::now();
    bool isSuccessfulResponse = false;

    // Make the API request and handle the response
    try {
        string jsonData = makeAPIRequest(endpoint.url, endpoint.token);
        isSuccessfulResponse = processJSONData(jsonData);
    } catch (exception& e) {
        LOG(ERROR) << "Exception occurred while fetching data from API: " << e.what();
    }

    // Update metrics and log the request duration and response status
    auto endTime = chrono::steady_clock::now();
    long long processingTime = chrono::duration_cast<chrono::milliseconds>(endTime - startTime).count();
    totalProcessingTime += processingTime;
    numRequests++;
    if (isSuccessfulResponse) {
        numSuccessfulResponses++;
    } else {
        numFailedResponses++;
    }
    LOG(INFO) << "Fetched and processed data from API: " << endpoint.url << "; Response status: " << isSuccessfulResponse;
}

// A function to make an API request and handle the response
string makeAPIRequest(const string& url, const string& token) {
    // Initialize variables for tracking request duration and response status
    auto startTime = chrono::steady_clock::now();
    bool isSuccessfulResponse = false;

    // Make the API request and handle the response
    try {
        string jsonData = makeAPIRequest(url, token);
        isSuccessfulResponse = processJSONData(jsonData);
    } catch (exception& e) {
        LOG(ERROR) << "Exception occurred while making API request: " << e.what();
    }

    // Update metrics and log the request duration and response status
    auto endTime = chrono::steady_clock::now();
    long long processingTime = chrono::duration_cast<chrono::milliseconds>(endTime - startTime).count();
    totalProcessingTime += processingTime;
    numRequests++;
    if (isSuccessfulResponse) {
        numSuccessfulResponses++;
    } else {
        numFailedResponses++;
    }
    LOG(INFO) << "Fetched and processed data from API: " << url << "; Response status: " << isSuccessfulResponse;
}

