void runThread(int threadIdx) {
    while (true) {
        // Get the next request from the queue
        Request request;
        if (!getNextRequest(request)) {
            LOG(INFO) << "No more requests available in the queue.";
            break;
        }

        // Fetch and process data for the request
        fetchAndProcessData(request.endpoint);
    }
}

// A function to get the next request from the queue
bool getNextRequest(Request& request) {
    lock_guard<mutex> lockGuard(queueMutex);
    if (requestQueue.empty()) {
        return false;
    }
    request = requestQueue.front();
    requestQueue.pop();
    return true;
}

// A function to add a request to the queue
void addRequest(const Request& request) {
    lock_guard<mutex> lockGuard(queueMutex);
    requestQueue.push(request);
    queueCondVar.notify_all();
}

