        lock_guard<mutex> lockGuard(futureMutex);
        threadFutures.push_back(move(threadFuture));

        // Increment the number of running threads and update metrics
        numRunningThreads++;
    }
}

// A function to stop all threads that fetch and process data from multiple web APIs concurrently
void stopThreads() {
    lock_guard<mutex> lockGuard(futureMutex);
    for (auto& threadFuture : threadFutures) {
        if (threadFuture.valid()) {
            threadFuture.wait();
        }
    }
}

