// NetworkEventManager.h
#include <stdint.h>
#include <stdbool.h>

typedef struct {
    uint32_t timestamp;
    uint16_t packetId;
    uint8_t type; // 0 - arrival, 1 - loss, 2 - retransmission
} NetworkEvent;

// Function prototypes
void netEventManagerInit(size_t capacity);
bool netEventManagerAddEvent(NetworkEvent* event);
void netEventManagerUpdate(uint32_t timestamp);
void netEventManagerReportStatistics();
void netEventManagerDestroy();

// Implementation
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>
#include <stdint.h>
#include <stdbool.h>
#include <pthread.h>

#define MAX_CAPACITY 10000
#define MIN_CAPACITY 100
#define PARTITION_SIZE 100

typedef struct {
    NetworkEvent* events;
    size_t capacity;
    size_t numEvents;
    pthread_mutex_t lock;
} NetEventManager;

static NetEventManager* manager = NULL;

void netEventManagerInit(size_t capacity) {
    if (manager != NULL) {
        printf("[ERROR] Network event manager already initialized\n");
        return;
    }
    if (capacity < MIN_CAPACITY || capacity > MAX_CAPACITY) {
        printf("[ERROR] Invalid capacity: %zu\n", capacity);
        return;
    }

    manager = malloc(sizeof(NetEventManager));
    memset(manager, 0, sizeof(NetEventManager));
    manager->capacity = capacity;
    manager->events = malloc(sizeof(NetworkEvent) * capacity);
    if (manager->events == NULL) {
        printf("[ERROR] Failed to allocate memory for network events\n");
        return;
    }
    pthread_mutex_init(&manager->lock, NULL);
}

bool netEventManagerAddEvent(NetworkEvent* event) {
    if (manager == NULL) {
        printf("[ERROR] Network event manager not initialized\n");
        return false;
    }

    pthread_mutex_lock(&manager->lock);
    // Check if the capacity is exceeded
    if (manager->numEvents >= manager->capacity) {
        size_t newCapacity = manager->capacity * 2;
        NetworkEvent* newEvents = realloc(manager->events, sizeof(NetworkEvent) * newCapacity);
        if (newEvents == NULL) {
            printf("[ERROR] Failed to resize network event buffer\n");
            pthread_mutex_unlock(&manager->lock);
            return false;
        }
        manager->events = newEvents;
        manager->capacity = newCapacity;
    }

    // Add the event to the end of the list
    memcpy(manager->events + manager->numEvents, event, sizeof(NetworkEvent));
    manager->numEvents++;

    pthread_mutex_unlock(&manager->lock);

    return true;
}

void netEventManagerUpdate(uint32_t timestamp) {
    if (manager == NULL) {
        printf("[ERROR] Network event manager not initialized\n");
        return;
    }

    // Update the timestamp for each event in the list
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->numEvents; i++) {
        NetworkEvent* event = manager->events + i;
        event->timestamp = timestamp;
    }
    pthread_mutex_unlock(&manager->lock);
}

void netEventManagerReportStatistics() {
    if (manager == NULL) {
        printf("[ERROR] Network event manager not initialized\n");
        return;
    }

    // Print the statistics for each partition
    size_t numPartitions = manager->numEvents / PARTITION_SIZE;
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < numPartitions; i++) {
        printf("Partition %zu: ", i);
        size_t startIndex = i * PARTITION_SIZE;
        size_t endIndex = (i + 1) * PARTITION_SIZE - 1;
        if (endIndex >= manager->numEvents) {
            endIndex = manager->numEvents - 1;
        }
        for (size_t j = startIndex; j <= endIndex; j++) {
            NetworkEvent* event = manager->events + j;
            printf("%u ", event->packetId);
        }
        printf("\n");
    }
    pthread_mutex_unlock(&manager->lock);
}

void netEventManagerDestroy() {
    if (manager == NULL) {
        printf("[ERROR] Network event manager not initialized\n");
        return;
    }

    free(manager->events);
    manager->events = NULL;
    pthread_mutex_destroy(&manager->lock);
    free(manager);
    manager = NULL;
}

// Unit tests
#include <stdio.h>
#include <stdbool.h>
#include <assert.h>

static bool testAddEvent() {
    netEventManagerInit(1000);
    NetworkEvent event;
    event.timestamp = 1000;
    event.packetId = 1000;
    event.type = 0; // arrival
    assert(netEventManagerAddEvent(&event));
    netEventManagerDestroy();
    return true;
}

static bool testUpdate() {
    netEventManagerInit(1000);
    NetworkEvent event;
    event.timestamp = 1000;
    event.packetId = 1000;
    event.type = 0; // arrival
    assert(netEventManagerAddEvent(&event));
    netEventManagerUpdate(2000);
    netEventManagerDestroy();
    return true;
}

static bool testReportStatistics() {
    netEventManagerInit(1000);
    NetworkEvent event;
    event.timestamp = 1000;
    event.packetId = 1000;
    event.type = 0; // arrival
    assert(netEventManagerAddEvent(&event));
    netEventManagerReportStatistics();
    netEventManagerDestroy();
    return true;
}

int main() {
    testAddEvent();
    testUpdate();
    testReportStatistics();
    return 0;
}']

