#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>
#include <semaphore.h>

// Structure to represent a CRC indication PDU
typedef struct {
    int rx_ue_information_tag;
    unsigned short rnti;
    char crc_indication_rel8_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Global variable to store the list of generated CRC indications
NFAPI_CRC_INDICATION_PDU_T *crc_indication_list = NULL;

// Function to generate and populate a list of CRC indications asynchronously
void generateAndPopulateNFADPDUs(int n, int sessionID, int maxEntriesPerSession) {
    // Create a new thread to handle the generation of CRC indications
    pthread_t generationThread;
    if (pthread_create(&generationThread, NULL, generateCRCIndications, (void *)sessionID) != 0) {
        fprintf(stderr, "Error creating generation thread\n");
        return;
    }

    // Create a semaphore to synchronize access to the list of generated CRC indications
    sem_t *crcIndicationSemaphore = NULL;
    if ((crcIndicationSemaphore = sem_open("crcIndicationSemaphore", O_CREAT, 0644, 1)) == SEM_FAILED) {
        fprintf(stderr, "Error creating semaphore\n");
        return;
    }

    // Loop until the generation thread finishes and signals the completion of CRC indication generation
    bool generationComplete = false;
    while (!generationComplete) {
        // Wait on the semaphore to acquire access to the list of generated CRC indications
        if (sem_wait(crcIndicationSemaphore) == -1) {
            fprintf(stderr, "Error waiting for semaphore\n");
            return;
        }

        // Check if the generation thread has finished and signal completion
        if (generationComplete) {
            break;
        }

        // Generate a random RNTI value and create a new CRC indication record
        unsigned short rnti = generateRandomRNTI();
        NFAPI_CRC_INDICATION_PDU_T crcIndication = {0};
        crcIndication.rx_ue_information_tag = sessionID;
        crcIndication.rnti = rnti;
        crcIndication.crc_indication_rel8_tag = generateRandomCRCIndicationRel8Tag();
        crcIndication.crcflag = true;

        // Add the new CRC indication record to the list of generated CRC indications
        if (addToGeneratedCRCIndications(&crcIndication) != 0) {
            fprintf(stderr, "Error adding to generated CRC indications\n");
            return;
        }

        // Signal completion of CRC indication generation and release the semaphore
        generationComplete = true;
        if (sem_post(crcIndicationSemaphore) == -1) {
            fprintf(stderr, "Error posting to semaphore\n");
            return;
        }
    }

    // Close the semaphore and join the generation thread
    if (sem_close(crcIndicationSemaphore) != 0) {
        fprintf(stderr, "Error closing semaphore\n");
        return;
    }
    if (pthread_join(generationThread, NULL) != 0) {
        fprintf(stderr, "Error joining generation thread\n");
        return;
    }
}

// Function to generate a random RNTI value
unsigned short generateRandomRNTI() {
    // Initialize the random number generator with a seed based on the current time
    srand((unsigned int)time(NULL));

    // Generate a random RNTI value within the range of 0-65535
    return (unsigned short)(rand() % 65536);
}

// Function to generate a random CRC indication Rel8 tag value
char generateRandomCRCIndicationRel8Tag() {
    // Initialize the random number generator with a seed based on the current time
    srand((unsigned int)time(NULL));

    // Generate a random CRC indication Rel8 tag value within the range of 0-255
    return (char)(rand() % 256);
}

// Function to add a new CRC indication record to the list of generated CRC indications
int addToGeneratedCRCIndications(NFAPI_CRC_INDICATION_PDU_T *crcIndication) {
    // Check if the list of generated CRC indications is empty
    if (crc_indication_list == NULL) {
        // Allocate memory for the first element in the list
        crc_indication_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (crc_indication_list == NULL) {
            fprintf(stderr, "Error allocating memory for generated CRC indications\n");
            return -1;
        }
    } else {
        // Allocate memory for a new element in the list and append it to the end of the list
        NFAPI_CRC_INDICATION_PDU_T *newElement = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (newElement == NULL) {
            fprintf(stderr, "Error allocating memory for new CRC indication record\n");
            return -1;
        }
        crc_indication_list->next = newElement;
    }

    // Copy the new CRC indication record into the list
    memcpy(crc_indication_list, crcIndication, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    return 0;
}

// Function to signal completion of CRC indication generation and release the semaphore
void signalCompletionOfCRCIndicationGeneration() {
    // Set the flag indicating that CRC indication generation has completed
    generationComplete = true;

    // Release the semaphore to allow other threads to access the list of generated CRC indications
    if (sem_post(crcIndicationSemaphore) == -1) {
        fprintf(stderr, "Error posting to semaphore\n");
        return;
    }
}

// Function to generate a random RNTI value for testing purposes
unsigned short generateTestRandomRNTI() {
