    // Generate a random CRC indication Rel8 tag value within the range of 0-255
    return (char)(rand() % 256);
}

// Function to test the addToGeneratedCRCIndications function for errors
void testAddToGeneratedCRCIndications(NFAPI_CRC_INDICATION_PDU_T *crcIndication) {
