    uint32_t rx_ue_information_tag;
    uint8_t l1_command_type;
    void* test_command_data;
};

// Define the configuration structure for defining thresholds for CPU, memory, and network utilization
struct processing_configuration {
    float cpu_threshold;
    float mem_threshold;
    float net_threshold;
};

// Define the persistent cache structure to store processed PDUs
struct persistent_cache {
    struct nfapi_l1_test_command_pdu* pdu_list;
    uint32_t pdu_count;
};

// Function declarations
void processAndCacheNFADPDUs(int sessionID, int maxEntriesPerSession, struct processing_configuration* config);
struct nfapi_l1_test_command_pdu* getNextProcessedPDUSlot(uint32_t rx_ue_information_tag);
void insertProcessedPDU(struct nfapi_l1_test_command_pdu* pdu);
void updateCacheSize(int sessionID, int maxEntriesPerSession);
void processCommandPayload(struct nfapi_l1_test_command_pdu* pdu);
float calculateCPUUtilization();
float calculateMemoryUtilization();
float calculateNetworkUtilization();
int getCurrentCacheSize(int sessionID, int maxEntriesPerSession);
void cleanupProcessedPDUs(int sessionID, int maxEntriesPerSession);

// Global variables
struct persistent_cache* cache;
pthread_mutex_t lock;
semaphore_t semaphore;

// Implementation of the processAndCacheNFADPDUs function
void processAndCacheNFADPDUs(int sessionID, int maxEntriesPerSession, struct processing_configuration* config) {
    // Initialize the cache and lock if necessary
    if (!cache) {
        cache = (struct persistent_cache*)calloc(1, sizeof(struct persistent_cache));
        cache->pdu_list = (struct nfapi_l1_test_command_pdu*)calloc(maxEntriesPerSession, sizeof(struct nfapi_l1_test_command_pdu));
        cache->pdu_count = 0;
    }
    if (!lock) {
        pthread_mutex_init(&lock, NULL);
    }
    if (!semaphore) {
        semaphore_init(&semaphore, 1);
    }

    // Loop indefinitely to process and cache NFAPI L1 test command PDUs
    while (1) {
        // Acquire the lock to synchronize access to the cache
        pthread_mutex_lock(&lock);

        // Get the next processed PDU slot
        struct nfapi_l1_test_command_pdu* pdu = getNextProcessedPDUSlot(sessionID, maxEntriesPerSession);

        // Check if the cache is full and update the cache size accordingly
        if (cache->pdu_count >= maxEntriesPerSession) {
            updateCacheSize(sessionID, maxEntriesPerSession);
        }

        // Insert the processed PDU into the cache
        insertProcessedPDU(pdu);

        // Release the lock to allow other threads to access the cache
        pthread_mutex_unlock(&lock);

        // Sleep for a short duration before processing the next PDU
        sleep(1);
    }
}

// Function to get the next processed PDU slot
struct nfapi_l1_test_command_pdu* getNextProcessedPDUSlot(uint32_t rx_ue_information_tag) {
    // Find the index of the first available slot in the cache
    int index = -1;
    for (int i = 0; i < maxEntriesPerSession; i++) {
        if (cache->pdu_list[i].rx_ue_information_tag == rx_ue_information_tag) {
            index = i;
            break;
        }
    }

    // Return the next available slot in the cache
    return &cache->pdu_list[index + 1];
}

// Function to insert a processed PDU into the cache
void insertProcessedPDU(struct nfapi_l1_test_command_pdu* pdu) {
    // Update the count of PDUS in the cache
    cache->pdu_count++;

    // Copy the processed PDU into the next available slot in the cache
    memcpy(&cache->pdu_list[cache->pdu_count - 1], pdu, sizeof(struct nfapi_l1_test_command_pdu));
}

// Function to update the size of the cache based on the current number of PDUs
void updateCacheSize(int sessionID, int maxEntriesPerSession) {
    // Calculate the new cache size
    int new_cache_size = cache->pdu_count * 2;

    // Update the cache size in the configuration structure
    config[sessionID].max_entries_per_session = new_cache_size;

    // Reallocate memory for the PDU list if necessary
    if (new_cache_size > maxEntriesPerSession) {
        cache->pdu_list = realloc(cache->pdu_list, sizeof(struct nfapi_l1_test_command_pdu) * new_cache_size);
    }
}

// Function to cleanup the processed PDUs in the cache
void cleanupProcessedPDUs(int sessionID, int maxEntriesPerSession) {
    // Cleanup the PDU list if necessary
    if (cache->pdu_count > maxEntriesPerSession) {
        free(cache->pdu_list);
    }
}
