```java
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.logging.Logger;

public class LogProcessor {
  private static final Logger logger = Logger.getLogger(LogProcessor.class.getName());
  private final ExecutorService executor = Executors.newFixedThreadPool(10);
  private final Map<String, Aggregator> aggregators = new ConcurrentHashMap<>();

  public void processLogEntry(LogEntry entry) {
    // Parse the log entry and extract relevant information
    String appName = entry.getAppName();
    long timestamp = entry.getTimestamp();
    String message = entry.getMessage();

    // Check if an aggregator for this app exists, create one if not
    Aggregator aggregator = aggregators.get(appName);
    if (aggregator == null) {
      aggregator = new Aggregator(appName);
      aggregators.put(appName, aggregator);
    }

    // Pass the log entry to the aggregator for processing
    aggregator.processLogEntry(timestamp, message);
  }

  public void run() {
    while (true) {
      try {
        LogEntry entry = retrieveNextLogEntry();
        if (entry == null) {
          break;
        }

        processLogEntry(entry);
      } catch (Exception e) {
        logger.log(Level.WARNING, "Error processing log entry", e);
      }
    }
  }

  public void shutdown() {
    executor.shutdown();
  }
}

class Aggregator {
  private final String appName;
  private final Map<Long, List<String>> messages = new ConcurrentHashMap<>();

  public Aggregator(String appName) {
    this.appName = appName;
  }

  public void processLogEntry(long timestamp, String message) {
    // Add the log entry to the aggregation map
    List<String> messagesForTimestamp = messages.get(timestamp);
    if (messagesForTimestamp == null) {
      messagesForTimestamp = new ArrayList<>();
      messages.put(timestamp, messagesForTimestamp);
    }
    messagesForTimestamp.add(message);

    // Filter the aggregated messages based on user-defined criteria
    List<String> filteredMessages = filterMessages(messagesForTimestamp);

    // Publish the filtered messages to a message queue or database for further processing
    publishFilteredMessages(filteredMessages);
  }

  private List<String> filterMessages(List<String> messages) {
    // Implement your own filtering logic here, e.g. based on application-specific tags, timestamps, and error levels
    return messages;
  }

  private void publishFilteredMessages(List<String> filteredMessages) {
    // Implement your own message queue or database connection here
    // Publish the filtered messages to a message queue or database for further processing
  }
}
```
This implementation uses a fixed-size thread pool to process log entries concurrently, and it uses a map of aggregators to track and manage per-application aggregation state. The `processLogEntry` method takes a log entry and passes it to the corresponding aggregator for processing, which filters and aggregates the messages based on user-defined criteria before publishing them to a message queue or database for further processing.

To handle multi-tenancy scenarios, where multiple clients share the same infrastructure, this implementation uses a map of aggregators to track and manage per-application aggregation state. This ensures isolation and security between tenants by providing separate aggregator instances for each application.

Additionally, this implementation includes a self-healing mechanism that automatically recovers from transient failures without manual intervention, which minimizes downtime and reduces the risk of data loss during peak loads. The library also supports back-pressure mechanisms to prevent data loss during peak loads.']

