        public LogProcessor(HttpClient httpClient, ILogger<LogProcessor> logger)
        {
            _httpClient = httpClient;
            _logger = logger;
        }

        public async Task ProcessAsync(StreamReader logStream)
        {
            using var jsonReader = new JsonTextReader(logStream);

            while (jsonReader.Read())
            {
                if (jsonReader.TokenType != JsonToken.StartObject) continue;

                var logEntry = await JObject.LoadAsync(jsonReader, _jsonOptions, default).ConfigureAwait(false);

                try
                {
                    // Process log entry here
                    // ...
                }
                catch (Exception e)
                {
                    _logger.LogError(e, "Failed to process log entry");
                }
            }
        }
    }
}

