use std::sync::Arc;
use std::thread;
use std::time::Duration;

fn compile_and_manage_bundle(config: &mut Config) -> Result<(), String> {
    // Initialize the configuration object with default values if necessary
    config.initialize();

    // Create a vector to hold the worker threads
    let mut workers = Vec::new();

    // Launch the first thread for compiling the bundle
    let compile_thread = thread::spawn(move || {
        // Use the Arc<Mutex<>> wrapper to ensure synchronized access to the configuration object
        let config_ref = Arc::new(Mutex::new(config));

        // Compile the bundle using the configuration object
        compile_bundle(&config_ref).map_err(|e| {
            // Handle error by printing a message and returning an error string
            eprintln!("Failed to compile bundle: {}", e);
            "Compilation failed".to_string()
        })
    });

    workers.push(compile_thread);

    // Launch additional threads for managing the resource bundle
    for _ in 1..config.num_workers {
        let config_ref = Arc::clone(&config_ref);
        let manage_thread = thread::spawn(move || {
            // Use a loop to continually monitor and manage the resource bundle
            loop {
                // Check if there are any pending updates to the resource bundle
                if !is_resource_bundle_updating(&config_ref) {
                    // If not, sleep for a short duration before checking again
                    thread::sleep(Duration::from_secs(1));
                    continue;
                }

                // Update the resource bundle using the configuration object
                update_resource_bundle(&config_ref).map_err(|e| {
                    // Handle error by printing a message and returning an error string
                    eprintln!("Failed to update resource bundle: {}", e);
                    "Resource bundle update failed".to_string()
                })?;
            }
        });

        workers.push(manage_thread);
    }

    // Join all the worker threads and return the result of the compilation or management task that failed first
    let mut errors = Vec::new();
    for w in workers {
        if let Err(e) = w.join() {
            errors.push(e);
        }
    }

    // If any errors occurred, return an error string
    if !errors.is_empty() {
        let mut message = String::new();
        for e in &errors {
            message += &format!("{}", e);
        }
        Err(message)
    } else {
        // If no errors occurred, return a successful result
        Ok(())
    }
}

fn compile_bundle(config: &Arc<Mutex<Config>>) -> Result<(), String> {
    // Use the configuration object to obtain the paths to the source files and build directory
    let source_files = config.lock().unwrap().source_files;
    let build_directory = config.lock().unwrap().build_directory;

    // Compile the bundle using the Rust compiler
    let output_file = compile_rust(source_files, build_directory)?;

    // Save the compiled binary to the configuration object
    let mut config = config.lock().unwrap();
    config.output_binary = Some(output_file);

    Ok(())
}

fn update_resource_bundle(config: &Arc<Mutex<Config>>) -> Result<(), String> {
    // Use the configuration object to obtain the path to the resource bundle JSON file
    let resource_bundle_path = config.lock().unwrap().resource_bundle_path;

    // Load the resource bundle from the JSON file
    let resource_bundle = load_resource_bundle(resource_bundle_path)?;

    // Update the resource bundle using the configuration object
    update_resource_bundle(&mut config.lock().unwrap(), &resource_bundle)?;

    Ok(())
}

fn is_resource_bundle_updating(config: &Arc<Mutex<Config>>) -> bool {
    // Use the configuration object to check if there are any pending updates to the resource bundle
    config.lock().unwrap().is_resource_bundle_updating()
}
