using System.Security.Cryptography;
using System.Text;

namespace SecureContentProcessor
{
    public class ContentProcessor
    {
        private static readonly string HashAlgorithm = "MD5"; // Initially, use MD5 for hash generation. Can be upgraded to SHA-256 if necessary.
        private static readonly int HashSize = 128; // The size of the generated hash in bits.
        private static readonly int SaltLength = 16; // The length of the salt used for hashing, in bytes.

        public static string GenerateHash(string input)
        {
            if (input == null || input.Length == 0) return null; // Handle edge cases gracefully.

            using var sha = new SHA256Managed(); // Use a SHA-256 hash algorithm to generate the hash.
            byte[] salt = GenerateSalt(); // Generate a random salt for hashing.
            byte[] inputBytes = Encoding.UTF8.GetBytes(input);
            byte[] outputBytes = sha.ComputeHash(inputBytes);
            string outputString = BitConverter.ToString(outputBytes).Replace("-", ""); // Convert the hash to a string representation.
            return $"{HashAlgorithm}:{outputString}"; // Return the generated hash, including the algorithm and its resulting string.
        }

        private static byte[] GenerateSalt()
        {
            using var rng = new RNGCryptoServiceProvider(); // Use a cryptographically secure random number generator to generate the salt.
            byte[] salt = new byte[SaltLength];
            rng.GetBytes(salt);
            return salt;
        }
    }
}
