#ifndef REAL_TIME_DATA_PROCESSOR_H
#define REAL_TIME_DATA_PROCESSOR_H

#include <string>
#include <map>
#include <memory>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <thread>

class RealTimeDataProcessor {
public:
    RealTimeDataProcessor();
    ~RealTimeDataProcessor();

    void startProcessing(std::string dataSource, std::string format);
    void stopProcessing();
    bool isRunning() const;

private:
    class DataSource {
    public:
        DataSource(const std::string& name, const std::string& format);
        ~DataSource();

        void start();
        void stop();
        bool isRunning() const;

        void processData(const std::string& data);
        bool hasData() const;
        void clearData();

    private:
        std::string name_;
        std::string format_;
        std::mutex mutex_;
        std::condition_variable conditionVariable_;
        std::unique_ptr<std::thread> thread_;
        bool running_;
        std::map<std::string, std::shared_ptr<std::string>> dataMap_;
    };

    class DataTransformer {
    public:
        DataTransformer(const std::string& name);
        ~DataTransformer();

        void start();
        void stop();
        bool isRunning() const;

        void transformData(const std::string& data);
        bool hasData() const;
        void clearData();

    private:
        std::string name_;
        std::mutex mutex_;
        std::condition_variable conditionVariable_;
        std::unique_ptr<std::thread> thread_;
        bool running_;
        std::map<std::string, std::shared_ptr<std::string>> dataMap_;
    };

    class DataCache {
    public:
        DataCache();
        ~DataCache();

        void cacheData(const std::string& data);
        bool hasCachedData() const;
        void clearCache();

    private:
        std::mutex mutex_;
        std::condition_variable conditionVariable_;
        std::unique_ptr<std::thread> thread_;
        bool running_;
        std::map<std::string, std::shared_ptr<std::string>> dataMap_;
    };

    void processData(const std::string& data);
    void handleError();
    void logStatus();

private:
    std::mutex mutex_;
    std::condition_variable conditionVariable_;
    bool running_;
    std::map<std::string, std::unique_ptr<DataSource>> dataSources_;
    std::map<std::string, std::unique_ptr<DataTransformer>> dataTransformers_;
    std::unique_ptr<DataCache> dataCache_;
};

#endif // REAL_TIME_DATA_PROCESSOR_H
