// RealTimeDataProcessor.cpp
```c++
#include "RealTimeDataProcessor.h"

RealTimeDataProcessor::RealTimeDataProcessor() {
    running_ = false;
}

RealTimeDataProcessor::~RealTimeDataProcessor() {
    stopProcessing();
}

void RealTimeDataProcessor::startProcessing(const std::string& dataSource, const std::string& format) {
    if (running_) {
        return;
    }

    running_ = true;

    // Create the data source object and start processing
    auto dataSourceObject = std::make_unique<DataSource>(dataSource, format);
    dataSources_.emplace(dataSource, std::move(dataSourceObject));
    dataSources_.at(dataSource)->start();

    // Create the data transformer object and start processing
    auto dataTransformerObject = std::make_unique<DataTransformer>(dataSource);
    dataTransformers_.emplace(dataSource, std::move(dataTransformerObject));
    dataTransformers_.at(dataSource)->start();
}

void RealTimeDataProcessor::stopProcessing() {
    if (!running_) {
        return;
    }

    running_ = false;

    // Stop all data sources and transformers
    for (auto& [name, source] : dataSources_) {
        source->stop();
    }

    for (auto& [name, transformer] : dataTransformers_) {
        transformer->stop();
    }
}

bool RealTimeDataProcessor::isRunning() const {
    return running_;
}
