// DataSource.cpp
```c++
#include "RealTimeDataProcessor.h"

RealTimeDataProcessor::DataSource::DataSource(const std::string& name, const std::string& format) : name_(name), format_(format) {
    running_ = false;
}

RealTimeDataProcessor::DataSource::~DataSource() {
    stop();
}

void RealTimeDataProcessor::DataSource::start() {
    if (running_) {
        return;
    }

    running_ = true;

    // Start the data source thread
    std::thread([this](){
        while (running_) {
            try {
                // Fetch the latest data from the streaming API
                auto data = fetchData();

                if (!data.empty()) {
                    processData(data);
                } else {
                    break;
                }
            } catch (const std::exception& e) {
                handleError(e.what());
            }
        }
    }).detach();
}

void RealTimeDataProcessor::DataSource::stop() {
    if (!running_) {
        return;
    }

    running_ = false;
}

bool RealTimeDataProcessor::DataSource::isRunning() const {
    return running_;
}
