// Define the structure for a network event
struct NetworkEvent {
    int id; // unique identifier for each event
    uint64_t timestamp; // time of arrival/occurrence
    uint32_t data[]; // variable-length data field
};

// Define a hash table for storing the events
struct HashTable {
    struct NetworkEvent** events; // array of pointers to network events
    size_t capacity; // current capacity of the hash table
    size_t count; // number of elements in the hash table
    pthread_mutex_t* mutex; // mutex for synchronizing access
};

// Define a linked list for storing the events in chronological order
struct LinkedList {
    struct NetworkEvent* head; // pointer to the head of the linked list
    size_t count; // number of elements in the linked list
    pthread_mutex_t* mutex; // mutex for synchronizing access
};

// Define a data structure for storing the events and the corresponding metrics
struct Metrics {
    struct HashTable* hashTable; // hash table for storing the events
    struct LinkedList* linkedList; // linked list for storing the events in chronological order
    size_t totalEvents; // total number of events received
    uint64_t averageDuration; // average duration of the events
    float criticalEventPercentage; // percentage of critical events
};

// Initialize a hash table with an initial capacity and support efficient resizing when the capacity is exceeded.
static void initHashTable(struct HashTable* table, size_t initialCapacity) {
    table->events = (struct NetworkEvent**)malloc(initialCapacity * sizeof(struct NetworkEvent*));
    if (table->events == NULL) {
        // Handle memory allocation failure gracefully
        printf("Error: Failed to allocate memory for the hash table\n");
        exit(1);
    }
    table->capacity = initialCapacity;
    table->count = 0;
    pthread_mutex_init(&table->mutex, NULL);
}

// Insert a network event into the hash table and update the linked list in chronological order.
static void insertEvent(struct HashTable* table, struct NetworkEvent* event) {
    // Acquire a lock on the hash table mutex to ensure thread-safe access
    pthread_mutex_lock(&table->mutex);

    // Check if the hash table is at capacity and resize it if necessary
    if (table->count >= table->capacity) {
        size_t newCapacity = table->capacity * 2;
        struct NetworkEvent** newEvents = (struct NetworkEvent**)realloc(table->events, newCapacity * sizeof(struct NetworkEvent*));
        if (newEvents == NULL) {
            // Handle memory allocation failure gracefully
            printf("Error: Failed to resize the hash table\n");
            exit(1);
        }
        table->events = newEvents;
        table->capacity = newCapacity;
    }

    // Insert the event into the hash table and update the linked list in chronological order
    table->events[table->count++] = event;
    if (table->head == NULL) {
        table->head = event;
    } else {
        struct NetworkEvent* current = table->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = event;
    }

    // Release the lock on the hash table mutex
    pthread_mutex_unlock(&table->mutex);
}

// Retrieve a network event from the hash table and remove it from the linked list.
static struct NetworkEvent* retrieveEvent(struct HashTable* table, int id) {
    // Acquire a lock on the hash table mutex to ensure thread-safe access
    pthread_mutex_lock(&table->mutex);

    // Find the event in the hash table and remove it from the linked list
    struct NetworkEvent* current = table->head;
    while (current != NULL && current->id != id) {
        current = current->next;
