    struct NetworkEvent* event = current;
    current = current->next;
    event->next = NULL;
    if (current == NULL) {
        table->head = NULL;
    } else {
        table->head = current;
    }

    // Release the lock on the hash table mutex
    pthread_mutex_unlock(&table->mutex);

    return event;
}

// Initialize a linked list with an initial capacity and support efficient resizing when the capacity is exceeded.
static void initLinkedList(struct LinkedList* list, size_t initialCapacity) {
    list->head = (struct NetworkEvent*)malloc(initialCapacity * sizeof(struct NetworkEvent));
    if (list->head == NULL) {
        // Handle memory allocation failure gracefully
        printf("Error: Failed to allocate memory for the linked list\n");
        exit(1);
