    // Acquire a lock on the linked list mutex to ensure thread-safe access
    pthread_mutex_lock(&list->mutex);

    // Check if the linked list is at capacity and resize it if necessary
    if (list->count >= list->capacity) {
        size_t newCapacity = list->capacity * 2;
        struct NetworkEvent* newEvents = (struct NetworkEvent*)realloc(list->head, newCapacity * sizeof(struct NetworkEvent));
        if (newEvents == NULL) {
