            printf("Error: Failed to resize the linked list\n");
            exit(1);
        }
        list->head = newEvents;
        list->capacity = newCapacity;
    }

    // Insert the event into the linked list
    list->head[list->count++] = event;

    // Release the lock on the linked list mutex
    pthread_mutex_unlock(&list->mutex);
}

// Retrieve a network event from the linked list.
static struct NetworkEvent* retrieveEventFromLinkedList(struct LinkedList* list, int id) {
    // Acquire a lock on the linked list mutex to ensure thread-safe access
    pthread_mutex_lock(&list->mutex);

    // Find the event in the linked list and remove it from the list
    struct NetworkEvent* current = list->head;
    while (current != NULL && current->id != id) {
        current = current->next;
