    while (true) {
        // Lock the raw data mutex to access the vector
        rawDataMutex.lock();

        if (rawData.empty()) {
            // If the vector is empty, wait for new data to arrive
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        } else {
            // Process the first element in the vector and remove it from the map
            RawData rawData = rawData.front();
            uniqueIdToRawDataMap.erase(rawData.uniqueId);
            rawDataMutex.unlock();

            // Perform data processing on the raw data
            DataProcessing dataProcessing;
            auto processedData = dataProcessing.processData(rawData);

            // Handle errors during data processing
            if (processedData == nullptr) {
                errorHandling.handleError("Failed to process data", "DataProcessor");
            } else {
                // Add the processed data to the map for further analysis
                uniqueIdToProcessedDataMap[rawData.uniqueId] = processedData;
            }
        }
    }
}
