type Request struct {
	Method  string `json:"method"`
	Url     string `json:"url"`
	Headers map[string]string `json:"headers"`
	Body    []byte   `json:"body"`
}

type Response struct {
	StatusCode int         `json:"status_code"`
	Headers    map[string]string `json:"headers"`
	Body      []byte       `json:"body"`
}

func handleRequest(w http.ResponseWriter, r *http.Request) {
	// Handle incoming request and create a new context
	ctx := context.Background()

	// Check if the request is valid
	if err := validateRequest(r); err != nil {
		log.Printf("Invalid request: %v", err)
		http.Error(w, fmt.Sprintf("Invalid request: %v", err), http.StatusBadRequest)
		return
	}

	// Create a new request object
	req := &Request{
		Method:  r.Method,
		Url:     r.URL.String(),
		Headers: make(map[string]string),
		Body:    []byte(""),
	}

	// Set the headers and body for the request object
	for k, v := range r.Header {
		req.Headers[k] = v[0]
	}
	body := make([]byte, r.ContentLength)
	r.Body.Read(body)
	req.Body = body

	// Handle the request and create a response object
	resp, err := handleRequestInternal(ctx, req)
	if err != nil {
		log.Printf("Error handling request: %v", err)
		http.Error(w, fmt.Sprintf("Error handling request: %v", err), http.StatusInternalServerError)
		return
	}

	// Write the response back to the client
	for k, v := range resp.Headers {
		w.Header().Set(k, v)
	}
	w.WriteHeader(resp.StatusCode)
	_, _ = w.Write([]byte(resp.Body))
}

