                if (!deployed)
                {
                    Console.WriteLine("Deployment failed.");
                    return false;
                }

                // Rollback on failure.
                if (result.HasError || !deployed)
                {
                    bool rolledBack = await RollbackSiteAsync(directoryPath, siteName);
                    if (!rolledBack)
                    {
                        Console.WriteLine(string.Format("Rollback failed: {0}.", DEPLOYMENT_FAILURE_MESSAGE));
                        return false;
                    }
                }

                // Notify relevant teams on success or failure.
                if (deployed)
                {
                    Console.WriteLine("Deployment successful.");
                    _alertService.Alert(string.Format("Site deployment successful: {0}", siteName));
                }
                else
                {
                    Console.WriteLine(string.Format("Deployment failed: {0}.", DEPLOYMENT_FAILURE_MESSAGE));
                    _alertService.Alert(string.Format("Site deployment failed: {0}", siteName));
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine(ex);
                return false;
            }
