using namespace std;

namespace PasswordEngine {
    class SecureGenerator {
    public:
        SecureGenerator(int seed = 0) : gen_(seed), dis_(0, 1) {}
        ~SecureGenerator() {}

        int generateRandomNumber() {
            return dis_(gen_);
        }

    private:
        random_device rd;
        mt19937 gen_;
        uniform_int_distribution<int> dis_;
    };
}

class PasswordManager {
public:
    static const int MAX_SEED = 10000;
    static const int MIN_SEED = 0;

    PasswordManager(int seed = 0) {
        if (seed < MIN_SEED || seed > MAX_SEED) {
            seed = getCurrentTimeSeed();
        }
        gen_.seed(seed);
    }

    ~PasswordManager() {}

    string generateRandomPassword(int len) {
        return generatePassword(len);
    }

private:
    SecureGenerator gen_;

    static int getCurrentTimeSeed() {
        return chrono::high_resolution_clock::now().time_since_epoch().count();
    }

    string generatePassword(int len) {
        if (len <= 0 || len > 128) {
            throw invalid_argument("Invalid password length");
        }

        string password;

        while (password.size() < len) {
            int nextChar = gen_.generateRandomNumber();
            char c = nextChar % 26 + 'a';
            if (nextChar > 26 && nextChar % 26 == 0) {
                c = nextChar % 10 + '0';
            }
            password += c;
        }

        return password;
    }
};
```
