    NetworkEvent *events;
    size_t num_events;
} EventList;

/* Function to initialize the library with an initial capacity and support efficient resizing when the capacity is exceeded */
int network_event_initialize(size_t init_capacity) {
    EventTable *table = malloc(sizeof(EventTable));
    if (table == NULL) {
        perror("malloc");
        return -1;
    }
    table->next_event_index = 0;
    table->events = calloc(EVENT_TABLE_SIZE, sizeof(NetworkEvent));
    if (table->events == NULL) {
        perror("calloc");
        free(table);
        return -1;
    }
    size_t capacity = EVENT_CAPACITY;
    if (init_capacity > 0 && init_capacity < capacity) {
        capacity = init_capacity;
    }
    table->events[0].event_type = -1; /* no events yet */
    return 0;
}

