    EventTable *table = get_event_table();
    if (table == NULL) {
        fprintf(stderr, "Error: failed to get event table\n");
        return -1;
    }
    pthread_mutex_lock(&table->lock);
    if (table->next_event_index >= EVENT_TABLE_SIZE) {
        fprintf(stderr, "Error: event table is full\n");
        pthread_mutex_unlock(&table->lock);
        return -1;
    }
    size_t idx = table->next_event_index++;
    table->events[idx] = *event;
    pthread_mutex_unlock(&table->lock);
    return 0;
}

/* Function to retrieve a list of events from the library */
EventList network_event_list(size_t num_events) {
    EventTable *table = get_event_table();
    if (table == NULL) {
        fprintf(stderr, "Error: failed to get event table\n");
        return -1;
    }
    pthread_mutex_lock(&table->lock);
    size_t idx = 0;
    while (idx < table->next_event_index && num_events > 0) {
        NetworkEvent *event = &table->events[idx];
