            if (list.events == NULL) {
                perror("malloc");
                pthread_mutex_unlock(&table->lock);
                return -1;
            }
            size_t events_copied = 0;
            for (size_t i = idx; i < table->next_event_index && events_copied < num_events; i++) {
                NetworkEvent *src = &table->events[i];
                if (checksum_valid(src)) {
                    memcpy(&list.events[events_copied], src, sizeof(NetworkEvent));
                    events_copied++;
                } else {
                    fprintf(stderr, "Warning: checksum for event at index %zu is invalid\n", i);
                }
            }
            list.num_events = events_copied;
