Here is a proposed design for an octree manager class that implements the requested features:
```c++
class OctreeManager {
 public:
  // Constructor to initialize the octree manager
  OctreeManager(int max_level = 8, int initial_size = 1000) :
      max_level_(max_level), initial_size_(initial_size) {}

  // Function to add a new node to the octree
  void AddNode(const Point& point, const Data& data);

  // Function to remove a node from the octree
  bool RemoveNode(const Point& point);

  // Function to query the octree for nodes near a given point
  std::vector<Data> Query(const Point& point) const;

  // Function to get the number of nodes in the octree
  int GetNumNodes() const;

 private:
  // Maximum level of the octree
  int max_level_;

  // Initial size of the octree
  int initial_size_;

  // Root node of the octree
  std::shared_ptr<OctreeNode> root_;
};
```
The `AddNode` function adds a new node to the octree with the given point and data. The function checks if the node is already present in the tree, and if not, it adds it at the appropriate level based on its distance from the root node. If the tree needs to be resized, it creates a new node at the next higher level and reassigns all the nodes in the tree to it.
```c++
void OctreeManager::AddNode(const Point& point, const Data& data) {
  // Check if the node is already present in the tree
  auto iter = root_->Find(point);
  if (iter != root_->end()) {
    return;
  }

  // Add the new node at the appropriate level
  int level = GetLevel(root_, point);
  std::shared_ptr<OctreeNode> new_node =
      std::make_shared<OctreeNode>(point, data, level);
  root_->AddChild(new_node);

  // Resize the tree if needed
  int num_nodes = GetNumNodes();
  if (num_nodes > initial_size_) {
    ResizeTree(num_nodes + initial_size_);
  }
}
```
The `RemoveNode` function removes a node from the octree with the given point. If the node is not present in the tree, it returns false. Otherwise, it removes the node and reassigns all the children of the removed node to its parent.
```c++
bool OctreeManager::RemoveNode(const Point& point) {
  // Find the node to remove
  auto iter = root_->Find(point);
  if (iter == root_->end()) {
    return false;
  }

  // Remove the node from the tree and reassign its children
  std::shared_ptr<OctreeNode> node = *iter;
  root_->RemoveChild(node);
  for (auto child : node->children_) {
    root_->AddChild(child);
  }
  return true;
}
```
The `Query` function returns a vector of nodes near the given point. It uses a recursive algorithm to traverse the tree and find all the nodes within the specified distance of the query point.
```c++
std::vector<Data> OctreeManager::Query(const Point& point) const {
  std::vector<Data> results;
  Query(point, root_, results);
  return results;
}

void OctreeManager::Query(const Point& point,
                         const std::shared_ptr<OctreeNode>& node,
                         std::vector<Data>& results) const {
  if (node->IsLeaf()) {
    // Check if the node is within the specified distance of the query point
    double distance = Distance(point, node->point_);
    if (distance <= max_level_) {
      results.push_back(node->data_);
    }
  } else {
    for (auto child : node->children_) {
      // Recursively query the children of the current node
      Query(point, child, results);
    }
  }
}
```
The `GetNumNodes` function returns the number of nodes in the octree. It uses a recursive algorithm to traverse the tree and count the total number of nodes.
```c++
int OctreeManager::GetNumNodes() const {
  return GetNumNodes(root_);
}

int OctreeManager::GetNumNodes(const std::shared_ptr<OctreeNode>& node) const {
  int num_nodes = 0;
  if (node->IsLeaf()) {
    ++num_nodes;
  } else {
    for (auto child : node->children_) {
      // Recursively count the number of nodes in the current node's children
      num_nodes += GetNumNodes(child);
    }
  }
  return num_nodes;
}
```
The `ResizeTree` function resizes the tree to the specified size. It creates a new root node with the given size and reassigns all the nodes in the tree to it.
```c++
void OctreeManager::ResizeTree(int size) {
  // Create a new root node with the specified size
  std::shared_ptr<OctreeNode> new_root =
      std::make_shared<OctreeNode>(size);

  // Reassign all the nodes in the tree to the new root node
  for (auto child : root_->children_) {
    new_root->AddChild(child);
  }
}
```
The `GetLevel` function returns the level of the given point in the octree. It uses a recursive algorithm to traverse the tree and find the level of the point.
```c++
int OctreeManager::GetLevel(const Point& point) const {
  return GetLevel(root_, point);
}

int OctreeManager::GetLevel(const std::shared_ptr<OctreeNode>& node,
                           const Point& point) const {
  int level = -1;
  if (node->IsLeaf()) {
    double distance = Distance(point, node->point_);
    if (distance <= max_level_) {
      ++level;
    }
  } else {
    for (auto child : node->children_) {
      // Recursively get the level of the current node's children
      int child_level = GetLevel(child, point);
      if (child_level >= 0) {
        ++level;
      }
    }
  }
  return level;
}
