        return 1; // error status code
    }

    // Validate OAuth2 access token response
    AccessTokenResponse *response = getOAuth2AccessToken(config->password);
    if (response == NULL || strcmp(response->token_type, "Bearer") != 0 || response->expires_in <= 0) {
        return 2; // error status code
    }

    // Enforce minimum attack interval
    int cooldown = COOLDOWN_DURATION - (int)(time(NULL) % COOLDOWN_DURATION);
    if (cooldown < 0) {
        cooldown += COOLDOWN_DURATION;
    }
    sleep(cooldown);

    // Select one of two possible attacks with equal probability
    int attack = rand() % 2 + 1; // random number between 1 and 2
    if (attack == 1) {
        // Attack 1: basic attack
        config->callback(config->connection.title);
    } else {
        // Attack 2: advanced attack
        config->callback(config->connection.title);
    }

    return 0; // success status code
}
