int processOrderRequest(const PaymentGatewayConfig *config, const char *orderJson) {
    // Validate the payment gateway configuration
    if (validatePaymentGatewayConfig(config) != 0) {
        return ERROR_STATUS;
    }

    // Initialize a JSON parser for the order JSON string
    json_t *root = NULL;
    json_error_t error;
    root = json_loads(orderJson, 0, &error);
    if (root == NULL) {
        fprintf(stderr, "JSON parsing failed: %s\n", error.text);
        return ERROR_STATUS;
    }

    // Parse and validate the required fields in the JSON string
    json_t *status = json_object_get(root, STATUS_KEY);
    if (status == NULL || !json_is_string(status)) {
        fprintf(stderr, "Invalid status field\n");
        goto cleanup;
    }
    json_t *transactionId = json_object_get(root, TRANSACTION_ID_KEY);
    if (transactionId == NULL || !json_is_string(transactionId)) {
        fprintf(stderr, "Invalid transaction ID field\n");
        goto cleanup;
    }
    json_t *amount = json_object_get(root, AMOUNT_KEY);
    if (amount == NULL || !json_is_number(amount)) {
        fprintf(stderr, "Invalid amount field\n");
        goto cleanup;
    }
    json_t *currency = json_object_get(root, CURRENCY_KEY);
    if (currency == NULL || !json_is_string(currency)) {
        fprintf(stderr, "Invalid currency field\n");
        goto cleanup;
    }
    json_t *paymentMethod = json_object_get(root, PAYMENT_METHOD_KEY);
    if (paymentMethod == NULL || !json_is_string(paymentMethod)) {
        fprintf(stderr, "Invalid payment method field\n");
        goto cleanup;
    }

    // Check the status value and return an error if it's not 'success' or 'failure'
    const char *statusString = json_string_value(status);
    if (strcmp(statusString, SUCCESS_VALUE) != 0 && strcmp(statusString, FAILURE_VALUE) != 0) {
        fprintf(stderr, "Invalid status value\n");
        goto cleanup;
    }

    // Create a JSON object for the payment gateway API request
    json_t *request = json_object();
    json_object_set_new(request, "order", root);

    // Set up the curl handle for making the API request
    CURL *curlHandle = NULL;
    CURLcode res;
    char errorBuffer[CURL_ERROR_SIZE];
    long responseCode;

    int retryCount = 0;
    do {
        // Set up the URL, headers, and payload for the API request
        curlHandle = curl_easy_init();
        if (curlHandle == NULL) {
            fprintf(stderr, "Failed to initialize CURL handle\n");
            goto cleanup;
        }
        curl_easy_setopt(curlHandle, CURLOPT_URL, PAYMENT_GATEWAY_ENDPOINT);
        curl_easy_setopt(curlHandle, CURLOPT_HTTPHEADER, HEADERS);
        curl_easy_setopt(curlHandle, CURLOPT_POSTFIELDS, json_dumps(request));
        curl_easy_setopt(curlHandle, CURLOPT_WRITEFUNCTION, writeCallback);
        curl_easy_setopt(curlHandle, CURLOPT_ERRORBUFFER, errorBuffer);
        curl_easy_setopt(curlHandle, CURLOPT_TIMEOUT, TIMEOUT_SECS);

        // Perform the API request and handle the response
        res = curl_easy_perform(curlHandle);
        if (res != CURLE_OK) {
            fprintf(stderr, "CURL error: %s\n", curl_easy_strerror(res));
            goto cleanup;
        }
        curl_easy_getinfo(curlHandle, CURLINFO_RESPONSE_CODE, &responseCode);
        if (responseCode != 200) {
            fprintf(stderr, "Response code: %ld\n", responseCode);
            goto cleanup;
        }

        // Check the status of the API request and retry if necessary
        json_t *apiStatus = NULL;
        apiStatus = json_object_get(root, STATUS_KEY);
        const char *apiStatusString = json_string_value(apiStatus);
        if (strcmp(apiStatusString, SUCCESS_VALUE) != 0 && strcmp(apiStatusString, FAILURE_VALUE) != 0) {
            retryCount++;
            sleep(RETRY_DELAY);
        } else {
            // Successful API request, exit the retry loop
            break;
        }
    } while (retryCount < MAX_RETRIES);

cleanup:
    if (root != NULL) {
        json_decref(root);
    }
    if (curlHandle != NULL) {
        curl_easy_cleanup(curlHandle);
    }

    return 0;
}

int main(void) {
    const char *orderJson = "{\"amount\":123.45,\"currency\":\"USD\",\"paymentMethod\":\"creditcard\"}";
