// State management database connection pool
struct connection_pool {
    int size;                     // Size of the connection pool
    int in_use;                   // Number of connections currently in use
    pthread_mutex_t lock;         // Lock for accessing the connection pool
    struct connection* connections;  // Array of connections
};

// State management database connection
struct connection {
    int fd;                       // File descriptor for the connection
    char* hostname;               // Hostname of the server
    unsigned short port;          // Port number of the server
    pthread_mutex_t lock;         // Lock for accessing the connection
};

// State list structure
struct state_list {
    int size;                     // Size of the state list
    struct state* states;         // Array of states
    pthread_mutex_t lock;         // Lock for accessing the state list
};

// State structure
struct state {
    char* name;                   // Name of the state
    int id;                       // Unique identifier of the state
    struct connection* conn;      // Connection to the database for this state
};

// Function to create a new state list from an FSA and an integer array of states
struct state_list* create_state_list(int* states, int num_states, struct fsa* fsa, int last_state) {
    // Check for valid inputs
    if (states == NULL || fsa == NULL || last_state < 0 || last_state >= fsa->num_states) {
        return NULL;
    }

    // Allocate memory for the state list
    struct state_list* state_list = malloc(sizeof(struct state_list));
    if (state_list == NULL) {
        return NULL;
    }

    // Initialize the state list
    state_list->size = num_states;
    state_list->states = malloc(num_states * sizeof(struct state));
    if (state_list->states == NULL) {
        free(state_list);
        return NULL;
    }

    // Iterate over the states and create a new connection for each one
    for (int i = 0; i < num_states; i++) {
        int state_id = states[i];
        struct state* state = &state_list->states[i];
        state->id = state_id;
        state->conn = create_connection(fsa, state_id);
        if (state->conn == NULL) {
            free(state);
            return NULL;
        }
    }

    // Return the new state list
    return state_list;
}

// Function to create a connection for a specific state in an FSA
struct connection* create_connection(struct fsa* fsa, int state_id) {
    // Check for valid inputs
    if (fsa == NULL || state_id < 0 || state_id >= fsa->num_states) {
        return NULL;
    }

    // Allocate memory for the connection
    struct connection* conn = malloc(sizeof(struct connection));
    if (conn == NULL) {
        return NULL;
    }

    // Initialize the connection
    conn->fd = -1;
    conn->hostname = strdup(fsa->servers[state_id % fsa->num_servers]);
    conn->port = fsa->ports[state_id % fsa->num_servers];
    if (conn->hostname == NULL) {
        free(conn);
        return NULL;
    }

    // Create a new connection to the database
    conn->fd = socket(AF_INET, SOCK_STREAM, 0);
    if (conn->fd < 0) {
        free(conn->hostname);
        free(conn);
        return NULL;
    }

    // Return the new connection
    return conn;
}

// Function to update a state list with a new FSA and an integer array of states
void update_state_list(struct state_list* state_list, struct fsa* fsa, int* states) {
    // Check for valid inputs
    if (state_list == NULL || fsa == NULL || states == NULL) {
        return;
    }

    // Lock the state list to prevent concurrent updates
    pthread_mutex_lock(&state_list->lock);

    // Iterate over the states and update the connections for each one
    for (int i = 0; i < state_list->size; i++) {
        int state_id = states[i];
        struct state* state = &state_list->states[i];
        if (state->conn != NULL) {
            // Update the connection to the database for this state
            free(state->conn);
            state->conn = create_connection(fsa, state_id);
        }
    }

    // Unlock the state list
    pthread_mutex_unlock(&state_list->lock);
}

// Function to retrieve a state from a state list using an integer ID
struct state* get_state(struct state_list* state_list, int state_id) {
    // Check for valid inputs
    if (state_list == NULL || state_id < 0) {
        return NULL;
    }

    // Lock the state list to prevent concurrent updates
    pthread_mutex_lock(&state_list->lock);

    // Iterate over the states and find the one with the matching ID
    for (int i = 0; i < state_list->size; i++) {
        struct state* state = &state_list->states[i];
        if (state->id == state_id) {
            // Unlock the state list and return the state
            pthread_mutex_unlock(&state_list->lock);
            return state;
        }
    }

    // Unlock the state list and return NULL
    pthread_mutex_unlock(&state_list->lock);
    return NULL;
}

// Function to close a connection to a database
void close_connection(struct connection* conn) {
    // Check for valid inputs
    if (conn == NULL || conn->fd < 0) {
        return;
    }

    // Close the socket and free the hostname
    close(conn->fd);
    free(conn->hostname);

    // Free the connection structure
    free(conn);
}

// Function to retrieve a state from a state list using a string ID
struct state* get_state_by_string_id(struct state_list* state_list, char* id) {
    // Check for valid inputs
    if (state_list == NULL || id == NULL) {
        return NULL;
    }

    // Lock the state list to prevent concurrent updates
    pthread_mutex_lock(&state_list->lock);

    // Iterate over the states and find the one with the matching ID
    for (int i = 0; i < state_list->size; i++) {
        struct state* state = &state_list->states[i];
        if (strcmp(state->id, id) == 0) {
            // Unlock the state list and return the state
            pthread_mutex_unlock(&state_list->lock);
            return state;
        }
    }

    // Unlock the state list and return NULL
    pthread_mutex_unlock(&state_list->lock);
    return NULL;
}

// Function to close a connection to a database
void close_connection(struct connection* conn) {
    // Check for valid inputs
    if (conn == NULL || conn->fd < 0) {
        return;
    }

    // Close the socket and free the hostname
    close(conn->fd);
    free(conn->hostname);

    // Free the connection structure
    free(conn);
}
