using System;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;
using Serilog;

namespace SecureCommunicationFramework
{
    public class CommunicationManager
    {
        private const int AES_KEY_SIZE = 32; // in bytes
        private const int IV_SIZE = 16; // in bytes
        private const int MAX_MESSAGE_LENGTH = 64; // in bytes

        private readonly ILogger _logger;
        private readonly UserAuthenticationService _authenticationService;
        private readonly RabbitMQMessageQueue _messageQueue;

        public CommunicationManager(ILogger logger, UserAuthenticationService authenticationService, RabbitMQMessageQueue messageQueue)
        {
            _logger = logger;
            _authenticationService = authenticationService;
            _messageQueue = messageQueue;
        }

        public async Task<string> EncryptAsync(string plaintext, string key)
        {
            try
            {
                // validate input
                if (plaintext == null || plaintext.Length > MAX_MESSAGE_LENGTH)
                    throw new ArgumentException("Invalid plaintext message.", nameof(plaintext));
                if (key == null || key.Length != AES_KEY_SIZE)
                    throw new ArgumentException("Invalid encryption key.", nameof(key));

                // generate initialization vector
                byte[] iv = new byte[IV_SIZE];
                Random random = new Random();
                random.NextBytes(iv);

                // encrypt message using AES-256 in CBC mode with HMACSHA256 for authentication
                var aes = new AesManaged { KeySize = 256, BlockSize = 128, Padding = PaddingMode.PKCS7 };
                var hmacSha256 = new HMACSHA256(Encoding.UTF8.GetBytes(key));
                using (var encryptor = aes.CreateEncryptor())
                {
                    byte[] encryptedMessage = encryptor.TransformFinalBlock(Encoding.UTF8.GetBytes(plaintext), 0, plaintext.Length);
                    hmacSha256.ComputeHash(encryptedMessage);
                    var result = new byte[encryptedMessage.Length + IV_SIZE];
                    Array.Copy(iv, result, IV_SIZE);
                    Array.Copy(encryptedMessage, 0, result, IV_SIZE, encryptedMessage.Length);
                    return Convert.ToBase64String(result);
                }
            }
            catch (Exception ex)
            {
                _logger.Error(ex, "Failed to encrypt message.");
                throw new DecryptionFailedException("Encryption failed.", ex);
            }
        }

        public async Task<string> DecryptAsync(string ciphertext, string key)
        {
            try
            {
                // validate input
                if (ciphertext == null || ciphertext.Length < IV_SIZE)
                    throw new ArgumentException("Invalid ciphertext message.", nameof(ciphertext));
                if (key == null || key.Length != AES_KEY_SIZE)
                    throw new ArgumentException("Invalid decryption key.", nameof(key));

                // extract initialization vector and encrypted message from ciphertext
                var iv = ciphertext.Substring(0, IV_SIZE);
                var encryptedMessage = ciphertext.Substring(IV_SIZE, ciphertext.Length - IV_SIZE);

                // decrypt message using AES-256 in CBC mode with HMACSHA256 for authentication
                var aes = new AesManaged { KeySize = 256, BlockSize = 128, Padding = PaddingMode.PKCS7 };
                var hmacSha256 = new HMACSHA256(Encoding.UTF8.GetBytes(key));
                using (var decryptor = aes.CreateDecryptor())
                {
                    byte[] plaintext = decryptor.TransformFinalBlock(Convert.FromBase64String(encryptedMessage), 0, Convert.FromBase64String(encryptedMessage).Length);
                    hmacSha256.ComputeHash(plaintext);
                    return Encoding.UTF8.GetString(plaintext);
                }
            }
            catch (Exception ex)
            {
                _logger.Error(ex, "Failed to decrypt message.");
                throw new DecryptionFailedException("Decryption failed.", ex);
            }
        }

        public async Task<string> AuthenticateAsync(string username, string password)
        {
            try
            {
                // validate input
                if (username == null || username.Length == 0)
                    throw new ArgumentException("Invalid username.", nameof(username));
                if (password == null || password.Length == 0)
                    throw new ArgumentException("Invalid password.", nameof(password));

                // authenticate user using external authentication service
                var authResponse = await _authenticationService.AuthenticateAsync(username, password);
                if (!authResponse.Success)
                    throw new AuthenticationFailedException($"Authentication failed for username '{username}'.");

                // return successful authentication response
                return authResponse.Token;
            }
            catch (Exception ex)
            {
                _logger.Error(ex, "Failed to authenticate user.");
                throw new AuthenticationFailedException("User authentication failed.", ex);
            }
        }

        public async Task<bool> LogAsync(string message, string username)
        {
            try
            {
                // validate input
                if (message == null || message.Length > MAX_MESSAGE_LENGTH)
                    throw new ArgumentException("Invalid log message.", nameof(message));
                if (username == null || username.Length == 0)
                    throw new ArgumentException("Invalid username.", nameof(username));

                // log message using external logging service
                await _loggingService.LogAsync(new LogMessage { Username = username, Message = message });

                // return successful log response
                return true;
            }
            catch (Exception ex)
            {
                _logger.Error(ex, "Failed to log message.");
                throw new LoggingFailedException("Logging failed.", ex);
            }
        }
    }
}
