    // Check if the requested pokemon is in the cache again after refreshing
    String cachedStrengths = strengthsCache.getIfPresent(name);
    if (cachedStrengths != null) {
      return new PokemonResponse(name, weakness, cachedStrengths, null);
    }

    // Fetch strengths from the external API
    List<String> strengths = fetchStrengths(name);

    // Check if the requested pokemon is in the cache again after refreshing
    String cachedCounterStrategies = counterStrategiesCache.getIfPresent(name);
    if (cachedCounterStrategies != null) {
      return new PokemonResponse(name, weakness, strengths, cachedCounterStrategies);
    }

    // Fetch counter strategies from the external API
    List<String> counterStrategies = fetchCounterStrategies(name);

    // Cache the results for future requests
    cacheWeaknesses(weakness);
    cacheStrengths(strengths);
    cacheCounterStrategies(counterStrategies);

    return new PokemonResponse(name, weakness, strengths, counterStrategies);
  }

  private String fetchWeakness(String name) {
    // Fetch the weakness for the requested pokemon from an external API
    try {
      URL url = new URL("https://pokeapi.co/api/v2/pokemon/" + name + "/weaknesses");
      HttpURLConnection connection = (HttpURLConnection) url.openConnection();
      connection.setRequestMethod("GET");
      connection.connect();
      if (connection.getResponseCode() == 200) {
        String response = IOUtils.toString(connection.getInputStream(), StandardCharsets.UTF_8);
        JSONObject json = new JSONObject(response);
        return json.getString("weaknesses");
      } else {
        throw new IOException("Failed to fetch weakness for " + name + ": " + connection.getResponseMessage());
      }
    } catch (IOException | JSONException e) {
      // Handle error
    }
  }

  private List<String> fetchStrengths(String name) {
    // Fetch the strengths for the requested pokemon from an external API
    try {
      URL url = new URL("https://pokeapi.co/api/v2/pokemon/" + name + "/strengths");
      HttpURLConnection connection = (HttpURLConnection) url.openConnection();
      connection.setRequestMethod("GET");
      connection.connect();
      if (connection.getResponseCode() == 200) {
        String response = IOUtils.toString(connection.getInputStream(), StandardCharsets.UTF_8);
        JSONObject json = new JSONObject(response);
        return json.getJSONArray("strengths").toList();
      } else {
        throw new IOException("Failed to fetch strengths for " + name + ": " + connection.getResponseMessage());
      }
    } catch (IOException | JSONException e) {
      // Handle error
    }
  }

  private List<String> fetchCounterStrategies(String name) {
    // Fetch the counter strategies for the requested pokemon from an external API
    try {
      URL url = new URL("https://pokeapi.co/api/v2/pokemon/" + name + "/counter-strategies");
      HttpURLConnection connection = (HttpURLConnection) url.openConnection();
      connection.setRequestMethod("GET");
      connection.connect();
      if (connection.getResponseCode() == 200) {
        String response = IOUtils.toString(connection.getInputStream(), StandardCharsets.UTF_8);
        JSONObject json = new JSONObject(response);
        return json.getJSONArray("counter-strategies").toList();
      } else {
        throw new IOException("Failed to fetch counter strategies for " + name + ": " + connection.getResponseMessage());
      }
    } catch (IOException | JSONException e) {
      // Handle error
    }
  }

  private void cacheWeaknesses(String weakness) {
    // Cache the weakness for future requests
    weaknessesCache.put(weakness);
  }

  private void cacheStrengths(List<String> strengths) {
    // Cache the strengths for future requests
    strengthsCache.put(strengths);
  }

  private void cacheCounterStrategies(List<String> counterStrategies) {
    // Cache the counter strategies for future requests
    counterStrategiesCache.put(counterStrategies);
  }
}
```

