char* process_string(const char* input, size_t limit) {
    if (input == NULL || limit <= 0) {
        return NULL;
    }

    // Load application settings from configuration file
    const char* config_path = "/etc/app_config.json";
    struct app_config* config = parse_config(config_path);

    // Validate input string length against configured limit
    size_t input_len = strlen(input);
    if (input_len > limit) {
        syslog(LOG_WARNING, "Input string length exceeds configured limit");
        return NULL;
    }

    // Allocate memory for output string
    char* output = malloc(limit + 1);
    if (output == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for output string: %s", strerror(errno));
        return NULL;
    }

    // Append slash to end of output string if it does not exceed the limit
    size_t output_len = input_len + 1;
    bool append_slash = (output_len <= limit);
    memcpy(output, input, input_len);
    if (append_slash) {
        output[input_len] = '/';
    } else {
        output[input_len - 1] = '\0';
    }

    // Log operation and return output string
    syslog(LOG_INFO, "Processed input string: %s", input);
    return output;
}
