    public void processOrderBatch(List<Map<String, Object>> orders) {
        // validate orders against schema
        for (Map<String, Object> order : orders) {
            validateOrder(order);
        }

        // prioritize high-priority orders and enqueue for processing
        PriorityQueue<Map<String, Object>> priorityQueue = new PriorityQueue<>(orders.size(), Comparator.comparingInt(o -> getPriority(o)));
        Map<String, Boolean> processedOrders = new ConcurrentHashMap<>();
        orders.forEach(order -> {
            if (getPriority(order) > MAX_PRIORITY) {
                priorityQueue.offer(order);
            } else {
                enqueueOrderForProcessing(order);
            }
        });

        // process high-priority orders in parallel, while maintaining a fair queue for regular orders
        List<Map<String, Object>> orderedOrders = new ArrayList<>(orders.size());
        while (!priorityQueue.isEmpty()) {
            Map<String, Object> order = priorityQueue.poll();
            if (processedOrders.putIfAbsent(order.get("id"), true) == null) {
                orderedOrders.add(order);
            }
        }
        for (Map<String, Object> order : orderedOrders) {
