// Structure to represent a connection status indicator
typedef struct {
    char *ip_address;
    int port;
    float latency;
    bool active;
    int priority;
} ConnectionStatusIndicator;

// Hash table to store the connection status indicators
static ConnectionStatusIndicator **connection_status_indicators;

// Number of elements in the hash table
static int num_elements;

// Function to initialize the connection status indicator hash table
void init_connection_status_indicator_table() {
    // Initialize the hash table with a default size of 1024 elements
    num_elements = 1024;
    connection_status_indicators = (ConnectionStatusIndicator **)malloc(sizeof(ConnectionStatusIndicator *) * num_elements);
    memset(connection_status_indicators, 0, sizeof(ConnectionStatusIndicator *) * num_elements);
}

// Function to add a connection status indicator to the hash table
void add_connection_status_indicator(const char *ip_address, int port, float latency, bool active, int priority) {
    // Check if the hash table needs to be resized
    if (num_elements == 0) {
        init_connection_status_indicator_table();
    } else if (num_elements == size_t(num_elements * LOAD_FACTOR)) {
        resize_connection_status_indicator_table();
    }

    // Add the connection status indicator to the hash table
    int index = hash(ip_address, port);
    ConnectionStatusIndicator *indicator = (ConnectionStatusIndicator *)malloc(sizeof(ConnectionStatusIndicator));
    memset(indicator, 0, sizeof(ConnectionStatusIndicator));
    strcpy(indicator->ip_address, ip_address);
    indicator->port = port;
    indicator->latency = latency;
    indicator->active = active;
    indicator->priority = priority;
    connection_status_indicators[index] = indicator;
}

// Function to update a connection status indicator in the hash table
void update_connection_status_indicator(const char *ip_address, int port, float latency, bool active, int priority) {
    // Check if the hash table needs to be resized
    if (num_elements == 0) {
        init_connection_status_indicator_table();
    } else if (num_elements == size_t(num_elements * LOAD_FACTOR)) {
        resize_connection_status_indicator_table();
    }

    // Update the connection status indicator in the hash table
    int index = hash(ip_address, port);
    ConnectionStatusIndicator *indicator = connection_status_indicators[index];
    if (indicator != NULL) {
        indicator->latency = latency;
        indicator->active = active;
        indicator->priority = priority;
    }
}

// Function to remove a connection status indicator from the hash table
void remove_connection_status_indicator(const char *ip_address, int port) {
    // Check if the hash table needs to be resized
    if (num_elements == 0) {
        init_connection_status_indicator_table();
    } else if (num_elements == size_t(num_elements * LOAD_FACTOR)) {
        resize_connection_status_indicator_table();
    }

    // Remove the connection status indicator from the hash table
    int index = hash(ip_address, port);
    ConnectionStatusIndicator *indicator = connection_status_indicators[index];
    if (indicator != NULL) {
        free(indicator);
        connection_status_indicators[index] = NULL;
    }
}

// Function to query the connection status indicators in the hash table
void query_connection_status_indicators() {
    // Print all the connection status indicators in the hash table
    for (int i = 0; i < num_elements; ++i) {
        ConnectionStatusIndicator *indicator = connection_status_indicators[i];
        if (indicator != NULL) {
            printf("%s:%d - Latency: %f, Active: %d, Priority: %d\n", indicator->ip_address, indicator->port, indicator->latency, indicator->active, indicator->priority);
        }
    }
}
