#include <errno.h>

#define MAX_PDU_COUNT 10000
#define MIN_RX_DELAY 1 // ms
#define MAX_RX_DELAY 100 // ms
#define PROB_PACKET_LOSS 0.05
#define LOCK_TIMEOUT 10 // seconds

typedef struct {
    int rx_information_tag;
    int rnti;
    int crc_indication_rel8_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to generate and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void generateAndPopulateNFADomainPDUList(NFAPI_CRC_INDICATION_PDU_T *pduList, int numEntries) {
    // Initialize semaphore for locking critical section
    sem_t *lock = sem_open("generateAndPopulateNFADomainPDUList", O_CREAT, 0644, 1);

    // Generate and populate the PDU list asynchronously
    for (int i = 0; i < numEntries; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &pduList[i];

        // Acquire lock to prevent race conditions and ensure thread safety
        int ret = sem_wait(lock);
        if (ret == -1) {
            perror("sem_wait");
            exit(EXIT_FAILURE);
        }

        // Generate RX information tag, RNTI, and CRCFlag with random values
        pdu->rx_information_tag = rand() % MAX_PDU_COUNT;
        pdu->rnti = rand() % MAX_PDU_COUNT;
        pdu->crcflag = (rand() % 2) == 0; // Randomly set CRCFlag to true or false

        // Simulate network latency by introducing random delays between 1ms and 100ms
        int rxDelay = rand_int(MIN_RX_DELAY, MAX_RX_DELAY);
        usleep(rxDelay * 1000);

        // Simulate packet loss with a probability of 5% per entry
        if (rand() % 20 < PROB_PACKET_LOSS) {
            // Handle partial processing when errors occur
            printf("Error: Packet loss detected. Continuing with reduced throughput.\n");
            pdu->rx_information_tag = -1;
            pdu->rnti = -1;
            pdu->crcflag = false;
        } else {
            // Release lock to allow other threads to access the critical section
            int ret = sem_post(lock);
            if (ret == -1) {
                perror("sem_post");
                exit(EXIT_FAILURE);
            }
        }
    }

    // Close semaphore when done
    int ret = sem_close(lock);
    if (ret == -1) {
        perror("sem_close");
        exit(EXIT_FAILURE);
    }
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T pduList[MAX_PDU_COUNT];
    int numEntries = MAX_PDU_COUNT;

    // Generate and populate the PDU list asynchronously
    generateAndPopulateNFADomainPDUList(pduList, numEntries);

    return 0;
}
