// adds a new PDU to the list, growing the list if necessary
void NFAPI_CRC_INDICATION_LIST_ADD(NFAPI_CRC_INDICATION_LIST_T *list,
                                  NFAPI_CRC_INDICATION_PDU_T *pdu) {
    int i;
    for (i = 0; i < list->count; i++) {
        if (list->pdu[i] == pdu) {
            // PDU already exists in the list, skip adding it again
            return;
        }
    }
    list->pdu[list->count++] = pdu;
}

// removes a PDU from the list, shrinking the list if necessary
void NFAPI_CRC_INDICATION_LIST_REMOVE(NFAPI_CRC_INDICATION_LIST_T *list,
                                     NFAPI_CRC_INDICATION_PDU_T *pdu) {
