    switch (errorCode) {
        case RESOURCE_BUNDLE_MANAGER_OK:
            logMessage(LOG_LEVEL_INFO, "Successfully retried resource operation.");
            break;
        case RESOURCE_BUNDLE_MANAGER_RESOURCE_NOT_FOUND:
            logMessage(LOG_LEVEL_ERROR, "Failed to retry resource operation due to a missing resource.");
            break;
        default:
            logMessage(LOG_LEVEL_ERROR, "Failed to retry resource operation due to an unknown error.");
    }
