            break;
        case RESOURCE_BUNDLE_MANAGER_RESOURCE_NOT_FOUND:
            logMessage(LOG_LEVEL_ERROR, "Failed to complete the operation due to a missing resource.");
            break;
        default:
            logMessage(LOG_LEVEL_ERROR, "Failed to complete the operation due to an unknown error.");
    }
