```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>

// Structure to hold the CRC indication data
typedef struct {
    RX_UE_INFORMATION_TAG RxInfoTag;
    RNTI Rnti;
    CRC_INDICATION_REL8_TAG Rel8;
} NFAPI_CRC_INDICATION_PDU_T;

// Linked list structure to store the CRC indications
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    pthread_mutex_t lock;
} NFAPI_CRC_INDICATION_LIST_T;

// Global variable to hold the linked list of CRC indications
NFAPI_CRC_INDICATION_LIST_T *crcIndicationList = NULL;

// Function to generate a randomly set CRCFLAG
int randomCRCFlag() {
    // Generate a random number between 0 and 100
    int rnd = rand() % 100;
    return (rnd > 50) ? 1 : 0;
}

// Function to add a new CRC indication to the linked list
void addCrcIndication(RX_UE_INFORMATION_TAG RxInfoTag, RNTI Rnti, CRC_INDICATION_REL8_TAG Rel8) {
    // Create a new node for the CRC indication
    NFAPI_CRC_INDICATION_PDU_T *newNode = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    newNode->RxInfoTag = RxInfoTag;
    newNode->Rnti = Rnti;
    newNode->Rel8 = Rel8;

    // Set the CRCFLAG randomly
    newNode->CRCFlag = randomCRCFlag();

    // Lock the linked list mutex
    pthread_mutex_lock(&crcIndicationList->lock);

    // Add the new node to the end of the linked list
    if (crcIndicationList->head == NULL) {
        crcIndicationList->head = newNode;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *curNode = crcIndicationList->head;
        while (curNode->next != NULL) {
            curNode = curNode->next;
        }
        curNode->next = newNode;
    }

    // Unlock the linked list mutex
    pthread_mutex_unlock(&crcIndicationList->lock);
}

// Function to remove a CRC indication from the linked list
void removeCrcIndication(RX_UE_INFORMATION_TAG RxInfoTag, RNTI Rnti) {
    // Lock the linked list mutex
    pthread_mutex_lock(&crcIndicationList->lock);

    // Search for the CRC indication to remove
    NFAPI_CRC_INDICATION_PDU_T *curNode = crcIndicationList->head;
    while (curNode != NULL) {
        if (curNode->RxInfoTag == RxInfoTag && curNode->Rnti == Rnti) {
            // Remove the node from the linked list
            if (curNode->next == NULL) {
                crcIndicationList->head = NULL;
            } else {
                NFAPI_CRC_INDICATION_PDU_T *prevNode = curNode->prev;
                prevNode->next = curNode->next;
                curNode->next->prev = prevNode;
            }
            break;
        }
        curNode = curNode->next;
    }

    // Unlock the linked list mutex
    pthread_mutex_unlock(&crcIndicationList->lock);
}

// Function to save the state of the linked list to disk
void saveCrcIndicationListToDisk() {
    // Lock the linked list mutex
    pthread_mutex_lock(&crcIndicationList->lock);

    // Open a file for writing
    FILE *fp = fopen("crcIndicationList.bin", "wb");

    // Write the linked list to the file
    NFAPI_CRC_INDICATION_PDU_T *curNode = crcIndicationList->head;
    while (curNode != NULL) {
        fwrite(curNode, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, fp);
        curNode = curNode->next;
    }

    // Close the file
    fclose(fp);

    // Unlock the linked list mutex
    pthread_mutex_unlock(&crcIndicationList->lock);
}

// Function to load the state of the linked list from disk
void loadCrcIndicationListFromDisk() {
    // Lock the linked list mutex
    pthread_mutex_lock(&crcIndicationList->lock);

    // Open a file for reading
    FILE *fp = fopen("crcIndicationList.bin", "rb");

    // Read the linked list from the file
    NFAPI_CRC_INDICATION_PDU_T *curNode = NULL;
    while (fread(&curNode, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, fp) == 1) {
        // Add the node to the end of the linked list
        if (crcIndicationList->head == NULL) {
            crcIndicationList->head = curNode;
        } else {
            NFAPI_CRC_INDICATION_PDU_T *curNode = crcIndicationList->head;
            while (curNode->next != NULL) {
                curNode = curNode->next;
            }
            curNode->next = newNode;
        }
    }

    // Close the file
    fclose(fp);

    // Unlock the linked list mutex
    pthread_mutex_unlock(&crcIndicationList->lock);
}

// Function to handle a CRC indication message
void handleCrcIndicationMessage(RX_UE_INFORMATION_PDU_T *msg) {
    // Check if the CRCFLAG is set
    if (msg->CRCFlag != 0) {
        // Add the CRC indication to the linked list
        addCrcIndication(msg->RxInfoTag, msg->Rnti, msg->Rel8);
    } else {
        // Remove the CRC indication from the linked list
        removeCrcIndication(msg->RxInfoTag, msg->Rnti);
    }
}

// Function to handle a CRCFlag message
void handleCRCFlagMessage(CRCFlagPDU_T *msg) {
    // Check if the CRCFLAG is set
    if (msg->CRCFlag != 0) {
        // Set the CRCFLAG randomly
        msg->CRCFlag = randomCRCFlag();
    }
}
