// Cache is a dynamic caching mechanism that anticipates file access patterns and reduces redundant data transfers, optimizing resource usage and improving performance.
type Cache struct {
	size    int
	storage map[string][]byte
}

// NewCache creates a new instance of the Cache with the given size.
func NewCache(size int) *Cache {
	return &Cache{
		size:    size,
		storage: make(map[string][]byte),
	}
}

// Get retrieves the value for the given key from the cache, or returns nil if it doesn't exist.
func (c *Cache) Get(key string) []byte {
	return c.storage[key]
}

// Set sets the value for the given key in the cache.
func (c *Cache) Set(key string, value []byte) {
	c.storage[key] = value
