        ipAddress_(ipAddress), port_(port), latency_(latency), status_(status) {}

    const std::string& getIpAddress() const { return ipAddress_; }
    int getPort() const { return port_; }
    double getLatency() const { return latency_; }
    Status getStatus() const { return status_; }
};

class ConnectionManager {
private:
    std::map<std::string, std::vector<ConnectionStatus>> connections_; // map IP address to vector of connection statuses

public:
    void addConnection(const std::string& ipAddress, int port, double latency, ConnectionStatus::Status status) {
        connections_[ipAddress].push_back(ConnectionStatus(ipAddress, port, latency, status));
    }

    const std::vector<ConnectionStatus>& getConnections() const { return connections_.at(""); } // return all connections

    void updateConnection(const std::string& ipAddress, int port, double latency, ConnectionStatus::Status status) {
        for (auto it = connections_[ipAddress].begin(); it != connections_[ipAddress].end(); ++it) {
            if (it->getPort() == port && it->getLatency() == latency && it->getStatus() == status) {
                *it = ConnectionStatus(ipAddress, port, latency, status); // update connection status
                return;
            }
        }
    }

    void removeConnection(const std::string& ipAddress, int port, double latency, ConnectionStatus::Status status) {
        for (auto it = connections_[ipAddress].begin(); it != connections_[ipAddress].end(); ++it) {
            if (it->getPort() == port && it->getLatency() == latency && it->getStatus() == status) {
                connections_[ipAddress].erase(it); // remove connection from map
                return;
            }
        }
    }
};

int main() {
    ConnectionManager cm;

    // Add connections
    cm.addConnection("192.168.0.1", 80, 50, ConnectionStatus::ACTIVE);
    cm.addConnection("192.168.0.2", 80, 100, ConnectionStatus::INACTIVE);
    cm.addConnection("192.168.0.3", 80, 200, ConnectionStatus::ACTIVE);

    // Update connections
    cm.updateConnection("192.168.0.1", 80, 50, ConnectionStatus::INACTIVE);
    cm.updateConnection("192.168.0.3", 80, 200, ConnectionStatus::ACTIVE);

    // Remove connections
    cm.removeConnection("192.168.0.2", 80, 100, ConnectionStatus::INACTIVE);

    // Get all connections
    for (const auto& connection : cm.getConnections()) {
        std::cout << "IP Address: " << connection.getIpAddress() << "\n";
        std::cout << "Port: " << connection.getPort() << "\n";
        std::cout << "Latency: " << connection.getLatency() << "\n";
        std::cout << "Status: " << (connection.getStatus() == ConnectionStatus::ACTIVE ? "Active" : "Inactive") << "\n\n";
    }

    return 0;
}']

