#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>

// Define a data structure to hold RX UE information, RNTI, and CRC indication tags
typedef struct NFAPI_CRC_INDICATION_PDU {
  char rx_ue[16]; // RX UE identifier
  char rnti[10]; // RNTI value
  int crc_ind; // CRC indication tag
} NFAPI_CRC_INDICATION_PDU;

// Define a data structure to hold the collection of PDUs
typedef struct NFAPI_CRC_INDICATION_COLLECTION {
  NFAPI_CRC_INDICATION_PDU *pdus[10000]; // Maximum number of concurrent UE instances
  int num_pdus; // Number of PDUs in the collection
} NFAPI_CRC_INDICATION_COLLECTION;

// Function to populate a PDU with RX UE information, RNTI, and CRC indication tags
void nfapi_crc_indication_pdu_populate(NFAPI_CRC_INDICATION_PDU *pdu, const char *rx_ue, const char *rnti, int crc_ind) {
  // Check if the PDU is NULL or not
  if (pdu == NULL) {
    return;
  }

  // Copy the RX UE identifier and RNTI values to the PDU structure
  strcpy(pdu->rx_ue, rx_ue);
  strcpy(pdu->rnti, rnti);
  pdu->crc_ind = crc_ind;
}

// Function to handle memory allocation failures gracefully
void nfapi_crc_indication_pdu_malloc_error(const char *rx_ue, const char *rnti) {
  printf("Memory allocation error for RX UE %s and RNTI %s\n", rx_ue, rnti);
}

// Function to handle memory deallocation gracefully
void nfapi_crc_indication_pdu_free(NFAPI_CRC_INDICATION_PDU *pdu) {
  if (pdu != NULL) {
    free(pdu);
  }
}

// Function to add a new PDU to the collection
int nfapi_crc_indication_add_pdu(NFAPI_CRC_INDICATION_COLLECTION *collection, const char *rx_ue, const char *rnti, int crc_ind) {
  // Check if the collection is full or not
  if (collection->num_pdus == 10000) {
    return -1;
  }

  // Allocate memory for a new PDU structure
  NFAPI_CRC_INDICATION_PDU *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
  if (pdu == NULL) {
    nfapi_crc_indication_pdu_malloc_error(rx_ue, rnti);
    return -1;
  }

  // Populate the PDU with RX UE information, RNTI, and CRC indication tags
  nfapi_crc_indication_pdu_populate(pdu, rx_ue, rnti, crc_ind);

  // Add the new PDU to the collection
  collection->pdus[collection->num_pdus++] = pdu;

  return 0;
}

// Function to remove a PDU from the collection
int nfapi_crc_indication_remove_pdu(NFAPI_CRC_INDICATION_COLLECTION *collection, const char *rx_ue, const char *rnti) {
  // Find the index of the PDU to remove
  int index = -1;
  for (int i = 0; i < collection->num_pdus; i++) {
    if (strcmp(collection->pdus[i]->rx_ue, rx_ue) == 0 && strcmp(collection->pdus[i]->rnti, rnti) == 0) {
      index = i;
      break;
    }
