  // Free the memory allocated for the PDU structure
  nfapi_crc_indication_pdu_free(collection->pdus[index]);

  // Shift the remaining PDUs in the collection up one index
  memmove(&collection->pdus[index], &collection->pdus[index + 1], (collection->num_pdus - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU));

  // Decrement the number of PDUs in the collection
  collection->num_pdus--;

  return 0;
}

