typedef struct MemoryPool {
    void **free_list; // Linked list of free memory blocks
    int num_free; // Number of free memory blocks in the pool
    size_t block_size; // Size of each memory block in bytes
} MemoryPool;

// Define a function to allocate a memory block from the pool
void *allocate_block(MemoryPool *pool, size_t size) {
    if (size > pool->block_size) {
        return NULL;
    }

    // Check if there are any free blocks in the pool
    if (pool->num_free == 0) {
        // No free blocks available, allocate a new block
        void *new_block = malloc(pool->block_size);
        if (!new_block) {
            return NULL;
        }
        pool->num_free++;
        pool->free_list = new_block;
    }

    // Get the first free block from the pool
    void *block = pool->free_list;
    pool->free_list = *(void **)block;
    pool->num_free--;

    return block;
}

// Define a function to deallocate a memory block back to the pool
void deallocate_block(MemoryPool *pool, void *block) {
    // Add the block to the list of free blocks in the pool
    *(void **)block = pool->free_list;
    pool->free_list = block;
    pool->num_free++;
}

