        exit(1);
    }
    new_node->data = data;
    new_node->next = NULL;

    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }

    list->size++;
}

void remove_node(struct list *list, NFAPI_CRC_INDICATION_PDU_T *data) {
    struct list_node *cur_node = list->head;
