        fprintf(stderr, "Data not found in list\n");
        exit(1);
    }

    if (cur_node == list->head && cur_node == list->tail) {
        list->head = NULL;
        list->tail = NULL;
    } else if (cur_node == list->head) {
        list->head = cur_node->next;
    } else if (cur_node == list->tail) {
        struct list_node *prev_node = cur_node->next;
        while (prev_node != NULL && prev_node->next != cur_node) {
            prev_node = prev_node->next;
        }
        if (prev_node == NULL) {
            fprintf(stderr, "Data not found in list\n");
            exit(1);
        }
        prev_node->next = NULL;
    } else {
        cur_node->next->next = cur_node->next;
    }

    free(cur_node);
    list->size--;
}

void update_node(struct list *list, NFAPI_CRC_INDICATION_PDU_T *data) {
    struct list_node *cur_node = list->head;
    while (cur_node != NULL && cur_node->data != data) {
