        fwrite(&cur_node->data->rnti, sizeof(uint16_t), 1, fp);
        fwrite(&cur_node->data->tag, TAG_LENGTH, 1, fp);
        cur_node = cur_node->next;
    }

    fclose(fp);
}

void deserialize_list(struct list *list, char *filename) {
    FILE *fp = fopen(filename, "rb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file %s for reading\n", filename);
        exit(1);
    }

    struct list_node *cur_node = list->head;
    while (fread(&cur_node->data->rnti, sizeof(uint16_t), 1, fp) == 1) {
        fread(&cur_node->data->tag, TAG_LENGTH, 1, fp);
        cur_node = cur_node->next;
    }

    fclose(fp);
}
