```
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <unordered_map>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <chrono>
#include <memory>
#include <future>

// Define a data structure to hold the incoming requests
struct Request {
  std::string deviceId; // ID of the device that sent the request
  std::string protocol; // Protocol used by the device (e.g., HTTP, HTTPS)
  std::string format;   // Data format of the request (e.g., JSON, XML, binary)
  std::string data;    // The actual data sent by the device
};

// Define a data structure to hold the outgoing responses
struct Response {
  std::string deviceId;     // ID of the device that received the response
  int statusCode;           // HTTP status code of the response
  std::string contentType;  // Content type of the response (e.g., JSON, XML)
  std::string data;         // The actual data sent in the response
};

// Define a class to handle the pipeline
class Pipeline {
 public:
  // Constructor takes in the external API and the message broker
  Pipeline(const std::string& api, const std::string& broker) :
    m_api{api}, m_broker{broker} {}

  // Function to add a new request to the pipeline
  void AddRequest(const Request& req) {
    std::lock_guard<std::mutex> lock(m_mutex);
    m_queue.push(req);
    m_cond.notify_one();
  }

  // Function to handle incoming requests from the API
  void HandleRequests() {
    while (true) {
      std::unique_lock<std::mutex> lock(m_mutex);
      m_cond.wait(lock, [this] { return !m_queue.empty(); });
      Request req = m_queue.front();
      m_queue.pop();
      lock.unlock();

      // Handle the request according to the protocol and format
      if (req.protocol == "HTTP" || req.protocol == "HTTPS") {
        // HTTP/HTTPS protocols are handled by the API
        std::string response = m_api.GetResponse(req.deviceId);
        Response res;
        res.deviceId = req.deviceId;
        res.statusCode = 200;
        res.contentType = "text/plain";
        res.data = response;
        AddResponse(res);
      } else if (req.format == "JSON" || req.format == "XML") {
        // JSON or XML requests are handled by the message broker
        std::string message = m_broker.GetMessage(req.deviceId);
        Response res;
        res.deviceId = req.deviceId;
        res.statusCode = 200;
        res.contentType = "text/plain";
        res.data = message;
        AddResponse(res);
      } else {
        // Unknown protocol or format, return error response
        Response res;
        res.deviceId = req.deviceId;
        res.statusCode = 400;
        res.contentType = "text/plain";
        res.data = "Unknown protocol or format.";
        AddResponse(res);
      }
    }
  }

  // Function to handle incoming responses from the API and message broker
  void HandleResponses() {
    while (true) {
      std::unique_lock<std::mutex> lock(m_mutex);
      m_cond.wait(lock, [this] { return !m_responses.empty(); });
      Response res = m_responses.front();
      m_responses.pop();
      lock.unlock();

      // Process the response according to its content type
      if (res.contentType == "text/plain") {
        // Text responses are handled by the API
        std::string response = res.data;
        m_api.ProcessResponse(res.deviceId, response);
      } else if (res.contentType == "application/json" || res.contentType == "application/xml") {
        // JSON or XML responses are handled by the message broker
        std::string message = res.data;
        m_broker.ProcessMessage(res.deviceId, message);
      } else {
        // Unknown content type, ignore response
      }
    }
  }

 private:
  // Add a new response to the pipeline
  void AddResponse(const Response& res) {
    std::lock_guard<std::mutex> lock(m_mutex);
    m_responses.push(res);
    m_cond.notify_one();
  }

  // The external API and message broker
  const std::string& m_api;
  const std::string& m_broker;

  // Mutex to protect the queue and condition variable
  std::mutex m_mutex;
  std::condition_variable m_cond;

  // Queue of incoming requests
  std::queue<Request> m_queue;

  // Queue of outgoing responses
  std::queue<Response> m_responses;
};

// Main function to run the pipeline
int main() {
  // Initialize the external API and message broker
  const std::string api = "https://example.com/api";
  const std::string broker = "rabbitmq://localhost:5672";

  // Create a new instance of the pipeline
  Pipeline p(api, broker);

  // Start the handling threads for requests and responses
  std::thread request_thread(&Pipeline::HandleRequests, &p);
  std::thread response_thread(&Pipeline::HandleResponses, &p);

  // Add a new request to the pipeline
  Request req;
  req.deviceId = "1234567890";
  req.protocol = "HTTPS";
  req.format = "JSON";
  p.AddRequest(req);

  // Wait for the threads to finish
  request_thread.join();
  response_thread.join();

  return 0;
}
```
This is a simple example of how you could use a pipeline to handle incoming requests and outgoing responses in a distributed system. The `Pipeline` class maintains two queues, one for incoming requests and another for outgoing responses, and uses mutexes and condition variables to protect the queues from concurrent access. The `HandleRequests()` function is responsible for handling incoming requests from the API, while the `HandleResponses()` function is responsible for handling incoming responses from the message broker. Both functions use locking mechanisms to ensure thread safety.

This example assumes that you have a RESTful API with an endpoint for retrieving data and a message broker that can handle messages in JSON or XML format. The `Pipeline` class handles all communication between the API, the message broker, and the rest of the system.

Note that this is just a simple example and may not be suitable for use in production environments without significant modification. In particular, you would need to add error handling, logging, and other features as needed.']

