  typedef struct {
    int crcIndPduCount;
    NFAPI_CRC_INDICATION_PDU_T *crcIndPdus;
  } CRC_INDICATION_CONTEXT_T;

  static pthread_mutex_t gCrcIndicationMutex = PTHREAD_MUTEX_INITIALIZER;

  static int gCrcIndicationFd = -1;

  static CRC_INDICATION_CONTEXT_T *gCrcIndicationContext = NULL;

  static pthread_cond_t gCrcIndicationCondVar = PTHREAD_COND_INITIALIZER;

  void NFAPI_CRC_INDICATION_CB(NFAPI_CRC_INDICATION_PDU_T *crcIndPdu) {
    pthread_mutex_lock(&gCrcIndicationMutex);

    if (gCrcIndicationContext == NULL) {
      gCrcIndicationContext = malloc(sizeof(CRC_INDICATION_CONTEXT_T));
      memset(gCrcIndicationContext, 0, sizeof(CRC_INDICATION_CONTEXT_T));
    }

    if (gCrcIndicationFd == -1) {
      gCrcIndicationFd = open("crcIndications.txt", O_WRONLY | O_CREAT, 0644);

      if (gCrcIndicationFd == -1) {
        perror("Error opening crcIndications file");
      } else {
        printf("Opened crcIndications file successfully\n");
      }
    }

    gCrcIndicationContext->crcIndPduCount++;

    if (gCrcIndicationContext->crcIndPduCount == 1) {
      gCrcIndicationContext->crcIndPdus = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
      memcpy(gCrcIndicationContext->crcIndPdus, crcIndPdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    } else {
      gCrcIndicationContext->crcIndPdus = realloc(gCrcIndicationContext->crcIndPdus, gCrcIndicationContext->crcIndPduCount * sizeof(NFAPI_CRC_INDICATION_PDU_T));
      memcpy(&gCrcIndicationContext->crcIndPdus[gCrcIndicationContext->crcIndPduCount - 1], crcIndPdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    pthread_cond_signal(&gCrcIndicationCondVar);
    pthread_mutex_unlock(&gCrcIndicationMutex);
  }

  void *handleCrcIndications(void *arg) {
    while (1) {
      NFAPI_CRC_INDICATION_PDU_T *crcIndPdu;

      pthread_mutex_lock(&gCrcIndicationMutex);

      while (gCrcIndicationContext == NULL || gCrcIndicationContext->crcIndPduCount == 0) {
        pthread_cond_wait(&gCrcIndicationCondVar, &gCrcIndicationMutex);
      }

      crcIndPdu = &gCrcIndicationContext->crcIndPdus[gCrcIndicationContext->crcIndPduCount - 1];

      printf("Handling crc indication: %d\n", crcIndPdu->sfnSf);

      if (gCrcIndicationFd != -1) {
        write(gCrcIndicationFd, crcIndPdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
      }

      gCrcIndicationContext->crcIndPduCount--;

      if (gCrcIndicationContext->crcIndPduCount == 0) {
        free(gCrcIndicationContext->crcIndPdus);
        gCrcIndicationContext->crcIndPdus = NULL;
