# Define a task to compute the MD5 hash of a file
@shared_task
def compute_md5(file_path):
    # Compute the MD5 hash of the file and store it in Redis
    with open(file_path, 'rb') as f:
        md5 = hashlib.md5()
        while chunk := f.read(1024):
            md5.update(chunk)
        redis.set(os.path.basename(file_path), md5.hexdigest())
    return True

# Define a task to asynchronously process files in a directory
@shared_task
def process_files(directory):
    # Recursively iterate over the directory and its subdirectories, computing MD5 hashes for each file
    for root, dirs, files in os.walk(directory):
        for file in files:
            file_path = os.path.join(root, file)
            compute_md5.apply_async((file_path,))
    return True

# Define a task to asynchronously process files in a directory and its subdirectories
@shared_task
def process_files_recurse(directory):
    # Recursively iterate over the directory and its subdirectories, computing MD5 hashes for each file
    for root, dirs, files in os.walk(directory):
        for file in files:
            file_path = os.path.join(root, file)
            compute_md5.apply_async((file_path,))
    # Recursively call the task for each subdirectory
    for dir in dirs:
        process_files_recurse.apply_async((os.path.join(directory, dir),))
    return True

# Define a function to compute MD5 hashes for all files in a directory and its subdirectories
def compute_md5_all(directory):
    # Asynchronously process the directory and its subdirectories using Celery tasks
    process_files_recurse.apply_async((directory,))
    return True

# Define a function to retrieve MD5 hashes for files in a directory
def get_md5(directory):
    # Iterate over the files in the directory and its subdirectories
    for root, dirs, files in os.walk(directory):
        for file in files:
            file_path = os.path.join(root, file)
            hash = redis.get(os.path.basename(file_path))
            if hash:
                yield (file_path, hash)
    return True

# Define a function to retrieve MD5 hashes for files in a directory and its subdirectories
def get_md5_recurse(directory):
    # Recursively iterate over the directory and its subdirectories
    for root, dirs, files in os.walk(directory):
        for file in files:
            file_path = os.path.join(root, file)
            hash = redis.get(os.path.basename(file_path))
            if hash:
                yield (file_path, hash)
    # Recursively call the function for each subdirectory
    for dir in dirs:
        get_md5_recurse((os.path.join(directory, dir)))
    return True

# Define a function to retrieve all MD5 hashes for files in a directory and its subdirectories
def get_all_md5(directory):
    # Asynchronously process the directory and its subdirectories using Celery tasks
    compute_md5_all.apply_async((directory,))
    return True

# Set up the Flask app
