    return render_template('index.html')

@app.route('/monitoring', methods=['GET'])
def monitoring():
    return render_template('monitoring.html')

# Define the functions for processing files asynchronously using Celery tasks
@app.route('/process-files', methods=['POST'])
def process_files():
    directory = request.form.get('directory')
    process_files_recurse.apply_async((directory,))
    return 'Processing files in ' + directory

# Define the functions for retrieving MD5 hashes for files in a directory and its subdirectories
@app.route('/get-md5', methods=['POST'])
def get_md5():
    directory = request.form.get('directory')
    return jsonify(list(get_md5(directory)))

@app.route('/get-all-md5', methods=['POST'])
