// Distributed Cache Library using REST API
#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <set>
#include <algorithm>
#include <future>

using namespace std;

class Node {
    public:
        string id;
        vector<string> keys;
        map<string, string> values;
};

class Cache {
    private:
        vector<Node> nodes;
        vector<string> keys;
        map<string, string> values;

    public:
        // Constructor
        Cache() {}

        // Add a node to the cache
        void add_node(string id) {
            Node new_node = Node(id);
            nodes.push_back(new_node);
        }

        // Remove a node from the cache
        void remove_node(string id) {
            int index = get_node_index(id);
            if (index != -1) {
                nodes.erase(nodes.begin() + index);
            }
        }

        // Get the node with the specified ID
        Node* get_node(string id) {
            int index = get_node_index(id);
            if (index != -1) {
                return &nodes[index];
            } else {
                return NULL;
            }
        }

        // Get the index of the node with the specified ID
        int get_node_index(string id) {
            for (int i = 0; i < nodes.size(); i++) {
                if (nodes[i].id == id) {
                    return i;
                }
            }
            return -1;
        }

        // Get the value associated with the specified key
        string get_value(string key) {
            int index = get_node_index(key);
            if (index != -1) {
                return nodes[index].values[key];
            } else {
                return NULL;
            }
        }

        // Set the value associated with the specified key
        void set_value(string key, string value) {
            int index = get_node_index(key);
            if (index != -1) {
                nodes[index].values[key] = value;
            } else {
                Node new_node = Node(key, value);
                nodes.push_back(new_node);
            }
        }

        // Get all the keys associated with a specific node ID
        vector<string> get_keys(string id) {
            int index = get_node_index(id);
            if (index != -1) {
                return nodes[index].keys;
            } else {
                return NULL;
            }
        }

        // Get all the values associated with a specific key
        vector<string> get_values(string key) {
            int index = get_node_index(key);
            if (index != -1) {
                return nodes[index].values[key];
            } else {
                return NULL;
            }
        }

        // Remove the key-value pair with the specified key
        void remove_key(string key) {
            int index = get_node_index(key);
            if (index != -1) {
                nodes[index].keys.erase(nodes[index].keys.begin() + key);
            }
        }

        // Remove the value associated with the specified key
        void remove_value(string key, string value) {
            int index = get_node_index(key);
            if (index != -1) {
                nodes[index].values.erase(nodes[index].values.begin() + value);
            }
        }
};
```
