#define KEY_MATERIAL_SIZE 16 // Size of key material (in bytes) needed to create a symmetric key
#define MEMORY_POOL_SIZE 4096 // Size of memory pool allocated for each session (in bytes)
#define THREAD_SAFE 1 // Flag indicating whether the cryptographic service is thread-safe or not

// Type definitions
typedef enum {
    AES,
    CAMELLIA,
    MD5,
    SHA,
    RSA,
    SHA1,
    ECC_P256,
    ECC_X25519,
    SYMMETRIC,
    HASH
} CipherType;

typedef struct {
    std::string key; // Key material for the cipher
    int keySize; // Size of the key in bytes (e.g., 16 for AES-128)
    unsigned char* iv; // Initialization vector for symmetric ciphers
} CipherKey;

typedef struct {
    std::string data; // Data to be encrypted/decrypted
    int dataSize; // Size of the data (in bytes)
} CipherData;

// Structure definitions
class CryptographicService {
    private:
        int maxKeySize; // Maximum key size allowed for each cipher type
        std::unordered_map<std::string, CipherType> cipherMap; // Map of cipher names to their corresponding types
        std::vector<CipherKey*> sessionKeys; // Vector of session keys used for encryption/decryption
        std::vector<int> sessionKeySizes; // Vector of key sizes for each session key
        std::vector<unsigned char*> sessionIVs; // Vector of session initialization vectors (IVs) for symmetric ciphers
        int memoryPoolSize; // Size of memory pool allocated for each session (in bytes)
        bool threadSafe; // Flag indicating whether the cryptographic service is thread-safe or not
    public:
        CryptographicService();
        ~CryptographicService();
        int getMaxKeySize();
        std::string getCipherName(int cipherType);
        CipherType getCipherType(std::string cipherName);
        bool isThreadSafe();
        void loadSessionKeys(const std::vector<CipherKey*> sessionKeys);
        void unloadSessionKeys(const std::vector<int> sessionKeySizes);
        void encryptData(const CipherData& data, const CipherType cipherType, const unsigned char* keyMaterial, int keySize);
        void decryptData(const CipherData& data, const CipherType cipherType, const unsigned char* keyMaterial, int keySize);
};

CryptographicService::CryptographicService() {
    maxKeySize = MAX_KEY_SIZE;
    threadSafe = THREAD_SAFE;
}

CryptographicService::~CryptographicService() {
    for (int i = 0; i < sessionKeys.size(); ++i) {
        delete sessionKeys[i];
    }
    for (int i = 0; i < sessionIVs.size(); ++i) {
        delete sessionIVs[i];
    }
}

int CryptographicService::getMaxKeySize() {
    return maxKeySize;
}

std::string CryptographicService::getCipherName(int cipherType) {
    switch (cipherType) {
        case AES:
            return "AES";
        case CAMELLIA:
            return "CAMELLIA";
        case MD5:
            return "MD5";
        case SHA:
            return "SHA";
        case RSA:
            return "RSA";
        case SHA1:
            return "SHA1";
        case ECC_P256:
            return "ECC_P256";
        case ECC_X25519:
            return "ECC_X25519";
        default:
            return "";
    }
}

CipherType CryptographicService::getCipherType(std::string cipherName) {
    if (cipherName == "AES") {
        return AES;
    } else if (cipherName == "CAMELLIA") {
        return CAMELLIA;
    } else if (cipherName == "MD5") {
        return MD5;
    } else if (cipherName == "SHA") {
        return SHA;
    } else if (cipherName == "RSA") {
        return RSA;
    } else if (cipherName == "SHA1") {
        return SHA1;
    } else if (cipherName == "ECC_P256") {
        return ECC_P256;
    } else if (cipherName == "ECC_X25519") {
        return ECC_X25519;
    } else {
        return SYMMETRIC;
    }
}

bool CryptographicService::isThreadSafe() {
    return threadSafe;
}

void CryptographicService::loadSessionKeys(const std::vector<CipherKey*> sessionKeys) {
    this->sessionKeys = sessionKeys;
    for (int i = 0; i < sessionKeys.size(); ++i) {
        sessionKeySizes[i] = sessionKeys[i]->keySize;
    }
}

void CryptographicService::unloadSessionKeys(const std::vector<int> sessionKeySizes) {
    for (int i = 0; i < sessionKeySizes.size(); ++i) {
        delete sessionKeys[i];
    }
}

