#include <sys/msg.h>
#include <curl/curl.h>
#include <gqe/gqe_api.h>
#include "nfapi_crc_indication_pdu.h"

// Define the maximum number of threads to use for processing requests
#define MAX_THREADS 16

// Define the size of the shared memory segment
#define SHARED_MEM_SIZE (1024 * 1024)

// Define the message queue key
#define MSGQ_KEY 12345

// Define the message queue size
#define MSGQ_SIZE 16

// Define the message structure for passing messages between threads
typedef struct {
    uint8_t* buffer;
    size_t size;
} message_t;

// Define the shared memory segment structure
typedef struct {
    uint8_t* data;
    size_t size;
} shm_segment_t;

// Define the thread-safe queue structure for storing messages
typedef struct {
    pthread_mutex_t mutex;
    message_t** messages;
    int head;
    int tail;
    int size;
} queue_t;

// Initialize the library
bool init() {
    // Create a shared memory segment for storing the data
    shm_segment_t* shm = create_shm(SHARED_MEM_SIZE);
    if (!shm) {
        return false;
    }

    // Initialize the message queue
    queue_t* msgq = create_msgq(MSGQ_SIZE);
    if (!msgq) {
        return false;
    }

    // Create a thread pool for processing requests
    pthread_t* threads = malloc(MAX_THREADS * sizeof(pthread_t));
    if (!threads) {
        return false;
    }

    int i;
    for (i = 0; i < MAX_THREADS; ++i) {
        // Create a thread and pass it the message queue and shared memory segment
        pthread_create(&threads[i], NULL, process_request, msgq);
    }

    return true;
}

// Process a request from an external data source
void* process_request(void* arg) {
    // Get the message queue and shared memory segment from the argument
    queue_t* msgq = (queue_t*)arg;
    shm_segment_t* shm = get_shm();

    // Continuously receive and process messages until the queue is empty
    while (1) {
        message_t* message = dequeue(msgq);
        if (!message) {
            break;
        }

        // Process the received message
        process_message(message->buffer, message->size, shm);

        free(message);
    }

    return NULL;
}

// Process a received message
void process_message(uint8_t* buffer, size_t size, shm_segment_t* shm) {
    // Create a new `NFAPI_CRC_INDICATION_PDU_T` structure and populate it with the data
    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        return;
    }

    // Initialize the structure with the received data
    memcpy(&pdu->rnti, buffer, sizeof(uint16_t));
    memcpy(&pdu->rx_ue_information_tag, buffer + 2, sizeof(uint8_t));
    memcpy(&pdu->crc_indication_rel8_tag, buffer + 3, sizeof(uint8_t));
    pdu->crflag = true;

    // Add the new structure to the shared memory segment
    add_pdu(shm, pdu);
}

// Add a `NFAPI_CRC_INDICATION_PDU_T` structure to the shared memory segment
void add_pdu(shm_segment_t* shm, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Compute the MD5 hash of the structure data
    uint8_t md5[16];
    compute_md5(pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), md5);

    // Write the structure to shared memory and update the metadata
    write_shm(shm, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    update_metadata(shm, md5);
}

// Compute the MD5 hash of a given string efficiently
uint8_t* compute_md5(uint8_t* data, size_t size, uint8_t* md5) {
    // Use the standard cryptographic library to compute the MD5 hash
    void* digest = NULL;
    int err = curl_digest_md5(data, size, &digest);
    if (err != CURLE_OK) {
        return false;
    }

    // Copy the hash to the output buffer and free the allocated memory
    memcpy(md5, digest, 16);
    curl_free(digest);

    return true;
}

// Write data to shared memory and update the metadata
void write_shm(shm_segment_t* shm, void* data, size_t size) {
    // Compute the offset of the next available location in shared memory
    int offset = shm->head * shm->size;

    // Check if there is enough space left in shared memory for the new data
    if (offset + size > shm->size) {
        return false;
    }

    // Write the new data to shared memory and update the metadata
    memcpy(shm->data + offset, data, size);
    shm->head = (shm->head + 1) % shm->size;

    return true;
}

// Update the metadata for a given structure in shared memory
void update_metadata(shm_segment_t* shm, uint8_t* md5) {
    // Compute the offset of the metadata for the new structure
    int offset = shm->head * sizeof(uint32_t);

    // Write the MD5 hash of the structure to shared memory and update the metadata
    memcpy(shm->data + offset, md5, 16);
}

// Get a pointer to the shared memory segment for storing data
shm_segment_t* get_shm() {
    // Use a thread-safe queue for accessing the shared memory segment
    queue_t* msgq = create_msgq(MSGQ_SIZE);
    if (!msgq) {
        return false;
    }

    message_t* message = malloc(sizeof(message_t));
    if (!message) {
        return false;
    }

    // Send a request to get the shared memory segment from the main thread
    message->buffer = NULL;
    message->size = 0;
    enqueue(msgq, message);

    // Wait for the main thread to send back the shared memory segment
    while (1) {
        message_t* message = dequeue(msgq);
        if (!message) {
            break;
        }

        if (message->buffer && message->size > 0) {
            return (shm_segment_t*)message->buffer;
        } else {
            free(message);
        }
    }

    return false;
}

// Create a thread-safe queue for storing messages
queue_t* create_msgq(int size) {
    // Allocate memory for the message queue and initialize its metadata
    queue_t* msgq = malloc(sizeof(queue_t));
    if (!msgq) {
        return false;
    }

    msgq->messages = malloc(size * sizeof(message_t*));
    msgq->head = 0;
    msgq->tail = 0;
    msgq->size = size;

    // Initialize the mutex for locking access to the queue
    pthread_mutex_init(&msgq->mutex, NULL);

    return msgq;
}

// Enqueue a message in the message queue
bool enqueue(queue_t* msgq, message_t* message) {
    // Lock the mutex to prevent race conditions when accessing the queue
    pthread_mutex_lock(&msgq->mutex);

    // Check if there is enough space left in the queue for the new message
    int available = (msgq->size - 1) - msgq->tail;
    if (available <= 0) {
        return false;
    }

    // Add the new message to the end of the queue and update the tail index
    msgq->messages[msgq->tail] = message;
    msgq->tail = (msgq->tail + 1) % msgq->size;

    // Unlock the mutex to allow other threads to access the queue
    pthread_mutex_unlock(&msgq->mutex);

    return true;
}

// Dequeue a message from the message queue
message_t* dequeue(queue_t* msgq) {
    // Lock the mutex to prevent race conditions when accessing the queue
    pthread_mutex_lock(&msgq->mutex);

    // Check if there are any messages in the queue
    int available = (msgq->size - 1) - msgq->head;
    if (available <= 0) {
        return NULL;
    }

    // Get a pointer to the next message in the queue and update the head index
    message_t* message = msgq->messages[msgq->head];
    msgq->head = (msgq->head + 1) % msgq->size;

    // Unlock the mutex to allow other threads to access the queue
    pthread_mutex_unlock(&msgq->mutex);

    return message;
}']

