// Define the function for generating a AES-128 encryption of a string
static void generate_aes_128(char* input, char* key, char* output) {
    // Use OpenSSL's EVP_BytesToKey() function to create a key from the input string
    unsigned char key_buffer[16];
    if (EVP_BytesToKey(EVP_aes_128_cbc(), EVP_md5(), NULL, key, strlen(key), 16, key_buffer, NULL) <= 0) {
        fprintf(stderr, "Failed to generate AES-128 encryption\n");
        return;
    }

    // Use the key to create an AES-128 cipher
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Failed to allocate memory for AES-128 cipher\n");
        return;
    }
    if (EVP_EncryptInit(ctx, EVP_aes_128_cbc(), key_buffer, NULL) <= 0) {
        fprintf(stderr, "Failed to initialize AES-128 cipher\n");
        return;
    }

    // Encrypt the input string
    size_t output_len = strlen(input);
    size_t block_size = EVP_CIPHER_CTX_block_size(ctx);
    unsigned char iv[block_size];
    if (EVP_EncryptInit(ctx, NULL, NULL, iv) <= 0) {
        fprintf(stderr, "Failed to initialize AES-128 cipher\n");
        return;
    }
    unsigned char* encrypted = (unsigned char*) malloc(output_len + block_size);
    if (!encrypted) {
        fprintf(stderr, "Failed to allocate memory for output buffer\n");
        return;
    }
    int len = 0;
    if (EVP_EncryptUpdate(ctx, encrypted, &output_len, (unsigned char*)input, strlen(input)) <= 0) {
        fprintf(stderr, "Failed to encrypt input string\n");
        return;
    }
    len += output_len;
    if (EVP_EncryptFinal(ctx, encrypted + len, &output_len) <= 0) {
        fprintf(stderr, "Failed to finalize AES-128 encryption\n");
        return;
    }
    len += output_len;

    // Convert the ciphertext into a hexadecimal string and return it
    char* encrypted_str = (char*) malloc(len * 2 + 1);
    if (!encrypted_str) {
        fprintf(stderr, "Failed to allocate memory for output buffer\n");
        return;
    }
    for (int i = 0; i < len; i++) {
        sprintf(&encrypted_str[i * 2], "%02x", encrypted[i]);
    }
    output = encrypted_str;
}

