// httprequestmanager.h
#ifndef HTTPREQUESTMANAGER_H
#define HTTPREQUESTMANAGER_H

#include <map>
#include <string>
#include <memory>
#include <vector>

namespace httprequestmanager {
    class HttpRequestManager {
    public:
        // Initialize the HttpRequestManager with a given number of worker threads and a cache size.
        HttpRequestManager(size_t numWorkers, size_t cacheSize);
        ~HttpRequestManager();

        // Submit an HTTP request to be processed asynchronously.
        void submit(const std::string& url, const std::vector<std::pair<std::string, std::string>>& headers, const std::string& body);

        // Retrieve the result of a submitted request. If the request is not yet complete, this method will block until it is.
        std::string getResult(const std::string& url);

    private:
        struct Request {
            std::string url;
            std::vector<std::pair<std::string, std::string>> headers;
            std::string body;
        };

        // Map of URL to request objects.
        std::map<std::string, std::unique_ptr<Request>> requests_;

        // Cache of recently accessed URLs.
        std::vector<std::string> cache_;

        // Thread pool for processing requests.
        std::vector<std::thread> workers_;

        // Mutex to protect concurrent access to the request map and cache.
        std::mutex mutex_;

        // Condition variable to signal when a new result is available.
        std::condition_variable cv_;

        // Flag indicating whether a shutdown has been requested.
        bool shutdown_;
    };
}

#endif // HTTPREQUESTMANAGER_H
