    char* RX_UE_INFORMATION_TAG;
    char* CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct NFAPI_CRC_INDICATION_PDU_LIST {
    NFAPI_CRC_INDICATION_PDU_T* head;
    NFAPI_CRC_INDICATION_PDU_T* tail;
} NFAPI_CRC_INDICATION_PDU_LIST;

void add_crc_indication(NFAPI_CRC_INDICATION_PDU_LIST* list, uint16_t RNTI, char* RX_UE_INFORMATION_TAG, char* CRC_INDICATION_REL8_TAG, bool CRCFLAG) {
    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->RNTI = RNTI;
    new_node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_node->CRCFLAG = CRCFLAG;

    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
}

void remove_crc_indication(NFAPI_CRC_INDICATION_PDU_LIST* list, uint16_t RNTI) {
    NFAPI_CRC_INDICATION_PDU_T* node = list->head;
    while (node != NULL && node->RNTI != RNTI) {
        node = node->next;
    }

    if (node == NULL) {
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T* temp = node;
    if (temp == list->head) {
        list->head = temp->next;
    } else {
        temp->prev->next = temp->next;
    }

    free(temp);
}

void compute_md5_hash(char* message, size_t length) {
    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, message, length);
    unsigned char digest[16];
    MD5_Final(digest, &ctx);
    for (int i = 0; i < 16; ++i) {
        printf("%02x", digest[i]);
    }
}

void handle_crc_indication(NFAPI_CRC_INDICATION_PDU_T* crc_indication) {
    // Perform any necessary actions based on the CRCFLAG value
    if (crc_indication->CRCFLAG) {
        compute_md5_hash(crc_indication->RX_UE_INFORMATION_TAG, strlen(crc_indication->RX_UE_INFORMATION_TAG));
    }
}

void handle_crc_indications(NFAPI_CRC_INDICATION_PDU_LIST* crc_indications) {
    NFAPI_CRC_INDICATION_PDU_T* node = crc_indications->head;
    while (node != NULL) {
        handle_crc_indication(node);
        node = node->next;
    }
}
