    Transcoder() : num_sessions_(0) {}

    void StartSession(const AudioSegment& segment) {
        // Create a new streaming session for the given segment.
        StreamingSession* session = new StreamingSession(segment.source_url, segment.token);
        sessions_.emplace(session->GetId(), session);
        num_sessions_++;
