            StreamingSession* session = it->second;
            session->Stop();
            num_sessions_--;
            sessions_.erase(it);
        }
    }

    void ProcessSegment(const AudioSegment& segment) {
        // Asynchronously process the given segment using multiple threads.
        vector<future<void>> futures;
        for (auto it = sessions_.begin(); it != sessions_.end(); ++it) {
            StreamingSession* session = it->second;
            future<void> future = async([session, &segment] { this->TranscodeSegment(session, segment); });
            futures.push_back(future);
        }

        // Wait for all transcoding tasks to complete.
        for (auto& future : futures) {
            future.get();
        }
    }

