using System;
using System.Data;
using System.Threading.Tasks;
using System.Net;
using System.Net.Http;
using System.IO;
using Newtonsoft.Json;

namespace DynamicQueryExecutor
{
    public class DynamicQueryExecutor : IDisposable
    {
        private readonly HttpClient _client;
        private readonly List<string> _queryLog = new List<string>();
        private readonly Dictionary<string, object> _cachedQueries = new Dictionary<string, object>();
        private readonly int _maxCacheSize = 1024 * 1024 * 5; // 5 MB
        private readonly int _cacheTTL = 60 * 60; // 1 hour
        private readonly bool _enableCaching = true;
        private readonly bool _enableTransactionManagement = true;
        private readonly string _connectionString;
        private readonly TimeSpan _timeout;
        private readonly int _maxRetries = 3;
        private readonly ExponentialBackoffPolicy _backoffPolicy;
        private readonly Dictionary<string, object> _parameters;

        public DynamicQueryExecutor(HttpClient client, string connectionString, TimeSpan timeout, int maxRetries, ExponentialBackoffPolicy backoffPolicy, Dictionary<string, object> parameters)
        {
            _client = client;
            _connectionString = connectionString;
            _timeout = timeout;
            _maxRetries = maxRetries;
            _backoffPolicy = backoffPolicy;
            _parameters = parameters;
        }

        public async Task<IDataReader> ExecuteQueryAsync(string query, List<object> values)
        {
            var requestUri = $"{_connectionString}&commandText={query}";
            var request = new HttpRequestMessage(HttpMethod.Post, requestUri);

            foreach (var value in values)
            {
                request.Content.Add(new StringContent(JsonConvert.SerializeObject(value), Encoding.UTF8, "application/json"));
            }

            var response = await _client.SendAsync(request).ConfigureAwait(false);
            response.EnsureSuccessStatusCode();

            var stream = await response.Content.ReadAsStreamAsync().ConfigureAwait(false);
            return new DataReader(stream, true);
        }

        public async Task<IDataReader> ExecuteQueryWithCachingAsync(string query, List<object> values)
        {
            if (!_enableCaching)
            {
                return await ExecuteQueryAsync(query, values).ConfigureAwait(false);
            }

            var cacheKey = GetCacheKey(query, values);
            if (_cachedQueries.ContainsKey(cacheKey))
            {
                return _cachedQueries[cacheKey];
            }

            try
            {
                var result = await ExecuteQueryAsync(query, values).ConfigureAwait(false);
                AddToCache(cacheKey, result);
                return result;
            }
            catch (Exception)
            {
                RemoveFromCache(cacheKey);
                throw;
            }
        }

        public async Task<IDataReader> ExecuteQueryWithTransactionManagementAsync(string query, List<object> values)
        {
            if (!_enableTransactionManagement)
            {
                return await ExecuteQueryWithCachingAsync(query, values).ConfigureAwait(false);
            }

            try
            {
                using (var transaction = new SqlTransaction(_connectionString))
                {
                    var result = await ExecuteQueryAsync(query, values).ConfigureAwait(false);
                    if (!result.HasRows)
                    {
                        throw new Exception("No rows returned");
                    }

                    transaction.Commit();
                    return result;
                }
            }
            catch (Exception)
            {
                throw;
            }
        }

        public async Task<IDataReader> ExecuteQueryAsync(string query, List<object> values, Action<IDataReader> callback)
        {
            var result = await ExecuteQueryWithTransactionManagementAsync(query, values).ConfigureAwait(false);
            if (callback != null)
            {
                callback.Invoke(result);
            }

            return result;
        }

        public async Task<IDataReader> ExecuteQueryAsync(string query, List<object> values, Action<IDataReader> callback, bool useCaching)
        {
            if (useCaching)
            {
                return await ExecuteQueryWithCachingAsync(query, values).ConfigureAwait(false);
            }

            return await ExecuteQueryWithTransactionManagementAsync(query, values).ConfigureAwait(false);
        }

        private void AddToCache(string cacheKey, IDataReader result)
        {
            if (_cachedQueries.ContainsKey(cacheKey))
            {
                return;
            }

            _cachedQueries.Add(cacheKey, result);
        }

        private void RemoveFromCache(string cacheKey)
        {
            if (!_cachedQueries.ContainsKey(cacheKey))
            {
                return;
            }

            _cachedQueries.Remove(cacheKey);
        }

        private string GetCacheKey(string query, List<object> values)
        {
            var cacheKey = $"{query}|{values}";
            return cacheKey;
        }

        public void Dispose()
        {
            _client.Dispose();
        }
    }

    public class ExponentialBackoffPolicy : IBackoffPolicy
    {
        private readonly int _maxRetries;
        private readonly TimeSpan _minDelay;
        private readonly TimeSpan _maxDelay;

        public ExponentialBackoffPolicy(int maxRetries, TimeSpan minDelay, TimeSpan maxDelay)
        {
            _maxRetries = maxRetries;
            _minDelay = minDelay;
            _maxDelay = maxDelay;
        }

        public int GetNextRetryCount()
        {
            return 0;
        }

        public TimeSpan GetNextDelay(int retryCount)
        {
            if (retryCount == 0)
            {
                return _minDelay;
            }

            var delay = Math.Min(_maxDelay, _minDelay * Math.Pow(2, retryCount - 1));
            return delay;
        }
    }
}']

