void initSocket() {
    // Initialize socket
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        handleError("Failed to create socket");
        return;
    }

    // Connect to server
    struct sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    server_address.sin_port = htons(PORT);
    inet_pton(AF_INET, SERVER_IP, &server_address.sin_addr);
    if (connect(sock, (struct sockaddr*)&server_address, sizeof(server_address)) < 0) {
        handleError("Failed to connect to server");
        return;
    }

    // Set timeout
    struct timeval tv;
    tv.tv_sec = DEFAULT_TIMEOUT;
    if (setsockopt(sock, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv)) < 0) {
        handleError("Failed to set receive timeout");
        return;
    }
}

void sendRequest(const string& endpoint, const string& method, const string& data) {
    // Send request
    struct Request {
        int sock;
        string endpoint;
        string method;
        string data;
    };
    Request request = {sock, endpoint, method, data};
    if (write(sock, &request, sizeof(request)) < 0) {
        handleError("Failed to send request");
        return;
    }
}

void processResponse(const string& response) {
    // Process response
    struct Response {
        int status_code;
        string body;
    };
    Response* pResponse = (Response*)&response;
    if (pResponse->status_code != 200) {
        handleError("Failed to process response");
        return;
    }
}

