```php
<?php

require_once __DIR__ . '/vendor/autoload.php';

use Symfony\Component\HttpFoundation\Request;
use Symfony\Component\HttpFoundation\Response;
use Doctrine\ORM\EntityManagerInterface;
use Doctrine\DBAL\Connection;
use Psr\Log\LoggerInterface;

class ClinicService {
    private $entityManager;
    private $connection;
    private $logger;

    public function __construct(EntityManagerInterface $entityManager, Connection $connection, LoggerInterface $logger) {
        $this->entityManager = $entityManager;
        $this->connection = $connection;
        $this->logger = $logger;
    }

    public function updateClinicStatus(Request $request): Response {
        // Retrieve clinic ID from request
        $clinicId = $request->get('clinic_id');

        // Connect to database and retrieve clinic record
        $clinic = $this->entityManager->find('App\Entity\Clinic', $clinicId);

        if (!$clinic) {
            throw new Exception("Clinic not found");
        }

        // Update status and last modified IP address
        $clinic->setStatus($request->get('status'));
        $clinic->setLastModifiedIpAddress($_SERVER['REMOTE_ADDR']);

        // Persist changes to database
        try {
            $this->entityManager->persist($clinic);
            $this->entityManager->flush();
            return new Response(200, [], 'Clinic status updated successfully');
        } catch (Exception $e) {
            $this->logger->error("Failed to update clinic status: {$e->getMessage()}");
            return new Response(500, [], 'Internal server error');
        }
    }
}
```
