        }

        public async Task DeploySiteAsync(string directoryPath, string siteName)
        {
            try
            {
                // Prepare the deployment by validating the directory path and site name.
                ValidateDirectoryPathAndSiteName(directoryPath, siteName);

                // Resolve any dependencies required for the site.
                var dependencyResults = await _dependencyResolver.ResolveDependenciesAsync(_siteName);

