                        {"SiteName", siteName }
                    });
                });

                // Handle any errors that may have occurred during the deployment process.
                if (monitoringResult.HasErrors)
                {
                    _logger.LogError($"Deployment of site {siteName} failed with error: {monitoringResult.ErrorMessage}");
                }
            }
            catch (Exception ex)
            {
                // Log the exception and notify the user of the deployment failure.
                _logger.LogError(ex, $"Deployment of site {siteName} failed with error: {ex.Message}");
