                // Monitor the update process to ensure it completes successfully.
                var monitoringResult = await _resourceMonitor.MonitorResourceUsageAsync(async () =>
                {
                    // Update the site and configuration.
                    await _configService.UpdateConfigurationAsync(_siteName, new Dictionary<string, string>
                    {
                        {"DirectoryPath", directoryPath },
                        {"SiteName", siteName }
                    });
                });

