// NetworkMonitor Library

#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <vector>
#include <algorithm>
#include <random>
#include <chrono>
#include <ctime>

namespace NetworkMonitor {
    class MersenneTwister {
        private:
            std::mt19937_64 mt;
            std::uniform_int_distribution<unsigned long long> dist;

        public:
            MersenneTwister(const unsigned long long seed = std::chrono::system_clock::now().time_since_epoch().count()) {
                this->mt.seed(seed);
                this->dist = std::uniform_int_distribution<unsigned long long>(0, std::numeric_limits<unsigned long long>::max());
            }

            unsigned long long getNext() {
                return this->dist(this->mt);
            }
    };

    class ConnectionStatusIndicator {
        private:
            std::string ipAddress;
            int port;
            double latency;
            bool active;

        public:
            ConnectionStatusIndicator(const std::string& ipAddress, const int port) : ipAddress(ipAddress), port(port) {
                this->latency = 0.0;
                this->active = false;
            }

            std::string getIpAddress() const { return this->ipAddress; }
            void setIpAddress(const std::string& ipAddress) { this->ipAddress = ipAddress; }

            int getPort() const { return this->port; }
            void setPort(const int port) { this->port = port; }

            double getLatency() const { return this->latency; }
            void setLatency(const double latency) { this->latency = latency; }

            bool isActive() const { return this->active; }
            void setActive(const bool active) { this->active = active; }
    };

    class ConnectionManager {
        private:
            std::mutex mutex;
            std::condition_variable cv;
            std::vector<ConnectionStatusIndicator*> connectionIndicators;
            MersenneTwister rng;

        public:
            ConnectionManager() : rng(std::chrono::system_clock::now().time_since_epoch().count()) { }

            void addConnectionIndicator(const std::string& ipAddress, const int port) {
                std::lock_guard<std::mutex> lock(this->mutex);
                this->connectionIndicators.push_back(new ConnectionStatusIndicator(ipAddress, port));
            }

            void updateConnectionIndicator(const std::string& ipAddress, const int port) {
                std::lock_guard<std::mutex> lock(this->mutex);
                for (auto it = this->connectionIndicators.begin(); it != this->connectionIndicators.end(); ++it) {
                    if ((*it)->getIpAddress() == ipAddress && (*it)->getPort() == port) {
                        (*it)->setActive(true);
                    }
                }
            }

            void removeConnectionIndicator(const std::string& ipAddress, const int port) {
                std::lock_guard<std::mutex> lock(this->mutex);
                for (auto it = this->connectionIndicators.begin(); it != this->connectionIndicators.end(); ++it) {
                    if ((*it)->getIpAddress() == ipAddress && (*it)->getPort() == port) {
                        delete *it;
                        it = this->connectionIndicators.erase(it);
                    }
                }
            }

            std::vector<ConnectionStatusIndicator*> getAllConnectionIndicators() const { return this->connectionIndicators; }
    };
}
```
