class NFAPI_CRC_INDICATION_PDU_T {
 public:
  static const int MAX_RETRY = 3;

  void handle_crc_indication(CRC_INDICATION_PDU_T pdu) {
    std::lock_guard<std::mutex> lock(mutex_);
    if (pdu.rx_ue_information_tag == RX_UE_INFORMATION_TAG) {
      // Check if the received RNTI is valid
      auto it = rnti_set_.find(pdu.rnti);
      if (it != rnti_set_.end()) {
        // The received RNTI is valid, update the list of CRC indications
        crc_indication_list_.push_back(pdu);
        return;
      } else {
        // The received RNTI is not valid, retry
        std::cout << "Received invalid RNTI: " << pdu.rnti << std::endl;
        if (retry_count_ < MAX_RETRY) {
          retry_count_++;
          // Retry the request with a backoff strategy
          std::this_thread::sleep_for(std::chrono::seconds(2 * retry_count_));
          handle_crc_indication(pdu);
        } else {
          std::cout << "Maximum retries reached, dropping CRC indication" << std::endl;
        }
      }
    }
  }

 private:
  int retry_count_ = 0;
  std::mutex mutex_;
  std::condition_variable cv_;
  std::vector<CRC_INDICATION_PDU_T> crc_indication_list_;
  std::set<uint16_t> rnti_set_;
};
