Highly skilled coding assistant: Design a high-performance, modular C++ library that efficiently manages a doubly-linked list of `HTTP_RESPONSE_RECORD` objects, each containing an HTTP status code, headers, and body data. The library must support concurrent access from multiple threads, ensuring data integrity through atomic operations and fine-grained locking mechanisms.
```c++
#include <iostream>
#include <mutex>
#include <condition_variable>

class HTTPResponseRecord {
public:
    int statusCode;
    std::string headers;
    std::string bodyData;
};

class HTTPResponseList {
private:
    std::mutex mutex_;
    std::condition_variable cv_;
    bool shutdown_;
    std::list<HTTPResponseRecord> list_;

public:
    HTTPResponseList() : shutdown_(false) {}

    ~HTTPResponseList() {
        // Ensure all threads have released the mutex before destroying the list.
        std::unique_lock<std::mutex> lock(mutex_);
        while (list_.size() > 0) {
            cv_.wait(lock);
        }
    }

    void addResponseRecord(HTTPResponseRecord record) {
        // Lock the mutex before accessing the list.
        std::unique_lock<std::mutex> lock(mutex_);

        // Add the new response record to the end of the list.
        list_.push_back(record);

        // Notify any threads waiting on the condition variable that a new response has been added.
        cv_.notify_all();
    }

    void removeResponseRecord(int index) {
        // Lock the mutex before accessing the list.
        std::unique_lock<std::mutex> lock(mutex_);

        // Remove the response record at the given index from the list.
        if (index >= 0 && index < list_.size()) {
            list_.erase(list_.begin() + index);
        }

        // Notify any threads waiting on the condition variable that a response has been removed.
        cv_.notify_all();
    }

    void getResponseRecord(int index) {
        // Lock the mutex before accessing the list.
        std::unique_lock<std::mutex> lock(mutex_);

        // Return the response record at the given index from the list.
        if (index >= 0 && index < list_.size()) {
            return list_[index];
        }
    }

    void shutdown() {
        // Lock the mutex before accessing the flag.
        std::unique_lock<std::mutex> lock(mutex_);

        // Set the shutdown flag to indicate that no more threads should be allowed to access the list.
        shutdown_ = true;

        // Notify any threads waiting on the condition variable that the list has been shut down.
        cv_.notify_all();
    }
};
```
