    // Send an HTTP request to the next available service in the list.
    std::string sendRequest() {
        // Lock the mutex before accessing the list and current service index.
        std::unique_lock<std::mutex> lock(mutex_);

        // Check if there are any services available.
        if (serviceList_.size() == 0) {
            return "";
        }

        // Get the next available service.
