        // Lock the mutex before accessing the flag.
        std::unique_lock<std::mutex> lock(mutex_);

        // Check if backoff is already in progress.
        if (backoffInProgress_) {
            return;
        }

        // Set the backoff flag to indicate that backoff is in progress.
        backoffInProgress_ = true;

        // Unlock the mutex before starting the backoff timer.
        lock.unlock();

        // Start the backoff timer.
        std::this_thread::sleep_for(std::chrono::seconds(5));

        // Lock the mutex again before accessing the flag and list.
        lock.lock();

        // Check if the backoff has been canceled.
        if (!backoffInProgress_) {
