        // Remove the last failed request from the list.
        serviceList_.erase(serviceList_.end() - 1);

        // Set the current service index to the beginning of the list.
        currentServiceIndex_ = 0;

        // Unset the backoff flag.
        backoffInProgress_ = false;

        // Notify any threads waiting on the condition variable that the list has changed.
        cv_.notify_all();
    }
};
