// MemoryManager.h

#pragma once

#include <mutex>
#include <unordered_map>
#include <vector>

struct Record {
    long offset;
    int key;
    float value;
};

class MemoryManager {
public:
    // Initialize the memory manager with a maximum size and key range.
    MemoryManager(size_t maxSize, int minKey, int maxKey);

    // Allocate a new record structure with the given offset, key, and value.
    Record* allocateRecord(long offset, int key, float value);

    // Free the given record structure.
    void freeRecord(Record* record);

    // Update the value of the given record structure.
    void updateValue(Record* record, float newValue);

    // Get the value of the given record structure.
    float getValue(Record* record);

private:
    // The maximum size of the memory manager.
    size_t _maxSize;

    // The minimum key range of the memory manager.
    int _minKey;

    // The maximum key range of the memory manager.
    int _maxKey;

    // A mutex for synchronizing access to the records.
    std::mutex _mutex;

    // A vector of record structures, sorted by offset.
    std::vector<Record*> _records;

    // An unordered map of record structures, indexed by key.
    std::unordered_map<int, Record*> _keyMap;
};

// MemoryManager.cpp

#include "MemoryManager.h"

MemoryManager::MemoryManager(size_t maxSize, int minKey, int maxKey) :
    _maxSize(maxSize),
    _minKey(minKey),
    _maxKey(maxKey),
    _mutex(),
    _records(),
    _keyMap()
{
}

Record* MemoryManager::allocateRecord(long offset, int key, float value) {
    // Check if the offset is within the range of the memory manager.
    if (offset < 0 || offset >= _maxSize) {
        throw std::invalid_argument("Offset out of range.");
    }

    // Check if the key is within the range of the memory manager.
    if (key < _minKey || key > _maxKey) {
        throw std::invalid_argument("Key out of range.");
    }

    // Create a new record structure with the given offset, key, and value.
    Record* record = new Record{offset, key, value};

    // Add the record to the vector of records sorted by offset.
    std::lock_guard<std::mutex> lock(_mutex);
    _records.push_back(record);

    // Add the record to the unordered map indexed by key.
    _keyMap[key] = record;

    return record;
}

void MemoryManager::freeRecord(Record* record) {
    std::lock_guard<std::mutex> lock(_mutex);

    // Remove the record from the vector of records sorted by offset.
    _records.erase(std::remove(_records.begin(), _records.end(), record), _records.end());

    // Remove the record from the unordered map indexed by key.
    _keyMap.erase(record->key);

    delete record;
}

void MemoryManager::updateValue(Record* record, float newValue) {
    std::lock_guard<std::mutex> lock(_mutex);

    // Update the value of the record structure.
    record->value = newValue;

    // Update the map indexed by key.
    _keyMap[record->key] = record;
}

float MemoryManager::getValue(Record* record) {
    std::lock_guard<std::mutex> lock(_mutex);

    return record->value;
}']

