    void HandleUserRequest(const std::string& id, const std::string& name, const std::string& email, const std::string& password, const std::string& sub_action) {
        if (sub_action == "create") {
            user_account_manager_.CreateUserAccount(id, name, email, password);
        } else if (sub_action == "update") {
            user_account_manager_.UpdateUserAccount(id, name, email, password);
        } else if (sub_action == "delete") {
            user_account_manager_.DeleteUserAccount(id);
        } else {
            throw std::runtime_error("Invalid sub-action");
        }
    }

private:
