['package main

import (
	"fmt"
	"time"
)

type Record struct {
	Offset int64
	Key    int32
	Value  float64
}

// MemoryManager manages memory allocation and initialization for records.
type MemoryManager struct {
	records      map[int]Record
	recordLength int
}

func (m *MemoryManager) AllocateRecords(numRecords int) error {
	// Check if the number of records to allocate is valid
	if numRecords <= 0 {
		return fmt.Errorf("invalid number of records to allocate: %d", numRecords)
	}

	m.records = make(map[int]Record, numRecords)
	for i := 0; i < numRecords; i++ {
		m.records[i] = Record{Offset: int64(i), Key: int32(i), Value: float64(i)}
	}
	return nil
}

func (m *MemoryManager) DeallocateRecords() error {
	// Check if any records are allocated
	if len(m.records) == 0 {
		return fmt.Errorf("no records allocated")
	}

	for _, record := range m.records {
		record.Offset = 0
		record.Key = 0
		record.Value = 0.0
	}
	m.records = make(map[int]Record)
	return nil
}

func (m *MemoryManager) InitializeRecords() error {
	// Check if any records are allocated
	if len(m.records) == 0 {
		return fmt.Errorf("no records allocated")
	}

	for _, record := range m.records {
		record.Offset = int64(record.Key)
		record.Value = float64(record.Key) * 2.0
	}
	return nil
}

// GetRecord returns a record from the memory manager by its key.
func (m *MemoryManager) GetRecord(key int32) (*Record, error) {
	// Check if the key is valid
	if key <= 0 {
		return nil, fmt.Errorf("invalid key: %d", key)
	}

	// Check if the record exists in the memory manager
	record, ok := m.records[key]
	if !ok {
		return nil, fmt.Errorf("record not found for key: %d", key)
	}

	return &record, nil
}

// SetRecord sets a record in the memory manager by its key.
func (m *MemoryManager) SetRecord(key int32, value float64) error {
	// Check if the key is valid
	if key <= 0 {
		return fmt.Errorf("invalid key: %d", key)
	}

	// Check if the record exists in the memory manager
	record, ok := m.records[key]
	if !ok {
		return fmt.Errorf("record not found for key: %d", key)
	}

	record.Value = value
	return nil
}

// AddRecord adds a record to the memory manager.
func (m *MemoryManager) AddRecord(key int32, value float64) error {
	// Check if the key is valid
	if key <= 0 {
		return fmt.Errorf("invalid key: %d", key)
	}

	// Check if the record already exists in the memory manager
	_, ok := m.records[key]
	if ok {
		return fmt.Errorf("record already exists for key: %d", key)
	}

	m.records[key] = Record{Offset: int64(key), Key: key, Value: value}
	return nil
}

// RemoveRecord removes a record from the memory manager by its key.
func (m *MemoryManager) RemoveRecord(key int32) error {
	// Check if the key is valid
	if key <= 0 {
		return fmt.Errorf("invalid key: %d", key)
	}

	// Check if the record exists in the memory manager
	_, ok := m.records[key]
	if !ok {
		return fmt.Errorf("record not found for key: %d", key)
	}

	delete(m.records, key)
	return nil
}

// PrintRecords prints all the records in the memory manager.
func (m *MemoryManager) PrintRecords() error {
	// Check if any records are allocated
	if len(m.records) == 0 {
		return fmt.Errorf("no records allocated")
	}

	for _, record := range m.records {
		fmt.Println(record)
	}
	return nil
}
