    handleError("Invalid API response");
  } else {
    // Update the cache and notify threads of new data
    Json::Value json_data = Json::parse(response);
    if (key == CURRENT_WEATHER_KEY) {
      updateCachedWeatherData(json_data);
    } else if (key == HISTORICAL_WEATHER_KEY) {
      updateCachedHistoricalWeatherData(json_data);
    } else if (key == CLIMATE_DATA_KEY) {
      updateCachedClimateData(json_data);
    } else if (key == WEATHER_ICONS_KEY) {
      updateCachedWeatherIcons(json_data);
    }
    --g_num_active_threads;
    g_cv.notify_all();
  }
