  std::string current_weather_url = buildURL(CURRENT_WEATHER_KEY);
  std::string historical_weather_url = buildURL(HISTORICAL_WEATHER_KEY);
  std::string climate_data_url = buildURL(CLIMATE_DATA_KEY);
  std::string weather_icons_url = buildURL(WEATHER_ICONS_KEY);
  std::vector<std::string> urls { current_weather_url, historical_weather_url, climate_data_url, weather_icons_url };
  for (const auto& url : urls) {
    std::cout << "Fetching API data from URL: " << url << std::endl;
    fetchData(url, handleAPIResponse);
  }
}

void handleError(std::string error_message) {
  std::cout << "Error: " << error_message << std::endl;
  --g_num_active_threads;
  g_cv.notify_all();
}

void run() {
  while (true) {
    fetchWeatherData();
    // Wait for all active threads to finish before updating the UI again
    while (g_num_active_threads > 0) {
      std::cout << "Waiting for API response..." << std::endl;
      g_cv.wait(g_mutex);
    }
  }
}
