struct nfapi_crc_indication_t {
    int pdu_type; // PDU type (e.g., CRC status)
    int pdu_size; // Size of the PDU in bytes
    char* pdu; // Pointer to the PDU data
};

// Structure for storing NFAPI_CRC_INDICATION_PDU_T structures in a linked list
struct nfapi_crc_indication_list {
    struct nfapi_crc_indication_t* head; // Pointer to the first element of the list
    struct nfapi_crc_indication_t* tail; // Pointer to the last element of the list
};

// Structure for storing NFAPI_CRC_INDICATION_PDU_T data in a hash table
struct nfapi_crc_indication_hash {
    struct nfapi_crc_indication_t* pdu; // Pointer to the PDU data
    UINT32 hash; // Hash value of the PDU data
};

// Function for creating a new NFAPI_CRC_INDICATION_PDU_T structure
struct nfapi_crc_indication_t* create_nfapi_crc_indication(int pdu_type, int pdu_size, char* pdu) {
    struct nfapi_crc_indication_t* new_pdu = (struct nfapi_crc_indication_t*) malloc(sizeof(struct nfapi_crc_indication_t));
    if (!new_pdu) {
        return NULL;
    }

    new_pdu->pdu_type = pdu_type;
    new_pdu->pdu_size = pdu_size;
    new_pdu->pdu = (char*) malloc(pdu_size * sizeof(char));
    if (!new_pdu->pdu) {
        free(new_pdu);
        return NULL;
    }
    memcpy(new_pdu->pdu, pdu, pdu_size * sizeof(char));

    return new_pdu;
}

// Function for inserting a NFAPI_CRC_INDICATION_PDU_T structure into a linked list
void insert_nfapi_crc_indication(struct nfapi_crc_indication_list* list, struct nfapi_crc_indication_t* pdu) {
    if (!list || !pdu) {
        return;
    }

    // Insert the new PDU at the end of the list
    if (list->tail) {
        list->tail->next = pdu;
    } else {
        list->head = pdu;
    }
    list->tail = pdu;
}

// Function for inserting a NFAPI_CRC_INDICATION_PDU_T structure into a hash table
void insert_nfapi_crc_indication(struct nfapi_crc_indication_hash* hash, struct nfapi_crc_indication_t* pdu) {
    if (!hash || !pdu) {
        return;
    }

    // Calculate the hash value for the PDU data
    UINT32 hash = calculate_hash(pdu->pdu, pdu->pdu_size);

    // Insert the new PDU into the hash table
    struct nfapi_crc_indication_t* existing_pdu = hash->table[hash];
    if (!existing_pdu) {
        // No PDU with this hash value exists, so create a new one
        existing_pdu = (struct nfapi_crc_indication_t*) malloc(sizeof(struct nfapi_crc_indication_t));
        if (!existing_pdu) {
            return;
        }
        hash->table[hash] = existing_pdu;
    }

    // Copy the PDU data into the existing PDU
    memcpy(existing_pdu->pdu, pdu->pdu, pdu->pdu_size * sizeof(char));
    existing_pdu->pdu_type = pdu->pdu_type;
    existing_pdu->pdu_size = pdu->pdu_size;
}

// Function for searching a NFAPI_CRC_INDICATION_PDU_T structure in a linked list
struct nfapi_crc_indication_t* search_nfapi_crc_indication(struct nfapi_crc_indication_list* list, UINT32 hash) {
    if (!list) {
        return NULL;
    }

    // Search the linked list for a matching PDU
    struct nfapi_crc_indication_t* current = list->head;
    while (current) {
        if (calculate_hash(current->pdu, current->pdu_size) == hash) {
            return current;
        }
        current = current->next;
    }

    return NULL;
}

// Function for searching a NFAPI_CRC_INDICATION_PDU_T structure in a hash table
struct nfapi_crc_indication_t* search_nfapi_crc_indication(struct nfapi_crc_indication_hash* hash, UINT32 hash) {
    if (!hash) {
        return NULL;
    }

    // Search the hash table for a matching PDU
    struct nfapi_crc_indication_t* existing_pdu = hash->table[hash];
    if (existing_pdu) {
