#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>
#include "nfaapi.h" // header file containing NFAPI_CRC_INDICATION_PDU_T and other related structures

// database connection struct for persistent storage
typedef struct {
    char* host;
    char* dbname;
    char* user;
    char* password;
} db_connection_t;

// thread-safe list structure for storing RNTIs
typedef struct {
    pthread_mutex_t mutex;
    size_t size;
    int capacity;
    int* elements;
} rnti_list_t;

// function to initialize the rnti list
void init_rnti_list(rnti_list_t* list) {
    // initialize mutex and allocate memory for elements array
    pthread_mutex_init(&list->mutex, NULL);
    list->size = 0;
    list->capacity = 1024;
    list->elements = malloc(sizeof(int) * list->capacity);
}

// function to add an RNTI to the rnti list
void add_rnti(rnti_list_t* list, int rnti) {
    // acquire mutex before modifying list
    pthread_mutex_lock(&list->mutex);
    // check if list is full and resize if necessary
    if (list->size == list->capacity) {
        list->capacity *= 2;
        list->elements = realloc(list->elements, sizeof(int) * list->capacity);
    }
    // add rnti to end of list and update size
    list->elements[list->size++] = rnti;
    pthread_mutex_unlock(&list->mutex);
}

// function to check if an RNTI is in the rnti list
bool contains_rnti(rnti_list_t* list, int rnti) {
    // acquire mutex before accessing list
    pthread_mutex_lock(&list->mutex);
    // iterate through list and check for match
    for (int i = 0; i < list->size; i++) {
        if (list->elements[i] == rnti) {
            pthread_mutex_unlock(&list->mutex);
            return true;
        }
    }
    // release mutex and return false if no match found
    pthread_mutex_unlock(&list->mutex);
    return false;
}

// function to process and store NFAPI CRC indications
void process_and_store_nfaapi_crc_indications(NFAPI_CRC_INDICATION_PDU_T* pdu, db_connection_t* connection) {
    // validate RNTI against real-time CRC check result
    if (pdu->rx_ue_information.rnti == -1) {
        printf("RNTI not found in NFAPI PDU\n");
        return;
    } else if (pdu->rx_ue_information.crc_indication_rel8.valid == 0) {
        printf("CRC check result is invalid\n");
        return;
    }

    // add RNTI to rnti list for uniqueness checking
    if (!contains_rnti(&list, pdu->rx_ue_information.rnti)) {
        add_rnti(&list, pdu->rx_ue_information.rnti);
    } else {
        printf("RNTI already present in list\n");
    }

    // store NFAPI CRC indications in database
    char query[1024];
    snprintf(query, 1024, "INSERT INTO nfaapi_crc_indications (rnti, crc) VALUES (%d, %u)", pdu->rx_ue_information.rnti, pdu->rx_ue_information.crc_indication_rel8.crc);
    // execute query and check for errors
    if (sqlite3_exec(connection, query, NULL, NULL, NULL) != SQLITE_OK) {
        printf("Error storing NFAPI CRC indications in database\n");
        return;
    }
}

// main function to handle NFAPI CRC indication stream
void main() {
    // initialize rnti list and database connection
    rnti_list_t list;
    db_connection_t* connection = malloc(sizeof(db_connection_t));
    init_rnti_list(&list);
    connection->host = "localhost";
    connection->dbname = "nfaapi_crc_indications";
    connection->user = "root";
    connection->password = "";

    // process NFAPI CRC indication stream
    while (1) {
        // read PDU from stream
        NFAPI_CRC_INDICATION_PDU_T pdu;
        read_pdu(&pdu);
        // validate and process CRCFLAG
        if (pdu.rx_ue_information.crcflag == 1) {
            process_and_store_nfaapi_crc_indications(&pdu, connection);
        } else {
            printf("CRCFLAG is invalid\n");
        }
    }
}
```
