// Initialize the database connections
void init_database() {
    int i;
    db_conns = malloc(POOL_SIZE * sizeof(sqlite3 *));
    for (i = 0; i < POOL_SIZE; i++) {
        db_conns[i] = sqlite3_open("mydatabase.db", &err);
        if (db_conns[i] == NULL) {
            fprintf(stderr, "Failed to open database: %s\n", err);
            exit(1);
        }
    }
}

// Close the database connections
void close_database() {
    int i;
    for (i = 0; i < POOL_SIZE; i++) {
        sqlite3_close(db_conns[i]);
    }
}

// Add a new RNTI to the linked list head if it is unique
void add_rnti(uint16_t rnti) {
    pthread_mutex_lock(&head->lock);
    if (head == NULL || head->next == NULL) {
        // Create a new node and set it as the head
        RNTI_NODE *new_node = malloc(sizeof(RNTI_NODE));
        new_node->RNTI = rnti;
        new_node->next = head;
        head = new_node;
    } else {
        // Search for an existing node with the same RNTI
        RNTI_NODE *current = head;
        while (current != NULL) {
            if (current->RNTI == rnti) {
                break;
            }
            current = current->next;
        }
        // If a node with the same RNTI is found, return without adding anything
        if (current != NULL) {
            pthread_mutex_unlock(&head->lock);
            return;
        } else {
            // Create a new node and add it to the end of the list
            RNTI_NODE *new_node = malloc(sizeof(RNTI_NODE));
            new_node->RNTI = rnti;
            new_node->next = NULL;
            current->next = new_node;
        }
    }
    pthread_mutex_unlock(&head->lock);
}

// Remove an RNTI from the linked list head if it exists
void remove_rnti(uint16_t rnti) {
    pthread_mutex_lock(&head->lock);
    if (head == NULL || head->next == NULL) {
        // The list is empty or there is only one node, so return without removing anything
        pthread_mutex_unlock(&head->lock);
        return;
    } else {
        // Search for an existing node with the same RNTI
        RNTI_NODE *current = head;
        while (current != NULL) {
            if (current->RNTI == rnti) {
                break;
            }
            current = current->next;
        }
        // If a node with the same RNTI is found, remove it from the list and return
        if (current != NULL) {
            RNTI_NODE *previous = head;
            while (previous != current) {
                previous = previous->next;
            }
            previous->next = current->next;
            free(current);
        } else {
            // The node with the given RNTI was not found in the list, so return without removing anything
            pthread_mutex_unlock(&head->lock);
            return;
        }
    }
    pthread_mutex_unlock(&head->lock);
}

// Process and store an NFAPI_CRC_INDICATION_PDU_T structure
void process_and_store_nfaapi_crc_indications(struct NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Add the RNTI to the linked list head if it is unique
    add_rnti(pdu->RNTI);
    // Store the CRC indication in the database
    char query[1024];
    sprintf(query, "INSERT INTO crc_indications VALUES(%d, %d)", pdu->RX_UE_INFORMATION_TAG, pdu->CRC_INDICATION_REL8_TAG);
    int status = sqlite3_exec(db_conns[pthread_self() % POOL_SIZE], query, NULL, NULL, &err);
    if (status != SQLITE_OK) {
        fprintf(stderr, "Failed to execute database query: %s\n", err);
        return;
    }
}

// Handle CRC validation against a real-time CRC check result
void handle_crc_validation(struct NFAPI_CRC_CHECK_RESULT *result) {
    // Compare the CRC check result with the stored CRC indication
    char query[1024];
    sprintf(query, "SELECT crc FROM crc_indications WHERE rx_ue_information_tag = %d", result->RX_UE_INFORMATION_TAG);
    int status = sqlite3_exec(db_conns[pthread_self() % POOL_SIZE], query, NULL, NULL, &err);
    if (status != SQLITE_OK) {
        fprintf(stderr, "Failed to execute database query: %s\n", err);
        return;
    }
    // If the CRC check result matches the stored CRC indication, remove the RNTI from the linked list head
    if (result->crc == 0) {
        remove_rnti(result->RX_UE_INFORMATION_TAG);
    }
}

