};

// Create a new memory pool with the given size
struct MemoryPool* create_memory_pool(int size) {
    struct MemoryPool *pool = malloc(sizeof(struct MemoryPool));
    pool->size = size;
    pool->num_allocated = 0;
    pool->block = malloc(size * sizeof(struct CRC_INDICATION_PDU_T));
    return pool;
}

// Allocate a new memory block from the pool
struct CRC_INDICATION_PDU_T* alloc_memory_block(struct MemoryPool *pool) {
    if (pool->num_allocated < pool->size) {
        struct CRC_INDICATION_PDU_T *block = &pool->block[pool->num_allocated++];
        return block;
    } else {
        return NULL;
    }
}

// Free a memory block from the pool
void free_memory_block(struct MemoryPool *pool, struct CRC_INDICATION_PDU_T *block) {
    if (pool->num_allocated > 0) {
        int index = block - pool->block;
        if (index < pool->size && index >= 0) {
            pool->num_allocated--;
            memmove(&pool->block[index], &pool->block[index + 1], pool->size - index - 1);
        }
    }
}

// Destroy the memory pool and free all allocated memory blocks
void destroy_memory_pool(struct MemoryPool *pool) {
    if (pool != NULL) {
        free(pool->block);
        free(pool);
    }
}

