        if (rntis->RNTIs[i]->RNTI == RNTI) {
            free(rntis->RNTIs[i]);
            memmove(&rntis->RNTIs[i], &rntis->RNTIs[i + 1], rntis->size - i - 1);
            rntis->num_allocated--;
            return;
        }
    }
}

// Destroy the unique RNTIs data structure and free all allocated memory blocks
void destroy_unique_rntis(struct UniqueRNTIs *rntis) {
    if (rntis != NULL) {
        for (int i = 0; i < rntis->num_allocated; i++) {
            free(rntis->RNTIs[i]);
        }
        free(rntis->RNTIs);
        free(rntis);
    }
}

// Persistent storage for CRC indications using a relational database
struct CRCPersistence {
    sqlite3 *db;
};

// Create a new persistent storage instance for the CRC indications
struct CRCPersistence* create_crc_persistence() {
    struct CRCPersistence *persist = malloc(sizeof(struct CRCPersistence));
    char *error = NULL;

    // Open the database and create the table if it does not exist yet
    persist->db = sqlite3_open("CRC_INDICATIONS.db", &error);
    if (persist->db == NULL) {
        printf("Error opening database: %s\n", error);
        return NULL;
    }

    char *create_table = "CREATE TABLE IF NOT EXISTS CRC_INDICATIONS (RNTI INTEGER, RX_INFO TEXT)";
    sqlite3_exec(persist->db, create_table, NULL, NULL, &error);
    if (error != NULL) {
        printf("Error creating table: %s\n", error);
        return NULL;
    }

    return persist;
}

// Destroy the persistent storage instance for the CRC indications and close the database connection
void destroy_crc_persistence(struct CRCPersistence *persist) {
    if (persist != NULL) {
        sqlite3_close(persist->db);
        free(persist);
    }
}

// Insert a new CRC indication into the persistent storage
void insert_crc_indication(struct CRCPersistence *persist, struct CRC_INDICATION_PDU *pdu) {
    char *error = NULL;

    // Prepare the SQL statement for inserting a new record
    char *insert = "INSERT INTO CRC_INDICATIONS (RNTI, RX_INFO) VALUES (@RNTI, @RX_INFO)";
    sqlite3_stmt *statement = sqlite3_prepare(persist->db, insert);

    // Bind the values for the record
    sqlite3_bind_int(statement, 1, pdu->rnti);
    sqlite3_bind_text(statement, 2, pdu->rx_info.data, -1, SQLITE_STATIC);

    // Execute the statement and check for errors
    if (sqlite3_step(statement) != SQLITE_DONE) {
        printf("Error inserting record: %s\n", sqlite3_errmsg(persist->db));
    }

    // Reset the prepared statement and release resources
    sqlite3_reset(statement);
    sqlite3_finalize(statement);
}

// Remove an existing CRC indication from the persistent storage
void remove_crc_indication(struct CRCPersistence *persist, int RNTI) {
    char *error = NULL;

    // Prepare the SQL statement for removing a record
    char *remove = "DELETE FROM CRC_INDICATIONS WHERE RNTI=@RNTI";
    sqlite3_stmt *statement = sqlite3_prepare(persist->db, remove);

    // Bind the value for the record to be removed
    sqlite3_bind_int(statement, 1, RNTI);

    // Execute the statement and check for errors
    if (sqlite3_step(statement) != SQLITE_DONE) {
        printf("Error removing record: %s\n", sqlite3_errmsg(persist->db));
    }

    // Reset the prepared statement and release resources
    sqlite3_reset(statement);
    sqlite3_finalize(statement);
}

// Main function for demonstrating the use of thread-safe unique RNTIs and persistent storage for CRC indications
int main() {
    // Initialize the persistent storage instance for the CRC indications
    struct CRCPersistence *persist = create_crc_persistence();

    // Create a new unique RNTIs data structure with 10 slots
    struct UniqueRNTIs *rntis = create_unique_rntis(10);

    // Insert the first CRC indication for RNTI=1 and store it in persistent storage
    struct CRC_INDICATION_PDU pdu;
    pdu.rnti = 1;
