// Modular, extensible C++ library for managing a large-scale dynamic graph database

#include <iostream>
#include <vector>
#include <unordered_map>
#include <string>
#include <chrono>
#include <mutex>
#include <condition_variable>

// Structure to represent a node in the graph
struct Node {
    std::string id; // unique identifier for the node
    int label; // label of the node (optional)
    std::unordered_map<std::string, Edge*> edges; // edges connecting to other nodes
};

// Structure to represent an edge in the graph
struct Edge {
    Node* source; // starting node of the edge
    Node* target; // ending node of the edge
    int weight; // weight or importance of the edge (optional)
};

// Structure to represent a graph database
class GraphDatabase {
private:
    std::unordered_map<std::string, Node*> nodes; // map from node IDs to nodes
    std::vector<Edge*> edges; // vector of all edges in the graph
    std::mutex mutex; // mutex for protecting the graph data structure
    std::condition_variable cv; // condition variable for signaling changes to the graph
public:
    GraphDatabase() {}
    ~GraphDatabase() {
        deleteAllNodes();
        deleteAllEdges();
    }

    // Add a node to the graph database
    void addNode(const std::string& id, int label) {
        std::lock_guard<std::mutex> lock(mutex);
        if (nodes.find(id) == nodes.end()) {
            Node* newNode = new Node();
            newNode->id = id;
            newNode->label = label;
            nodes[id] = newNode;
            cv.notify_all();
        }
    }

    // Add an edge to the graph database
    void addEdge(const std::string& sourceId, const std::string& targetId, int weight) {
        std::lock_guard<std::mutex> lock(mutex);
        if (nodes.find(sourceId) != nodes.end() && nodes.find(targetId) != nodes.end()) {
            Edge* newEdge = new Edge();
            newEdge->source = nodes[sourceId];
            newEdge->target = nodes[targetId];
            newEdge->weight = weight;
            edges.push_back(newEdge);
            cv.notify_all();
        }
    }

    // Delete a node from the graph database
    void deleteNode(const std::string& id) {
        std::lock_guard<std::mutex> lock(mutex);
        if (nodes.find(id) != nodes.end()) {
            Node* node = nodes[id];
            for (Edge* edge : edges) {
                if (edge->source == node || edge->target == node) {
                    delete edge;
                }
            }
            nodes.erase(id);
        }
    }

    // Delete an edge from the graph database
    void deleteEdge(const std::string& sourceId, const std::string& targetId) {
        std::lock_guard<std::mutex> lock(mutex);
        if (nodes.find(sourceId) != nodes.end() && nodes.find(targetId) != nodes.end()) {
            for (Edge* edge : edges) {
                if (edge->source->id == sourceId && edge->target->id == targetId) {
                    delete edge;
                    break;
                }
            }
        }
    }

    // Delete all nodes from the graph database
    void deleteAllNodes() {
        std::lock_guard<std::mutex> lock(mutex);
        for (auto it = nodes.begin(); it != nodes.end(); ++it) {
            Node* node = it->second;
            delete node;
        }
        nodes.clear();
    }

    // Delete all edges from the graph database
    void deleteAllEdges() {
        std::lock_guard<std::mutex> lock(mutex);
        for (Edge* edge : edges) {
            delete edge;
        }
        edges.clear();
    }

    // Get a node from the graph database
    Node* getNode(const std::string& id) {
        std::lock_guard<std::mutex> lock(mutex);
        if (nodes.find(id) != nodes.end()) {
            return nodes[id];
        } else {
            return nullptr;
        }
    }

    // Get an edge from the graph database
    Edge* getEdge(const std::string& sourceId, const std::string& targetId) {
        std::lock_guard<std::mutex> lock(mutex);
        if (nodes.find(sourceId) != nodes.end() && nodes.find(targetId) != nodes.end()) {
            for (Edge* edge : edges) {
                if (edge->source->id == sourceId && edge->target->id == targetId) {
                    return edge;
                }
            }
        }
        return nullptr;
    }

    // Get all nodes in the graph database
    std::vector<Node*> getNodes() {
        std::lock_guard<std::mutex> lock(mutex);
        std::vector<Node*> result;
        for (auto it = nodes.begin(); it != nodes.end(); ++it) {
            Node* node = it->second;
            result.push_back(node);
        }
        return result;
    }

    // Get all edges in the graph database
    std::vector<Edge*> getEdges() {
        std::lock_guard<std::mutex> lock(mutex);
        std::vector<Edge*> result;
        for (Edge* edge : edges) {
            result.push_back(edge);
        }
        return result;
    }
};
