        running = false;
        cv.notify_all();
        std::cout << "Streaming data processor shutting down." << std::endl;
    }

    void processPacket(SENSOR_DATA_PACKET_T packet) {
        std::lock_guard<std::mutex> lock(mtx);
        if (packets.size() >= capacity) {
            // Drop oldest packet if capacity is reached
            packets.erase(packets.begin());
        }
        packets.push_back(packet);
        cv.notify_one();
