// network_event.h

#ifndef NETWORK_EVENT_H
#define NETWORK_EVENT_H

typedef struct NetworkEvent {
    time_t eventTime;
    int eventType;
    int sourceId;
} NetworkEvent;

// network_event_manager.h

#ifndef NETWORK_EVENT_MANAGER_H
#define NETWORK_EVENT_MANAGER_H

#include "network_event.h"

typedef struct NetworkEventManager {
    pthread_mutex_t lock;
    int eventCounter;
    NetworkEvent* events;
} NetworkEventManager;

void networkEventManagerInit(NetworkEventManager* manager);
void networkEventManagerInsert(NetworkEventManager* manager, NetworkEvent* event);
int networkEventManagerCount(NetworkEventManager* manager);
void networkEventManagerGetEvents(NetworkEventManager* manager, int count, NetworkEvent** events);

#endif /* NETWORK_EVENT_MANAGER_H */

// network_event_manager.c

#include "network_event_manager.h"

void networkEventManagerInit(NetworkEventManager* manager) {
    pthread_mutex_init(&manager->lock, NULL);
    manager->eventCounter = 0;
    manager->events = malloc(sizeof(NetworkEvent) * EVENTS_CAPACITY);
}

void networkEventManagerInsert(NetworkEventManager* manager, NetworkEvent* event) {
    pthread_mutex_lock(&manager->lock);
    if (manager->eventCounter < EVENTS_CAPACITY) {
        memcpy(&manager->events[manager->eventCounter], event, sizeof(NetworkEvent));
        manager->eventCounter++;
    } else {
        // Handle overflow: insert only the most recent events
        memmove(&manager->events[0], &manager->events[1], sizeof(NetworkEvent) * (EVENTS_CAPACITY - 1));
        memcpy(&manager->events[EVENTS_CAPACITY - 1], event, sizeof(NetworkEvent));
    }
    pthread_mutex_unlock(&manager->lock);
}

int networkEventManagerCount(NetworkEventManager* manager) {
    return manager->eventCounter;
}

void networkEventManagerGetEvents(NetworkEventManager* manager, int count, NetworkEvent** events) {
    pthread_mutex_lock(&manager->lock);
    if (count > manager->eventCounter) {
        count = manager->eventCounter;
    }
    for (int i = 0; i < count; i++) {
        memcpy(events[i], &manager->events[i], sizeof(NetworkEvent));
    }
    pthread_mutex_unlock(&manager->lock);
}
