// Structure to represent a node in the doubly-linked list
struct Node {
    struct Node *prev;
    struct Node *next;
    NFAPI_CRC_INDICATION_PDU_T data;
};

// Structure to represent the linked list itself
struct List {
    struct Node *head;
    struct Node *tail;
    size_t count;
};

// Function to create a new node in the doubly-linked list
struct Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    struct Node *node = malloc(sizeof(struct Node));
    if (!node) {
        return NULL;
    }
    node->prev = NULL;
    node->next = NULL;
    node->data = data;
    return node;
}

// Function to add a new node to the doubly-linked list
int add_to_list(struct List *list, NFAPI_CRC_INDICATION_PDU_T data) {
    struct Node *node = create_node(data);
    if (!node) {
        return -1;
    }
    if (list->head == NULL && list->tail == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        node->prev = list->tail;
        list->tail = node;
    }
    list->count++;
    return 0;
}

// Function to remove a node from the doubly-linked list
int remove_from_list(struct List *list, NFAPI_CRC_INDICATION_PDU_T data) {
    struct Node *node = NULL;
    for (node = list->head; node != NULL && node->data != data; node = node->next);
    if (node == NULL) {
        return -1;
    }
    // If the node is the head of the list, update the head pointer
    if (node == list->head) {
        list->head = node->next;
        // If the next node is also the tail, we need to update the tail pointer as well
        if (list->tail == node) {
            list->tail = NULL;
        }
    } else {
        // Otherwise, update the previous node's next pointer to skip over this node
        node->prev->next = node->next;
    }
    // If the node is the tail of the list, update the tail pointer
    if (node == list->tail) {
        list->tail = node->prev;
    } else {
        // Otherwise, update the next node's previous pointer to skip over this node
        node->next->prev = node->prev;
    }
    free(node);
    list->count--;
    return 0;
}

// Function to traverse the doubly-linked list and perform a callback function for each node
void foreach_in_list(struct List *list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T data)) {
    struct Node *node = list->head;
    while (node != NULL) {
        callback(node->data);
        node = node->next;
    }
}

// Function to free the memory allocated by the linked list
void destroy_list(struct List *list) {
    struct Node *node = list->head, *next;
    while (node != NULL) {
        next = node->next;
        free(node);
        node = next;
    }
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
}
