    // If the statistics were fetched successfully, update the global array
    if (stats != NULL) {
        // Update the bandwidth usage in the global array
        nic_stats_array[interface].bandwidth = stats->bandwidth;

        // Update the packet loss rate in the global array
        nic_stats_array[interface].packet_loss_rate = stats->packet_loss_rate;

        // Update the latency in the global array
        nic_stats_array[interface].latency = stats->latency;
    } else {
        // If the statistics were not fetched successfully, return an error code
        return -1;
    }

    // Return 0 on success, or an error code if there was a problem
    return 0;
}

// Function to update the NIC statistics in the global array
void update_nic_stats(char* interface) {
    // If the global array is not initialized, initialize it
    if (nic_stats_array == NULL) {
        nic_stats_array = calloc(100, sizeof(struct nic_stats));
    }

    // Fetch the NIC statistics for the given interface
    fetch_nic_stats(interface);
}

