            printf("Latency: %d ms\n", nic_stats_array[i].latency);
        }
    }
}

// Main function for the program
int main(int argc, char* argv[]) {
    // Initialize the global array of NIC statistics
    update_nic_stats("eth0");
    update_nic_stats("wlan0");

    // Display the NIC statistics in the global array
    display_nic_stats();

    return 0;
}
