int processString(const char *input, size_t sizeLimit, char **output) {
    // Initialize a mutex for locking access to the shared resource
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Check if input is NULL or empty string
    if (input == NULL || *input == '\0') {
        errno = EINVAL;
        return -1;
    }

    // Get the length of the input string
    size_t inputLen = strlen(input);

    // Check if the size limit is valid
    if (sizeLimit <= 0) {
        errno = ERANGE;
        return -1;
    }

    // Allocate memory for the output string, if not provided by the caller
    char *newOutput = NULL;
    if (output == NULL) {
        newOutput = malloc(sizeof(char) * inputLen);
        if (newOutput == NULL) {
            errno = ENOMEM;
            return -1;
        }
    } else {
        // Check if the output string is valid and has enough space for the appended slash
        if (*output == NULL || *outputLen < inputLen + 1) {
            errno = ERANGE;
            return -1;
        }
    }

    // Append a forward slash to the input string, if necessary
    size_t newLen = inputLen + (input[inputLen - 1] != '/' ? 1 : 0);
    if (newLen > sizeLimit) {
        errno = EOVERFLOW;
        return -1;
    }
    strcpy(newOutput, input);
    if (input[inputLen - 1] != '/') {
        newOutput[inputLen] = '/';
        newOutput[inputLen + 1] = '\0';
    }

    // Log the new string length to the external log service asynchronously
    pthread_mutex_lock(&mutex);
    int rc = logToExternalLogService(newLen, "processString");
    pthread_mutex_unlock(&mutex);
    if (rc != 0) {
        // Log an error message if the asynchronous call fails
        fprintf(stderr, "Failed to log string length: %d\n", rc);
    }

    // Update the output parameter with the new string value
    if (output == NULL) {
        *output = newOutput;
    } else {
        strcpy(*output, newOutput);
    }

    // Free the allocated memory, if any
    if (newOutput != NULL && output == NULL) {
        free(newOutput);
    }

    return 0;
}
