class MailboxSync:
    def __init__(self, username, password, server):
        self.username = username
        self.password = password
        self.server = server

    def connect(self):
        # Connect to the IMAP server using SSL
        self.client = IMAPClient(self.server, use_uid=True)
        self.client.login(self.username, self.password)
        self.client.select_folder('INBOX')

    def disconnect(self):
        # Disconnect from the IMAP server
        self.client.logout()

    def get_mailbox_info(self):
        # Get information about the mailbox, including the total number of emails and unread emails
        status, messages = self.client.search(None, 'ALL')
        total_emails = len(messages[0].split())
        status, messages = self.client.search(None, 'UNSEEN')
        unread_emails = len(messages[0].split())
        return {'total_emails': total_emails, 'unread_emails': unread_emails}

    def get_email_details(self, uid):
        # Get details about a specific email based on its UID
        status, messages = self.client.search(None, 'UID {}'.format(uid))
        msg = envelope(messages[0])
        subject = msg['subject']
        sender = msg['from']
        body = msg.get_payload()
        return {'subject': subject, 'sender': sender, 'body': body}

    def mark_email_read(self, uid):
        # Mark an email as read
        status, messages = self.client.search(None, 'UID {}'.format(uid))
        if not messages:
            return False
        else:
            self.client.add('FLAGS', uid, '\Seen')
            return True

    def delete_email(self, uid):
        # Delete an email from the mailbox
        status, messages = self.client.search(None, 'UID {}'.format(uid))
        if not messages:
            return False
        else:
            self.client.add('FLAGS', uid, '\Deleted')
            return True

    def move_email(self, uid, destination):
        # Move an email to a specific folder
        status, messages = self.client.search(None, 'UID {}'.format(uid))
        if not messages:
            return False
        else:
            self.client.move(messages[0], destination)
            return True

