// Module for managing a distributed microservices' configuration system
#include <iostream>
#include <string>
#include <map>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <atomic>
#include <fstream>
#include <sstream>
#include <vector>
#include <chrono>
#include <algorithm>
#include <ctime>
#include <functional>
#include "json.hpp"

namespace ConfigManager {
    struct Configuration {
        std::string serviceName;
        int portNumber;
        std::map<std::string, std::string> environmentVariables;
        std::vector<Configuration> childrenConfigurations;
    };

    class ConfigManager {
    public:
        ConfigManager();
        ~ConfigManager();
        void loadConfig(const std::string& configFilePath);
        Configuration getCurrentConfiguration() const;
        bool updateConfig(const std::string& newConfig, const std::function<void()>& callback = nullptr);
        bool setConfiguration(const Configuration& config);
        void printLogs();
    private:
        Configuration m_currentConfiguration;
        std::mutex m_mutex;
        std::condition_variable m_cv;
        std::atomic<bool> m_isConfigLoaded = false;
        std::vector<std::thread> m_watcherThreads;
        std::ofstream m_logFile;
    };
}

ConfigManager::ConfigManager() {
    // Initialize log file
    m_logFile.open("config_manager.log");
}

ConfigManager::~ConfigManager() {
    // Close log file
    if (m_logFile.is_open()) {
        m_logFile.close();
    }
}

void ConfigManager::loadConfig(const std::string& configFilePath) {
    // Lock mutex to prevent concurrent access
    std::lock_guard<std::mutex> lock(m_mutex);

    // Read configuration from file and parse it
    std::ifstream configFile(configFilePath);
    if (!configFile.is_open()) {
        m_logFile << "Failed to open configuration file: " + configFilePath << std::endl;
        return;
    }

    // Parse JSON object from file stream
    nlohmann::json jsonObject = nlohmann::json::parse(configFile);

    // Create a new Configuration object and populate it with parsed data
    m_currentConfiguration.serviceName = jsonObject["serviceName"];
    m_currentConfiguration.portNumber = jsonObject["portNumber"];

    // Read environment variables from JSON object
    for (auto& envVar : jsonObject["environmentVariables"]) {
        m_currentConfiguration.environmentVariables[envVar.key()] = envVar.value();
    }

    // Read children configurations from JSON object
    for (auto& childConfig : jsonObject["childrenConfigurations"]) {
        Configuration config;
        config.serviceName = childConfig["serviceName"];
        config.portNumber = childConfig["portNumber"];

        // Read environment variables from JSON object
        for (auto& envVar : childConfig["environmentVariables"]) {
            config.environmentVariables[envVar.key()] = envVar.value();
        }

        m_currentConfiguration.childrenConfigurations.push_back(config);
    }

    // Set flag to indicate that configuration is loaded
    m_isConfigLoaded = true;

    // Notify all threads waiting for configuration update
    m_cv.notify_all();
}

Configuration ConfigManager::getCurrentConfiguration() const {
    // Lock mutex to prevent concurrent access
    std::lock_guard<std::mutex> lock(m_mutex);

    return m_currentConfiguration;
}

bool ConfigManager::updateConfig(const std::string& newConfig, const std::function<void()>& callback) {
    // Lock mutex to prevent concurrent access
    std::lock_guard<std::mutex> lock(m_mutex);

    // Parse JSON object from string stream
    nlohmann::json jsonObject = nlohmann::json::parse(newConfig);

    // Update configuration with parsed data
    m_currentConfiguration.serviceName = jsonObject["serviceName"];
    m_currentConfiguration.portNumber = jsonObject["portNumber"];

    // Update environment variables from JSON object
    for (auto& envVar : jsonObject["environmentVariables"]) {
        m_currentConfiguration.environmentVariables[envVar.key()] = envVar.value();
    }

    // Update children configurations from JSON object
    for (auto& childConfig : jsonObject["childrenConfigurations"]) {
        Configuration config;
        config.serviceName = childConfig["serviceName"];
        config.portNumber = childConfig["portNumber"];

        // Read environment variables from JSON object
        for (auto& envVar : childConfig["environmentVariables"]) {
            config.environmentVariables[envVar.key()] = envVar.value();
        }

        m_currentConfiguration.childrenConfigurations.push_back(config);
    }

    // Set flag to indicate that configuration is updated
    m_isConfigLoaded = true;

    // Notify all threads waiting for configuration update
    m_cv.notify_all();

    if (callback != nullptr) {
        callback();
    }
}

bool ConfigManager::setConfiguration(const Configuration& config) {
    // Lock mutex to prevent concurrent access
    std::lock_guard<std::mutex> lock(m_mutex);

    m_currentConfiguration.serviceName = config.serviceName;
    m_currentConfiguration.portNumber = config.portNumber;

    for (auto& envVar : config.environmentVariables) {
        m_currentConfiguration.environmentVariables[envVar.key()] = envVar.value();
    }

    for (auto& childConfig : config.childrenConfigurations) {
        Configuration child;
        child.serviceName = childConfig.serviceName;
        child.portNumber = childConfig.portNumber;

        for (auto& envVar : childConfig.environmentVariables) {
            child.environmentVariables[envVar.key()] = envVar.value();
        }

        m_currentConfiguration.childrenConfigurations.push_back(child);
    }

    // Set flag to indicate that configuration is updated
    m_isConfigLoaded = true;

    // Notify all threads waiting for configuration update
    m_cv.notify_all();
}

void ConfigManager::printLogs() {
    // Lock mutex to prevent concurrent access
    std::lock_guard<std::mutex> lock(m_mutex);

    if (m_logFile.is_open()) {
        m_logFile.close();
    }
}

int main() {
    // Initialize configuration manager
    ConfigManager configManager;

    // Load initial configuration from file
    configManager.loadConfigFromFile("config.json");

    // Start threads that will wait for configuration update
    std::vector<std::thread> threads;
    for (int i = 0; i < 5; ++i) {
        threads.push_back(std::thread([&]() {
            while (true) {
                // Wait for configuration update
                configManager.waitForConfigUpdate();

                // Print current configuration
                std::cout << "Current configuration: " << configManager.getCurrentConfiguration().serviceName << std::endl;
            }
        }));
    }

    // Start thread that will update configuration
    std::thread updateThread([&]() {
        while (true) {
            // Wait for 1 second
            std::this_thread::sleep_for(std::chrono::seconds(1));

            // Update configuration with new data
            configManager.updateConfig("{ \"serviceName\": \"new-value\" }");
        }
    });
}']

