void parseConfig(char* filename) {
    // Open the configuration file for reading
    FILE* fp = fopen(filename, "r");

    // Read the number of tasks in the configuration file
    int numTasks;
    fscanf(fp, "%d", &numTasks);

    // Allocate memory for the task list and initialize it
    struct Task* tasks = malloc(numTasks * sizeof(struct Task));
    memset(tasks, 0, numTasks * sizeof(struct Task));

    // Read each task in the configuration file and populate the task list
    int i;
    for (i = 0; i < numTasks; i++) {
        struct Task* task = &tasks[i];
        char name[256], command[1024];
        fscanf(fp, "%s %s", name, command);
        task->name = malloc(strlen(name) + 1);
        strcpy(task->name, name);
        task->command = malloc(strlen(command) + 1);
        strcpy(task->command, command);
    }

    // Close the configuration file and return the parsed tasks
    fclose(fp);
    return tasks;
}

// Function to execute a task asynchronously
void* runTask(struct Task* task) {
    printf("Starting task %s\n", task->name);

    // Set up the process environment for running the command
    char* envp[] = {"PATH=/bin:/usr/bin", "SHELL=/bin/bash", NULL};
    char* argv[] = {task->command, NULL};

    // Execute the task asynchronously and handle any errors
    int pid = fork();
