import asyncio
import logging
from typing import Dict, List, Optional

class DynamicLogger:
    def __init__(self) -> None:
        self.loggers: Dict[str, logging.Logger] = {}
        self.log_levels: Dict[str, int] = {}
        self.log_destinations: Dict[str, str] = {}

    def add_logger(self, name: str, level: int) -> None:
        if name in self.loggers:
            raise ValueError("Logger with name '{}' already exists".format(name))
        self.loggers[name] = logging.getLogger(name)
        self.log_levels[name] = level

    def add_destination(self, name: str, destination: str) -> None:
        if name in self.log_destinations:
            raise ValueError("Destination with name '{}' already exists".format(name))
        self.log_destinations[name] = destination

    def set_level(self, name: str, level: int) -> None:
        if name not in self.loggers:
            raise ValueError("Logger with name '{}' does not exist".format(name))
        self.log_levels[name] = level

    def get_level(self, name: str) -> int:
        if name not in self.loggers:
            raise ValueError("Logger with name '{}' does not exist".format(name))
        return self.log_levels[name]

    def log(self, message: str, level: int = logging.INFO) -> None:
        for logger in self.loggers.values():
            if level >= self.get_level(logger.name):
                logger.log(level, message)

    async def send_logs(self, destinations: List[str]) -> Optional[Exception]:
        exceptions = []
        for destination in destinations:
            try:
                await self.log_destinations[destination].send()
            except Exception as e:
                exceptions.append(e)

        if len(exceptions) > 0:
            return exceptions[-1]
        else:
            return None

    async def send_logs_retry(self, destinations: List[str]) -> Optional[Exception]:
        exceptions = []
        for destination in destinations:
            try:
                await self.log_destinations[destination].send()
            except Exception as e:
                exceptions.append(e)

        if len(exceptions) > 0:
            return exceptions[-1]
        else:
            return None
```
