// Semaphore Implementation

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <semaphore.h>
#include <signal.h>

// Structs and Enums
typedef enum {
    INITIALIZING,
    READY,
    SHUTDOWN
} sem_state;

typedef struct client {
    int id;
    char* name;
    int priority;
} client;

// Semaphore Variables
sem_t *sem;
int sem_val = 0;
bool is_initialized = false;
bool is_shutdown = false;

// Client List and Priority Map
std::map<int, client> clients;
std::map<int, int> priorities;

// Semaphore Functions
void sem_init() {
    if (is_initialized) return;
    sem = sem_open("sem", O_CREAT | O_EXCL, 0644, 1);
    is_initialized = true;
}

bool sem_acquire(int id) {
    if (!is_initialized || is_shutdown) return false;
    client* c = &clients[id];
    if (c == nullptr) return false;
    int p = priorities[id];
    if (sem_val >= p) {
        sem_wait(sem);
        sem_val--;
        return true;
    } else {
        return false;
    }
}

void sem_release(int id) {
    if (!is_initialized || is_shutdown) return;
    client* c = &clients[id];
    if (c == nullptr) return;
    int p = priorities[id];
    if (sem_val < p) return;
    sem_post(sem);
    sem_val++;
}

void sem_add_client(int id, const char* name, int priority) {
    if (!is_initialized || is_shutdown) return;
    client c = {id, strdup(name), priority};
    clients[id] = c;
    priorities[id] = priority;
}

void sem_remove_client(int id) {
    if (!is_initialized || is_shutdown) return;
    client* c = &clients[id];
    if (c == nullptr) return;
    priorities.erase(id);
    free((void*) c->name);
    clients.erase(id);
}

void sem_shutdown() {
    if (!is_initialized || is_shutdown) return;
    sem_close(sem);
    is_shutdown = true;
}

// Function Definitions
void handle_signal(int sig) {
    printf("Caught signal %d\n", sig);
    sem_remove_client(getpid());
    exit(0);
}

void sem_run() {
    sem_init();
    // Add current process as a client with default priority 1
    sem_add_client(getpid(), "process", 1);
    while (!is_shutdown) {
        int id = getpid();
        if (sem_acquire(id)) {
            printf("Process %d acquired resource\n", id);
            // Perform action on the shared resource
            sleep(2);
            sem_release(id);
            printf("Process %d released resource\n", id);
        } else {
            // Handle failed acquisition
            printf("Process %d failed to acquire resource\n", id);
            // Continue running and retry later
        }
    }
    sem_shutdown();
}

int main(int argc, char* argv[]) {
    signal(SIGINT, handle_signal);
    sem_run();
    return 0;
}']

