// Define a function to dynamically update transaction alerts within a web application based on specified criteria
function updateTransactionAlerts(transactions) {
  // Initialize an empty list of alerts
  const alerts = [];

  // Iterate through each transaction record and apply filters
  transactions.forEach((transaction) => {
    // Check if the transaction meets the specified criteria for triggering an alert
    if (meetsCriteria(transaction)) {
      // Add the alert to the list of alerts
      alerts.push({
        type: 'transaction',
        details: {
          id: transaction.id,
          amount: transaction.amount,
          currency: transaction.currency,
        },
      });
    }
  });

  // Update the web application with the list of alerts
  updateWebApp(alerts);
}

// Define a function to check if a transaction meets the specified criteria for triggering an alert
function meetsCriteria(transaction) {
  // Check if the transaction amount is greater than a certain threshold
  if (transaction.amount > THRESHOLD_AMOUNT) {
    return true;
  }

  // Check if the transaction currency is not supported by the web application
  if (!SUPPORTED_CURRENCIES.includes(transaction.currency)) {
    return true;
  }

  // If none of the above criteria are met, return false
  return false;
}

// Define a function to update the web application with the list of alerts
function updateWebApp(alerts) {
  // Send an HTTP request to the web application API to update the list of alerts
  fetch(`https://web-app.com/api/v1/alerts`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(alerts),
  })
    .then((response) => response.json())
    .catch((error) => console.error('Error updating web app:', error));
}
```
