// Define a function to load and integrate third-party libraries
async function loadLibrary(libraryName) {
  const libraryPath = path.join(__dirname, `libraries/${libraryName}`);
  if (!fs.existsSync(libraryPath)) {
    throw new Error(`Library ${libraryName} not found`);
  }

  // Load the library into a sandboxed environment
  const script = vm.createScript(fs.readFileSync(libraryPath), {
    filename: libraryName,
  });
  script.runInContext(vm.createContext());

  // Expose the library to the global scope
  global[libraryName] = require(libraryName);
}

