  if (cache.hasOwnProperty(cacheKey)) {
    return cache[cacheKey];
  }

  try {
    // Fetch the data from the API
    const response = await axios.get(url);
    cache[cacheKey] = response.data;
    return response.data;
  } catch (error) {
    console.log(`Error fetching data: ${error}`);
  }
}

