std::string manipulateString(const char* inputString, size_t sizeLimit) {
    // Check if the input string is null or empty
    if (inputString == nullptr || *inputString == '\0') {
        return "";
    }

    // Convert the input string to a vector of characters
    std::vector<char> chars(inputString, inputString + sizeLimit);

    // Remove any unnecessary characters from the vector
    chars.erase(std::remove_if(chars.begin(), chars.end(), [](char c) { return !isalnum(c); }), chars.end());

    // Convert the vector back to a string and return it
    return std::string(chars.begin(), chars.end());
}
